-- parity: _get_or_create_manager_vault(uuid)
CREATE OR REPLACE FUNCTION public._get_or_create_manager_vault(p_org_id uuid)
 RETURNS manager_vault_account
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vault public.manager_vault_account;
begin
  select * into v_vault from public.manager_vault_account where organization_id = p_org_id;
  if not found then
    insert into public.manager_vault_account (organization_id)
    values (p_org_id)
    on conflict (organization_id) do update set updated_at = now()
    returning * into v_vault;
  end if;
  return v_vault;
end;
$function$;
revoke all on function _get_or_create_manager_vault(uuid) from public, anon, authenticated, service_role;
grant execute on function _get_or_create_manager_vault(uuid) to authenticated;
grant execute on function _get_or_create_manager_vault(uuid) to service_role;

-- parity: _goldia_assert_seller_rate(text,numeric,numeric,boolean)
CREATE OR REPLACE FUNCTION public._goldia_assert_seller_rate(p_role text, p_rate numeric, p_official_rate numeric, p_has_cash boolean)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if not p_has_cash or not public._goldia_is_seller_role(p_role) then
    return;
  end if;
  if p_official_rate is null or p_official_rate <= 0 then
    raise exception 'ERR_DAILY_RATE_NOT_SET: Naqd pul yoki dollarni qabul qilish uchun 585 oltin kursi kiritilishi shart! Avval kunlik kursni belgilang.';
  end if;
  if p_rate is null or abs(round(p_rate, 2) - round(p_official_rate, 2)) > 0.01 then
    raise exception 'ERR_RATE_MISMATCH: Sotuvchi faqat rasmiy kunlik 585 kursi (% UZS/g) bilan to''lov qabul qila oladi. Yuborilgan kurs: % UZS/g',
      p_official_rate, p_rate using errcode = '42501';
  end if;
end;
$function$;
revoke all on function _goldia_assert_seller_rate(text,numeric,numeric,boolean) from public, anon, authenticated, service_role;
grant execute on function _goldia_assert_seller_rate(text,numeric,numeric,boolean) to service_role;

-- parity: _goldia_backfill_markup_difference()
CREATE OR REPLACE FUNCTION public._goldia_backfill_markup_difference()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer;
begin
  with candidates as (
    select s.id as sale_id, s.base_weight_grams, s.client_markup_pct,
           coalesce(cp.seller_markup_pct, sc.seller_markup_pct) as pct
      from public.jewelry_sales s
      left join lateral (select p.consignment_id, p.seller_markup_pct from public.consignment_pieces p
                          where p.sale_id = s.id limit 1) cp on true
      join public.seller_consignments sc on sc.id = coalesce(cp.consignment_id, s.consignment_id)
     where s.assigned_seller_markup_pct is null
       and s.client_markup_pct is not null
       and sc.seller_markup_pct is not null
       and (cp.seller_markup_pct is null or cp.seller_markup_pct = sc.seller_markup_pct)
       and sc.original_base_weight_grams > 0
       and abs(sc.original_seller_obligation_g
               - round(sc.original_base_weight_grams * (1 + sc.seller_markup_pct / 100.0), 4)) <= 0.001
  )
  update public.jewelry_sales s
     set assigned_seller_markup_pct = c.pct,
         markup_difference_g = round(coalesce(c.base_weight_grams, 0) * (c.client_markup_pct - c.pct) / 100.0, 4),
         markup_snapshot_source = 'reconstructed'
    from candidates c
   where s.id = c.sale_id;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;
revoke all on function _goldia_backfill_markup_difference() from public, anon, authenticated, service_role;
grant execute on function _goldia_backfill_markup_difference() to service_role;

