-- parity: _goldia_repair_factory_counters()
CREATE OR REPLACE FUNCTION public._goldia_repair_factory_counters()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vault   record;
  v_recv    numeric(14, 4);
  v_obl     numeric(14, 4);
  v_handed  numeric(14, 4);
  v_net     numeric(14, 4);
  v_report  jsonb := '[]'::jsonb;
begin
  for v_vault in select * from public.manager_vault_account for update loop
    select coalesce(sum(original_physical_g), 0), coalesce(sum(factory_obligation_g), 0)
      into v_recv, v_obl
      from public.factory_receipts
     where organization_id = v_vault.organization_id and status not in ('reversed', 'cancelled');
    if abs(v_recv - coalesce(v_vault.total_factory_received_g, 0)) <= 0.0001
       and abs(v_obl - coalesce(v_vault.total_factory_obligation_g, 0)) <= 0.0001 then
      continue;
    end if;
    -- Same rule as rpc_record_factory_gold_handover: handed over = all non-reversed handovers.
    select coalesce(sum(agreed_equivalent_g), 0) into v_handed
      from public.factory_gold_handovers
     where organization_id = v_vault.organization_id and status <> 'reversed';
    v_net := round(v_obl - v_handed, 4);

    update public.manager_vault_account
       set total_factory_received_g     = v_recv,
           total_factory_obligation_g   = v_obl,
           total_factory_handed_over_g  = v_handed,
           current_factory_obligation_g = greatest(v_net, 0),
           current_factory_advance_g    = greatest(-v_net, 0),
           updated_at                   = now()
     where organization_id = v_vault.organization_id;

    insert into public.audit_logs (organization_id, table_name, record_id, action, old_data, new_data, reason)
    values (v_vault.organization_id, 'manager_vault_account', v_vault.organization_id::text, 'REPAIR_FACTORY_COUNTERS',
      jsonb_build_object('total_factory_received_g', v_vault.total_factory_received_g,
        'total_factory_obligation_g', v_vault.total_factory_obligation_g,
        'total_factory_handed_over_g', v_vault.total_factory_handed_over_g,
        'current_factory_obligation_g', v_vault.current_factory_obligation_g,
        'current_factory_advance_g', v_vault.current_factory_advance_g),
      jsonb_build_object('total_factory_received_g', v_recv, 'total_factory_obligation_g', v_obl,
        'total_factory_handed_over_g', v_handed, 'current_factory_obligation_g', greatest(v_net, 0),
        'current_factory_advance_g', greatest(-v_net, 0)),
      'Migration 068: counters rebuilt from active factory receipts (039 receipt reversal did not reduce them)');

    v_report := v_report || jsonb_build_object('organization_id', v_vault.organization_id,
      'before', jsonb_build_object('received_g', v_vault.total_factory_received_g, 'obligation_g', v_vault.total_factory_obligation_g,
        'current_obligation_g', v_vault.current_factory_obligation_g, 'current_advance_g', v_vault.current_factory_advance_g),
      'after', jsonb_build_object('received_g', v_recv, 'obligation_g', v_obl, 'current_obligation_g', greatest(v_net, 0),
        'current_advance_g', greatest(-v_net, 0)));
  end loop;
  return v_report;
end;
$function$;
revoke all on function _goldia_repair_factory_counters() from public, anon, authenticated, service_role;
grant execute on function _goldia_repair_factory_counters() to service_role;

-- parity: _goldia_repair_weight_sale_pieces()
CREATE OR REPLACE FUNCTION public._goldia_repair_weight_sale_pieces()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sale    record;
  v_linked  numeric(14, 4);
  v_short   numeric(14, 4);
  v_excess  numeric(14, 4);
  v_before  jsonb;
  v_after   jsonb;
  v_left    numeric(14, 4);
  v_report  jsonb := '[]'::jsonb;
begin
  for v_sale in
    select s.* from public.jewelry_sales s
     where s.sale_type = 'weight' and s.status not in ('reversed', 'cancelled')
       and not exists (select 1 from public.weight_sale_allocations a where a.sale_id = s.id)
       and exists (select 1 from public.consignment_pieces p where p.sale_id = s.id and p.status = 'sold')
     order by s.created_at, s.id
  loop
    select coalesce(sum(weight_grams), 0) into v_linked
      from public.consignment_pieces where sale_id = v_sale.id and status = 'sold';
    v_short := round(coalesce(v_sale.base_weight_grams, 0) - v_linked, 4);

    -- Record the pieces the old code already consumed, so a later reversal restores them exactly.
    insert into public.weight_sale_allocations (organization_id, sale_id, piece_id, consignment_id, grams,
      piece_weight_before, fully_consumed, source)
    select v_sale.organization_id, v_sale.id, p.id, p.consignment_id, p.weight_grams, p.weight_grams, true, 'repair'
      from public.consignment_pieces p where p.sale_id = v_sale.id and p.status = 'sold'
    on conflict (sale_id, piece_id) do nothing;

    if v_short <= 0.0001 then
      continue;
    end if;

    select round(
        coalesce((select sum(weight_grams) from public.consignment_pieces
                   where seller_id = v_sale.seller_id and organization_id = v_sale.organization_id and status = 'held_by_seller'), 0)
      - greatest(0,
          coalesce((select sum(base_weight_grams) from public.seller_consignments
                     where seller_id = v_sale.seller_id and organization_id = v_sale.organization_id
                       and status in ('held_by_seller', 'partially_sold', 'fully_sold')), 0)
        - coalesce((select sum(base_weight_grams) from public.jewelry_sales
                     where seller_id = v_sale.seller_id and organization_id = v_sale.organization_id
                       and status not in ('cancelled', 'reversed')), 0)), 4)
      into v_excess;
    if v_excess <= 0.0001 then
      continue;
    end if;

    select coalesce(jsonb_agg(jsonb_build_object('piece_id', id, 'status', status, 'weight_grams', weight_grams, 'sale_id', sale_id) order by id), '[]'::jsonb)
      into v_before
      from public.consignment_pieces where seller_id = v_sale.seller_id and status = 'held_by_seller';

    v_left := public._goldia_consume_weight_sale_pieces(v_sale.id, v_sale.seller_id, v_sale.consignment_id,
                least(v_short, v_excess), v_sale.organization_id, 'repair');

    select coalesce(jsonb_agg(jsonb_build_object('piece_id', p.id, 'status', p.status, 'weight_grams', p.weight_grams, 'sale_id', p.sale_id) order by p.id), '[]'::jsonb)
      into v_after
      from public.consignment_pieces p
     where p.id in (select (x->>'piece_id')::uuid from jsonb_array_elements(v_before) x);

    insert into public.audit_logs (organization_id, table_name, record_id, action, old_data, new_data, reason)
    values (v_sale.organization_id, 'consignment_pieces', v_sale.id::text, 'REPAIR_WEIGHT_SALE_PIECES',
      jsonb_build_object('sale_id', v_sale.id, 'sale_no', v_sale.sale_no, 'sale_weight_g', v_sale.base_weight_grams,
        'linked_pieces_g', v_linked, 'shortfall_g', v_short, 'shelf_excess_g', v_excess, 'held_pieces', v_before),
      jsonb_build_object('consumed_g', least(v_short, v_excess) - v_left, 'held_pieces', v_after),
      'Migration 068: weight sale consumed only one piece; remaining sold weight assigned to held pieces');

    v_report := v_report || jsonb_build_object('sale_id', v_sale.id, 'sale_no', v_sale.sale_no,
      'shortfall_g', v_short, 'consumed_g', least(v_short, v_excess) - v_left, 'before', v_before, 'after', v_after);
  end loop;
  return v_report;
end;
$function$;
revoke all on function _goldia_repair_weight_sale_pieces() from public, anon, authenticated, service_role;
grant execute on function _goldia_repair_weight_sale_pieces() to service_role;

-- parity: _goldia_restore_weight_sale_allocations(uuid)
CREATE OR REPLACE FUNCTION public._goldia_restore_weight_sale_allocations(p_sale_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_alloc public.weight_sale_allocations%rowtype;
  v_piece public.consignment_pieces%rowtype;
  v_sale  public.jewelry_sales%rowtype;
  v_n     integer := 0;
begin
  select * into v_sale from public.jewelry_sales where id = p_sale_id;
  for v_alloc in
    select * from public.weight_sale_allocations
     where sale_id = p_sale_id and reversed_at is null
     order by created_at desc, id
     for update
  loop
    select * into v_piece from public.consignment_pieces where id = v_alloc.piece_id for update;
    if v_alloc.fully_consumed and v_piece.sale_id = p_sale_id then
      update public.consignment_pieces
         set status = 'held_by_seller', sale_id = null, sold_at = null, updated_at = now()
       where id = v_piece.id;
    elsif not v_alloc.fully_consumed and v_piece.status = 'held_by_seller' then
      update public.consignment_pieces
         set weight_grams = round((weight_grams + v_alloc.grams)::numeric, 4), updated_at = now()
       where id = v_piece.id;
    else
      -- The piece left the seller meanwhile (returned): give the weight back as its own held piece.
      insert into public.consignment_pieces (organization_id, consignment_id, model_code, model_name, category,
        purity, weight_grams, status, seller_id, seller_markup_pct, notes)
      values (v_piece.organization_id, v_piece.consignment_id, v_piece.model_code, v_piece.model_name, v_piece.category,
        v_piece.purity, v_alloc.grams, 'held_by_seller', v_piece.seller_id, v_piece.seller_markup_pct,
        'Restored from reversed sale ' || coalesce(v_sale.sale_no, p_sale_id::text));
    end if;
    v_n := v_n + 1;
  end loop;

  update public.weight_sale_allocations set reversed_at = now() where sale_id = p_sale_id and reversed_at is null;

  update public.seller_consignments
     set sold_quantity = greatest(0, coalesce(sold_quantity, 1) - 1), updated_at = now()
   where id = v_sale.consignment_id;
  update public.seller_consignments sc
     set status = case when not exists (select 1 from public.consignment_pieces p
                                         where p.consignment_id = sc.id and p.status = 'held_by_seller') then 'fully_sold'
                       when coalesce(sc.sold_quantity, 0) > 0 then 'partially_sold' else 'held_by_seller' end,
         updated_at = now()
   where sc.id in (select consignment_id from public.weight_sale_allocations where sale_id = p_sale_id)
      or sc.id = v_sale.consignment_id;
  return v_n;
end;
$function$;
revoke all on function _goldia_restore_weight_sale_allocations(uuid) from public, anon, authenticated, service_role;
grant execute on function _goldia_restore_weight_sale_allocations(uuid) to service_role;

-- parity: _goldia_seller_rate_limits(uuid)
CREATE OR REPLACE FUNCTION public._goldia_seller_rate_limits(p_org_id uuid)
 RETURNS seller_rate_limits
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
