-- parity: _goldia_validate_rate_value(numeric,numeric,numeric,text)
CREATE OR REPLACE FUNCTION public._goldia_validate_rate_value(p_value numeric, p_min numeric, p_max numeric, p_label text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_value is null or p_value::text in ('NaN', 'Infinity', '-Infinity') or p_value <= 0 then
    raise exception 'ERR_RATE_INVALID: % musbat va chekli son bo''lishi shart', p_label using errcode = '22023';
  end if;
  if p_value < p_min or p_value > p_max then
    raise exception 'ERR_RATE_OUT_OF_RANGE: % % ruxsat etilgan oraliqdan tashqarida (% — %)', p_label, p_value, p_min, p_max
      using errcode = '22023';
  end if;
  return round(p_value, 2);
end;
$function$;
revoke all on function _goldia_validate_rate_value(numeric,numeric,numeric,text) from public, anon, authenticated, service_role;
grant execute on function _goldia_validate_rate_value(numeric,numeric,numeric,text) to service_role;

-- parity: _sync_seller_consignments_original_fields()
CREATE OR REPLACE FUNCTION public._sync_seller_consignments_original_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.original_quantity is null or new.original_quantity = 0 then
    new.original_quantity := greatest(1, coalesce(new.quantity, 1));
  end if;
  if new.original_base_weight_grams is null or new.original_base_weight_grams = 0 then
    new.original_base_weight_grams := coalesce(new.base_weight_grams, 0);
  end if;
  if new.original_seller_obligation_g is null or new.original_seller_obligation_g = 0 then
    new.original_seller_obligation_g := coalesce(new.seller_obligation_g, 0);
  end if;
  return new;
end;
$function$;
revoke all on function _sync_seller_consignments_original_fields() from public, anon, authenticated, service_role;
grant execute on function _sync_seller_consignments_original_fields() to public;
grant execute on function _sync_seller_consignments_original_fields() to anon;
grant execute on function _sync_seller_consignments_original_fields() to authenticated;
grant execute on function _sync_seller_consignments_original_fields() to service_role;

-- parity: apply_gold_transaction()
CREATE OR REPLACE FUNCTION public.apply_gold_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_delta numeric(14, 4) := 0;
  v_type  text := lower(coalesce(new.type::text, new.transaction_type, ''));
  v_w     numeric(14, 4) := coalesce(new.weight_grams, new.gross_weight, 0);
begin
  -- Operational ledger entries that reference inventory_items instead of gold_lots
  if new.lot_id is null or v_type = '' or v_w <= 0 then
    return new;
  end if;

  case v_type
    when 'lot_received', 'receipt', 'returned_from_batch', 'return_from_batch', 'scrap_recovered', 'scrap_recovery', 'adjustment', 'adjustment_plus' then
      v_delta := v_w;
    when 'issued_to_batch', 'issue_to_batch', 'adjustment_minus' then
      v_delta := -v_w;
    when 'melting_loss' then
      if new.batch_id is null then
        v_delta := -v_w;
      else
        v_delta := 0;
      end if;
    else
      v_delta := 0;
  end case;

  if v_delta <> 0 and to_regclass('public.gold_lots') is not null then
    update public.gold_lots
       set remaining_weight_grams = remaining_weight_grams + v_delta
     where id = new.lot_id;
  end if;

  return new;
end;
$function$;
revoke all on function apply_gold_transaction() from public, anon, authenticated, service_role;
grant execute on function apply_gold_transaction() to authenticated;
grant execute on function apply_gold_transaction() to service_role;

-- parity: apply_inventory_transaction()
CREATE OR REPLACE FUNCTION public.apply_inventory_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sign integer;
begin
  v_sign := case
    when new.type in ('purchase_in', 'production_return', 'adjustment_in') then 1
    else -1
  end;

  update inventory_items
  set quantity_on_hand = quantity_on_hand + (v_sign * new.quantity)
  where id = new.item_id;

  return new;
end;
$function$;
revoke all on function apply_inventory_transaction() from public, anon, authenticated, service_role;
grant execute on function apply_inventory_transaction() to authenticated;
grant execute on function apply_inventory_transaction() to service_role;

-- parity: assert_erp_permission(text[])
CREATE OR REPLACE FUNCTION public.assert_erp_permission(p_allowed_roles text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid        uuid := auth.uid();
  v_emp        public.employees%rowtype;
  v_norm_role  text;
  v_allowed    boolean := false;
begin
  -- Fail closed: reject unauthenticated / anonymous invocations immediately
  if v_uid is null then
    raise exception 'Permission denied: authentication required'
      using errcode = '42501';
  end if;

  select *
    into v_emp
    from public.employees e
   where (e.user_id = v_uid or e.id::text = v_uid::text)
     and coalesce(e.is_active, true) = true
     and lower(coalesce(e.status, e.employment_status::text, 'active')) in ('active', 'faol')
   limit 1;

  if not found then
    raise exception 'Permission denied: no active employee profile for current user'
      using errcode = '42501';
  end if;

  v_norm_role := coalesce(public.current_employee_role_text(), 'viewer');

  select exists (
    select 1
      from unnest(p_allowed_roles) as r(token)
     where public.normalize_erp_role_token(r.token) = v_norm_role
  ) into v_allowed;

  if not v_allowed then
    raise exception 'Permission denied for role "%" (required one of: %)',
      v_norm_role,
      array_to_string(p_allowed_roles, ', ')
      using errcode = '42501';
  end if;
end;
$function$;
