 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_gross_weight <= 0 or p_proba <= 0 or p_proba > 1000 then 0::numeric(18, 6)
    else round((p_gross_weight::numeric(18, 6) * p_proba::numeric(18, 6)) / 1000.0, 6)
  end;
