grant execute on function calculate_melting_loss(numeric,numeric) to service_role;

-- parity: check_and_lock_idempotency(text,text,jsonb)
CREATE OR REPLACE FUNCTION public.check_and_lock_idempotency(p_key text, p_operation text, p_payload jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key text := nullif(btrim(coalesce(p_key, '')), '');
  v_row public.idempotency_keys%rowtype;
begin
  if v_key is null then
    return null;
  end if;

  -- Serialize concurrent requests with the same idempotency key within the transaction
  perform pg_advisory_xact_lock(hashtext('jewelryflow_idemp'), hashtext(v_key));

  select *
    into v_row
    from public.idempotency_keys
   where idempotency_key = v_key;

  if not found then
    return null;
  end if;

  if v_row.operation_name <> p_operation then
    raise exception 'Idempotency key conflict: key "%" was already used for operation "%"',
      v_key, v_row.operation_name
      using errcode = '23505';
  end if;

  if p_payload is not null
     and (v_row.response_data ? '_request_hash')
     and (v_row.response_data ->> '_request_hash') <> md5(p_payload::text) then
    raise exception 'Idempotency key conflict: key "%" was already used with different request parameters',
      v_key
      using errcode = '23505';
  end if;

  return v_row.response_data - '_request_hash';
end;
$function$;
revoke all on function check_and_lock_idempotency(text,text,jsonb) from public, anon, authenticated, service_role;
grant execute on function check_and_lock_idempotency(text,text,jsonb) to authenticated;
grant execute on function check_and_lock_idempotency(text,text,jsonb) to service_role;

