-- parity: current_employee_role_text()
CREATE OR REPLACE FUNCTION public.current_employee_role_text()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_emp       public.employees%rowtype;
  v_role_type text;
  v_role_col  text;
  v_pos_role  text;
begin
  if v_uid is null then
    return null;
  end if;

  select *
    into v_emp
    from public.employees e
   where (e.user_id = v_uid or e.id::text = v_uid::text)
     and coalesce(e.is_active, true) = true
     and lower(coalesce(e.status, e.employment_status::text, 'active')) in ('active', 'faol')
   limit 1;

  if not found then
    return 'viewer';
  end if;

  v_role_type := public.normalize_erp_role_token(v_emp.role_type);
  v_role_col  := public.normalize_erp_role_token(v_emp.role::text);
  v_pos_role  := public.normalize_erp_role_token(v_emp.position);

  -- Explicit role precedence rule:
  -- 1. Specific non-generic role_type (Director, Manager, Accountant, Seller, Warehouse, Supervisor)
  --    takes precedence over legacy/default role column ('worker'/'viewer'/'department_operator').
  -- 2. Specific non-generic role column takes next precedence.
  -- 3. Validated generic role_type / role column / position fallback.
  -- 4. Unknown or malformed role values fail closed to 'viewer'.
  if v_role_type is not null and v_role_type not in ('worker', 'viewer') then
    return v_role_type;
  elsif v_role_col is not null and v_role_col not in ('worker', 'viewer') then
    return v_role_col;
  elsif v_role_type is not null then
    return v_role_type;
  elsif v_role_col is not null then
    return v_role_col;
  elsif v_pos_role is not null then
    return v_pos_role;
  else
    return 'viewer';
  end if;
end;
$function$;
revoke all on function current_employee_role_text() from public, anon, authenticated, service_role;
grant execute on function current_employee_role_text() to authenticated;
grant execute on function current_employee_role_text() to service_role;

-- parity: current_organization_id()
CREATE OR REPLACE FUNCTION public.current_organization_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid       uuid := auth.uid();
  v_org_id    uuid;
  v_cfg_org   text;
begin
  -- Optional session/transaction override (used in automated multi-tenant test suites or API proxies)
  v_cfg_org := current_setting('app.current_organization_id', true);
  if v_cfg_org is not null and v_cfg_org ~* '^[0-9a-f-]{36}$' then
    return v_cfg_org::uuid;
  end if;

  -- Fail-closed if no authenticated session
  if v_uid is null then
    return null;
  end if;

  -- 1. Check employee organization assignment
  select organization_id
    into v_org_id
    from public.employees e
   where (e.user_id = v_uid or e.id::text = v_uid::text)
     and e.organization_id is not null
     and coalesce(e.is_active, true) = true
   limit 1;

  if v_org_id is not null then
    return v_org_id;
  end if;

  -- 2. Check profile organization assignment (if legacy profiles table exists)
  if exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'profiles') then
    execute 'select organization_id from public.profiles where user_id = $1 and organization_id is not null limit 1'
      into v_org_id using v_uid;
    if v_org_id is not null then
      return v_org_id;
    end if;
  end if;

  -- 3. Fail closed: Unassigned users have NO organization (NULL).
  return null;
end;
$function$;
revoke all on function current_organization_id() from public, anon, authenticated, service_role;
grant execute on function current_organization_id() to public;
grant execute on function current_organization_id() to anon;
grant execute on function current_organization_id() to authenticated;
grant execute on function current_organization_id() to service_role;

