grant execute on function log_batch_status_change() to service_role;

-- parity: normalize_erp_role_token(text)
CREATE OR REPLACE FUNCTION public.normalize_erp_role_token(p_token text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_clean text := lower(btrim(coalesce(p_token, '')));
begin
  if v_clean = '' then
    return null;
  end if;

  case v_clean
    when 'admin', 'director', 'owner', 'direktor', 'rahbar' then
      return 'admin';
    when 'production_manager', 'production manager', 'manager', 'ishlab chiqarish boshlig''i', 'boshqaruvchi' then
      return 'production_manager';
    when 'department_head', 'supervisor', 'master', 'bosh usta', 'usta' then
      return 'supervisor';
    when 'quality_inspector', 'quality_control', 'qc', 'otk' then
      return 'quality_inspector';
    when 'inventory_manager', 'warehouse', 'omborchi' then
      return 'inventory_manager';
    when 'accountant', 'buxgalter', 'hisobchi' then
      return 'accountant';
    when 'seller', 'sales', 'sotuvchi', 'savdo', 'seller_agent' then
      return 'seller';
    when 'department_operator', 'worker', 'zargar', 'operator' then
      return 'worker';
    when 'viewer' then
      return 'viewer';
    else
      return null;
  end case;
end;
$function$;
revoke all on function normalize_erp_role_token(text) from public, anon, authenticated, service_role;
grant execute on function normalize_erp_role_token(text) to authenticated;
grant execute on function normalize_erp_role_token(text) to service_role;

-- parity: prevent_employee_privilege_escalation()
CREATE OR REPLACE FUNCTION public.prevent_employee_privilege_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_in_salary_rpc  boolean := (coalesce(current_setting('app.in_salary_rpc', true), 'false') = 'true');
  v_in_auth_link   boolean := (coalesce(current_setting('app.in_auth_link_trigger', true), 'false') = 'true');
begin
  -- 070: moving an employee between organizations is never allowed through the API (JWT callers)
  if auth.uid() is not null and new.organization_id is distinct from old.organization_id then
    raise exception 'Privilege escalation blocked: organization_id cannot be changed' using errcode = '42501';
  end if;
  if auth.uid() is not null and not public.is_admin_or_manager() then
    if new.role is distinct from old.role
       or new.role_type is distinct from old.role_type
       or new.status is distinct from old.status
       or new.employment_status is distinct from old.employment_status
       or new.is_active is distinct from old.is_active
       or new.employee_code is distinct from old.employee_code
       or new.primary_department_id is distinct from old.primary_department_id
       or new.rate is distinct from old.rate
       or (new.user_id is distinct from old.user_id and not v_in_auth_link)
       or new.email is distinct from old.email
       or (new.balance is distinct from old.balance and not v_in_salary_rpc)
    then
      raise exception 'Privilege escalation blocked: only admin or manager may modify role, identity link, status, rate, or balance'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$function$;
revoke all on function prevent_employee_privilege_escalation() from public, anon, authenticated, service_role;
grant execute on function prevent_employee_privilege_escalation() to authenticated;
grant execute on function prevent_employee_privilege_escalation() to service_role;

-- parity: prevent_ledger_delete_or_tamper()
CREATE OR REPLACE FUNCTION public.prevent_ledger_delete_or_tamper()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Deleting records from immutable ledger table "%" is strictly prohibited', tg_table_name
      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and tg_table_name in (
    'audit_log', 'audit_logs', 'gold_transactions', 'inventory_transactions',
    'debt_repayments', 'salary_ledger', 'affinaj_records'
  ) then
    raise exception 'Modifying existing records in immutable ledger table "%" is strictly prohibited', tg_table_name
      using errcode = '42501';
  end if;

  return new;
end;
$function$;
revoke all on function prevent_ledger_delete_or_tamper() from public, anon, authenticated, service_role;
grant execute on function prevent_ledger_delete_or_tamper() to authenticated;
grant execute on function prevent_ledger_delete_or_tamper() to service_role;

-- parity: recalc_seller_gold_account(uuid,uuid)
CREATE OR REPLACE FUNCTION public.recalc_seller_gold_account(p_seller_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_total_phys       numeric(14, 4);
  v_consignment_obl  numeric(14, 4);
  v_legacy_debt_obl  numeric(14, 4);
  v_total_obl        numeric(14, 4);
  v_total_stl        numeric(14, 4);
  v_s_owes           numeric(14, 4);
  v_m_owes           numeric(14, 4);
  v_signed           numeric(14, 4);
  v_total_sold       numeric(14, 4);
  v_cur_stock        numeric(14, 4);
BEGIN
  IF p_seller_id IS NULL OR p_org_id IS NULL THEN
    RETURN;
  END IF;

  -- 1. Active Consignments: sum base_weight_grams which represents active remaining physical grams
  SELECT
    COALESCE(SUM(base_weight_grams), 0),
    COALESCE(SUM(COALESCE(seller_obligation_g, factory_gold_due_grams)), 0)
  INTO v_total_phys, v_consignment_obl
  FROM public.seller_consignments
  WHERE seller_id = p_seller_id AND organization_id = p_org_id
    AND status IN ('held_by_seller', 'partially_sold', 'fully_sold');

  -- 1b. Legacy client debts assigned to this seller (unreversed)
  SELECT COALESCE(SUM(delta_585_g), 0)
  INTO v_legacy_debt_obl
  FROM public.client_legacy_debts
  WHERE seller_id = p_seller_id AND organization_id = p_org_id
    AND balance_type = 'debt'
    AND status <> 'reversed';

  v_total_obl := ROUND(v_consignment_obl + v_legacy_debt_obl, 4);

  -- 2. Total non-reversed settlements surrendered to manager/factory
  SELECT COALESCE(SUM(total_settled_grams), 0)
  INTO v_total_stl
  FROM public.gold_settlements
  WHERE seller_id = p_seller_id AND organization_id = p_org_id
    AND direction IN ('seller_to_manager', 'seller_to_factory')
    AND (status IS NULL OR status NOT IN ('reversed', 'cancelled'))
    AND reversal_of_id IS NULL;

  v_s_owes := ROUND(GREATEST(0, v_total_obl - v_total_stl), 4);
  v_m_owes := ROUND(GREATEST(0, v_total_stl - v_total_obl), 4);
  v_signed := ROUND(v_m_owes - v_s_owes, 4);

  -- 3. Total sold physical grams (sales not cancelled or reversed)
  SELECT COALESCE(SUM(base_weight_grams), 0)
  INTO v_total_sold
  FROM public.jewelry_sales
  WHERE seller_id = p_seller_id AND organization_id = p_org_id
    AND status NOT IN ('cancelled', 'reversed');

  -- Note: v_total_phys ALREADY reflects base_weight_grams reduced by returned pieces!
  v_cur_stock := ROUND(GREATEST(0, v_total_phys - v_total_sold), 4);

  INSERT INTO public.seller_gold_accounts (
    seller_id, organization_id,
    total_transferred_physical_g, total_seller_obligation_g,
    total_settled_to_manager_g, seller_owes_manager_g,
    manager_owes_seller_g, bozor_qarzi_signed_g,
    total_consigned_gold_grams, current_factory_obligation_grams,
    current_physical_stock_g, seller_legacy_debt_obligation_g,
    updated_at
  ) VALUES (
    p_seller_id, p_org_id,
    v_total_phys, v_total_obl,
    v_total_stl, v_s_owes,
    v_m_owes, v_signed,
    v_consignment_obl, v_s_owes,
    v_cur_stock, v_legacy_debt_obl,
    NOW()
  )
  ON CONFLICT (seller_id) DO UPDATE SET
    total_transferred_physical_g = v_total_phys,
    total_seller_obligation_g = v_total_obl,
    total_settled_to_manager_g = v_total_stl,
    seller_owes_manager_g = v_s_owes,
    manager_owes_seller_g = v_m_owes,
    bozor_qarzi_signed_g = v_signed,
    total_consigned_gold_grams = v_consignment_obl,
    current_factory_obligation_grams = v_s_owes,
    current_physical_stock_g = v_cur_stock,
    seller_legacy_debt_obligation_g = v_legacy_debt_obl,
    updated_at = NOW();
END;
$function$;
revoke all on function recalc_seller_gold_account(uuid,uuid) from public, anon, authenticated, service_role;
grant execute on function recalc_seller_gold_account(uuid,uuid) to service_role;

-- parity: record_audit_event()
CREATE OR REPLACE FUNCTION public.record_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_emp_uuid uuid;
  v_emp_name text;
  v_emp_role text;
  v_rec_text text := coalesce(new.id::text, old.id::text);
  v_rec_uuid uuid := public.try_cast_uuid(v_rec_text);
  v_setting  text := nullif(current_setting('app.current_employee_id', true), '');
begin
  select
    coalesce(public.try_cast_uuid(e.id::text), e.user_id),
    coalesce(nullif(trim(e.name), ''), nullif(trim(e.full_name), ''), e.email),
    coalesce(nullif(trim(e.role_type), ''), nullif(trim(e.role::text), ''), nullif(trim(e.position), ''))
    into v_emp_uuid, v_emp_name, v_emp_role
    from public.employees e
   where (e.user_id = auth.uid() or e.id::text = coalesce(v_setting, auth.uid()::text))
   limit 1;

  if to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs (
      table_name, record_id, action, actor_id, actor_name, actor_role, old_data, new_data
    ) values (
      tg_table_name,
      v_rec_text,
      upper(tg_op),
      coalesce(auth.uid(), v_emp_uuid),
      coalesce(v_emp_name, 'System / Trigger'),
      coalesce(v_emp_role, public.current_employee_role_text(), 'system'),
      case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
      case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end
    );
  end if;

  if v_rec_uuid is not null and to_regclass('public.audit_log') is not null then
    insert into public.audit_log (table_name, record_id, action, old_data, new_data, changed_by)
    values (
      tg_table_name,
      v_rec_uuid,
      lower(tg_op),
      case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
      case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end,
      v_emp_uuid
    );
  end if;

  return coalesce(new, old);
end;
$function$;
revoke all on function record_audit_event() from public, anon, authenticated, service_role;
grant execute on function record_audit_event() to authenticated;
grant execute on function record_audit_event() to service_role;

-- parity: rpc_accept_stage_handover(text,text,text,integer,numeric,text,text,text,boolean,text)
CREATE OR REPLACE FUNCTION public.rpc_accept_stage_handover(p_handover_id text, p_receiver_worker_id text, p_receiver_worker_name text, p_received_qty integer, p_received_weight_gram numeric, p_supervisor_override_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_measurement_mode text DEFAULT 'MANUAL_ENTRY'::text, p_is_scale_stable boolean DEFAULT true, p_scale_model text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_h             public.two_party_handovers%rowtype;
  v_rec_weight    numeric(14, 4) := round(coalesce(p_received_weight_gram, 0)::numeric, 4);
  v_discrepancy   numeric(14, 4);
  v_qty_mismatch  boolean;
  v_weight_excess boolean;
  v_new_status    text := 'ACCEPTED';
  v_flag_reason   text := null;
  v_caller_role   text := public.current_employee_role_text();
  v_existing      jsonb;
  v_payload       jsonb;
  v_salary_res    jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  v_payload := jsonb_build_object(
    'handover_id', btrim(coalesce(p_handover_id, '')),
    'receiver_worker_id', btrim(coalesce(p_receiver_worker_id, '')),
    'received_qty', p_received_qty,
    'received_weight_gram', v_rec_weight
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_accept_stage_handover', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_h
    from public.two_party_handovers
   where id = btrim(p_handover_id)
     for update;

  if not found then
    raise exception 'Handover record not found: %', p_handover_id;
  end if;

  -- Cross-tenant isolation verification
  if v_h.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Handover does not belong to your organization' using errcode = '42501';
  end if;

  if v_h.status not in ('PENDING_ACCEPTANCE', 'DISCREPANCY_FLAGGED') then
    raise exception 'Handover % is already finalized in status %', p_handover_id, v_h.status;
  end if;

  if coalesce(p_received_qty, 0) <= 0 or v_rec_weight <= 0 then
    raise exception 'Received quantity and weight must be positive';
  end if;

  v_discrepancy := round(abs(v_h.dispatched_weight_gram - v_rec_weight), 4);
  v_qty_mismatch := (v_h.dispatched_qty <> p_received_qty);
  v_weight_excess := (v_discrepancy > coalesce(v_h.tolerance_gram, 0.05));

  if v_qty_mismatch or v_weight_excess then
    if p_supervisor_override_reason is not null and length(btrim(p_supervisor_override_reason)) >= 5 then
      if v_caller_role not in ('admin', 'director', 'owner', 'manager', 'production_manager', 'supervisor', 'master') then
        raise exception 'Only supervisor or manager can override handover discrepancies';
      end if;
      v_new_status := 'ACCEPTED_WITH_OVERRIDE';
      v_flag_reason := 'Supervayzer tasdiqladi: ' || btrim(p_supervisor_override_reason);
    else
      v_new_status := 'DISCREPANCY_FLAGGED';
      v_flag_reason := case
        when v_qty_mismatch and v_weight_excess then 'Soni va og''irligi mos kelmadi (farq: ' || v_discrepancy || 'g)'
        when v_qty_mismatch then 'Soni mos kelmadi (' || v_h.dispatched_qty || ' vs ' || p_received_qty || ')'
        else 'Og''irlik nomuvofiqligi me''yordan ortiq (' || v_discrepancy || 'g > ' || coalesce(v_h.tolerance_gram, 0.05) || 'g)'
      end;
    end if;
  end if;

  update public.two_party_handovers
     set receiver_worker_id          = btrim(p_receiver_worker_id),
         receiver_worker_name        = btrim(p_receiver_worker_name),
         received_qty                = p_received_qty,
         received_weight_gram        = v_rec_weight,
         weight_discrepancy_gram     = v_discrepancy,
         status                      = v_new_status,
         flag_reason                 = v_flag_reason,
         supervisor_override_id      = case when v_new_status = 'ACCEPTED_WITH_OVERRIDE' then btrim(p_receiver_worker_id) else null end,
         supervisor_override_reason  = case when v_new_status = 'ACCEPTED_WITH_OVERRIDE' then btrim(p_supervisor_override_reason) else null end,
         resolved_at                 = case when v_new_status in ('ACCEPTED', 'ACCEPTED_WITH_OVERRIDE') then clock_timestamp() else null end,
         received_measurement_mode   = coalesce(nullif(btrim(p_measurement_mode), ''), 'MANUAL_ENTRY'),
         received_scale_stable       = coalesce(p_is_scale_stable, true),
         received_scale_model        = nullif(btrim(p_scale_model), '')
   where id = v_h.id;

  -- AUTOMATIC PIECEWORK SALARY CALCULATION:
  -- Only award piecework salary when work is confirmed (ACCEPTED, SUPERVISOR_OVERRIDDEN, ACCEPTED_WITH_OVERRIDE)
  if v_new_status in ('ACCEPTED', 'SUPERVISOR_OVERRIDDEN', 'ACCEPTED_WITH_OVERRIDE') then
    v_salary_res := public.rpc_calculate_piecework_salary(
      p_handover_id     := v_h.id::text,
      p_worker_id       := v_h.sender_worker_id,
      p_worker_name     := v_h.sender_worker_name,
      p_batch_no        := v_h.batch_no,
      p_stage_name      := v_h.from_stage_name,
      p_stage_order     := v_h.from_stage_order,
      p_weight_done     := v_rec_weight,
      p_qty_done        := p_received_qty,
      p_idempotency_key := 'earned-ho-' || v_h.id::text
    );
  end if;

  v_existing := jsonb_build_object(
    'success', (v_new_status in ('ACCEPTED', 'SUPERVISOR_OVERRIDDEN', 'ACCEPTED_WITH_OVERRIDE')),
    'handover_id', v_h.id,
    'status', v_new_status,
    'discrepancy_gram', v_discrepancy,
    'flag_reason', v_flag_reason,
    'measurement_mode', coalesce(nullif(btrim(p_measurement_mode), ''), 'MANUAL_ENTRY'),
    'piecework_earned', v_salary_res
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_accept_stage_handover', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_accept_stage_handover(text,text,text,integer,numeric,text,text,text,boolean,text) from public, anon, authenticated, service_role;
grant execute on function rpc_accept_stage_handover(text,text,text,integer,numeric,text,text,text,boolean,text) to authenticated;
grant execute on function rpc_accept_stage_handover(text,text,text,integer,numeric,text,text,text,boolean,text) to service_role;

-- parity: rpc_adjust_piecework_salary(text,numeric,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_adjust_piecework_salary(p_original_ledger_id text, p_adjustment_amount numeric, p_reason text, p_tx_type text DEFAULT 'ADJUSTMENT'::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org        uuid := public.current_organization_id();
  v_caller_role       text := public.current_employee_role_text();
  v_orig              public.salary_ledger%rowtype;
  v_adj_amount        numeric(18, 2) := round(abs(coalesce(p_adjustment_amount, 0))::numeric, 2);
  v_tx_type           text := upper(btrim(coalesce(p_tx_type, 'ADJUSTMENT')));
  v_new_ledger_id     uuid;
  v_existing          jsonb;
  v_payload           jsonb;
  v_already_adjusted  numeric(18, 2) := 0;
  v_remaining_balance numeric(18, 2);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_caller_role not in (
    'admin', 'director', 'owner', 'manager', 'production_manager',
    'accountant', 'buxgalter', 'hisobchi', 'supervisor'
  ) then
    raise exception 'Permission denied: Role "%" is not authorized to adjust piecework salary', v_caller_role
      using errcode = '42501';
  end if;

  if p_reason is null or length(btrim(p_reason)) < 5 then
    raise exception 'Salary adjustment requires a documented justification reason (min 5 characters)';
  end if;

  if v_tx_type not in ('ADJUSTMENT', 'REVERSAL') then
    raise exception 'Invalid adjustment type: % (must be ADJUSTMENT or REVERSAL)', v_tx_type;
  end if;

  v_payload := jsonb_build_object(
    'original_ledger_id', btrim(coalesce(p_original_ledger_id, '')),
    'amount', v_adj_amount,
    'tx_type', v_tx_type
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_adjust_piecework_salary', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_orig
    from public.salary_ledger
   where id::text = btrim(p_original_ledger_id)
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'Original salary ledger record (%) not found', p_original_ledger_id;
  end if;

  if v_orig.tx_type in ('ADJUSTMENT', 'REVERSAL') then
    raise exception 'Cannot adjust an adjustment or reversal transaction (only original EARNED records can be adjusted)';
  end if;

  select coalesce(sum(amount), 0) into v_already_adjusted
    from public.salary_ledger
   where original_ledger_id = v_orig.id::text
     and organization_id = v_caller_org
     and tx_type in ('ADJUSTMENT', 'REVERSAL');

  v_remaining_balance := v_orig.amount - v_already_adjusted;

  if v_remaining_balance <= 0 then
    raise exception 'Original salary record (%) has already been fully adjusted or reversed (% UZS adjusted of % UZS total)',
      v_orig.id, v_already_adjusted, v_orig.amount;
  end if;

  if v_adj_amount <= 0 or v_tx_type = 'REVERSAL' then
    v_adj_amount := v_remaining_balance;
  end if;

  if v_adj_amount > v_remaining_balance then
    raise exception 'Requested adjustment (% UZS) exceeds remaining adjustable balance (% UZS of original % UZS)',
      v_adj_amount, v_remaining_balance, v_orig.amount;
  end if;

  insert into public.salary_ledger (
    employee_id, worker_name, batch_no, stage_name, tx_type,
    weight_done, rate, amount, payment_status, note,
    handover_id, stage_order, original_ledger_id, idempotency_key, organization_id
  ) values (
    v_orig.employee_id,
    v_orig.worker_name,
    v_orig.batch_no,
    v_orig.stage_name,
    v_tx_type,
    v_orig.weight_done,
    v_orig.rate,
    v_adj_amount,
    'PAID',
    format('%s: %s (Orig Ledger: %s)', v_tx_type, btrim(p_reason), v_orig.id::text),
    v_orig.handover_id,
    v_orig.stage_order,
    v_orig.id::text,
    nullif(btrim(p_idempotency_key), ''),
    v_caller_org
  ) returning id into v_new_ledger_id;

  insert into public.audit_logs (
    table_name, record_id, action, actor_id, actor_name, actor_role,
    reason, new_data, organization_id
  ) values (
    'salary_ledger',
    v_new_ledger_id::text,
    'SALARY_' || v_tx_type,
    auth.uid(),
    public.current_employee_name(),
    v_caller_role,
    btrim(p_reason),
    jsonb_build_object(
      'original_ledger_id', v_orig.id::text,
      'adjusted_amount', v_adj_amount,
      'previous_adjusted', v_already_adjusted,
      'remaining_balance', v_remaining_balance - v_adj_amount,
      'worker_name', v_orig.worker_name,
      'batch_no', v_orig.batch_no,
      'tx_type', v_tx_type
    ),
    v_caller_org
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'adjustment_ledger_id', v_new_ledger_id::text,
    'original_ledger_id', v_orig.id::text,
    'worker_name', v_orig.worker_name,
    'adjusted_amount', v_adj_amount,
    'remaining_balance', v_remaining_balance - v_adj_amount,
    'tx_type', v_tx_type,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_adjust_piecework_salary', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_adjust_piecework_salary(text,numeric,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_adjust_piecework_salary(text,numeric,text,text,text) to authenticated;
grant execute on function rpc_adjust_piecework_salary(text,numeric,text,text,text) to service_role;

-- parity: rpc_archive_customer(uuid,boolean)
CREATE OR REPLACE FUNCTION public.rpc_archive_customer(p_customer_id uuid, p_archive boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar']);

  update public.customers
     set is_archived = p_archive,
         updated_at = now()
   where id = p_customer_id and organization_id = v_caller_org;

  if not found then
    raise exception 'Mijoz topilmadi: %', p_customer_id;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'customer_id', p_customer_id,
    'is_archived', p_archive
  );
end;
$function$;
revoke all on function rpc_archive_customer(uuid,boolean) from public, anon, authenticated, service_role;
