grant execute on function rpc_archive_customer(uuid,boolean) to service_role;

-- parity: rpc_assign_machine_station(text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_assign_machine_station(p_machine_id text, p_batch_no text, p_operator_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_machine    public.machines%rowtype;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_operator'
  ]);

  -- Atomic update with concurrency guard: only succeed if machine is IDLE/ACTIVE and not occupied
  update public.machines
     set current_batch = btrim(p_batch_no),
         status        = 'BUSY',
         updated_at    = now()
   where id::text = btrim(p_machine_id)
     and organization_id = v_caller_org
     and status in ('ACTIVE', 'IDLE')
     and (current_batch is null or btrim(current_batch) = '')
  returning * into v_machine;

  if not found then
    -- Check if machine exists under this tenant
    select * into v_machine from public.machines where id::text = btrim(p_machine_id);
    if not found then
      raise exception 'Machine station (%) not found', p_machine_id;
    end if;
    if v_machine.organization_id is distinct from v_caller_org then
      raise exception 'Cross-tenant violation: Machine station does not belong to your organization' using errcode = '42501';
    end if;
    raise exception 'Machine station "%" is already occupied by batch "%" or is in status "%"',
      v_machine.name, coalesce(v_machine.current_batch, 'None'), v_machine.status;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'machine_id', v_machine.id::text,
    'machine_name', v_machine.name,
    'current_batch', v_machine.current_batch,
    'machine_status', v_machine.status,
    'assigned_operator', btrim(coalesce(p_operator_name, public.current_employee_name())),
    'organization_id', v_caller_org
  );
end;
$function$;
revoke all on function rpc_assign_machine_station(text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_assign_machine_station(text,text,text) to authenticated;
grant execute on function rpc_assign_machine_station(text,text,text) to service_role;

-- parity: rpc_calculate_piecework_salary(text,text,text,text,text,integer,numeric,integer,numeric,text)
CREATE OR REPLACE FUNCTION public.rpc_calculate_piecework_salary(p_handover_id text DEFAULT NULL::text, p_worker_id text DEFAULT NULL::text, p_worker_name text DEFAULT NULL::text, p_batch_no text DEFAULT NULL::text, p_stage_name text DEFAULT NULL::text, p_stage_order integer DEFAULT NULL::integer, p_weight_done numeric DEFAULT 0, p_qty_done integer DEFAULT 0, p_rate numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org   uuid := public.current_organization_id();
  v_caller_role  text := public.current_employee_role_text();
  v_emp          public.employees%rowtype;
  v_rate         numeric(18, 2);
  v_amount       numeric(18, 2);
  v_weight       numeric(14, 4) := round(coalesce(p_weight_done, 0)::numeric, 4);
  v_existing     jsonb;
  v_payload      jsonb;
  v_ledger_id    uuid;
  v_worker_title text;
  v_ho           public.two_party_handovers%rowtype;
  v_existing_row public.salary_ledger%rowtype;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if p_handover_id is not null and btrim(p_handover_id) <> '' then
    select * into v_ho
      from public.two_party_handovers
     where id::text = btrim(p_handover_id)
       and organization_id = v_caller_org;

    if not found then
      raise exception 'Handover % not found in your organization', p_handover_id;
    end if;

    if v_ho.status not in ('ACCEPTED', 'SUPERVISOR_OVERRIDDEN') then
      raise exception 'Cannot award piecework salary for unapproved handover status: %', v_ho.status;
    end if;
  else
    perform public.assert_erp_permission(array[
      'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
      'supervisor', 'master', 'accountant', 'buxgalter'
    ]);
  end if;

  v_payload := jsonb_build_object(
    'handover_id', btrim(coalesce(p_handover_id, '')),
    'worker_id', btrim(coalesce(p_worker_id, '')),
    'batch_no', btrim(coalesce(p_batch_no, '')),
    'stage_name', btrim(coalesce(p_stage_name, '')),
    'weight_done', v_weight
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_calculate_piecework_salary', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if v_weight <= 0 and coalesce(p_qty_done, 0) <= 0 then
    raise exception 'Cannot calculate piecework salary with zero weight and quantity';
  end if;

  -- Resolve employee and rate
  select * into v_emp
    from public.employees
   where (id::text = btrim(coalesce(p_worker_id, ''))
          or lower(trim(name)) = lower(trim(coalesce(p_worker_name, '')))
          or lower(trim(full_name)) = lower(trim(coalesce(p_worker_name, ''))))
     and (organization_id = v_caller_org or organization_id is null)
   limit 1;

  v_worker_title := coalesce(v_emp.full_name, v_emp.name, p_worker_name, 'Xodim');

  if p_rate is not null and p_rate > 0 then
    v_rate := round(p_rate::numeric, 2);
  elsif v_emp.gram_rate is not null and v_emp.gram_rate > 0 then
    v_rate := round(v_emp.gram_rate::numeric, 2);
  elsif v_emp.rate is not null and v_emp.rate > 0 then
    v_rate := round(v_emp.rate::numeric, 2);
  else
    v_rate := 15000.00;
  end if;

  v_amount := round((v_weight * v_rate)::numeric, 2);
  if v_amount <= 0 then
    v_amount := 1.00;
  end if;

  -- Idempotently check if an EARNED entry already exists for this handover
  if p_handover_id is not null and btrim(p_handover_id) != '' then
    select * into v_existing_row
      from public.salary_ledger
     where handover_id = btrim(p_handover_id)
       and organization_id = v_caller_org
       and tx_type = 'EARNED'
     limit 1;

    if found then
      v_existing := jsonb_build_object(
        'status', 'ok',
        'deduplicated', true,
        'ledger_id', v_existing_row.id::text,
        'amount', v_existing_row.amount,
        'worker_name', v_worker_title,
        'rate', v_rate,
        'weight_done', v_weight,
        'organization_id', v_caller_org
      );
      return v_existing;
    end if;
  end if;

  -- Check if already earned by employee + batch + stage in this organization
  select * into v_existing_row
    from public.salary_ledger
   where organization_id = v_caller_org
     and (employee_id::text = coalesce(v_emp.id::text, p_worker_id)
          or lower(trim(worker_name)) = lower(trim(v_worker_title)))
     and upper(trim(batch_no)) = upper(trim(coalesce(p_batch_no, 'BATCH')))
     and lower(trim(stage_name)) = lower(trim(coalesce(p_stage_name, 'Manufacturing')))
     and tx_type = 'EARNED'
   limit 1;

  if found then
    v_existing := jsonb_build_object(
      'status', 'ok',
      'deduplicated', true,
      'ledger_id', v_existing_row.id::text,
      'amount', v_existing_row.amount,
      'worker_name', v_worker_title,
      'rate', v_rate,
      'weight_done', v_weight,
      'organization_id', v_caller_org
    );
    return v_existing;
  end if;

  insert into public.salary_ledger (
    employee_id, worker_name, batch_no, stage_name, tx_type,
    weight_done, rate, amount, payment_status, note,
    handover_id, stage_order, idempotency_key, organization_id
  ) values (
    coalesce(v_emp.id::text, p_worker_id),
    v_worker_title,
    btrim(coalesce(p_batch_no, 'BATCH')),
    btrim(coalesce(p_stage_name, 'Manufacturing')),
    'EARNED',
    v_weight,
    v_rate,
    v_amount,
    'UNPAID',
    format('Piecework earned: %sg @ %s UZS/g (Handover %s)', v_weight, v_rate, coalesce(p_handover_id, 'direct')),
    nullif(btrim(p_handover_id), ''),
    p_stage_order,
    nullif(btrim(p_idempotency_key), ''),
    v_caller_org
  ) returning id into v_ledger_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'deduplicated', false,
    'ledger_id', v_ledger_id::text,
    'amount', v_amount,
    'worker_name', v_worker_title,
    'rate', v_rate,
    'weight_done', v_weight,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_calculate_piecework_salary', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_calculate_piecework_salary(text,text,text,text,text,integer,numeric,integer,numeric,text) from public, anon, authenticated, service_role;
grant execute on function rpc_calculate_piecework_salary(text,text,text,text,text,integer,numeric,integer,numeric,text) to authenticated;
grant execute on function rpc_calculate_piecework_salary(text,text,text,text,text,integer,numeric,integer,numeric,text) to service_role;

-- parity: rpc_complete_qc_rework(text,text,text,integer,integer,integer,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_complete_qc_rework(p_qc_id text DEFAULT NULL::text, p_batch_id text DEFAULT NULL::text, p_batch_no text DEFAULT NULL::text, p_rework_stage_order integer DEFAULT NULL::integer, p_inspect_stage_order integer DEFAULT 20, p_completed_qty integer DEFAULT 0, p_master_name text DEFAULT ''::text, p_resolution_notes text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_role      text := public.current_employee_role_text();
  v_effective_bno    text := btrim(coalesce(p_batch_no, ''));
  v_effective_bid    text := btrim(coalesce(p_batch_id, ''));
  v_rw_st            integer := coalesce(p_rework_stage_order, 8);
  v_insp_st          integer := coalesce(p_inspect_stage_order, 20);
  v_qty              integer := coalesce(p_completed_qty, 0);
  v_rw_wip           public.batch_stage_wip%rowtype;
  v_insp_wip         public.batch_stage_wip%rowtype;
  v_qc               public.quality_control%rowtype;
  v_existing         jsonb;
  v_payload          jsonb;
  v_resolved_by      text;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'supervisor', 'master', 'bosh usta', 'usta', 'quality_inspector', 'qc', 'otk'
  ]);

  if v_qty <= 0 then
    raise exception 'Completed rework quantity must be greater than zero (received %)', v_qty;
  end if;

  v_payload := jsonb_build_object(
    'qc_id', btrim(coalesce(p_qc_id, '')),
    'batch_no', v_effective_bno,
    'completed_qty', v_qty,
    'rework_stage_order', v_rw_st,
    'inspect_stage_order', v_insp_st
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_complete_qc_rework', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  v_resolved_by := coalesce(nullif(btrim(p_master_name), ''), public.current_employee_name());

  -- 1. Identify and lock QC record
  if p_qc_id is not null and btrim(p_qc_id) <> '' then
    select * into v_qc
      from public.quality_control
     where id::text = btrim(p_qc_id)
       and organization_id = v_caller_org
     for update;
    if not found then
      raise exception 'QC record % not found in your organization', p_qc_id;
    end if;
  else
    select * into v_qc
      from public.quality_control
     where (batch_id = v_effective_bid or batch_no = v_effective_bno)
       and organization_id = v_caller_org
       and status = 'IN_REWORK'
     order by created_at desc
     limit 1
     for update;
    if not found then
      raise exception 'No active rework QC record found for batch %', coalesce(v_effective_bno, v_effective_bid);
    end if;
  end if;

  if v_qc.id is not null and v_qc.status not in ('IN_REWORK', 'REWORK_IN_PROGRESS') then
    raise exception 'QC record % is in status %, not in rework status', v_qc.id, v_qc.status;
  end if;

  if v_effective_bno = '' and v_qc.batch_no is not null then
    v_effective_bno := v_qc.batch_no;
  end if;
  if v_effective_bid = '' and v_qc.batch_id is not null then
    v_effective_bid := v_qc.batch_id;
  end if;

  -- 2. Lock rework WIP stage and transfer back to inspection WIP stage
  select * into v_rw_wip
    from public.batch_stage_wip
   where (batch_id = v_effective_bid or batch_no = v_effective_bno)
     and stage_order = v_rw_st
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'Rework WIP record for stage % and batch % not found', v_rw_st, v_effective_bno;
  end if;

  if coalesce(v_rw_wip.available_qty, 0) < v_qty then
    raise exception 'Insufficient available pieces at rework stage % (available=%, requested=%)',
      v_rw_st, coalesce(v_rw_wip.available_qty, 0), v_qty;
  end if;

  -- Deduct from rework stage
  update public.batch_stage_wip
     set available_qty = available_qty - v_qty,
         completed_qty = coalesce(completed_qty, 0) + v_qty,
         updated_at    = now()
   where id = v_rw_wip.id;

  -- Return to inspection stage (clear rework_qty, restore available_qty)
  select * into v_insp_wip
    from public.batch_stage_wip
   where (batch_id = v_effective_bid or batch_no = v_effective_bno)
     and stage_order = v_insp_st
     and organization_id = v_caller_org
   for update;

  if found then
    update public.batch_stage_wip
       set available_qty = coalesce(available_qty, 0) + v_qty,
           rework_qty    = greatest(0, coalesce(rework_qty, 0) - v_qty),
           updated_at    = now()
     where id = v_insp_wip.id;
  else
    insert into public.batch_stage_wip (
      organization_id, batch_id, batch_no, stage_order, stage_name, department,
      available_qty, completed_qty, rework_qty, queue_status
    ) values (
      v_caller_org, v_effective_bid, v_effective_bno, v_insp_st, 'QC / Yakuniy nazorat', 'QC',
      v_qty, 0, 0, 'NOW'
    );
  end if;

  -- 3. Update QC record status
  if v_qc.id is not null then
    update public.quality_control
       set status           = 'REWORK_COMPLETED',
           resolved_at      = now(),
           resolved_by      = v_resolved_by,
           resolution_notes = coalesce(nullif(btrim(p_resolution_notes), ''), 'Rework successfully completed by master and returned for re-inspection'),
           updated_at       = now()
     where id = v_qc.id;
  end if;

  -- 4. Record audit trail
  insert into public.audit_logs (
    table_name, record_id, action, actor_id, actor_name, actor_role,
    reason, new_data, organization_id
  ) values (
    'quality_control',
    coalesce(v_qc.id::text, v_effective_bno),
    'QC_REWORK_COMPLETED',
    auth.uid(),
    v_resolved_by,
    v_caller_role,
    coalesce(nullif(btrim(p_resolution_notes), ''), 'QC rework completed'),
    jsonb_build_object(
      'batch_no', v_effective_bno,
      'completed_qty', v_qty,
      'from_rework_stage', v_rw_st,
      'to_inspect_stage', v_insp_st,
      'master_name', v_resolved_by
    ),
    v_caller_org
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'qcId', coalesce(v_qc.id::text, null),
    'batchNo', v_effective_bno,
    'completedReworkQty', v_qty,
    'reworkStage', v_rw_st,
    'returnedStage', v_insp_st,
    'resolvedBy', v_resolved_by
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_complete_qc_rework', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_complete_qc_rework(text,text,text,integer,integer,integer,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_complete_qc_rework(text,text,text,integer,integer,integer,text,text,text) to authenticated;
grant execute on function rpc_complete_qc_rework(text,text,text,integer,integer,integer,text,text,text) to service_role;

-- parity: rpc_confirm_accounting_baseline(text,text,numeric)
CREATE OR REPLACE FUNCTION public.rpc_confirm_accounting_baseline(p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_usd_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id                 uuid := public.current_organization_id();
  v_caller_emp_id          uuid := public.current_employee_id();
  v_today                  date := (timezone('Asia/Tashkent', now()))::date;
  v_rate_585               numeric(18, 2);
  v_rate_usd               numeric(18, 2);
  v_mgr_finished_g         numeric(14, 4);
  v_mgr_scrap_585_eq_g     numeric(14, 4);
  v_mgr_refined_g          numeric(14, 4);
  v_mgr_capital_pure_g     numeric(14, 4);
  v_mgr_purchased_g        numeric(14, 4);
  v_mgr_cash_uzs           numeric(18, 2);
  v_mgr_cash_usd           numeric(18, 2);
  v_seller_finished_g      numeric(14, 4);
  v_seller_scrap_585_eq_g  numeric(14, 4);
  v_seller_cash_uzs        numeric(18, 2);
  v_seller_cash_usd        numeric(18, 2);
  v_refining_wip_g         numeric(14, 4);
  v_cash_uzs_total         numeric(18, 2);
  v_cash_usd_total         numeric(18, 2);
  v_cash_uzs_585_eq_g      numeric(14, 4);
  v_cash_usd_585_eq_g      numeric(14, 4);
  v_customer_debts_g       numeric(14, 4);
  v_customer_advances_g    numeric(14, 4);
  v_factory_rcp_g          numeric(14, 4);
  v_factory_hnd_g          numeric(14, 4);
  v_net_factory_g          numeric(14, 4);
  v_factory_obligation_g   numeric(14, 4);
  v_factory_advance_g      numeric(14, 4);
  v_total_assets_g         numeric(14, 4);
  v_total_liabilities_g    numeric(14, 4);
  v_net_assets_g           numeric(14, 4);
  v_baseline_no            text;
  v_baseline_id            uuid;
  v_snapshot               jsonb;
  v_payload                jsonb;
  v_existing               jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  if v_caller_emp_id is null then
    select id into v_caller_emp_id from public.employees where user_id = auth.uid() and organization_id = v_org_id limit 1;
  end if;

  select rate_per_gram into v_rate_585
    from public.daily_gold_rates
   where organization_id = v_org_id
     and proba = 585
     and rate_date = v_today
     and is_confirmed = true
   order by created_at desc
   limit 1;

  if v_rate_585 is null or v_rate_585 <= 0 then
    raise exception 'ERR_DAILY_RATE_NOT_SET: Boshlang''ich hisobni tasdiqlash uchun bugungi (% sanadagi) tasdiqlangan 585 oltin kursi kiritilishi shart', v_today
      using errcode = '22023';
  end if;

  v_payload := jsonb_build_object('action', 'confirm_accounting_baseline', 'org_id', v_org_id);
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_confirm_accounting_baseline', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  perform public._get_or_create_manager_vault(v_org_id);
  select coalesce(sum(available_physical_g), 0) into v_mgr_finished_g
  from public.factory_receipts
  where organization_id = v_org_id and status <> 'reversed';

  select coalesce(manager_scrap_585_eq_g, manager_scrap_grams, 0),
         coalesce(manager_refined_gold_grams, 0),
         coalesce(manager_capital_pure_gold_g, 0),
         coalesce(manager_purchased_gold_grams, 0),
         coalesce(manager_cash_amount, 0),
         coalesce(manager_usd_amount, 0)
    into v_mgr_scrap_585_eq_g, v_mgr_refined_g, v_mgr_capital_pure_g, v_mgr_purchased_g, v_mgr_cash_uzs, v_mgr_cash_usd
    from public.manager_vault_account
   where organization_id = v_org_id;

  select coalesce(sum(coalesce(input_585_equiv_grams, input_scrap_grams * (coalesce(input_scrap_proba, 585.0) / 585.0))), 0)
    into v_refining_wip_g
    from public.refining_batches
   where organization_id = v_org_id and status in ('pending', 'in_progress');

  select coalesce(sum(public.get_seller_available_stock_grams(seller_id)), 0),
         coalesce(sum(coalesce(seller_till_scrap_585_eq_g, seller_till_scrap_grams, 0)), 0),
         coalesce(sum(seller_till_cash_amount), 0),
         coalesce(sum(coalesce(seller_till_usd_amount, 0)), 0)
    into v_seller_finished_g, v_seller_scrap_585_eq_g, v_seller_cash_uzs, v_seller_cash_usd
    from public.seller_gold_accounts
   where organization_id = v_org_id;

  v_cash_uzs_total := round(v_mgr_cash_uzs + v_seller_cash_uzs, 2);
  v_cash_usd_total := round(v_mgr_cash_usd + v_seller_cash_usd, 2);

  if v_cash_usd_total > 0 then
    if p_usd_rate is not null and p_usd_rate > 0 then
      v_rate_usd := round(p_usd_rate::numeric, 2);
    else
      raise exception 'ERR_USD_RATE_NOT_SET: Kassalarda dollar (USD) mavjud, boshlang''ich hisob uchun tasdiqlangan USD kursi kiritilishi shart'
        using errcode = '22023';
    end if;
  else
    v_rate_usd := coalesce(p_usd_rate, 1.0);
  end if;

  select coalesce(sum(current_debt_grams), 0),
         coalesce(sum(advance_balance_grams), 0)
    into v_customer_debts_g, v_customer_advances_g
    from public.client_gold_accounts
   where organization_id = v_org_id;

  v_cash_uzs_585_eq_g := round((v_cash_uzs_total / v_rate_585)::numeric, 4);
  if v_cash_usd_total > 0 and v_rate_usd > 0 then
    v_cash_usd_585_eq_g := round(((v_cash_usd_total * v_rate_usd) / v_rate_585)::numeric, 4);
  else
    v_cash_usd_585_eq_g := 0;
  end if;

  -- Factory net balance: receipts vs handovers
  select coalesce(sum(factory_obligation_g), 0) into v_factory_rcp_g
  from public.factory_receipts
  where organization_id = v_org_id and status <> 'reversed';

  select coalesce(sum(agreed_equivalent_g), 0) into v_factory_hnd_g
  from public.factory_gold_handovers
  where organization_id = v_org_id and status <> 'reversed';

  v_net_factory_g := v_factory_rcp_g - v_factory_hnd_g;
  if v_net_factory_g >= 0 then
    v_factory_obligation_g := round(v_net_factory_g, 4);
    v_factory_advance_g := 0;
  else
    v_factory_obligation_g := 0;
    v_factory_advance_g := round(abs(v_net_factory_g), 4);
  end if;

  -- Total Assets includes factory advance gold as enterprise asset!
  v_total_assets_g := round(
    v_mgr_finished_g + v_seller_finished_g +
    v_mgr_scrap_585_eq_g + v_seller_scrap_585_eq_g +
    v_mgr_refined_g + v_mgr_capital_pure_g + v_mgr_purchased_g +
    v_refining_wip_g +
    v_customer_debts_g +
    v_cash_uzs_585_eq_g + v_cash_usd_585_eq_g +
    v_factory_advance_g,
    4
  );

  v_total_liabilities_g := round(v_factory_obligation_g + v_customer_advances_g, 4);
  v_net_assets_g := round(v_total_assets_g - v_total_liabilities_g, 4);

  update public.accounting_baselines
     set status = 'archived'
   where organization_id = v_org_id and status = 'active';

  v_baseline_no := 'BASE-' || to_char(v_today, 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  v_snapshot := jsonb_build_object(
    'gold_rate_585', v_rate_585,
    'usd_rate', v_rate_usd,
    'rate_date', v_today,
    'manager_finished_g', v_mgr_finished_g,
    'seller_finished_g', v_seller_finished_g,
    'manager_scrap_585_eq_g', v_mgr_scrap_585_eq_g,
    'seller_scrap_585_eq_g', v_seller_scrap_585_eq_g,
    'manager_refined_gold_g', v_mgr_refined_g,
    'manager_capital_pure_gold_g', v_mgr_capital_pure_g,
    'manager_purchased_gold_g', v_mgr_purchased_g,
    'refining_wip_585_g', v_refining_wip_g,
    'customer_debts_585_g', v_customer_debts_g,
    'customer_advances_585_g', v_customer_advances_g,
    'cash_uzs_total', v_cash_uzs_total,
    'cash_uzs_585_eq_g', v_cash_uzs_585_eq_g,
    'cash_usd_total', v_cash_usd_total,
    'cash_usd_585_eq_g', v_cash_usd_585_eq_g,
    'factory_obligation_585_g', v_factory_obligation_g,
    'factory_advance_585_g', v_factory_advance_g,
    'total_assets_585_g', v_total_assets_g,
    'total_liabilities_585_g', v_total_liabilities_g,
    'net_assets_585_g', v_net_assets_g
  );

  insert into public.accounting_baselines (
    organization_id, baseline_no, baseline_date, confirmed_by, status, notes,
    gold_rate_585, usd_rate,
    manager_finished_g, seller_finished_g,
    manager_scrap_585_eq_g, seller_scrap_585_eq_g,
    manager_refined_gold_g, manager_purchased_gold_g,
    customer_debts_585_g, cash_uzs_amount, cash_uzs_585_eq_g,
    cash_usd_amount, cash_usd_585_eq_g,
    total_assets_585_g, factory_obligation_585_g, factory_advance_585_g,
    customer_advances_585_g, total_liabilities_585_g,
    net_assets_585_g, components_snapshot
  ) values (
    v_org_id, v_baseline_no, now(), v_caller_emp_id, 'active', p_notes,
    v_rate_585, v_rate_usd,
    v_mgr_finished_g, v_seller_finished_g,
    v_mgr_scrap_585_eq_g, v_seller_scrap_585_eq_g,
    v_mgr_refined_g, v_mgr_purchased_g,
    v_customer_debts_g, v_cash_uzs_total, v_cash_uzs_585_eq_g,
    v_cash_usd_total, v_cash_usd_585_eq_g,
    v_total_assets_g, v_factory_obligation_g, v_factory_advance_g,
    v_customer_advances_g, v_total_liabilities_g,
    v_net_assets_g, v_snapshot
  ) returning id into v_baseline_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'baseline_id', v_baseline_id,
    'baseline_no', v_baseline_no,
    'baseline_date', v_today,
    'gold_rate_585', v_rate_585,
    'usd_rate', v_rate_usd,
    'total_assets_585_g', v_total_assets_g,
    'factory_obligation_585_g', v_factory_obligation_g,
    'factory_advance_585_g', v_factory_advance_g,
    'total_liabilities_585_g', v_total_liabilities_g,
    'net_assets_585_g', v_net_assets_g,
    'snapshot', v_snapshot
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_confirm_accounting_baseline', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_confirm_accounting_baseline(text,text,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_confirm_accounting_baseline(text,text,numeric) to authenticated;
grant execute on function rpc_confirm_accounting_baseline(text,text,numeric) to service_role;

-- parity: rpc_create_batch_with_gold_issue(text,text,text,text,numeric,integer,numeric,numeric,text,date,text)
CREATE OR REPLACE FUNCTION public.rpc_create_batch_with_gold_issue(p_source_item_id text, p_batch_no text, p_product_name text, p_master_name text, p_proba numeric, p_planned_qty integer, p_issued_gold_gram numeric, p_pure_gold numeric, p_priority text DEFAULT 'Normal'::text, p_deadline date DEFAULT NULL::date, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_src        public.inventory_items%rowtype;
  v_batch_id   text;
  v_issued     numeric(14, 4) := round(coalesce(p_issued_gold_gram, 0)::numeric, 4);
  v_fine       numeric(18, 6);
  v_existing   jsonb;
  v_payload    jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  v_payload := jsonb_build_object(
    'source_item_id', btrim(coalesce(p_source_item_id, '')),
    'batch_no', btrim(coalesce(p_batch_no, '')),
    'planned_qty', p_planned_qty,
    'issued_gold_gram', v_issued
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_create_batch_with_gold_issue', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_source_item_id), '') = '' or coalesce(btrim(p_batch_no), '') = '' or p_planned_qty <= 0 or v_issued <= 0 then
    raise exception 'Invalid batch parameters';
  end if;

  select * into v_src
    from public.inventory_items
   where id::text = btrim(p_source_item_id)
     for update;

  if not found then
    raise exception 'Source gold item not found';
  end if;

  -- Cross-tenant verification
  if v_src.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Source inventory does not belong to your organization' using errcode = '42501';
  end if;

  if (coalesce(v_src.on_hand, v_src.quantity_on_hand, 0) - coalesce(v_src.reserved, 0)) < v_issued then
    raise exception 'Insufficient available gold in SAFE: available=%g, required=%g',
      (coalesce(v_src.on_hand, v_src.quantity_on_hand, 0) - coalesce(v_src.reserved, 0)), v_issued;
  end if;

  update public.inventory_items
     set on_hand = coalesce(on_hand, quantity_on_hand, 0) - v_issued,
         quantity_on_hand = coalesce(on_hand, quantity_on_hand, 0) - v_issued
   where id = v_src.id;

  v_fine := public.calc_fine_gold_exact(v_issued, p_proba);

  insert into public.batches (
    batch_number, batch_no, number, product_name, product, master_name,
    proba, planned_qty, planned_gram, issued_gold_gram, wip_gram,
    good_output_gram, sprue_gram, scrap_gram, rework_gram, loss_gram,
    finished_qty, credited_finished_qty, current_step, status, status_label,
    priority, priority_label, deadline, due_date, organization_id
  ) values (
    btrim(p_batch_no), btrim(p_batch_no), btrim(p_batch_no), btrim(p_product_name), btrim(p_product_name), btrim(p_master_name),
    p_proba, p_planned_qty, v_issued, v_issued, v_issued,
    0, 0, 0, 0, 0,
    0, 0, '8. Quyish', 'Jarayonda', 'Jarayonda',
    p_priority, p_priority, p_deadline, p_deadline, v_caller_org
  ) returning id::text into v_batch_id;

  insert into public.batch_stage_wip (
    batch_id, batch_no, stage_order, stage_name, department,
    available_qty, completed_qty, rework_qty, input_weight, output_weight, loss_weight,
    queue_status, assigned_worker, organization_id
  ) values (
    v_batch_id, btrim(p_batch_no), 8, '8. Quyish', 'Quyish',
    p_planned_qty, 0, 0, v_issued, 0, 0,
    'NOW', btrim(p_master_name), v_caller_org
  );

  insert into public.gold_transactions (
    transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, batch_no, description,
    idempotency_key, performed_by, organization_id
  ) values (
    'chiqim', 'SAFE', 'CASTING', v_src.name,
    v_issued, v_issued, p_proba, v_fine, btrim(p_batch_no),
    format('Batch %s issue: %s pcs / %sg (%s)', btrim(p_batch_no), p_planned_qty, v_issued, p_proba),
    nullif(btrim(p_idempotency_key), ''), public.current_employee_id(), v_caller_org
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'batch_id', v_batch_id,
    'batch_no', btrim(p_batch_no),
    'issued_gold_gram', v_issued,
    'pure_gold', v_fine,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_create_batch_with_gold_issue', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_create_batch_with_gold_issue(text,text,text,text,numeric,integer,numeric,numeric,text,date,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_batch_with_gold_issue(text,text,text,text,numeric,integer,numeric,numeric,text,date,text) to authenticated;
grant execute on function rpc_create_batch_with_gold_issue(text,text,text,text,numeric,integer,numeric,numeric,text,date,text) to service_role;

-- parity: rpc_create_customer_with_code(text,text,text,uuid,text)
CREATE OR REPLACE FUNCTION public.rpc_create_customer_with_code(p_contact_name text, p_phone text DEFAULT NULL::text, p_company_name text DEFAULT NULL::text, p_seller_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org   uuid := public.current_organization_id();
  v_clean_name   text := nullif(btrim(p_contact_name), '');
  v_next_seq     integer;
  v_cust_code    text;
  v_cust_id      uuid;
  v_seller_id    uuid := p_seller_id;
  v_existing_id  uuid;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_clean_name is null then
    raise exception 'Mijoz ismi kiritilishi shart';
  end if;

  -- Default seller to caller employee if not supplied
  if v_seller_id is null then
    select id into v_seller_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_caller_org
    limit 1;
  end if;

  -- Duplicate check by name and seller
  select id into v_existing_id
  from public.customers
  where organization_id = v_caller_org
    and lower(contact_name) = lower(v_clean_name)
    and (v_seller_id is null or seller_id = v_seller_id)
  limit 1;

  if v_existing_id is not null then
    return jsonb_build_object(
      'status', 'existing',
      'customer_id', v_existing_id,
      'message', 'Ushbu nomdagi mijoz allaqachon mavjud'
    );
  end if;

  -- Generate sequential customer code (look across entire table to respect unique constraint)
  select coalesce(max(nullif(regexp_replace(customer_code, '\D', '', 'g'), '')::integer), 0) + 1
  into v_next_seq
  from public.customers;

  v_cust_code := 'CUST-' || lpad(v_next_seq::text, 4, '0');

  -- Loop to guarantee zero unique constraint collision
  while exists (select 1 from public.customers where customer_code = v_cust_code) loop
    v_next_seq := v_next_seq + 1;
    v_cust_code := 'CUST-' || lpad(v_next_seq::text, 4, '0');
  end loop;

  insert into public.customers (
    organization_id, customer_code, contact_name, phone, company_name, seller_id, notes
  ) values (
    v_caller_org, v_cust_code, v_clean_name, p_phone, p_company_name, v_seller_id, p_notes
  ) returning id into v_cust_id;

  return jsonb_build_object(
    'status', 'ok',
    'customer_id', v_cust_id,
    'customer_code', v_cust_code,
    'contact_name', v_clean_name,
    'phone', p_phone,
    'seller_id', v_seller_id
  );
end;
$function$;
revoke all on function rpc_create_customer_with_code(text,text,text,uuid,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_customer_with_code(text,text,text,uuid,text) to authenticated;
grant execute on function rpc_create_customer_with_code(text,text,text,uuid,text) to service_role;

-- parity: rpc_create_jewelry_model(text,text,text,numeric,text,text,uuid,text)
CREATE OR REPLACE FUNCTION public.rpc_create_jewelry_model(p_name text, p_category text DEFAULT 'Серьги'::text, p_decorations text DEFAULT NULL::text, p_reference_weight_grams numeric DEFAULT NULL::numeric, p_purity text DEFAULT '585'::text, p_model_code text DEFAULT NULL::text, p_organization_id uuid DEFAULT NULL::uuid, p_primary_image_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid;
  v_model_code text := trim(p_model_code);
  v_next_num integer;
  v_new_model record;
  v_purity_val integer;
  v_purity_text text;
  v_img_url text := nullif(trim(p_primary_image_url), '');
begin
  -- Validation: name is required
  if p_name is null or trim(p_name) = '' then
    raise exception 'Model nomi kiritilishi shart!';
  end if;

  -- Organization assignment
  v_org_id := coalesce(p_organization_id, public.current_organization_id());
  if v_org_id is null then
    select id into v_org_id from public.organizations order by created_at asc limit 1;
  end if;

  -- Advisory lock to prevent concurrent duplicate model codes
  perform pg_advisory_xact_lock(hashtext('jewelry_models_sequence_lock'));

  -- Clean and parse purity
  v_purity_text := trim(coalesce(p_purity, '585'));
  begin
    v_purity_val := nullif(regexp_replace(v_purity_text, '[^0-9]', '', 'g'), '')::integer;
  exception when others then
    v_purity_val := 585;
  end;
  if v_purity_val is null or v_purity_val <= 0 then
    v_purity_val := 585;
  end if;

  -- Generate or normalize sequential model_code (e.g. JF-M-0001, JF-M-0002)
  if v_model_code is null or v_model_code = '' or v_model_code ~* '^JF-M-0*$' then
    select coalesce(max(substring(model_code from 'JF-M-([0-9]+)')::integer), 0) + 1
      into v_next_num
      from public.jewelry_models
     where model_code ~ '^JF-M-[0-9]+';

    v_model_code := 'JF-M-' || lpad(v_next_num::text, 4, '0');
  else
    -- If custom code provided, check for duplicate collision
    if exists (select 1 from public.jewelry_models where upper(model_code) = upper(v_model_code)) then
      select coalesce(max(substring(model_code from 'JF-M-([0-9]+)')::integer), 0) + 1
        into v_next_num
        from public.jewelry_models
       where model_code ~ '^JF-M-[0-9]+';

      v_model_code := 'JF-M-' || lpad(v_next_num::text, 4, '0');
    end if;
  end if;

  -- Insert atomic record
  insert into public.jewelry_models (
    organization_id,
    model_code,
    name,
    category,
    decorations,
    reference_weight_grams,
    gold_purity,
    proba,
    primary_image_url,
    is_active
  )
  values (
    v_org_id,
    upper(v_model_code),
    trim(p_name),
    trim(coalesce(p_category, 'Серьги')),
    nullif(trim(p_decorations), ''),
    case when p_reference_weight_grams is not null and p_reference_weight_grams > 0
         then p_reference_weight_grams else null end,
    v_purity_val::text,
    v_purity_val,
    v_img_url,
    true
  )
  returning * into v_new_model;

  -- Record audit log
  if to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs (
      organization_id,
      table_name,
      record_id,
      action,
      new_data,
      reason,
      created_at
    ) values (
      v_org_id,
      'jewelry_models',
      v_new_model.id::text,
      'create_model',
      jsonb_build_object(
        'model_code', v_new_model.model_code,
        'name', v_new_model.name,
        'category', v_new_model.category,
        'purity', v_purity_val,
        'weight', v_new_model.reference_weight_grams,
        'primary_image_url', v_new_model.primary_image_url
      ),
      'Created new permanent jewelry model with photo support',
      now()
    );
  end if;

  return to_jsonb(v_new_model);
end;
$function$;
revoke all on function rpc_create_jewelry_model(text,text,text,numeric,text,text,uuid,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_jewelry_model(text,text,text,numeric,text,text,uuid,text) to authenticated;
grant execute on function rpc_create_jewelry_model(text,text,text,numeric,text,text,uuid,text) to service_role;

-- parity: rpc_create_jewelry_sale(uuid,numeric,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_create_jewelry_sale(p_customer_id uuid, p_weight_grams numeric, p_markup_pct numeric DEFAULT 15.0, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_caller_emp_id uuid := public.current_employee_id();
  v_seller        public.employees%rowtype;
  v_customer      public.customers%rowtype;
  v_seller_acc    public.seller_gold_accounts%rowtype;
  v_consign       public.seller_consignments%rowtype;
  v_piece         public.consignment_pieces%rowtype;
  v_weight        numeric(14, 4);
  v_markup        numeric(6, 2);
  v_client_due    numeric(14, 4);
  v_sale_id       uuid;
  v_sale_no       text;
  v_existing      jsonb;
  v_avail_adv     numeric(14, 4) := 0;
  v_apply_adv     numeric(14, 4) := 0;
  v_net_rem_due   numeric(14, 4) := 0;
  v_rem_to_deduct numeric(14, 4) := 0;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select * into v_seller
    from public.employees
   where (id = v_caller_emp_id or user_id = auth.uid())
     and organization_id = v_caller_org
   limit 1;

  if not found then
    raise exception 'Sotuvchi xodim topilmadi';
  end if;

  v_weight := round(greatest(0, coalesce(p_weight_grams, 0))::numeric, 4);
  v_markup := round(coalesce(p_markup_pct, 15.0)::numeric, 2);

  if v_weight <= 0.0001 then
    raise exception 'Sotuv vazni 0 dan katta bo''lishi shart';
  end if;

  if v_markup < 0 then
    raise exception 'Ustama foizi manfiy bo''lishi mumkin emas';
  end if;

  select * into v_customer
    from public.customers
   where id = p_customer_id and organization_id = v_caller_org;

  if not found then
    raise exception 'Mijoz topilmadi: %', p_customer_id;
  end if;

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'sale_id', id,
      'sale_no', sale_no,
      'weight_grams', base_weight_grams,
      'client_due_grams', client_gold_due_grams
    ) into v_existing
    from public.jewelry_sales
    where idempotency_key = p_idempotency_key and organization_id = v_caller_org;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  -- Lock seller gold account & check available physical stock
  select * into v_seller_acc
    from public.seller_gold_accounts
   where seller_id = v_seller.id and organization_id = v_caller_org
   for update;

  if coalesce(v_seller_acc.current_physical_stock_g, 0) < v_weight then
    raise exception 'Sotuvchi omborida yetarli mahsulot yo''q (Mavjud: % g, Talab: % g)',
      coalesce(v_seller_acc.current_physical_stock_g, 0), v_weight;
  end if;

  -- Calculate client due grams
  v_client_due := round((v_weight * (1.0 + (v_markup / 100.0)))::numeric, 4);

  -- Check customer advance balance
  select coalesce(advance_balance_grams, 0) into v_avail_adv
    from public.client_gold_accounts
   where customer_id = v_customer.id and organization_id = v_caller_org;

  if v_avail_adv > 0 then
    v_apply_adv   := round(least(v_avail_adv, v_client_due)::numeric, 4);
    v_net_rem_due := round((v_client_due - v_apply_adv)::numeric, 4);
  else
    v_apply_adv   := 0;
    v_net_rem_due := v_client_due;
  end if;

  -- FIFO: Link sale to seller's active consignment
  select * into v_consign
    from public.seller_consignments
   where seller_id = v_seller.id and organization_id = v_caller_org
     and status in ('held_by_seller', 'partially_sold')
   order by created_at asc
   limit 1
   for update;

  v_sale_no := 'SALE-W-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.jewelry_sales (
    organization_id, sale_no, seller_id, customer_id, consignment_id,
    product_name, quantity, base_weight_grams, proba,
    factory_markup_pct, factory_gold_due_grams,
    client_markup_pct, client_gold_due_grams,
    markup_spread_grams, settled_gold_grams, remaining_gold_grams,
    status, sale_date, idempotency_key, notes, sale_type
  ) values (
    v_caller_org, v_sale_no, v_seller.id, v_customer.id, v_consign.id,
    'Standart 585 Oltin (Vazn bo''yicha)', 1, v_weight, 585.00,
    0.00, v_weight,
    v_markup, v_client_due,
    round((v_client_due - v_weight)::numeric, 4), v_apply_adv, v_net_rem_due,
    case when v_net_rem_due <= 0.0001 then 'fully_paid' else 'open_debt' end,
    public._goldia_business_date(), nullif(btrim(p_idempotency_key), ''), p_notes, 'weight'
  ) returning id into v_sale_id;

  -- If a consignment was linked, update sold info and loop over pieces
  if v_consign.id is not null then
    update public.seller_consignments
       set status = 'partially_sold',
           sold_quantity = coalesce(sold_quantity, 0) + 1,
           updated_at = now()
     where id = v_consign.id;

    -- Multi-piece decrement loop to keep pieces synchronized with gram sales
    v_rem_to_deduct := v_weight;
    for v_piece in
      select * from public.consignment_pieces
       where consignment_id = v_consign.id and status = 'held_by_seller'
       order by created_at asc
       for update
    loop
      exit when v_rem_to_deduct <= 0.0001;
      if v_piece.weight_grams <= v_rem_to_deduct + 0.0001 then
        v_rem_to_deduct := round((v_rem_to_deduct - v_piece.weight_grams)::numeric, 4);
        update public.consignment_pieces
           set status = 'sold',
               sale_id = v_sale_id,
               sold_at = now(),
               updated_at = now()
         where id = v_piece.id;
      else
        update public.consignment_pieces
           set weight_grams = round((v_piece.weight_grams - v_rem_to_deduct)::numeric, 4),
               updated_at = now()
         where id = v_piece.id;
        v_rem_to_deduct := 0;
      end if;
    end loop;
  end if;

  -- Update client_gold_accounts atomically
  insert into public.client_gold_accounts (
    customer_id, organization_id, seller_id, total_purchased_gold_grams,
    current_debt_grams, advance_balance_grams, total_settled_grams, updated_at
  ) values (
    v_customer.id, v_caller_org, v_seller.id, v_client_due,
    v_net_rem_due, round(greatest(0, v_avail_adv - v_apply_adv)::numeric, 4), v_apply_adv, now()
  )
  on conflict (customer_id) do update
  set total_purchased_gold_grams = round((public.client_gold_accounts.total_purchased_gold_grams + v_client_due)::numeric, 4),
      current_debt_grams = round((public.client_gold_accounts.current_debt_grams + v_net_rem_due)::numeric, 4),
      advance_balance_grams = round(greatest(0, public.client_gold_accounts.advance_balance_grams - v_apply_adv)::numeric, 4),
      total_settled_grams = round((public.client_gold_accounts.total_settled_grams + v_apply_adv)::numeric, 4),
      updated_at = now();

  -- Atomically deduct physical stock from seller_gold_accounts
  update public.seller_gold_accounts
     set current_physical_stock_g = round(greatest(0, current_physical_stock_g - v_weight)::numeric, 4),
         updated_at = now()
   where seller_id = v_seller.id and organization_id = v_caller_org;

  -- Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) values (
    v_caller_org, 'jewelry_sales', v_sale_id::text,
    'CREATE_JEWELRY_SALE', auth.uid(),
    null,
    jsonb_build_object(
      'sale_no', v_sale_no,
      'seller_id', v_seller.id,
      'customer_id', v_customer.id,
      'weight_grams', v_weight,
      'markup_pct', v_markup,
      'client_due_grams', v_client_due,
      'applied_advance_grams', v_apply_adv,
      'net_debt_grams', v_net_rem_due
    ),
    p_notes
  );

  return jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale_id,
    'sale_no', v_sale_no,
    'weight_grams', v_weight,
    'markup_pct', v_markup,
    'client_due_grams', v_client_due,
    'applied_advance_grams', v_apply_adv,
    'remaining_debt_grams', v_net_rem_due,
    'customer_name', coalesce(v_customer.full_name, v_customer.name)
  );
end;
$function$;
revoke all on function rpc_create_jewelry_sale(uuid,numeric,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_jewelry_sale(uuid,numeric,numeric,text,text) to authenticated;
grant execute on function rpc_create_jewelry_sale(uuid,numeric,numeric,text,text) to service_role;

-- parity: rpc_create_order_with_advance(text,text,text,text,text,numeric,integer,numeric,numeric,numeric,date,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_create_order_with_advance(p_order_no text, p_client_name text, p_phone text DEFAULT ''::text, p_product_model text DEFAULT ''::text, p_details text DEFAULT ''::text, p_proba numeric DEFAULT 585, p_qty integer DEFAULT 1, p_weight_gram numeric DEFAULT 0, p_total_price numeric DEFAULT 0, p_advance numeric DEFAULT 0, p_deadline date DEFAULT NULL::date, p_priority text DEFAULT 'Normal'::text, p_payment_type text DEFAULT 'Avans (Naqd)'::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org   uuid := public.current_organization_id();
  v_order_no     text := btrim(coalesce(p_order_no, ''));
  v_client       text := btrim(coalesce(p_client_name, ''));
  v_model        text := btrim(coalesce(p_product_model, ''));
  v_qty          integer := coalesce(p_qty, 0);
  v_weight       numeric(14, 4) := round(coalesce(p_weight_gram, 0)::numeric, 4);
  v_total        numeric(18, 2) := round(coalesce(p_total_price, 0)::numeric, 2);
  v_adv          numeric(18, 2) := round(coalesce(p_advance, 0)::numeric, 2);
  v_debt         numeric(18, 2);
  v_order_id     text;
  v_sale_id      text := null;
  v_existing     jsonb;
  v_payload      jsonb;
  v_priority_val public.order_priority;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'sales', 'accountant', 'buxgalter', 'hisobchi'
  ]);

  v_payload := jsonb_build_object(
    'order_no', v_order_no,
    'client_name', lower(v_client),
    'product_model', lower(v_model),
    'qty', v_qty,
    'weight_gram', v_weight,
    'total_price', v_total,
    'advance', v_adv
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_create_order_with_advance', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if v_order_no = '' or v_client = '' or v_model = '' then
    raise exception 'Order number, client name, and product model are required';
  end if;

  if v_qty <= 0 or v_weight <= 0 then
    raise exception 'Order quantity (%) and weight (%g) must be greater than 0', v_qty, v_weight;
  end if;

  if v_total < 0 or v_adv < 0 then
    raise exception 'Order total price (%s) and advance (%s) cannot be negative', v_total, v_adv;
  end if;

  if v_adv > v_total then
    raise exception 'Order advance (%s) cannot exceed total price (%s)', v_adv, v_total;
  end if;

  v_debt := round(v_total - v_adv, 2);

  -- Safe enum conversion
  case lower(btrim(coalesce(p_priority, 'normal')))
    when 'low' then v_priority_val := 'low'::public.order_priority;
    when 'high' then v_priority_val := 'high'::public.order_priority;
    when 'urgent' then v_priority_val := 'urgent'::public.order_priority;
    else v_priority_val := 'normal'::public.order_priority;
  end case;

  insert into public.orders (
    organization_id, order_no, order_number, client_name, customer_name, phone,
    product_model, details, proba, qty, weight_gram,
    total_price, advance, paid_amount, debt_amount,
    deadline, priority, priority_label, status, status_label, batch_created
  ) values (
    v_caller_org, v_order_no, v_order_no, v_client, v_client, btrim(coalesce(p_phone, '')),
    v_model, btrim(coalesce(p_details, '')), coalesce(p_proba, 585), v_qty, v_weight,
    v_total, v_adv, v_adv, v_debt,
    p_deadline, v_priority_val, coalesce(nullif(btrim(p_priority), ''), 'Normal'),
    'Kutilmoqda', 'Kutilmoqda', false
  ) returning id::text into v_order_id;

  if v_adv > 0 then
    insert into public.sales (
      organization_id, order_id, client_name, product_name, quantity, weight, proba,
      payment_type, sale_total_amount, total_amount, debt_amount, tx_type, idempotency_key
    ) values (
      v_caller_org,
      v_order_id,
      v_client,
      format('Buyurtma Avansi (%s - %s)', v_order_no, v_model),
      v_qty,
      v_weight,
      coalesce(p_proba, 585),
      coalesce(nullif(btrim(p_payment_type), ''), 'Avans (Naqd)'),
      v_total,
      v_adv,
      v_debt,
      'kirim',
      nullif(btrim(p_idempotency_key), '')
    ) returning id::text into v_sale_id;
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'order_id', v_order_id,
    'order_no', v_order_no,
    'advance_sale_id', v_sale_id,
    'total_price', v_total,
    'advance', v_adv,
    'debt_amount', v_debt,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_create_order_with_advance', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_create_order_with_advance(text,text,text,text,text,numeric,integer,numeric,numeric,numeric,date,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_order_with_advance(text,text,text,text,text,numeric,integer,numeric,numeric,numeric,date,text,text,text) to authenticated;
grant execute on function rpc_create_order_with_advance(text,text,text,text,text,numeric,integer,numeric,numeric,numeric,date,text,text,text) to service_role;

-- parity: rpc_create_product_with_bom(text,text,numeric,integer,numeric,numeric,numeric,numeric,numeric,numeric,text,text,jsonb,text)
CREATE OR REPLACE FUNCTION public.rpc_create_product_with_bom(p_name text, p_category text DEFAULT 'Komplekt'::text, p_proba numeric DEFAULT 585, p_bom_version integer DEFAULT 1, p_ring_weight numeric DEFAULT 0, p_earring_weight numeric DEFAULT 0, p_chain_weight numeric DEFAULT 0, p_dorika_weight numeric DEFAULT 0, p_stone_weight numeric DEFAULT 0, p_weight numeric DEFAULT NULL::numeric, p_bom_details text DEFAULT NULL::text, p_image_url text DEFAULT NULL::text, p_bom_items jsonb DEFAULT NULL::jsonb, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_ring_w     numeric(14, 4) := round(greatest(0, coalesce(p_ring_weight, 0))::numeric, 4);
  v_ear_w      numeric(14, 4) := round(greatest(0, coalesce(p_earring_weight, 0))::numeric, 4);
  v_chain_w    numeric(14, 4) := round(greatest(0, coalesce(p_chain_weight, 0))::numeric, 4);
  v_dorika_w   numeric(14, 4) := round(greatest(0, coalesce(p_dorika_weight, 0))::numeric, 4);
  v_stone_w    numeric(14, 4) := round(greatest(0, coalesce(p_stone_weight, 0))::numeric, 4);
  v_tot_w      numeric(14, 4);
  v_summary    text;
  v_prod_id    text;
  v_prod_uuid  uuid;
  v_bom_elem   jsonb;
  v_existing   jsonb;
  v_payload    jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'warehouse', 'omborchi',
    'inventory_manager', 'manager', 'production_manager', 'production manager'
  ]);

  v_tot_w := round(
    coalesce(nullif(p_weight, 0), v_ring_w + v_ear_w + v_chain_w + v_dorika_w + v_stone_w)::numeric,
    4
  );

  v_payload := jsonb_build_object(
    'name', lower(btrim(coalesce(p_name, ''))),
    'category', btrim(coalesce(p_category, 'Komplekt')),
    'proba', coalesce(p_proba, 585),
    'total_weight', v_tot_w
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_create_product_with_bom', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_name), '') = '' or v_tot_w <= 0 or v_stone_w >= v_tot_w then
    raise exception 'Invalid product model or BOM weights (total=%g, stone=%g)', v_tot_w, v_stone_w;
  end if;

  v_summary := coalesce(
    nullif(btrim(p_bom_details), ''),
    format('v%s: Uzuk(%sg) + Zirak(%sg) + Zanjir(%sg) + Dorika(%sg) + Tosh(%sg)',
      coalesce(p_bom_version, 1), v_ring_w, v_ear_w, v_chain_w, v_dorika_w, v_stone_w)
  );

  insert into public.products (
    organization_id, name, title, category, weight, proba, stock, quantity,
    stone_weight, bom_version, bom_details, image_url
  ) values (
    v_caller_org, btrim(p_name), btrim(p_name), coalesce(nullif(btrim(p_category), ''), 'Komplekt'),
    v_tot_w, coalesce(p_proba, 585), 0, 0,
    v_stone_w, coalesce(p_bom_version, 1), v_summary,
    coalesce(p_image_url, 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?auto=format&fit=crop&w=600&q=80')
  ) returning id::text into v_prod_id;

  v_prod_uuid := public.try_cast_uuid(v_prod_id);

  if p_bom_items is not null and jsonb_typeof(p_bom_items) = 'array' and jsonb_array_length(p_bom_items) > 0 then
    for v_bom_elem in select * from jsonb_array_elements(p_bom_items)
    loop
      insert into public.bom_items (
        product_id, component_name, component_type, quantity, unit_weight, total_weight, proba, notes
      ) values (
        v_prod_uuid,
        coalesce(v_bom_elem->>'component_name', 'Qism'),
        coalesce(v_bom_elem->>'component_type', 'gold'),
        coalesce((v_bom_elem->>'quantity')::integer, 1),
        coalesce((v_bom_elem->>'unit_weight')::numeric, 0),
        coalesce((v_bom_elem->>'total_weight')::numeric, 0),
        coalesce((v_bom_elem->>'proba')::numeric, coalesce(p_proba, 585)),
        v_bom_elem->>'notes'
      );
    end loop;
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'product_id', v_prod_id,
    'name', btrim(p_name),
    'category', coalesce(p_category, 'Komplekt'),
    'total_weight', v_tot_w,
    'proba', coalesce(p_proba, 585),
    'bom_version', coalesce(p_bom_version, 1),
    'summary', v_summary,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_create_product_with_bom', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_create_product_with_bom(text,text,numeric,integer,numeric,numeric,numeric,numeric,numeric,numeric,text,text,jsonb,text) from public, anon, authenticated, service_role;
grant execute on function rpc_create_product_with_bom(text,text,numeric,integer,numeric,numeric,numeric,numeric,numeric,numeric,text,text,jsonb,text) to authenticated;
grant execute on function rpc_create_product_with_bom(text,text,numeric,integer,numeric,numeric,numeric,numeric,numeric,numeric,text,text,jsonb,text) to service_role;

-- parity: rpc_diagnose_piece_inventory_conflicts()
CREATE OR REPLACE FUNCTION public.rpc_diagnose_piece_inventory_conflicts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_anomalies  jsonb := '[]'::jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(d), '[]'::jsonb)
  into v_anomalies
  from (
    select
      cp.id as piece_id,
      cp.model_code,
      cp.model_name,
      cp.weight_grams,
      cp.status as piece_status,
      cp.sale_id,
      sc.id as consignment_id,
      sc.consignment_no,
      sc.status as consignment_status,
      case
        when sc.status = 'fully_sold' and cp.status = 'held_by_seller' then 'consignment_fully_sold_but_piece_marked_held'
        when cp.status = 'held_by_seller' and cp.sale_id is not null then 'piece_marked_held_with_active_sale_id'
        when cp.status = 'sold' and cp.sale_id is null then 'piece_marked_sold_without_sale_id'
        when sc.sold_quantity > sc.quantity then 'consignment_sold_quantity_overflow'
        else 'other_anomaly'
      end as conflict_type
    from public.consignment_pieces cp
    join public.seller_consignments sc on sc.id = cp.consignment_id
    where cp.organization_id = v_caller_org
      and (
        (sc.status = 'fully_sold' and cp.status = 'held_by_seller')
        or (cp.status = 'held_by_seller' and cp.sale_id is not null)
        or (cp.status = 'sold' and cp.sale_id is null)
        or (sc.sold_quantity > sc.quantity)
      )
  ) d;

  return jsonb_build_object(
    'organization_id', v_caller_org,
    'conflict_count', jsonb_array_length(v_anomalies),
    'conflicts', v_anomalies,
    'audit_timestamp', now()
  );
end;
$function$;
revoke all on function rpc_diagnose_piece_inventory_conflicts() from public, anon, authenticated, service_role;
grant execute on function rpc_diagnose_piece_inventory_conflicts() to authenticated;
grant execute on function rpc_diagnose_piece_inventory_conflicts() to service_role;

-- parity: rpc_dispatch_stage_handover(text,text,integer,text,text,integer,text,text,text,text,integer,numeric,text,text,numeric,text,text,boolean,text,text)
CREATE OR REPLACE FUNCTION public.rpc_dispatch_stage_handover(p_batch_id text, p_batch_no text, p_from_stage_order integer, p_from_stage_name text, p_from_department text, p_to_stage_order integer, p_to_stage_name text, p_to_department text, p_sender_worker_id text, p_sender_worker_name text, p_dispatched_qty integer, p_dispatched_weight_gram numeric, p_receiver_worker_id text DEFAULT NULL::text, p_receiver_worker_name text DEFAULT NULL::text, p_tolerance_gram numeric DEFAULT 0.05, p_idempotency_key text DEFAULT NULL::text, p_measurement_mode text DEFAULT 'MANUAL_ENTRY'::text, p_is_scale_stable boolean DEFAULT true, p_scale_model text DEFAULT NULL::text, p_scale_raw_reading text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_batch         public.batches%rowtype;
  v_handover_id   text;
  v_tol           numeric(6, 4) := round(coalesce(p_tolerance_gram, 0.05)::numeric, 4);
  v_weight        numeric(14, 4) := round(coalesce(p_dispatched_weight_gram, 0)::numeric, 4);
  v_existing      jsonb;
  v_payload       jsonb;
  v_open_ho       public.two_party_handovers%rowtype;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  if coalesce(p_dispatched_qty, 0) <= 0 then
    raise exception 'Dispatched quantity must be greater than 0';
  end if;
  if v_weight <= 0 then
    raise exception 'Dispatched weight must be greater than 0';
  end if;
  if p_from_stage_order = p_to_stage_order then
    raise exception 'Cannot dispatch handover to the same stage';
  end if;

  -- Verify batch ownership
  select * into v_batch
    from public.batches
   where (id::text = btrim(p_batch_id) or batch_no = btrim(p_batch_no))
   limit 1;

  if found and v_batch.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Batch does not belong to your organization' using errcode = '42501';
  end if;

  -- Duplicate Handover Prevention: Check if an open pending handover already exists for this stage transition
  select * into v_open_ho
    from public.two_party_handovers
   where organization_id = v_caller_org
     and batch_no = btrim(p_batch_no)
     and from_stage_order = p_from_stage_order
     and to_stage_order = p_to_stage_order
     and status = 'PENDING_ACCEPTANCE'
   limit 1;

  if v_open_ho.id is not null then
    raise exception 'Ushbu bosqich bo''yicha qabul qilinishi kutilayotgan handover (%s) allaqachon mavjud! Avval uni qabul qiling yoki bekor qiling.', v_open_ho.id;
  end if;

  v_payload := jsonb_build_object(
    'batch_id', p_batch_id,
    'batch_no', p_batch_no,
    'from_stage_order', p_from_stage_order,
    'to_stage_order', p_to_stage_order,
    'dispatched_qty', p_dispatched_qty,
    'dispatched_weight_gram', v_weight
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_dispatch_stage_handover', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  v_handover_id := 'HO-' || to_char(clock_timestamp(), 'YYYYMMDD-HH24MISS') || '-' || substr(md5(random()::text), 1, 6);

  insert into public.two_party_handovers (
    id, organization_id, batch_id, batch_no,
    from_stage_order, from_stage_name, from_department,
    to_stage_order, to_stage_name, to_department,
    sender_worker_id, sender_worker_name,
    receiver_worker_id, receiver_worker_name,
    dispatched_qty, dispatched_weight_gram,
    status, tolerance_gram, dispatched_at,
    measurement_mode, is_scale_stable, scale_model, scale_raw_reading
  ) values (
    v_handover_id, v_caller_org, btrim(p_batch_id), btrim(p_batch_no),
    p_from_stage_order, btrim(p_from_stage_name), btrim(p_from_department),
    p_to_stage_order, btrim(p_to_stage_name), btrim(p_to_department),
    btrim(p_sender_worker_id), btrim(p_sender_worker_name),
    nullif(btrim(p_receiver_worker_id), ''), nullif(btrim(p_receiver_worker_name), ''),
    p_dispatched_qty, v_weight,
    'PENDING_ACCEPTANCE', v_tol, clock_timestamp(),
    coalesce(nullif(btrim(p_measurement_mode), ''), 'MANUAL_ENTRY'),
    coalesce(p_is_scale_stable, true),
    nullif(btrim(p_scale_model), ''),
    nullif(btrim(p_scale_raw_reading), '')
  );

  v_existing := jsonb_build_object(
    'success', true,
    'status', 'PENDING_ACCEPTANCE',
    'handover_id', v_handover_id,
    'batch_no', btrim(p_batch_no),
    'dispatched_qty', p_dispatched_qty,
    'dispatched_weight_gram', v_weight,
    'measurement_mode', coalesce(nullif(btrim(p_measurement_mode), ''), 'MANUAL_ENTRY')
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_dispatch_stage_handover', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_dispatch_stage_handover(text,text,integer,text,text,integer,text,text,text,text,integer,numeric,text,text,numeric,text,text,boolean,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_dispatch_stage_handover(text,text,integer,text,text,integer,text,text,text,text,integer,numeric,text,text,numeric,text,text,boolean,text,text) to authenticated;
grant execute on function rpc_dispatch_stage_handover(text,text,integer,text,text,integer,text,text,text,text,integer,numeric,text,text,numeric,text,text,boolean,text,text) to service_role;

-- parity: rpc_execute_affinaj_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_affinaj_transaction(p_scrap_item_id text, p_target_gold_item_id text, p_scrap_weight numeric, p_estimated_proba numeric, p_output_weight numeric, p_output_proba numeric DEFAULT 999, p_expected_fine numeric DEFAULT 0, p_actual_fine numeric DEFAULT 0, p_refining_loss numeric DEFAULT 0, p_master_name text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org  uuid := public.current_organization_id();
  v_scrap     public.inventory_items%rowtype;
  v_target    public.inventory_items%rowtype;
  v_sc_w      numeric(14, 4) := round(coalesce(p_scrap_weight, 0)::numeric, 4);
  v_out_w     numeric(14, 4) := round(coalesce(p_output_weight, 0)::numeric, 4);
  v_exp_fine  numeric(18, 6);
  v_act_fine  numeric(18, 6);
  v_loss_fine numeric(18, 6);
  v_existing  jsonb;
  v_payload   jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'warehouse', 'omborchi',
    'inventory_manager', 'manager', 'production_manager', 'production manager'
  ]);

  v_payload := jsonb_build_object(
    'scrap_item_id', btrim(coalesce(p_scrap_item_id, '')),
    'target_gold_item_id', btrim(coalesce(p_target_gold_item_id, '')),
    'scrap_weight', v_sc_w,
    'output_weight', v_out_w,
    'estimated_proba', p_estimated_proba
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_execute_affinaj_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_scrap_item_id), '') = '' or coalesce(btrim(p_target_gold_item_id), '') = '' then
    raise exception 'Scrap and target gold inventory item IDs are required';
  end if;

  if v_sc_w <= 0 or v_out_w <= 0 or p_estimated_proba <= 0 then
    raise exception 'Invalid refining parameters: scrap=%g, output=%g, proba=%g', v_sc_w, v_out_w, p_estimated_proba;
  end if;

  select * into v_scrap from public.inventory_items where id::text = btrim(p_scrap_item_id) for update;
  if not found then
    raise exception 'Scrap inventory item not found';
  end if;

  if v_scrap.organization_id is not null and v_scrap.organization_id <> v_caller_org then
    raise exception 'Cross-tenant violation: Scrap item does not belong to your organization' using errcode = '42501';
  end if;

  if (coalesce(v_scrap.on_hand, v_scrap.quantity_on_hand, 0) - coalesce(v_scrap.reserved, 0)) < v_sc_w then
    raise exception 'Insufficient scrap available: available=%g, required=%g',
      (coalesce(v_scrap.on_hand, v_scrap.quantity_on_hand, 0) - coalesce(v_scrap.reserved, 0)), v_sc_w;
  end if;

  select * into v_target from public.inventory_items where id::text = btrim(p_target_gold_item_id) for update;
  if not found then
    raise exception 'Target 999 gold inventory item not found';
  end if;

  if v_target.organization_id is not null and v_target.organization_id <> v_caller_org then
    raise exception 'Cross-tenant violation: Target item does not belong to your organization' using errcode = '42501';
  end if;

  v_exp_fine  := public.calc_fine_gold_exact(v_sc_w, p_estimated_proba);
  v_act_fine  := public.calc_fine_gold_exact(v_out_w, coalesce(nullif(p_output_proba, 0), 999));
  v_loss_fine := round(greatest(0, v_exp_fine - v_act_fine)::numeric, 6);

  -- Deduct scrap inventory
  update public.inventory_items
     set on_hand = on_hand - v_sc_w,
         quantity_on_hand = quantity_on_hand - v_sc_w
   where id = v_scrap.id;

  -- Add refined 999 gold to inventory
  update public.inventory_items
     set on_hand = coalesce(on_hand, 0) + v_out_w,
         quantity_on_hand = coalesce(quantity_on_hand, 0) + v_out_w
   where id = v_target.id;

  insert into public.affinaj_records (
    organization_id, scrap_batch_no, scrap_weight, estimated_purity,
    output_weight, actual_purity, expected_pure_gold, actual_pure_gold,
    loss_weight, refiner_name, notes, status, idempotency_key
  ) values (
    v_caller_org,
    v_scrap.name,
    v_sc_w,
    p_estimated_proba,
    v_out_w,
    coalesce(nullif(p_output_proba, 0), 999),
    v_exp_fine,
    v_act_fine,
    v_loss_fine,
    coalesce(nullif(btrim(p_master_name), ''), public.current_employee_name()),
    format('Affinaj %sg (%s) -> %sg (999)', v_sc_w, p_estimated_proba, v_out_w),
    'COMPLETED',
    nullif(btrim(p_idempotency_key), '')
  );

  insert into public.gold_transactions (
    organization_id, transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, description, idempotency_key, performed_by
  ) values (
    v_caller_org,
    'affinaj',
    v_scrap.name,
    v_target.name,
    'Fine Gold 999',
    v_out_w,
    v_out_w,
    coalesce(nullif(p_output_proba, 0), 999),
    v_act_fine,
    format('Refining output: %sg fine gold from %sg scrap', v_out_w, v_sc_w),
    nullif(btrim(p_idempotency_key), ''),
    public.current_employee_id()
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'scrap_item_id', v_scrap.id::text,
    'target_gold_item_id', v_target.id::text,
    'scrap_weight', v_sc_w,
    'output_weight', v_out_w,
    'expected_fine', v_exp_fine,
    'actual_fine', v_act_fine,
    'refining_loss', v_loss_fine
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_execute_affinaj_transaction', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_execute_affinaj_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_affinaj_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text) to authenticated;
grant execute on function rpc_execute_affinaj_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text) to service_role;

-- parity: rpc_execute_alloy_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text,numeric,text,numeric,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_alloy_transaction(p_source_item_id text, p_target_item_id text, p_input_weight numeric, p_source_proba numeric, p_target_proba numeric, p_ligature_weight numeric DEFAULT 0, p_fine_gold_added numeric DEFAULT 0, p_output_weight numeric DEFAULT 0, p_pure_gold numeric DEFAULT 0, p_fine_gold_item_id text DEFAULT NULL::text, p_silver_item_id text DEFAULT NULL::text, p_silver_weight numeric DEFAULT 0, p_copper_item_id text DEFAULT NULL::text, p_copper_weight numeric DEFAULT 0, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org  uuid := public.current_organization_id();
  v_src         public.inventory_items%rowtype;
  v_tar         public.inventory_items%rowtype;
  v_fine_item   public.inventory_items%rowtype;
  v_silver_item public.inventory_items%rowtype;
  v_copper_item public.inventory_items%rowtype;
  v_in_w        numeric(14, 4) := round(coalesce(p_input_weight, 0)::numeric, 4);
  v_lig_w       numeric(14, 4) := round(coalesce(p_ligature_weight, 0)::numeric, 4);
  v_fine_add_w  numeric(14, 4) := round(coalesce(p_fine_gold_added, 0)::numeric, 4);
  v_out_w       numeric(14, 4) := round(coalesce(p_output_weight, 0)::numeric, 4);
  v_silver_w    numeric(14, 4) := round(coalesce(p_silver_weight, 0)::numeric, 4);
  v_copper_w    numeric(14, 4) := round(coalesce(p_copper_weight, 0)::numeric, 4);
  v_pure_gold   numeric(18, 6);
  v_existing    jsonb;
  v_payload     jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'warehouse', 'omborchi',
    'inventory_manager', 'manager', 'production_manager', 'production manager'
  ]);

  v_payload := jsonb_build_object(
    'source_item_id', btrim(coalesce(p_source_item_id, '')),
    'target_item_id', btrim(coalesce(p_target_item_id, '')),
    'input_weight', v_in_w,
    'source_proba', p_source_proba,
    'target_proba', p_target_proba,
    'output_weight', v_out_w
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_execute_alloy_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_source_item_id), '') = '' or coalesce(btrim(p_target_item_id), '') = '' then
    raise exception 'Source and target inventory item IDs are required';
  end if;

  if v_in_w <= 0 or p_source_proba <= 0 or p_target_proba <= 0 or p_source_proba = p_target_proba then
    raise exception 'Invalid alloy parameters';
  end if;

  if btrim(p_source_item_id) = btrim(p_target_item_id) then
    raise exception 'Source and target inventory items must be distinct';
  end if;

  select * into v_src from public.inventory_items where id::text = btrim(p_source_item_id) for update;
  if not found then
    raise exception 'Source gold item not found';
  end if;

  if v_src.organization_id is not null and v_src.organization_id <> v_caller_org then
    raise exception 'Cross-tenant violation: Source item does not belong to your organization' using errcode = '42501';
  end if;

  if (coalesce(v_src.on_hand, v_src.quantity_on_hand, 0) - coalesce(v_src.reserved, 0)) < v_in_w then
    raise exception 'Insufficient available source gold: available=%g, required=%g',
      (coalesce(v_src.on_hand, v_src.quantity_on_hand, 0) - coalesce(v_src.reserved, 0)), v_in_w;
  end if;

  select * into v_tar from public.inventory_items where id::text = btrim(p_target_item_id) for update;
  if not found then
    raise exception 'Target alloy gold item not found';
  end if;

  if v_tar.organization_id is not null and v_tar.organization_id <> v_caller_org then
    raise exception 'Cross-tenant violation: Target item does not belong to your organization' using errcode = '42501';
  end if;

  -- Up-alloying: consume additional 999 fine gold item
  if p_target_proba > p_source_proba and v_fine_add_w > 0 and p_fine_gold_item_id is not null then
    select * into v_fine_item from public.inventory_items where id::text = btrim(p_fine_gold_item_id) for update;
    if found and (v_fine_item.organization_id is null or v_fine_item.organization_id = v_caller_org) then
      if (coalesce(v_fine_item.on_hand, 0) - coalesce(v_fine_item.reserved, 0)) < v_fine_add_w then
        raise exception 'Insufficient 999 fine gold for up-alloying';
      end if;
      update public.inventory_items
         set on_hand = on_hand - v_fine_add_w,
             quantity_on_hand = quantity_on_hand - v_fine_add_w
       where id = v_fine_item.id;
    end if;
  end if;

  -- Deduct source gold
  update public.inventory_items
     set on_hand = on_hand - v_in_w,
         quantity_on_hand = quantity_on_hand - v_in_w
   where id = v_src.id;

  -- Add to target alloy stock
  update public.inventory_items
     set on_hand = coalesce(on_hand, 0) + v_out_w,
         quantity_on_hand = coalesce(quantity_on_hand, 0) + v_out_w
   where id = v_tar.id;

  v_pure_gold := public.calc_fine_gold_exact(v_out_w, p_target_proba);

  insert into public.gold_transactions (
    organization_id, transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, description, idempotency_key, performed_by
  ) values (
    v_caller_org,
    'alloy',
    v_src.name,
    v_tar.name,
    format('Alloy %s -> %s', p_source_proba, p_target_proba),
    v_out_w,
    v_out_w,
    p_target_proba,
    v_pure_gold,
    format('Alloy: in=%sg (%s), out=%sg (%s)', v_in_w, p_source_proba, v_out_w, p_target_proba),
    nullif(btrim(p_idempotency_key), ''),
    public.current_employee_id()
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'source_item_id', v_src.id::text,
    'target_item_id', v_tar.id::text,
    'input_weight', v_in_w,
    'output_weight', v_out_w,
    'pure_gold', v_pure_gold,
    'target_proba', p_target_proba
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_execute_alloy_transaction', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_execute_alloy_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text,numeric,text,numeric,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_alloy_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text,numeric,text,numeric,text) to authenticated;
grant execute on function rpc_execute_alloy_transaction(text,text,numeric,numeric,numeric,numeric,numeric,numeric,numeric,text,text,numeric,text,numeric,text) to service_role;

-- parity: rpc_execute_full_test_reset(text,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_full_test_reset(p_confirmation_code text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_caller_emp_id uuid := public.current_employee_id();
  v_reason        text := nullif(btrim(p_reason), '');
  v_rev_ts        timestamptz := now();
  v_rev_note      text;
  v_base_archived int := 0;
  v_sale_rev      int := 0;
  v_settle_rev    int := 0;
  v_piece_rev     int := 0;
  v_consign_rev   int := 0;
  v_rcp_rev       int := 0;
  v_hnd_rev       int := 0;
  v_ref_rev       int := 0;
  v_fintx_rev     int := 0;
  v_purch_rev     int := 0;
  v_leg_rev       int := 0;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  if v_caller_emp_id is null then
    select id into v_caller_emp_id from public.employees where user_id = auth.uid() and organization_id = v_caller_org limit 1;
  end if;

  if p_confirmation_code is null or btrim(p_confirmation_code) <> 'RESET_TEST_ACCOUNT_2026' then
    raise exception 'Tasdiqlash kodi noto''g''ri. Talab qilinadi: RESET_TEST_ACCOUNT_2026';
  end if;

  if v_reason is null then
    raise exception 'Test hisobini tozalash sababi (audit uchun) kiritilishi shart';
  end if;

  v_rev_note := 'TEST HISOBI TOZALANDI: ' || v_reason || ' (' || to_char(v_rev_ts, 'YYYY-MM-DD HH24:MI') || ')';

  -- A. Reverse sales
  update public.jewelry_sales
     set status = 'reversed',
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']',
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');
  get diagnostics v_sale_rev = row_count;

  -- B. Reverse customer settlements and manager surrenders
  update public.gold_settlements
     set status = 'reversed',
         reversed_at = v_rev_ts,
         reversed_by = v_caller_emp_id,
         reversal_reason = v_reason,
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']'
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');
  get diagnostics v_settle_rev = row_count;

  -- C. Reset client gold accounts
  update public.client_gold_accounts
     set current_debt_grams = 0,
         advance_balance_grams = 0,
         total_settled_grams = 0,
         total_purchased_gold_grams = 0,
         total_scrap_paid_grams = 0,
         total_cash_paid_amount = 0,
         total_cash_equiv_grams = 0,
         total_usd_paid_amount = 0,
         total_usd_equiv_grams = 0,
         updated_at = v_rev_ts
   where organization_id = v_caller_org;

  -- D. Reverse legacy client debts
  update public.client_legacy_debts
     set status = 'reversed',
         reversed_at = v_rev_ts,
         reversed_by = v_caller_emp_id,
         reversal_reason = v_reason,
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status <> 'reversed';
  get diagnostics v_leg_rev = row_count;

  -- E. Mark consignment pieces CANCELLED (never returned_to_manager!)
  update public.consignment_pieces
     set status = 'cancelled',
         sale_id = null,
         sold_at = null,
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']',
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status <> 'cancelled';
  get diagnostics v_piece_rev = row_count;

  -- F. Cancel seller consignments
  update public.seller_consignments
     set status = 'cancelled',
         base_weight_grams = 0,
         seller_obligation_g = 0,
         quantity = 0,
         sold_quantity = 0,
         returned_quantity = 0,
         returned_weight_grams = 0,
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']',
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status <> 'cancelled';
  get diagnostics v_consign_rev = row_count;

  -- G. Reverse factory receipts
  update public.factory_receipts
     set status = 'reversed',
         available_physical_g = 0,
         transferred_physical_g = 0,
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']',
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status <> 'reversed';
  get diagnostics v_rcp_rev = row_count;

  -- H. Reverse factory gold handovers
  update public.factory_gold_handovers
     set status = 'reversed',
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']',
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status <> 'reversed';
  get diagnostics v_hnd_rev = row_count;

  -- I. Cancel refining batches
  update public.refining_batches
     set status = 'reversed',
         reversed_at = v_rev_ts,
         reversed_by = v_caller_emp_id,
         reversal_reason = v_reason,
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');
  get diagnostics v_ref_rev = row_count;

  -- J. Reverse financial transactions
  update public.financial_transactions
     set status = 'reversed',
         reversed_at = v_rev_ts,
         reversed_by = v_caller_emp_id,
         reversal_reason = v_reason,
         updated_at = v_rev_ts
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');
  get diagnostics v_fintx_rev = row_count;

  -- J2. Reverse gold purchases
  update public.gold_purchases
     set status = 'reversed',
         notes = coalesce(notes, '') || ' [' || v_rev_note || ']'
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');
  get diagnostics v_purch_rev = row_count;

  -- K. Reset seller gold accounts to exact zero
  update public.seller_gold_accounts
     set total_transferred_physical_g = 0,
         total_seller_obligation_g = 0,
         total_settled_to_manager_g = 0,
         seller_owes_manager_g = 0,
         manager_owes_seller_g = 0,
         bozor_qarzi_signed_g = 0,
         total_consigned_gold_grams = 0,
         current_factory_obligation_grams = 0,
         current_physical_stock_g = 0,
         seller_till_scrap_grams = 0,
         seller_till_scrap_physical_g = 0,
         seller_till_scrap_585_eq_g = 0,
         seller_till_cash_amount = 0,
         seller_till_usd_amount = 0,
         -- 073: empty the 072 valued till pool together with the till (the reset reverses handovers, whose grams
         -- would otherwise flow back into the pool and mix with the first post-reset collection).
         till_valued_cash_uzs = 0,
         till_valued_cash_585_g = 0,
         till_valued_usd = 0,
         till_valued_usd_585_g = 0,
         seller_legacy_debt_obligation_g = 0,
         updated_at = v_rev_ts
   where organization_id = v_caller_org;

  -- L. Reset manager vault to exact zero
  perform public._get_or_create_manager_vault(v_caller_org);
  update public.manager_vault_account
     set manager_physical_stock_g        = 0,
         manager_scrap_grams             = 0,
         manager_scrap_physical_g        = 0,
         manager_scrap_585_eq_g          = 0,
         manager_refined_gold_grams      = 0,
         manager_refined_gold_fine_grams = 0,
         manager_capital_pure_gold_g     = 0,
         manager_capital_pure_gold_fine_g= 0,
         manager_finished_capital_g      = 0,
         manager_purchased_gold_grams    = 0,
         manager_cash_amount             = 0,
         manager_usd_amount              = 0,
         total_factory_received_g        = 0,
         total_factory_obligation_g      = 0,
         total_factory_handed_over_g     = 0,
         current_factory_obligation_g    = 0,
         current_factory_advance_g       = 0,
         updated_at                      = v_rev_ts
   where organization_id = v_caller_org;

  -- M. Archive active baseline
  update public.accounting_baselines
     set status = 'archived',
         notes = coalesce(notes, '') || ' [TEST HISOBI TOZALASH BILAN ARXIVLANDI: ' || v_reason || ']'
   where organization_id = v_caller_org and status = 'active';
  get diagnostics v_base_archived = row_count;

  -- N. Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, new_data
  ) values (
    v_caller_org, 'accounting_baselines', 'FULL_RESET', 'FULL_TEST_ACCOUNT_RESET', auth.uid(),
    jsonb_build_object(
      'reason', v_reason,
      'baselines_archived', v_base_archived,
      'sales_reversed', v_sale_rev,
      'settlements_reversed', v_settle_rev,
      'consignments_cancelled', v_consign_rev,
      'pieces_cancelled', v_piece_rev,
      'receipts_reversed', v_rcp_rev,
      'handovers_reversed', v_hnd_rev,
      'refining_reversed', v_ref_rev,
      'fintx_reversed', v_fintx_rev,
      'purchases_reversed', v_purch_rev,
      'legacy_debts_reversed', v_leg_rev
    )
  );

  return jsonb_build_object(
    'status', 'ok',
    'message', 'Test hisobi to''liq muvaffaqiyatli tozalandi va barcha faol qoldiqlar 0 ga keltirildi!',
    'summary', jsonb_build_object(
      'baselines_archived', v_base_archived,
      'sales_reversed', v_sale_rev,
      'settlements_reversed', v_settle_rev,
      'consignments_cancelled', v_consign_rev,
      'pieces_cancelled', v_piece_rev,
      'factory_receipts_reversed', v_rcp_rev,
      'factory_handovers_reversed', v_hnd_rev,
      'refining_batches_reversed', v_ref_rev,
      'financial_transactions_reversed', v_fintx_rev,
      'gold_purchases_reversed', v_purch_rev,
      'legacy_debts_reversed', v_leg_rev,
      'active_inventory_g', 0.0,
      'active_factory_obligation_g', 0.0,
      'active_customer_debts_g', 0.0,
      'active_seller_obligation_g', 0.0,
      'active_vault_scrap_g', 0.0,
      'active_vault_cash_uzs', 0.0,
      'active_vault_usd', 0.0
    )
  );
end;
$function$;
revoke all on function rpc_execute_full_test_reset(text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_full_test_reset(text,text) to authenticated;
grant execute on function rpc_execute_full_test_reset(text,text) to service_role;

-- parity: rpc_execute_selective_test_cleanup(uuid[],text,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_selective_test_cleanup(p_receipt_ids uuid[], p_reason text DEFAULT NULL::text, p_confirmation_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_clean_reason   text := nullif(btrim(p_reason), '');
  v_r_id           uuid;
  v_rev_res        jsonb;
  v_cleaned_count  int := 0;
  v_tot_obl_g      numeric(14, 4) := 0;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi'
  ]);

  if p_confirmation_code is null or btrim(p_confirmation_code) <> 'CONFIRM_TEST_CLEANUP_2026' then
    raise exception 'Xavfsizlik tasdiqlash kodi noto''g''ri. Talab qilinadi: CONFIRM_TEST_CLEANUP_2026';
  end if;

  if v_clean_reason is null then
    raise exception 'Sinov ma''lumotlarini tozalash sababi (audit uchun) kiritilishi shart';
  end if;

  if p_receipt_ids is null or array_length(p_receipt_ids, 1) = 0 then
    raise exception 'Tozalanadigan sinov partiyalari tanlanmagan';
  end if;

  foreach v_r_id in array p_receipt_ids loop
    v_rev_res := public.rpc_reverse_factory_receipt(v_r_id, v_clean_reason, null);
    v_cleaned_count := v_cleaned_count + 1;
    v_tot_obl_g := v_tot_obl_g + coalesce((v_rev_res->>'deducted_obligation_grams')::numeric, 0);
  end loop;

  return jsonb_build_object(
    'status', 'ok',
    'cleaned_receipts_count', v_cleaned_count,
    'total_deducted_obligation_g', v_tot_obl_g,
    'reason', v_clean_reason,
    'message', format('%s ta sinov partiyasi muvaffaqiyatli tozalandi (bekor qilindi).', v_cleaned_count)
  );
end;
$function$;
revoke all on function rpc_execute_selective_test_cleanup(uuid[],text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_selective_test_cleanup(uuid[],text,text) to authenticated;
grant execute on function rpc_execute_selective_test_cleanup(uuid[],text,text) to service_role;

-- parity: rpc_execute_sheets_historical_import(text,text,jsonb,boolean,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_sheets_historical_import(p_sheet_type text, p_batch_no text, p_rows jsonb, p_is_opening_balance boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid;
  v_caller_emp_id uuid;
  v_row jsonb;
  v_total_rows integer := 0;
  v_valid_rows integer := 0;
  v_skipped_rows integer := 0;
  v_total_weight numeric(18, 4) := 0;
  v_total_cash numeric(18, 2) := 0;
  v_receipt_no text;
  v_purchase_no text;
  v_batch_no text;
  v_weight numeric(18, 4);
  v_proba numeric(18, 4);
  v_markup numeric(18, 4);
  v_oblig numeric(18, 4);
  v_cash numeric(18, 2);
  v_rate numeric(18, 2);
  v_seller_id uuid;
  v_seller_name text;
  v_prod_name text;
begin
  select id into v_org_id from public.organizations limit 1;
  select id into v_caller_emp_id from public.employees where user_id = auth.uid() limit 1;

  if jsonb_array_length(p_rows) = 0 then
    raise exception 'Import qilish uchun qatorlar mavjud emas!';
  end if;

  v_total_rows := jsonb_array_length(p_rows);

  -- Process based on sheet type
  case p_sheet_type
    when 'Zavod bilan' then
      for v_row in select * from jsonb_array_elements(p_rows) loop
        v_weight := coalesce((v_row ->> 'weight_g')::numeric, 0);
        v_proba := coalesce((v_row ->> 'proba')::numeric, 585);
        v_markup := coalesce((v_row ->> 'markup_pct')::numeric, 8.0);
        v_prod_name := coalesce(v_row ->> 'product_name', 'Zavod tovari (Import)');

        if v_weight > 0 then
          v_oblig := round(v_weight * (1 + (v_markup / 100.0)), 4);
          v_receipt_no := 'IMP-ZVD-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 6);

          insert into public.factory_receipts (
            organization_id,
            receipt_no,
            receipt_date,
            product_name,
            proba,
            quantity,
            original_physical_g,
            factory_markup_pct,
            factory_obligation_g,
            transferred_physical_g,
            available_physical_g,
            status,
            notes
          ) values (
            v_org_id,
            v_receipt_no,
            coalesce((v_row ->> 'date')::date, current_date),
            v_prod_name,
            v_proba,
            coalesce((v_row ->> 'quantity')::integer, 1),
            v_weight,
            v_markup,
            v_oblig,
            0,
            v_weight,
            'in_manager_stock',
            'Sheets import: ' || coalesce(p_notes, p_batch_no)
          );

          v_valid_rows := v_valid_rows + 1;
          v_total_weight := v_total_weight + v_weight;
        else
          v_skipped_rows := v_skipped_rows + 1;
        end if;
      end loop;

    when 'Tovar olish' then
      for v_row in select * from jsonb_array_elements(p_rows) loop
        v_weight := coalesce((v_row ->> 'weight_g')::numeric, 0);
        v_cash := coalesce((v_row ->> 'cash_uzs')::numeric, 0);
        v_rate := coalesce((v_row ->> 'rate_per_g')::numeric, 900000);
        v_proba := coalesce((v_row ->> 'proba')::numeric, 585);

        if v_weight > 0 and v_cash > 0 then
          v_purchase_no := 'IMP-BUY-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 6);

          insert into public.gold_purchases (
            organization_id,
            purchase_no,
            purchase_date,
            supplier_name,
            cash_spent_uzs,
            rate_per_gram,
            gold_weight_grams,
            proba,
            equiv_585_grams,
            notes
          ) values (
            v_org_id,
            v_purchase_no,
            coalesce((v_row ->> 'date')::date, current_date),
            coalesce(v_row ->> 'supplier', 'Bozor (Import)'),
            v_cash,
            v_rate,
            v_weight,
            v_proba,
            round(v_weight * (v_proba / 585.0), 4),
            'Sheets import: ' || coalesce(p_notes, p_batch_no)
          );

          v_valid_rows := v_valid_rows + 1;
          v_total_weight := v_total_weight + v_weight;
          v_total_cash := v_total_cash + v_cash;
        else
          v_skipped_rows := v_skipped_rows + 1;
        end if;
      end loop;

    when 'Lom pateriya' then
      for v_row in select * from jsonb_array_elements(p_rows) loop
        v_weight := coalesce((v_row ->> 'input_scrap_g')::numeric, 0);
        v_oblig := coalesce((v_row ->> 'output_fine_g')::numeric, 0);
        v_proba := coalesce((v_row ->> 'fine_proba')::numeric, 995);

        if v_weight > 0 and v_oblig > 0 then
          v_batch_no := 'IMP-REF-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 6);
          declare
            v_eq585 numeric(18, 4) := round(v_oblig * (v_proba / 585.0), 4);
            v_loss numeric(18, 4) := greatest(0, round(v_weight - v_eq585, 4));
            v_loss_p numeric(18, 3) := case when v_weight > 0 then round((v_loss / v_weight) * 100.0, 3) else 0 end;
          begin
            insert into public.refining_batches (
              organization_id,
              batch_no,
              batch_date,
              input_scrap_grams,
              melted_weight_grams,
              melt_loss_grams,
              output_fine_grams,
              output_fine_proba,
              output_585_equiv_grams,
              total_loss_grams,
              loss_pct,
              status,
              notes
            ) values (
              v_org_id,
              v_batch_no,
              coalesce((v_row ->> 'date')::date, current_date),
              v_weight,
              coalesce((v_row ->> 'melted_g')::numeric, v_weight),
              greatest(0, v_weight - coalesce((v_row ->> 'melted_g')::numeric, v_weight)),
              v_oblig,
              v_proba,
              v_eq585,
              v_loss,
              v_loss_p,
              'completed',
              'Sheets import: ' || coalesce(p_notes, p_batch_no)
            );
          end;

          v_valid_rows := v_valid_rows + 1;
          v_total_weight := v_total_weight + v_weight;
        else
          v_skipped_rows := v_skipped_rows + 1;
        end if;
      end loop;

    else -- Seller sheets: 'Sanatoni sotuv', 'Otush sotuv', 'Buxoro sotuv', etc.
      v_seller_name := split_part(p_sheet_type, ' ', 1);
      -- Find or identify seller employee
      select id into v_seller_id from public.employees
      where lower(full_name) like '%' || lower(v_seller_name) || '%'
      limit 1;

      if v_seller_id is null then
        select id into v_seller_id from public.employees
        where role in ('sales', 'seller')
        limit 1;
      end if;

      for v_row in select * from jsonb_array_elements(p_rows) loop
        v_weight := coalesce((v_row ->> 'weight_g')::numeric, 0);
        v_markup := coalesce((v_row ->> 'markup_pct')::numeric, 12.0);

        if v_weight > 0 and v_seller_id is not null then
          v_oblig := round(v_weight * (1 + (v_markup / 100.0)), 4);

          insert into public.seller_consignments (
            organization_id,
            consignment_no,
            seller_id,
            consignment_date,
            total_items_count,
            total_physical_weight_grams,
            gold_purity,
            factory_markup_pct,
            seller_markup_pct,
            remaining_gold_due_grams,
            seller_obligation_g,
            notes
          ) values (
            v_org_id,
            'IMP-CSG-' || to_char(now(), 'YYYYMMDD') || '-' || substr(gen_random_uuid()::text, 1, 6),
            v_seller_id,
            coalesce((v_row ->> 'date')::date, current_date),
            1,
            v_weight,
            585,
            8.0,
            v_markup,
            v_oblig,
            v_oblig,
            'Sheets import: ' || p_sheet_type || ' ' || coalesce(p_notes, '')
          );

          v_valid_rows := v_valid_rows + 1;
          v_total_weight := v_total_weight + v_weight;
        else
          v_skipped_rows := v_skipped_rows + 1;
        end if;
      end loop;
  end case;

  -- Record import in sheets_import_batches
  insert into public.sheets_import_batches (
    organization_id,
    batch_no,
    sheet_name,
    imported_by,
    total_rows,
    valid_rows,
    skipped_rows,
    total_weight_g,
    total_cash_amount,
    is_opening_balance,
    notes,
    raw_data_json
  ) values (
    v_org_id,
    p_batch_no,
    p_sheet_type,
    v_caller_emp_id,
    v_total_rows,
    v_valid_rows,
    v_skipped_rows,
    v_total_weight,
    v_total_cash,
    p_is_opening_balance,
    p_notes,
    p_rows
  );

  return jsonb_build_object(
    'success', true,
    'batch_no', p_batch_no,
    'sheet_name', p_sheet_type,
    'total_rows', v_total_rows,
    'valid_rows', v_valid_rows,
    'skipped_rows', v_skipped_rows,
    'total_weight_g', v_total_weight,
    'total_cash_amount', v_total_cash
  );
end;
$function$;
revoke all on function rpc_execute_sheets_historical_import(text,text,jsonb,boolean,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_sheets_historical_import(text,text,jsonb,boolean,text) to authenticated;
grant execute on function rpc_execute_sheets_historical_import(text,text,jsonb,boolean,text) to service_role;

-- parity: rpc_execute_staging_test_cleanup(text,text)
CREATE OR REPLACE FUNCTION public.rpc_execute_staging_test_cleanup(p_preview_token text, p_confirmation_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_snapshot         public.staging_backup_snapshots%rowtype;
  v_target_ids       jsonb;
  v_receipt_ids      uuid[];
  v_consign_ids      uuid[];
  v_sale_ids         uuid[];
  v_settle_ids       uuid[];
  v_three_tier       jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  -- Strict confirmation code guard
  if p_confirmation_code <> 'CONFIRM_STAGING_CLEANUP_2026' then
    raise exception 'Tasdiqlash kodi noto''g''ri. Qat''iy talab: "CONFIRM_STAGING_CLEANUP_2026"';
  end if;

  -- Validate preview token
  select * into v_snapshot
    from public.staging_backup_snapshots
   where preview_token = p_preview_token
     and organization_id = v_caller_org
     and snapshot_type = 'CLEANUP_PREVIEW'
     and created_at >= (now() - interval '30 minutes')
   order by created_at desc
   limit 1;

  if not found then
    raise exception 'Yaroqli preview_token topilmadi yoki 30 daqiqalik muddati o''tgan. Avval rpc_preview_staging_test_cleanup ni qayta bajaring.';
  end if;

  v_target_ids := v_snapshot.snapshot_data->'target_ids';

  -- Create full backup snapshot before applying non-destructive compensations
  insert into public.staging_backup_snapshots (
    organization_id, snapshot_type, preview_token, affected_tables,
    record_count, gold_impact_g, snapshot_data, created_by
  ) values (
    v_caller_org, 'PRE_CLEANUP_FULL_BACKUP', p_preview_token,
    v_snapshot.affected_tables, v_snapshot.record_count, v_snapshot.gold_impact_g,
    jsonb_build_object(
      'executed_by', v_caller_emp_id,
      'preview_data', v_snapshot.snapshot_data,
      'timestamp', now()
    ),
    v_caller_emp_id
  );

  -- Perform verified balance integrity check
  v_three_tier := public.rpc_get_three_tier_ledger_summary();

  return jsonb_build_object(
    'status', 'ok',
    'action', 'staging_cleanup_dryrun_completed',
    'preview_token', p_preview_token,
    'backup_snapshot_created', true,
    'verified_three_tier_balances', v_three_tier,
    'message', 'Staging test tozalash muvaffaqiyatli xavfsiz simulyatsiya qilindi va to''liq zaxira nusxasi yaratildi. Baza butunligi 100% saqlab qolindi.'
  );
end;
$function$;
revoke all on function rpc_execute_staging_test_cleanup(text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_execute_staging_test_cleanup(text,text) to authenticated;
grant execute on function rpc_execute_staging_test_cleanup(text,text) to service_role;

-- parity: rpc_generate_telegram_link_code(uuid)
CREATE OR REPLACE FUNCTION public.rpc_generate_telegram_link_code(p_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code text;
  v_expires timestamptz;
  v_emp record;
begin
  select id, full_name, role into v_emp
  from public.employees
  where id = p_employee_id;

  if not found then
    raise exception 'Xodim topilmadi: %', p_employee_id;
  end if;

  -- Generate 6-digit random code
  v_code := lpad(floor(random() * 900000 + 100000)::text, 6, '0');
  v_expires := now() + interval '15 minutes';

  update public.employees
  set telegram_link_code = v_code,
      telegram_link_expires_at = v_expires
  where id = p_employee_id;

  return jsonb_build_object(
    'employee_id', p_employee_id,
    'full_name', v_emp.full_name,
    'role', v_emp.role::text,
    'link_code', v_code,
    'expires_at', v_expires
  );
end;
$function$;
revoke all on function rpc_generate_telegram_link_code(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_generate_telegram_link_code(uuid) to authenticated;
grant execute on function rpc_generate_telegram_link_code(uuid) to service_role;

-- parity: rpc_get_accounting_profit_summary(date,date,numeric,numeric,uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_accounting_profit_summary(p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_gold_rate numeric DEFAULT NULL::numeric, p_usd_rate numeric DEFAULT NULL::numeric, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id                 uuid := coalesce(p_org_id, public.current_organization_id());
  v_today                  date := (timezone('Asia/Tashkent', now()))::date;
  v_gold_rate_585          numeric(18, 2);
  v_usd_rate               numeric(18, 2);
  v_rate_confirmed         boolean := false;
  v_base                   public.accounting_baselines%rowtype;
  v_mgr_stock_g            numeric(14, 4) := 0;
  v_seller_stock_g         numeric(14, 4) := 0;
  v_mgr_scrap_g            numeric(14, 4) := 0;
  v_mgr_scrap_phys_g       numeric(14, 4) := 0;
  v_seller_scrap_g         numeric(14, 4) := 0;
  v_seller_scrap_phys_g    numeric(14, 4) := 0;
  v_mgr_refined_g          numeric(14, 4) := 0;
  v_mgr_capital_pure_g     numeric(14, 4) := 0;
  v_mgr_purchased_g        numeric(14, 4) := 0;
  v_refining_wip_g         numeric(14, 4) := 0;
  v_cust_debts_g           numeric(14, 4) := 0;
  v_cust_advances_g        numeric(14, 4) := 0;
  v_mgr_cash_uzs           numeric(18, 2) := 0;
  v_seller_cash_uzs        numeric(18, 2) := 0;
  v_total_cash_uzs         numeric(18, 2) := 0;
  v_cash_585_eq_g          numeric(14, 4) := 0;
  v_mgr_usd                numeric(18, 2) := 0;
  v_seller_usd             numeric(18, 2) := 0;
  v_total_usd              numeric(18, 2) := 0;
  v_usd_585_eq_g           numeric(14, 4) := 0;
  v_factory_rcp_due_g      numeric(14, 4) := 0;
  v_factory_hnd_paid_g     numeric(14, 4) := 0;
  v_net_factory_g          numeric(14, 4) := 0;
  v_factory_debt_g         numeric(14, 4) := 0;
  v_factory_advance_g      numeric(14, 4) := 0;
  v_tot_assets_g           numeric(14, 4) := 0;
  v_tot_liabilities_g      numeric(14, 4) := 0;
  v_cur_net_assets_g       numeric(14, 4) := 0;
  v_cap_in_g               numeric(14, 4) := 0;
  v_cap_out_g              numeric(14, 4) := 0;
  v_expenses_g             numeric(14, 4) := 0;
  v_refining_loss_g        numeric(14, 4) := 0;
  v_post_base_legacy_adj   numeric(14, 4) := 0;
  v_period_accounting_res  numeric(14, 4) := null;
  v_vault_rec              public.manager_vault_account%rowtype;
  v_components             jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  -- 070: an explicit p_org_id may only name the caller's own organization (or be used by trusted
  -- server-side code without a JWT); company-wide profit data is restricted to management roles.
  if auth.uid() is not null then
    if v_org_id is distinct from public.current_organization_id() then
      raise exception 'Permission denied: boshqa tashkilot ma''lumotiga ruxsat yo''q' using errcode = '42501';
    end if;
    perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter', 'manager', 'production_manager', 'boshqaruvchi']);
  end if;

  if p_end_date is not null and p_end_date > v_today then
    return jsonb_build_object(
      'status', 'unsupported_pilot_period',
      'error', format('Pilot davrida faqat bugungi kungacha (jonli real-time) hisoblash qo''llab-quvvatlanadi. Tanlangan oxirgi sana: %s, Bugun: %s.', p_end_date, v_today),
      'is_computable', false,
      'is_complete', false,
      'accounting_method', 'realtime_pilot_locked'
    );
  end if;

  select * into v_base
    from public.accounting_baselines
   where organization_id = v_org_id
     and status = 'active'
   order by baseline_date desc, created_at desc
   limit 1;

  if p_gold_rate is not null and p_gold_rate > 0 then
    v_gold_rate_585 := round(p_gold_rate::numeric, 2);
    v_rate_confirmed := true;
  else
    select rate_per_gram, is_confirmed
      into v_gold_rate_585, v_rate_confirmed
      from public.daily_gold_rates
     where organization_id = v_org_id
       and proba = 585
       and rate_date = v_today
     order by created_at desc
     limit 1;

    if v_gold_rate_585 is null and v_base.id is not null then
      v_gold_rate_585 := v_base.gold_rate_585;
      v_rate_confirmed := true;
    end if;
  end if;

  if p_usd_rate is not null and p_usd_rate > 0 then
    v_usd_rate := round(p_usd_rate::numeric, 2);
  else
    if v_base.id is not null and v_base.usd_rate is not null and v_base.usd_rate > 0 then
      v_usd_rate := v_base.usd_rate;
    else
      v_usd_rate := 12800.0;
    end if;
  end if;

  select coalesce(sum(available_physical_g), 0) into v_mgr_stock_g
  from public.factory_receipts
  where organization_id = v_org_id and status <> 'reversed';

  select coalesce(sum(public.get_seller_available_stock_grams(seller_id)), 0)
    into v_seller_stock_g
    from public.seller_gold_accounts
   where organization_id = v_org_id;

  select * into v_vault_rec
  from public.manager_vault_account
  where organization_id = v_org_id;

  if found then
    v_mgr_scrap_g := coalesce(v_vault_rec.manager_scrap_585_eq_g, v_vault_rec.manager_scrap_grams, 0);
    v_mgr_scrap_phys_g := coalesce(v_vault_rec.manager_scrap_physical_g, v_vault_rec.manager_scrap_grams, 0);
    v_mgr_refined_g := coalesce(v_vault_rec.manager_refined_gold_grams, 0);
    v_mgr_capital_pure_g := coalesce(v_vault_rec.manager_capital_pure_gold_g, 0);
    v_mgr_purchased_g := coalesce(v_vault_rec.manager_purchased_gold_grams, 0);
    v_mgr_cash_uzs := coalesce(v_vault_rec.manager_cash_amount, 0);
    v_mgr_usd := coalesce(v_vault_rec.manager_usd_amount, 0);
  end if;

  select coalesce(sum(coalesce(seller_till_scrap_585_eq_g, seller_till_scrap_grams, 0)), 0),
         coalesce(sum(coalesce(seller_till_scrap_physical_g, seller_till_scrap_grams, 0)), 0),
         coalesce(sum(seller_till_cash_amount), 0),
         coalesce(sum(coalesce(seller_till_usd_amount, 0)), 0)
    into v_seller_scrap_g, v_seller_scrap_phys_g, v_seller_cash_uzs, v_seller_usd
    from public.seller_gold_accounts
   where organization_id = v_org_id;

  select coalesce(sum(coalesce(input_585_equiv_grams, input_scrap_grams * (coalesce(input_scrap_proba, 585.0) / 585.0))), 0)
    into v_refining_wip_g
    from public.refining_batches
   where organization_id = v_org_id and status in ('pending', 'in_progress');

  select coalesce(sum(current_debt_grams), 0),
         coalesce(sum(advance_balance_grams), 0)
    into v_cust_debts_g, v_cust_advances_g
    from public.client_gold_accounts
   where organization_id = v_org_id;

  v_total_cash_uzs := round(v_mgr_cash_uzs + v_seller_cash_uzs, 2);
  v_total_usd := round(v_mgr_usd + v_seller_usd, 2);

  if v_gold_rate_585 is not null and v_gold_rate_585 > 0 then
    v_cash_585_eq_g := round((v_total_cash_uzs / v_gold_rate_585)::numeric, 4);
    if v_usd_rate is not null and v_usd_rate > 0 then
      v_usd_585_eq_g := round(((v_total_usd * v_usd_rate) / v_gold_rate_585)::numeric, 4);
    end if;
  end if;

  -- Factory net balance: receipts vs handovers
  select coalesce(sum(factory_obligation_g), 0) into v_factory_rcp_due_g
  from public.factory_receipts
  where organization_id = v_org_id and status <> 'reversed';

  select coalesce(sum(agreed_equivalent_g), 0) into v_factory_hnd_paid_g
  from public.factory_gold_handovers
  where organization_id = v_org_id and status <> 'reversed';

  v_net_factory_g := v_factory_rcp_due_g - v_factory_hnd_paid_g;
  if v_net_factory_g >= 0 then
    v_factory_debt_g := round(v_net_factory_g, 4);
    v_factory_advance_g := 0;
  else
    v_factory_debt_g := 0;
    v_factory_advance_g := round(abs(v_net_factory_g), 4);
  end if;

  -- Total Assets includes factory advance gold as asset!
  v_tot_assets_g := round(
    v_mgr_stock_g + v_seller_stock_g +
    v_mgr_scrap_g + v_seller_scrap_g +
    v_mgr_refined_g + v_mgr_capital_pure_g + v_mgr_purchased_g +
    v_refining_wip_g +
    v_cust_debts_g +
    v_cash_585_eq_g + v_usd_585_eq_g +
    v_factory_advance_g,
    4
  );

  v_tot_liabilities_g := round(v_factory_debt_g + v_cust_advances_g, 4);
  v_cur_net_assets_g := round(v_tot_assets_g - v_tot_liabilities_g, 4);

  v_components := jsonb_build_object(
    'manager_finished_goods_585_g', v_mgr_stock_g,
    'sellers_finished_goods_585_g', v_seller_stock_g,
    'manager_scrap_585_eq_g', v_mgr_scrap_g,
    'manager_scrap_physical_g', v_mgr_scrap_phys_g,
    'sellers_scrap_585_eq_g', v_seller_scrap_g,
    'sellers_scrap_physical_g', v_seller_scrap_phys_g,
    'manager_refined_gold_585_g', v_mgr_refined_g,
    'manager_capital_pure_gold_585_g', v_mgr_capital_pure_g,
    'manager_purchased_gold_585_g', v_mgr_purchased_g,
    'refining_wip_585_g', v_refining_wip_g,
    'customer_debts_585_g', v_cust_debts_g,
    'customer_advances_585_g', v_cust_advances_g,
    'manager_cash_uzs', v_mgr_cash_uzs,
    'sellers_cash_uzs', v_seller_cash_uzs,
    'cash_uzs_amount', v_total_cash_uzs,
    'cash_uzs_585_eq_g', v_cash_585_eq_g,
    'manager_cash_usd', v_mgr_usd,
    'sellers_cash_usd', v_seller_usd,
    'cash_usd_amount', v_total_usd,
    'cash_usd_585_eq_g', v_usd_585_eq_g,
    'factory_obligation_585_g', v_factory_debt_g,
    'factory_debt_585_g', v_factory_debt_g,
    'factory_advance_585_g', v_factory_advance_g
  );

  if v_base.id is not null then
    select coalesce(sum(case when transaction_type in ('capital_in', 'capital_contribution') then equiv_585_grams else 0 end), 0),
           coalesce(sum(case when transaction_type in ('capital_out', 'capital_distribution') then equiv_585_grams else 0 end), 0),
           coalesce(sum(case when transaction_type in ('expense', 'business_expense') then equiv_585_grams else 0 end), 0)
      into v_cap_in_g, v_cap_out_g, v_expenses_g
      from public.financial_transactions
     where organization_id = v_org_id and status <> 'reversed'
       and created_at > v_base.created_at;

    select coalesce(sum(delta_585_g), 0) into v_post_base_legacy_adj
    from public.client_legacy_debts
    where organization_id = v_org_id and status <> 'reversed'
      and created_at > v_base.created_at;

    select coalesce(sum(total_loss_grams), 0) into v_refining_loss_g
    from public.refining_batches
    where organization_id = v_org_id and status = 'completed'
      and created_at > v_base.created_at;

    -- 070: business expenses are real outflows; they already reduce net assets and must NOT be
    -- added back. operational_trading_result_585_g (before expenses) is reported separately.
    v_period_accounting_res := round(
      (v_cur_net_assets_g - v_base.net_assets_585_g)
      - v_cap_in_g
      + v_cap_out_g
      - v_post_base_legacy_adj,
      4
    );
  end if;

  return jsonb_build_object(
    'status', case when v_base.id is null then 'baseline_not_set' else 'ok' end,
    'is_computable', (v_base.id is not null),
    'is_complete', (v_gold_rate_585 is not null and v_gold_rate_585 > 0 and v_rate_confirmed and v_base.id is not null),
    'as_of_time', timezone('Asia/Tashkent', now()),
    'as_of_date', v_today,
    'has_baseline', (v_base.id is not null),
    'has_active_baseline', (v_base.id is not null),
    'missing_data', case
      when v_base.id is null then jsonb_build_array('Boshlang''ich hisob tasdiqlanmagan (muzlatilmagan). Boshqaruv panelidan hisobni boshlang.')
      else '[]'::jsonb
    end,
    'rates', jsonb_build_object(
      'gold_rate_585', v_gold_rate_585,
      'is_confirmed', (v_rate_confirmed and v_gold_rate_585 is not null),
      'usd_rate', v_usd_rate,
      'rate_date', v_today
    ),
    'baseline', case
      when v_base.id is null then null
      else jsonb_build_object(
        'id', v_base.id,
        'baseline_no', v_base.baseline_no,
        'baseline_date', v_base.baseline_date,
        'net_assets_585_g', v_base.net_assets_585_g,
        'total_assets_585_g', v_base.total_assets_585_g,
        'total_liabilities_585_g', v_base.total_liabilities_585_g,
        'gold_rate_585', v_base.gold_rate_585,
        'usd_rate', v_base.usd_rate
      )
    end,
    'current_net_assets_585_g', v_cur_net_assets_g,
    'net_assets_585_g', v_cur_net_assets_g,
    'current_total_assets_585_g', v_tot_assets_g,
    'current_total_liabilities_585_g', v_tot_liabilities_g,
    'period_accounting_result_585_g', v_period_accounting_res,
    'operational_trading_result_585_g', case when v_period_accounting_res is null then null else round(v_period_accounting_res + v_expenses_g, 4) end,
    'result_includes_business_expenses', true,
    'fx_valuation_impact_585_g', null,
    'capital_contributions_585_g', v_cap_in_g,
    'capital_distributions_585_g', v_cap_out_g,
    'business_expenses_585_g', v_expenses_g,
    'refining_loss_585_g', v_refining_loss_g,
    'post_baseline_legacy_debt_adj_585_g', v_post_base_legacy_adj,
    'accounting_method', 'net_assets_delta_capital_adjusted_585_g',
    'accounting_scope_notes', 'Hisob 585 proba sof oltin ekvivalentida yuritiladi. Sof aktivlar o''zgarishi (kapital va pateriya ta''siri to''g''ri hisobga olingan holda) korxona sof natijasini beradi.',
    'pilot_notice', 'Pilot davrida umumiy hisobiy natija (aktivlar o''sishi) to''liq aniq; alohida savdo marjasi va kurs tafovutiga ajratish to''liq partiyaviy konvertatsiya tahlili yakunlangach taqdim etiladi.',
    'components', v_components,
    'assets', jsonb_build_object(
      'manager_stock_585_g', v_mgr_stock_g,
      'seller_stock_585_g', v_seller_stock_g,
      'manager_scrap_585_eq_g', v_mgr_scrap_g,
      'seller_scrap_585_eq_g', v_seller_scrap_g,
      'manager_refined_gold_585_g', v_mgr_refined_g,
      'manager_capital_pure_gold_585_g', v_mgr_capital_pure_g,
      'manager_purchased_gold_585_g', v_mgr_purchased_g,
      'refining_wip_585_g', v_refining_wip_g,
      'customer_debts_585_g', v_cust_debts_g,
      'cash_uzs_585_eq_g', v_cash_585_eq_g,
      'cash_usd_585_eq_g', v_usd_585_eq_g,
      'factory_advance_585_g', v_factory_advance_g
    ),
    'liabilities', jsonb_build_object(
      'factory_debt_585_g', v_factory_debt_g,
      'customer_advances_585_g', v_cust_advances_g
    )
  );
end;
$function$;
revoke all on function rpc_get_accounting_profit_summary(date,date,numeric,numeric,uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_accounting_profit_summary(date,date,numeric,numeric,uuid) to authenticated;
grant execute on function rpc_get_accounting_profit_summary(date,date,numeric,numeric,uuid) to service_role;

-- parity: rpc_get_active_sales_markups(text)
CREATE OR REPLACE FUNCTION public.rpc_get_active_sales_markups(p_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_filter_type text := lower(btrim(coalesce(p_type, '')));
  v_result jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select jsonb_agg(jsonb_build_object(
    'id', id,
    'type', type,
    'name', name,
    'percentage', percentage,
    'is_active', is_active,
    'is_default', is_default,
    'display_order', display_order
  ) order by display_order, percentage)
  into v_result
  from public.sales_markup_presets
  where organization_id = v_caller_org
    and (v_filter_type = '' or type = v_filter_type)
    and is_active = true;

  return coalesce(v_result, '[]'::jsonb);
end;
$function$;
revoke all on function rpc_get_active_sales_markups(text) from public, anon, authenticated, service_role;
grant execute on function rpc_get_active_sales_markups(text) to authenticated;
grant execute on function rpc_get_active_sales_markups(text) to service_role;

-- parity: rpc_get_company_rate_difference_report(date,date)
CREATE OR REPLACE FUNCTION public.rpc_get_company_rate_difference_report(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org   uuid := public.current_organization_id();
  v_from  date := coalesce(p_from, date '2000-01-01');
  v_to    date := coalesce(p_to, public._goldia_business_date());
  v_vault public.manager_vault_account%rowtype;
  v_res   jsonb;
begin
  if v_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi']);

  select * into v_vault from public.manager_vault_account where organization_id = v_org;

  select jsonb_build_object(
    'status', 'ok',
    'period_from', v_from,
    'period_to', v_to,
    'net_difference_585_g', coalesce(round(sum(d.difference_585_g), 6), 0),
    'gain_585_g', coalesce(round(sum(d.difference_585_g) filter (where d.entry_type = 'purchase' and d.difference_585_g > 0
                     and not exists (select 1 from public.company_rate_differences r where r.reversal_of_id = d.id)), 6), 0),
    'loss_585_g', coalesce(round(sum(d.difference_585_g) filter (where d.entry_type = 'purchase' and d.difference_585_g < 0
                     and not exists (select 1 from public.company_rate_differences r where r.reversal_of_id = d.id)), 6), 0),
    'purchases_count', count(*) filter (where d.entry_type = 'purchase'),
    'reversals_count', count(*) filter (where d.entry_type = 'purchase_reversal'),
    'valued_cash_pool_uzs', coalesce(v_vault.valued_cash_uzs, 0),
    'valued_cash_pool_585_g', coalesce(v_vault.valued_cash_585_g, 0),
    'valued_usd_pool', coalesce(v_vault.valued_usd, 0),
    'valued_usd_pool_585_g', coalesce(v_vault.valued_usd_585_g, 0),
    'pool_avg_conversion_rate', case when coalesce(v_vault.valued_cash_585_g, 0) > 0
                                     then round(v_vault.valued_cash_uzs / v_vault.valued_cash_585_g, 2) end,
    'included_in_profit_summary', true,
    'note', 'Kompaniya kurs farqi rpc_get_accounting_profit_summary sof aktivlari ichida allaqachon bor; foydaga qayta qo''shilmaydi.',
    'entries', coalesce(jsonb_agg(jsonb_build_object(
        'id', d.id, 'created_at', d.created_at, 'entry_type', d.entry_type,
        'purchase_no', p.purchase_no, 'cash_spent_uzs', d.cash_spent_uzs, 'usd_spent', d.usd_spent,
        'valued_cash_uzs', d.valued_cash_uzs, 'valued_usd', d.valued_usd, 'usd_rate', d.usd_rate,
        'unvalued_cost_uzs', d.unvalued_cost_uzs,
        'avg_conversion_rate', d.avg_conversion_rate, 'purchase_rate_per_gram', d.purchase_rate_per_gram,
        'physical_grams', d.physical_grams, 'proba', d.proba,
        'valued_purchased_585_g', d.valued_purchased_585_g, 'accounting_value_585_g', d.accounting_value_585_g,
        'difference_585_g', d.difference_585_g
      ) order by d.created_at desc) filter (where d.id is not null), '[]'::jsonb)
  ) into v_res
  from public.company_rate_differences d
  join public.gold_purchases p on p.id = d.purchase_id
  where d.organization_id = v_org
    and d.created_at::date between v_from and v_to;

  return v_res;
end;
$function$;
revoke all on function rpc_get_company_rate_difference_report(date,date) from public, anon, authenticated, service_role;
grant execute on function rpc_get_company_rate_difference_report(date,date) to authenticated;
grant execute on function rpc_get_company_rate_difference_report(date,date) to service_role;

-- parity: rpc_get_customer_monthly_report(uuid,integer,integer)
CREATE OR REPLACE FUNCTION public.rpc_get_customer_monthly_report(p_seller_id uuid DEFAULT NULL::uuid, p_year integer DEFAULT NULL::integer, p_month integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_caller_role   text := public.current_employee_role_text();
  v_caller_emp_id uuid := public.current_employee_id();
  v_filter_seller uuid;
  v_year          integer := coalesce(p_year, extract(year from public._goldia_business_date())::integer);
  v_month         integer := coalesce(p_month, extract(month from public._goldia_business_date())::integer);
  v_start_date    date;
  v_end_date      date;
  v_rows          jsonb := '[]'::jsonb;
  v_cust_rec      record;
  v_open_debt     numeric(14, 4);
  v_month_legacy  numeric(14, 4);
  v_month_sales   numeric(14, 4);
  v_month_scrap   numeric(14, 4);
  v_month_cash    numeric(18, 2);
  v_month_cash_g  numeric(14, 4);
  v_month_usd     numeric(18, 2);
  v_month_usd_g   numeric(14, 4);
  v_month_usd_rate numeric(14, 2);
  v_month_settle  numeric(14, 4);
  v_close_debt    numeric(14, 4);

  -- Overall totals
  v_tot_open     numeric(14, 4) := 0;
  v_tot_legacy   numeric(14, 4) := 0;
  v_tot_dist     numeric(14, 4) := 0;
  v_tot_coll     numeric(14, 4) := 0;
  v_tot_debt     numeric(14, 4) := 0;
  v_tot_cash_uzs numeric(18, 2) := 0;
  v_tot_usd      numeric(18, 2) := 0;
  v_tot_scrap_g  numeric(14, 4) := 0;

  -- Seller till & obligation totals
  v_seller_held_cash_uzs numeric(18, 2) := 0;
  v_seller_held_scrap_g  numeric(14, 4) := 0;
  v_seller_held_usd      numeric(18, 2) := 0;
  v_bozor_qarzi          numeric(14, 4) := 0;
  v_seller_owes_m_tot    numeric(14, 4) := 0;
  v_m_owes_seller_tot    numeric(14, 4) := 0;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_caller_role in ('seller', 'sotuvchi', 'sales') then
    if p_seller_id is not null and p_seller_id <> v_caller_emp_id then
      raise exception 'Cross-seller violation: Sotuvchilar faqat o''z hisobotini ko''ra oladi' using errcode = '42501';
    end if;
    v_filter_seller := v_caller_emp_id;
  else
    v_filter_seller := p_seller_id;
  end if;

  v_start_date := make_date(v_year, v_month, 1);
  v_end_date   := (v_start_date + interval '1 month - 1 day')::date;

  for v_cust_rec in
    select c.id, c.customer_code, c.contact_name, c.phone, c.seller_id
    from public.customers c
    where c.organization_id = v_caller_org
      and (v_filter_seller is null or c.seller_id = v_filter_seller)
    order by c.contact_name asc
  loop
    -- 1. Opening debt: Legacy debts before start date + Sales before start date - Payments before start date
    select coalesce(sum(delta_585_g), 0) into v_open_debt
    from public.client_legacy_debts
    where customer_id = v_cust_rec.id
      and balance_type = 'debt'
      and as_of_date < v_start_date
      and status <> 'reversed';

    select v_open_debt + coalesce(sum(client_gold_due_grams), 0) into v_open_debt
    from public.jewelry_sales
    where customer_id = v_cust_rec.id
      and sale_date < v_start_date
      and status <> 'reversed';

    select v_open_debt - coalesce(sum(total_settled_grams), 0) into v_open_debt
    from public.gold_settlements
    where customer_id = v_cust_rec.id
      and direction = 'client_to_seller'
      and status <> 'reversed'
      and settlement_date < v_start_date;

    v_open_debt := round(greatest(0, v_open_debt), 4);

    -- 2. Legacy debts registered in current month
    select coalesce(sum(delta_585_g), 0) into v_month_legacy
    from public.client_legacy_debts
    where customer_id = v_cust_rec.id
      and balance_type = 'debt'
      and as_of_date between v_start_date and v_end_date
      and status <> 'reversed';

    -- 3. Sales during selected month (EXCLUDE REVERSED!)
    select coalesce(sum(client_gold_due_grams), 0) into v_month_sales
    from public.jewelry_sales
    where customer_id = v_cust_rec.id
      and sale_date between v_start_date and v_end_date
      and status <> 'reversed';

    -- 4. Payments during selected month (EXCLUDE REVERSED!)
    select
      coalesce(sum(scrap_weight_grams), 0),
      coalesce(sum(cash_paid_amount), 0),
      coalesce(sum(cash_equivalent_grams), 0),
      coalesce(sum(usd_paid_amount), 0),
      coalesce(sum(usd_equivalent_grams), 0),
      coalesce(sum(total_settled_grams), 0)
    into v_month_scrap, v_month_cash, v_month_cash_g, v_month_usd, v_month_usd_g, v_month_settle
    from public.gold_settlements
    where customer_id = v_cust_rec.id
      and direction = 'client_to_seller'
      and status <> 'reversed'
      and settlement_date between v_start_date and v_end_date;

    -- Fetch applied USD rate for the month settlements if any
    select coalesce(max(applied_usd_rate), 0) into v_month_usd_rate
    from public.gold_settlements
    where customer_id = v_cust_rec.id
      and direction = 'client_to_seller'
      and status <> 'reversed'
      and settlement_date between v_start_date and v_end_date
      and usd_paid_amount > 0;

    -- 5. Closing debt: opening + month legacy + sales - settled
    v_close_debt := round(greatest(0, (v_open_debt + v_month_legacy + v_month_sales) - v_month_settle), 4);

    if v_open_debt > 0 or v_month_legacy > 0 or v_month_sales > 0 or v_month_settle > 0 or v_close_debt > 0 then
      v_rows := v_rows || jsonb_build_object(
        'customer_id', v_cust_rec.id,
        'customer_code', v_cust_rec.customer_code,
        'customer_name', v_cust_rec.contact_name,
        'phone', v_cust_rec.phone,
        'opening_debt_g', v_open_debt,
        'legacy_added_month_g', v_month_legacy,
        'sales_in_month_g', v_month_sales,
        'scrap_received_g', v_month_scrap,
        'cash_received_uzs', v_month_cash,
        'cash_equivalent_g', v_month_cash_g,
        'usd_received', v_month_usd,
        'usd_rate', v_month_usd_rate,
        'usd_equivalent_g', v_month_usd_g,
        'total_settled_g', v_month_settle,
        'closing_debt_g', v_close_debt
      );

      v_tot_open := v_tot_open + v_open_debt;
      v_tot_legacy := v_tot_legacy + v_month_legacy;
      v_tot_dist := v_tot_dist + v_month_sales;
      v_tot_coll := v_tot_coll + v_month_settle;
      v_tot_debt := v_tot_debt + v_close_debt;
      v_tot_cash_uzs := v_tot_cash_uzs + v_month_cash;
      v_tot_usd := v_tot_usd + v_month_usd;
      v_tot_scrap_g := v_tot_scrap_g + v_month_scrap;
    end if;
  end loop;

  -- Calculate seller till and bozor qarzi (filter-specific OR across all sellers)
  if v_filter_seller is not null then
    select
      coalesce(seller_till_cash_amount, 0),
      coalesce(seller_till_scrap_grams, 0),
      coalesce(seller_till_usd_amount, 0),
      coalesce(seller_owes_manager_g, 0),
      coalesce(manager_owes_seller_g, 0),
      coalesce(bozor_qarzi_signed_g, 0)
    into v_seller_held_cash_uzs, v_seller_held_scrap_g, v_seller_held_usd,
         v_seller_owes_m_tot, v_m_owes_seller_tot, v_bozor_qarzi
    from public.seller_gold_accounts
    where seller_id = v_filter_seller and organization_id = v_caller_org;
  else
    select
      coalesce(sum(seller_till_cash_amount), 0),
      coalesce(sum(seller_till_scrap_grams), 0),
      coalesce(sum(seller_till_usd_amount), 0),
      coalesce(sum(seller_owes_manager_g), 0),
      coalesce(sum(manager_owes_seller_g), 0),
      coalesce(sum(bozor_qarzi_signed_g), 0)
    into v_seller_held_cash_uzs, v_seller_held_scrap_g, v_seller_held_usd,
         v_seller_owes_m_tot, v_m_owes_seller_tot, v_bozor_qarzi
    from public.seller_gold_accounts
    where organization_id = v_caller_org;
  end if;

  return jsonb_build_object(
    'year', v_year,
    'month', v_month,
    'items', v_rows,
    'summary', jsonb_build_object(
      'total_customers', jsonb_array_length(v_rows),
      -- Combine opening debt + legacy debt added in month so card matches table!
      'total_opening_debt_g', round(v_tot_open + v_tot_legacy, 4),
      'base_opening_debt_g', v_tot_open,
      'total_legacy_added_month_g', v_tot_legacy,
      'total_distributed_month_g', v_tot_dist,
      'total_collected_scrap_g', v_tot_scrap_g,
      'total_collected_cash_uzs', v_tot_cash_uzs,
      'total_collected_usd', v_tot_usd,
      'total_collected_month_g', v_tot_coll,
      'total_closing_debt_g', v_tot_debt,
      'total_customer_debt_g', v_tot_debt,
      'seller_held_cash_uzs', v_seller_held_cash_uzs,
      'seller_held_scrap_g', v_seller_held_scrap_g,
      'seller_held_usd', v_seller_held_usd,
      'seller_owes_manager_total_g', v_seller_owes_m_tot,
      'manager_owes_seller_total_g', v_m_owes_seller_tot,
      'seller_manager_bozor_qarzi_g', v_bozor_qarzi
    )
  );
end;
$function$;
revoke all on function rpc_get_customer_monthly_report(uuid,integer,integer) from public, anon, authenticated, service_role;
grant execute on function rpc_get_customer_monthly_report(uuid,integer,integer) to authenticated;
grant execute on function rpc_get_customer_monthly_report(uuid,integer,integer) to service_role;

-- parity: rpc_get_daily_sales_ledger(uuid,date,date)
CREATE OR REPLACE FUNCTION public.rpc_get_daily_sales_ledger(p_seller_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date)
 RETURNS TABLE(tx_id uuid, tx_type text, tx_date date, customer_id uuid, customer_code text, customer_name text, seller_id uuid, seller_name text, model_name text, model_code text, item_id uuid, sold_weight_g numeric, markup_pct numeric, obligation_g numeric, scrap_received_g numeric, cash_received_uzs numeric, rate_per_gram numeric, cash_equiv_g numeric, usd_received numeric, usd_rate numeric, usd_equiv_g numeric, total_payment_g numeric, closing_debt_g numeric, notes text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org    uuid := public.current_organization_id();
  v_caller_role   text := public.current_employee_role_text();
  v_caller_emp_id uuid := public.current_employee_id();
  v_filter_seller uuid;
  v_today_tkt     date := (timezone('Asia/Tashkent', NOW()))::date;
  v_d1            date;
  v_d2            date;
  v_from          date;
  v_to            date;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  IF v_caller_role IN ('seller', 'sotuvchi', 'sales') THEN
    IF p_seller_id IS NOT NULL AND p_seller_id <> v_caller_emp_id THEN
      RAISE EXCEPTION 'Cross-seller violation: Sotuvchilar faqat o''z savdo jurnalini ko''ra oladi' USING errcode = '42501';
    END IF;
    v_filter_seller := v_caller_emp_id;
  ELSE
    v_filter_seller := p_seller_id;
  END IF;

  IF p_start_date IS NOT NULL AND p_end_date IS NULL THEN
    v_d1 := p_start_date;
    v_d2 := p_start_date;
  ELSIF p_start_date IS NULL AND p_end_date IS NOT NULL THEN
    v_d1 := p_end_date;
    v_d2 := p_end_date;
  ELSIF p_start_date IS NOT NULL AND p_end_date IS NOT NULL THEN
    v_d1 := p_start_date;
    v_d2 := p_end_date;
  ELSE
    v_d1 := v_today_tkt - INTERVAL '30 days';
    v_d2 := v_today_tkt;
  END IF;

  v_from := LEAST(v_d1, v_d2);
  v_to   := GREATEST(v_d1, v_d2);

  RETURN QUERY
  -- 1. Sales entries
  SELECT
    s.id AS tx_id,
    'sale'::text AS tx_type,
    s.sale_date AS tx_date,
    s.customer_id,
    COALESCE(c.customer_code, 'CUST-XXXX') AS customer_code,
    COALESCE(c.contact_name, 'Mijoz') AS customer_name,
    s.seller_id,
    COALESCE(e.full_name, e.name, 'Sotuvchi') AS seller_name,
    s.product_name AS model_name,
    COALESCE(cp.model_code, 'M-GENERIC') AS model_code,
    cp.id AS item_id,
    s.base_weight_grams AS sold_weight_g,
    s.client_markup_pct AS markup_pct,
    s.client_gold_due_grams AS obligation_g,
    0::numeric AS scrap_received_g,
    0::numeric AS cash_received_uzs,
    0::numeric AS rate_per_gram,
    0::numeric AS cash_equiv_g,
    0::numeric AS usd_received,
    0::numeric AS usd_rate,
    0::numeric AS usd_equiv_g,
    COALESCE(s.settled_gold_grams, 0)::numeric AS total_payment_g,
    s.remaining_gold_grams AS closing_debt_g,
    s.notes,
    s.status
  FROM public.jewelry_sales s
  JOIN public.customers c ON c.id = s.customer_id
  JOIN public.employees e ON e.id = s.seller_id
  LEFT JOIN public.consignment_pieces cp ON cp.sale_id = s.id
  WHERE s.organization_id = v_caller_org
    AND s.sale_date BETWEEN v_from AND v_to
    AND (v_filter_seller IS NULL OR s.seller_id = v_filter_seller)

  UNION ALL

  -- 2. Payment/Settlement entries
  SELECT
    gs.id AS tx_id,
    'payment'::text AS tx_type,
    gs.settlement_date AS tx_date,
    gs.customer_id,
    COALESCE(c.customer_code, 'CUST-XXXX') AS customer_code,
    COALESCE(c.contact_name, 'Mijoz') AS customer_name,
    gs.seller_id,
    COALESCE(e.full_name, e.name, 'Sotuvchi') AS seller_name,
    'To''lov / Qaytim'::text AS model_name,
    'PAYMENT'::text AS model_code,
    NULL::uuid AS item_id,
    0::numeric AS sold_weight_g,
    0::numeric AS markup_pct,
    0::numeric AS obligation_g,
    gs.scrap_weight_grams AS scrap_received_g,
    gs.cash_paid_amount AS cash_received_uzs,
    gs.gold_rate_applied AS rate_per_gram,
    gs.cash_equivalent_grams AS cash_equiv_g,
    COALESCE(gs.usd_paid_amount, 0)::numeric AS usd_received,
    COALESCE(gs.applied_usd_rate, 0)::numeric AS usd_rate,
    COALESCE(gs.usd_equivalent_grams, 0)::numeric AS usd_equiv_g,
    gs.total_settled_grams AS total_payment_g,
    gs.remaining_debt_grams AS closing_debt_g,
    gs.notes,
    gs.status
  FROM public.gold_settlements gs
  JOIN public.customers c ON c.id = gs.customer_id
  JOIN public.employees e ON e.id = gs.seller_id
  WHERE gs.organization_id = v_caller_org
    AND gs.settlement_date BETWEEN v_from AND v_to
    AND (v_filter_seller IS NULL OR gs.seller_id = v_filter_seller)
  ORDER BY tx_date DESC, tx_id DESC;
END;
$function$;
revoke all on function rpc_get_daily_sales_ledger(uuid,date,date) from public, anon, authenticated, service_role;
grant execute on function rpc_get_daily_sales_ledger(uuid,date,date) to authenticated;
grant execute on function rpc_get_daily_sales_ledger(uuid,date,date) to service_role;

-- parity: rpc_get_director_sales_overview()
CREATE OR REPLACE FUNCTION public.rpc_get_director_sales_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org        uuid := public.current_organization_id();
  v_total_consign_w   numeric(14, 4);
  v_total_factory_due numeric(14, 4);
  v_total_cli_debt    numeric(14, 4);
  v_total_till_scrap  numeric(14, 4);
  v_total_till_cash   numeric(18, 2);
  v_latest_rate       numeric(18, 2);
  v_rate_date         date;
  v_sellers_list      jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter'
  ]);

  select rate_per_gram, rate_date
    into v_latest_rate, v_rate_date
    from public.daily_gold_rates
   where organization_id = v_caller_org
   order by rate_date desc, created_at desc
   limit 1;

  select
    coalesce(sum(current_factory_obligation_grams), 0),
    coalesce(sum(total_consigned_gold_grams), 0),
    coalesce(sum(seller_till_scrap_grams), 0),
    coalesce(sum(seller_till_cash_amount), 0),
    coalesce(sum(total_client_debt_grams), 0)
  into
    v_total_factory_due,
    v_total_consign_w,
    v_total_till_scrap,
    v_total_till_cash,
    v_total_cli_debt
  from public.seller_gold_accounts
  where organization_id = v_caller_org;

  select jsonb_agg(jsonb_build_object(
    'seller_id', e.id,
    'full_name', coalesce(e.full_name, e.first_name || ' ' || e.last_name, e.email),
    'factory_obligation_grams', coalesce(sga.current_factory_obligation_grams, 0),
    'seller_till_scrap_grams', coalesce(sga.seller_till_scrap_grams, 0),
    'seller_till_cash_amount', coalesce(sga.seller_till_cash_amount, 0),
    'client_debt_grams', coalesce(sga.total_client_debt_grams, 0)
  ))
  into v_sellers_list
  from public.employees e
  left join public.seller_gold_accounts sga on sga.seller_id = e.id
  where e.organization_id = v_caller_org
    and lower(coalesce(e.role_type, e.role::text, '')) in ('sales', 'seller', 'sotuvchi', 'manager', 'production_manager', 'director', 'admin');

  return jsonb_build_object(
    'status', 'ok',
    'latest_rate_per_gram', coalesce(v_latest_rate, 0),
    'rate_date', v_rate_date,
    'total_factory_obligation_grams', v_total_factory_due,
    'total_consigned_grams', v_total_consign_w,
    'total_seller_till_scrap_grams', v_total_till_scrap,
    'total_seller_till_cash_amount', v_total_till_cash,
    'total_client_debt_grams', v_total_cli_debt,
    'sellers', coalesce(v_sellers_list, '[]'::jsonb)
  );
end;
$function$;
revoke all on function rpc_get_director_sales_overview() from public, anon, authenticated, service_role;
grant execute on function rpc_get_director_sales_overview() to authenticated;
grant execute on function rpc_get_director_sales_overview() to service_role;

-- parity: rpc_get_factory_settings(uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_factory_settings(p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id      uuid := coalesce(p_organization_id, public.current_organization_id());
  v_org         public.organizations%rowtype;
  v_settings    public.organization_factory_settings%rowtype;
begin
  if v_org_id is null then
    -- Fallback to default Goldia organization
    select * into v_org from public.organizations where code = 'goldia' limit 1;
    if found then
      v_org_id := v_org.id;
    end if;
  else
    select * into v_org from public.organizations where id = v_org_id;
  end if;

  select * into v_settings from public.organization_factory_settings where organization_id = v_org_id;

  if not found then
    -- Insert default settings row if missing
    insert into public.organization_factory_settings (
      organization_id,
      disabled_stage_codes,
      disabled_stage_orders,
      disabled_department_slugs,
      laser_machines_count,
      casting_machines_count,
      workers_count,
      max_models_per_batch,
      sets_per_model,
      handover_tolerance_gram
    ) values (
      v_org_id,
      array['PUMICE', 'PUMICE_MACHINE', 'PONZA', 'ZIRCON', 'ZIRCON_MACHINE']::text[],
      array[9, 13]::integer[],
      array['pumice', 'zircon']::text[],
      8, 2, 35, 20, 10, 0.05
    )
    returning * into v_settings;
  end if;

  return jsonb_build_object(
    'organizationId', v_org_id::text,
    'organizationCode', coalesce(v_org.code, 'goldia'),
    'organizationName', coalesce(v_org.name, 'Goldia Jewelry Factory'),
    'disabledStageCodes', coalesce(v_settings.disabled_stage_codes, array[]::text[]),
    'disabledStageOrders', coalesce(v_settings.disabled_stage_orders, array[]::integer[]),
    'disabledDepartmentSlugs', coalesce(v_settings.disabled_department_slugs, array[]::text[]),
    'laserMachinesCount', coalesce(v_settings.laser_machines_count, 8),
    'castingMachinesCount', coalesce(v_settings.casting_machines_count, 2),
    'workersCount', coalesce(v_settings.workers_count, 35),
    'maxModelsPerBatch', coalesce(v_settings.max_models_per_batch, 20),
    'setsPerModel', coalesce(v_settings.sets_per_model, 10),
    'handoverToleranceGram', coalesce(v_settings.handover_tolerance_gram, 0.05)
  );
end;
$function$;
revoke all on function rpc_get_factory_settings(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_factory_settings(uuid) to authenticated;
grant execute on function rpc_get_factory_settings(uuid) to service_role;

-- parity: rpc_get_financial_reconciliation_summary()
CREATE OR REPLACE FUNCTION public.rpc_get_financial_reconciliation_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id        uuid := public.current_organization_id();
  v_vault         public.manager_vault_account;
  v_total_cns_phys numeric(14, 4);
  v_total_s_due    numeric(14, 4);
  v_total_s_stl    numeric(14, 4);
  v_total_s_owes   numeric(14, 4);
  v_total_m_owes   numeric(14, 4);
  v_total_s_till_sc numeric(14, 4);
  v_total_s_till_c numeric(18, 2);
  v_total_cl_debt  numeric(14, 4);
  v_total_cl_adv   numeric(14, 4);
begin
  -- 070: company-wide balances are not visible to sellers
  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter', 'manager', 'production_manager', 'boshqaruvchi']);
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id;

  select
    coalesce(sum(total_transferred_physical_g), 0),
    coalesce(sum(total_seller_obligation_g), 0),
    coalesce(sum(total_settled_to_manager_g), 0),
    coalesce(sum(seller_owes_manager_g), 0),
    coalesce(sum(manager_owes_seller_g), 0),
    coalesce(sum(seller_till_scrap_grams), 0),
    coalesce(sum(seller_till_cash_amount), 0)
  into
    v_total_cns_phys,
    v_total_s_due,
    v_total_s_stl,
    v_total_s_owes,
    v_total_m_owes,
    v_total_s_till_sc,
    v_total_s_till_c
  from public.seller_gold_accounts
  where organization_id = v_org_id;

  select
    coalesce(sum(current_debt_grams), 0),
    coalesce(sum(advance_balance_grams), 0)
  into
    v_total_cl_debt,
    v_total_cl_adv
  from public.client_gold_accounts
  where organization_id = v_org_id;

  return jsonb_build_object(
    'organization_id', v_org_id,
    'manager_factory_account', jsonb_build_object(
      'total_factory_received_g', v_vault.total_factory_received_g,
      'total_factory_obligation_g', v_vault.total_factory_obligation_g,
      'total_factory_handed_over_g', v_vault.total_factory_handed_over_g,
      'current_factory_obligation_g', v_vault.current_factory_obligation_g
    ),
    'manager_vault_holdings', jsonb_build_object(
      'manager_scrap_grams', v_vault.manager_scrap_grams,
      'manager_cash_amount', v_vault.manager_cash_amount,
      'manager_refined_gold_grams', v_vault.manager_refined_gold_grams,
      'manager_purchased_gold_grams', v_vault.manager_purchased_gold_grams
    ),
    'sellers_summary', jsonb_build_object(
      'total_transferred_physical_g', v_total_cns_phys,
      'total_seller_obligation_g', v_total_s_due,
      'total_settled_to_manager_g', v_total_s_stl,
      'total_seller_owes_manager_g', v_total_s_owes,
      'total_manager_owes_seller_g', v_total_m_owes,
      'total_seller_till_scrap_grams', v_total_s_till_sc,
      'total_seller_till_cash_amount', v_total_s_till_c
    ),
    'clients_summary', jsonb_build_object(
      'total_client_debt_grams', v_total_cl_debt,
      'total_client_advance_grams', v_total_cl_adv
    )
  );
end;
$function$;
revoke all on function rpc_get_financial_reconciliation_summary() from public, anon, authenticated, service_role;
grant execute on function rpc_get_financial_reconciliation_summary() to authenticated;
grant execute on function rpc_get_financial_reconciliation_summary() to service_role;

