-- parity: rpc_get_piece_sales_reconciliation_report()
CREATE OR REPLACE FUNCTION public.rpc_get_piece_sales_reconciliation_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid := public.current_organization_id();
  v_discrepancies jsonb := '[]'::jsonb;
  v_total_pieces integer := 0;
  v_held_pieces integer := 0;
  v_sold_pieces integer := 0;
  v_ret_pieces integer := 0;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select
    count(*),
    count(*) filter (where status = 'held_by_seller'),
    count(*) filter (where status = 'sold'),
    count(*) filter (where status like 'returned%')
  into v_total_pieces, v_held_pieces, v_sold_pieces, v_ret_pieces
  from public.consignment_pieces
  where organization_id = v_org_id;

  -- Find pieces with discrepancies:
  -- Case A: Piece marked held_by_seller but has sale_id
  -- Case B: Piece marked sold but has no sale_id or sale record doesn't exist
  -- Case C: Consignment marked fully_sold but pieces still held_by_seller
  select coalesce(jsonb_agg(d), '[]'::jsonb)
  into v_discrepancies
  from (
    select
      cp.id as piece_id,
      cp.model_code,
      cp.model_name,
      cp.weight_grams,
      cp.status as piece_status,
      cp.sale_id,
      sc.consignment_no,
      sc.status as consignment_status,
      case
        when cp.status = 'held_by_seller' and cp.sale_id is not null then 'piece_marked_held_but_has_sale_id'
        when cp.status = 'sold' and cp.sale_id is null then 'piece_marked_sold_without_sale_id'
        when sc.status = 'fully_sold' and cp.status = 'held_by_seller' then 'consignment_fully_sold_but_piece_held'
        else 'other_anomaly'
      end as anomaly_type
    from public.consignment_pieces cp
    join public.seller_consignments sc on sc.id = cp.consignment_id
    where cp.organization_id = v_org_id
      and (
        (cp.status = 'held_by_seller' and cp.sale_id is not null)
        or (cp.status = 'sold' and cp.sale_id is null)
        or (sc.status = 'fully_sold' and cp.status = 'held_by_seller')
      )
  ) d;

  return jsonb_build_object(
    'organization_id', v_org_id,
    'total_pieces', v_total_pieces,
    'held_pieces', v_held_pieces,
    'sold_pieces', v_sold_pieces,
    'returned_pieces', v_ret_pieces,
    'anomaly_count', jsonb_array_length(v_discrepancies),
    'discrepancies', v_discrepancies
  );
end;
$function$;
revoke all on function rpc_get_piece_sales_reconciliation_report() from public, anon, authenticated, service_role;
grant execute on function rpc_get_piece_sales_reconciliation_report() to authenticated;
grant execute on function rpc_get_piece_sales_reconciliation_report() to service_role;

-- parity: rpc_get_seller_available_pieces(uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_seller_available_pieces(p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_caller_emp uuid := public.current_employee_id();
  v_caller_role text := public.current_employee_role();
  v_target_seller uuid;
  v_pieces jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  -- 070: a seller may only list their own pieces
  if public._goldia_is_seller_role(public.current_employee_role_text())
     and p_seller_id is not null and p_seller_id is distinct from v_caller_emp then
    raise exception 'Ruxsat etilmadi: Sotuvchi faqat o''z mahsulotlarini ko''ra oladi' using errcode = '42501';
  end if;
  if p_seller_id is not null then
    v_target_seller := p_seller_id;
  else
    v_target_seller := v_caller_emp;
  end if;

  select coalesce(jsonb_agg(row_to_json(r)), '[]'::jsonb)
  into v_pieces
  from (
    select 
      cp.id,
      cp.consignment_id,
      cp.model_id,
      cp.model_code,
      cp.model_name,
      cp.category,
      cp.purity,
      cp.proba,
      cp.weight_grams,
      cp.status,
      cp.seller_id,
      cp.raw_barcode,
      jm.primary_image_url,
      cp.notes,
      cp.seller_markup_pct,
      cp.seller_obligation_grams,
      cp.created_at,
      sc.consignment_no
    from public.consignment_pieces cp
    join public.seller_consignments sc on sc.id = cp.consignment_id
    left join public.jewelry_models jm on jm.id = cp.model_id
    where cp.organization_id = v_caller_org
      and (v_target_seller is null or cp.seller_id = v_target_seller)
      and cp.status = 'held_by_seller'
      and cp.sale_id is null
      and sc.status not in ('fully_sold', 'returned_to_manager', 'cancelled')
      and coalesce(sc.sold_quantity, 0) < sc.quantity
    order by cp.created_at desc
  ) r;

  return v_pieces;
end;
$function$;
revoke all on function rpc_get_seller_available_pieces(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_seller_available_pieces(uuid) to authenticated;
grant execute on function rpc_get_seller_available_pieces(uuid) to service_role;

-- parity: rpc_get_seller_markup_difference_report(uuid,date,date)
CREATE OR REPLACE FUNCTION public.rpc_get_seller_markup_difference_report(p_seller_id uuid DEFAULT NULL::uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org     uuid := public.current_organization_id();
  v_role    text := public.current_employee_role_text();
  v_emp     uuid := public.current_employee_id();
  v_seller  uuid := p_seller_id;
  v_from    date := coalesce(p_from, date '2000-01-01');
  v_to      date := coalesce(p_to, public._goldia_business_date());
  v_res     jsonb;
begin
  if v_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi']);
  if public._goldia_is_seller_role(v_role) then
    if v_seller is not null and v_seller is distinct from v_emp then
      raise exception 'Ruxsat etilmadi: Sotuvchi faqat o''z ustama farqini ko''ra oladi' using errcode = '42501';
    end if;
    v_seller := v_emp;
  end if;

  with s as (
    select js.*, (js.status in ('reversed', 'cancelled')) as is_reversed,
           case when coalesce(js.client_gold_due_grams, 0) > 0
                then least(1, greatest(0, coalesce(js.settled_gold_grams, 0) / js.client_gold_due_grams)) else 0 end as paid_ratio
      from public.jewelry_sales js
     where js.organization_id = v_org
       and (v_seller is null or js.seller_id = v_seller)
       and js.sale_date between v_from and v_to
  ),
  active as (select * from s where not is_reversed and markup_difference_g is not null)
  select jsonb_build_object(
    'status', 'ok',
    'seller_id', v_seller,
    'period_from', v_from,
    'period_to', v_to,
    'total_difference_g', coalesce((select round(sum(markup_difference_g), 4) from active), 0),
    'positive_g', coalesce((select round(sum(markup_difference_g), 4) from active where markup_difference_g > 0), 0),
    'negative_g', coalesce((select round(sum(markup_difference_g), 4) from active where markup_difference_g < 0), 0),
    'realized_g', coalesce((select round(sum(markup_difference_g * paid_ratio), 4) from active), 0),
    'unrealized_g', coalesce((select round(sum(markup_difference_g * (1 - paid_ratio)), 4) from active), 0),
    'active_sales', (select count(*) from active),
    'reversed_sales', (select count(*) from s where is_reversed),
    'unknown_sales', (select count(*) from s where not is_reversed and markup_difference_g is null),
    'included_in_profit_summary', true,
    'note', 'Ustama farqi kompaniyaga tegishli; mijoz qarzi va sotuvchi majburiyatini o''zgartirmaydi, foyda hisobotida allaqachon bor — qayta qo''shilmaydi. Amalga oshgan qism mijoz to''lagan ulushga teng.',
    'by_seller', case when public._goldia_is_seller_role(v_role) then '[]'::jsonb else coalesce((
        select jsonb_agg(jsonb_build_object('seller_id', a.seller_id,
                 'seller_name', coalesce(e.full_name, e.name), 'total_difference_g', a.total, 'positive_g', a.pos,
                 'negative_g', a.neg, 'sales', a.cnt) order by a.total desc)
          from (select seller_id, round(sum(markup_difference_g), 4) total,
                       round(sum(markup_difference_g) filter (where markup_difference_g > 0), 4) pos,
                       round(sum(markup_difference_g) filter (where markup_difference_g < 0), 4) neg, count(*) cnt
                  from active group by seller_id) a
          left join public.employees e on e.id = a.seller_id), '[]'::jsonb) end,
    'entries', coalesce((
        select jsonb_agg(jsonb_build_object(
                 'sale_id', x.id, 'sale_no', x.sale_no, 'sale_date', x.sale_date, 'seller_id', x.seller_id,
                 'customer_name', c.contact_name, 'model', coalesce(x.model_code, x.product_name),
                 'base_weight_grams', x.base_weight_grams, 'assigned_seller_markup_pct', x.assigned_seller_markup_pct,
                 'client_markup_pct', x.client_markup_pct, 'markup_difference_g', x.markup_difference_g,
                 'snapshot_source', x.markup_snapshot_source, 'status', x.status, 'reversed', x.is_reversed)
               order by x.sale_date desc, x.created_at desc)
          from (select * from s order by sale_date desc, created_at desc limit 500) x
          left join public.customers c on c.id = x.customer_id), '[]'::jsonb)
  ) into v_res;
  return v_res;
end;
$function$;
revoke all on function rpc_get_seller_markup_difference_report(uuid,date,date) from public, anon, authenticated, service_role;
grant execute on function rpc_get_seller_markup_difference_report(uuid,date,date) to authenticated;
grant execute on function rpc_get_seller_markup_difference_report(uuid,date,date) to service_role;

-- parity: rpc_get_seller_rates(uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_seller_rates(p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org  uuid := public.current_organization_id();
  v_role text := public.current_employee_role_text();
  v_emp  uuid := public.current_employee_id();
  v_lim  public.seller_rate_limits%rowtype;
  v_filter uuid;
begin
  if v_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi']);
  if public._goldia_is_seller_role(v_role) then
    if p_seller_id is not null and p_seller_id is distinct from v_emp then
      raise exception 'Ruxsat etilmadi: boshqa sotuvchining kursini ko''rish mumkin emas' using errcode = '42501';
    end if;
    v_filter := v_emp;
  else
    v_filter := p_seller_id;
  end if;
  v_lim := public._goldia_seller_rate_limits(v_org);
  return jsonb_build_object(
    'status', 'ok',
    'official_585_rate', public._goldia_official_585_rate(v_org),
    'limits', jsonb_build_object('lom_min_uzs', v_lim.lom_min_uzs, 'lom_max_uzs', v_lim.lom_max_uzs,
                                 'usd_min_uzs', v_lim.usd_min_uzs, 'usd_max_uzs', v_lim.usd_max_uzs,
                                 'max_lom_deviation_pct', v_lim.max_lom_deviation_pct),
    'sellers', coalesce((
      select jsonb_agg(jsonb_build_object('seller_id', e.id, 'seller_name', coalesce(e.name, e.full_name),
               'lom_rate_uzs', r.lom_rate_uzs, 'usd_rate_uzs', r.usd_rate_uzs, 'updated_at', r.updated_at)
             order by coalesce(e.name, e.full_name))
        from public.employees e
        left join public.seller_rates r on r.seller_id = e.id and r.organization_id = v_org
       where e.organization_id = v_org
         and coalesce(e.is_active, true)
         and (v_filter is null and public._goldia_is_seller_role(coalesce(
                nullif(nullif(public.normalize_erp_role_token(e.role_type), 'worker'), 'viewer'),
                public.normalize_erp_role_token(e.role::text)))
              or e.id = v_filter)), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(h order by h.changed_at desc) from (
        select seller_id, old_lom_rate_uzs, new_lom_rate_uzs, old_usd_rate_uzs, new_usd_rate_uzs, changed_by, reason, changed_at
          from public.seller_rate_history
         where organization_id = v_org and (v_filter is null or seller_id = v_filter)
         order by changed_at desc limit 50) h), '[]'::jsonb)
  );
end;
$function$;
revoke all on function rpc_get_seller_rates(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_seller_rates(uuid) to authenticated;
grant execute on function rpc_get_seller_rates(uuid) to service_role;

-- parity: rpc_get_seller_reconciliation_statement(uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_seller_reconciliation_statement(p_seller_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org        uuid := public.current_organization_id();
  v_seller            public.employees%rowtype;
  v_seller_acc        public.seller_gold_accounts%rowtype;

  -- Section A: Received from Manager + Legacy customer debts assigned
  v_sec_a_orig_g      numeric(14, 4) := 0;
  v_sec_a_obl_g       numeric(14, 4) := 0;
  v_sec_a_count       integer := 0;
  v_sec_a_legacy_g    numeric(14, 4) := 0;

  -- Section B: Goods Unsold
  v_sec_b_count       integer := 0;
  v_sec_b_orig_g      numeric(14, 4) := 0;
  v_sec_b_equiv_g     numeric(14, 4) := 0;
  v_sec_b_pieces_g    numeric(14, 4) := 0;
  v_sec_b_auth_g      numeric(14, 4) := 0;

  -- Section C: Goods Sold to Customers
  v_sec_c_count       integer := 0;
  v_sec_c_orig_g      numeric(14, 4) := 0;
  v_sec_c_equiv_g     numeric(14, 4) := 0;

  -- Section D: Customer Receivables
  v_sec_d_client_obl  numeric(14, 4) := 0;
  v_sec_d_scrap_rec   numeric(14, 4) := 0;
  v_sec_d_cash_rec    numeric(18, 2) := 0;
  v_sec_d_cash_eq     numeric(14, 4) := 0;
  v_sec_d_usd_rec     numeric(18, 2) := 0;
  v_sec_d_usd_eq      numeric(14, 4) := 0;
  v_sec_d_cust_debt   numeric(14, 4) := 0;

  -- Section E: Seller Holdings
  v_sec_e_cash_uzs    numeric(18, 2) := 0;
  v_sec_e_cash_usd    numeric(18, 2) := 0;
  v_sec_e_scrap_g     numeric(14, 4) := 0;

  -- Section F: Seller-to-Manager Settlements & Returns
  v_sec_f_scrap_g     numeric(14, 4) := 0;
  v_sec_f_cash_uzs    numeric(18, 2) := 0;
  v_sec_f_cash_eq     numeric(14, 4) := 0;
  v_sec_f_usd_amount  numeric(18, 2) := 0;
  v_sec_f_usd_eq      numeric(14, 4) := 0;
  v_sec_f_ret_count   integer := 0;
  v_sec_f_ret_orig_g  numeric(14, 4) := 0;
  v_sec_f_ret_obl_g   numeric(14, 4) := 0;
  v_sec_f_total_ded   numeric(14, 4) := 0;

  -- Section G: Signed Bozor Qarzi
  v_sec_g_signed_g    numeric(14, 4) := 0;
  v_sec_g_owes_m_g    numeric(14, 4) := 0;
  v_sec_g_m_owes_s_g  numeric(14, 4) := 0;
  v_expected_obl      numeric(14, 4) := 0;
  v_discrepancy       numeric(14, 4) := 0;
  v_is_reconciled     boolean := true;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  SELECT * INTO v_seller
    FROM public.employees
   WHERE id = p_seller_id AND organization_id = v_caller_org;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sotuvchi topilmadi (%)', p_seller_id;
  END IF;
  IF public._goldia_is_seller_role(public.current_employee_role_text())
     AND p_seller_id IS DISTINCT FROM public.current_employee_id() THEN
    RAISE EXCEPTION 'Ruxsat etilmadi: Sotuvchi faqat o''z hisobotini ko''ra oladi' USING errcode = '42501';
  END IF;

  SELECT * INTO v_seller_acc
    FROM public.seller_gold_accounts
   WHERE seller_id = p_seller_id AND organization_id = v_caller_org;

  -- Section A: Consignments (Sum base_weight + returned_weight + sold_weight, and quantity + returned_quantity + sold_quantity)
  SELECT
    COALESCE(SUM(base_weight_grams + returned_weight_grams), 0),
    COALESCE(SUM(COALESCE(seller_obligation_g, 0) + returned_seller_obligation_g), 0),
    COALESCE(SUM(quantity + returned_quantity + COALESCE(sold_quantity, 0)), 0)
  INTO v_sec_a_orig_g, v_sec_a_obl_g, v_sec_a_count
  FROM public.seller_consignments
  WHERE seller_id = p_seller_id
    AND organization_id = v_caller_org
    AND (status IS NULL OR status NOT IN ('cancelled', 'reversed'));

  -- Legacy customer debts assigned to this seller
  SELECT COALESCE(SUM(delta_585_g), 0)
  INTO v_sec_a_legacy_g
  FROM public.client_legacy_debts
  WHERE seller_id = p_seller_id
    AND organization_id = v_caller_org
    AND balance_type = 'debt'
    AND status <> 'reversed';

  -- Section B: Unsold goods
  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(weight_grams), 0),
    COALESCE(SUM(ROUND(weight_grams * (1.0 + COALESCE(seller_markup_pct, 12.0) / 100.0), 4)), 0)
  INTO v_sec_b_count, v_sec_b_orig_g, v_sec_b_equiv_g
  FROM public.consignment_pieces
  WHERE seller_id = p_seller_id
    AND organization_id = v_caller_org
    AND status = 'held_by_seller';

  -- 068: unsold grams follow the authoritative stock (active consignments - active sales); the piece
  -- total is shown alongside so any shelf/stock difference is visible instead of silently reported.
  v_sec_b_pieces_g := v_sec_b_orig_g;
  SELECT ROUND(GREATEST(0,
           COALESCE((SELECT SUM(base_weight_grams) FROM public.seller_consignments
                      WHERE seller_id = p_seller_id AND organization_id = v_caller_org
                        AND status IN ('held_by_seller', 'partially_sold', 'fully_sold')), 0)
         - COALESCE((SELECT SUM(base_weight_grams) FROM public.jewelry_sales
                      WHERE seller_id = p_seller_id AND organization_id = v_caller_org
                        AND status NOT IN ('cancelled', 'reversed')), 0)), 4)
    INTO v_sec_b_auth_g;
  IF v_sec_b_pieces_g > 0 THEN
    v_sec_b_equiv_g := ROUND(v_sec_b_equiv_g * v_sec_b_auth_g / v_sec_b_pieces_g, 4);
  END IF;
  v_sec_b_orig_g := v_sec_b_auth_g;

  -- Section C: Sold goods (Calculate seller obligation equivalent)
  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(s.base_weight_grams), 0),
    COALESCE(SUM(ROUND(s.base_weight_grams * (1.0 + COALESCE(cp.seller_markup_pct, sc.seller_markup_pct, 12.0) / 100.0), 4)), 0)
  INTO v_sec_c_count, v_sec_c_orig_g, v_sec_c_equiv_g
  FROM public.jewelry_sales s
  LEFT JOIN public.consignment_pieces cp ON cp.sale_id = s.id
  LEFT JOIN public.seller_consignments sc ON sc.id = cp.consignment_id
  WHERE s.seller_id = p_seller_id
    AND s.organization_id = v_caller_org
    AND s.status NOT IN ('cancelled', 'reversed');

  -- Section D: Customer Receivables & Payments
  SELECT
    COALESCE(SUM(s.client_gold_due_grams), 0)
  INTO v_sec_d_client_obl
  FROM public.jewelry_sales s
  WHERE s.seller_id = p_seller_id AND s.organization_id = v_caller_org AND s.status NOT IN ('cancelled', 'reversed');

  SELECT
    COALESCE(SUM(gs.scrap_weight_grams), 0),
    COALESCE(SUM(gs.cash_paid_amount), 0),
    COALESCE(SUM(gs.cash_equivalent_grams), 0),
    COALESCE(SUM(gs.usd_paid_amount), 0),
    COALESCE(SUM(gs.usd_equivalent_grams), 0)
  INTO v_sec_d_scrap_rec, v_sec_d_cash_rec, v_sec_d_cash_eq, v_sec_d_usd_rec, v_sec_d_usd_eq
  FROM public.gold_settlements gs
  WHERE gs.seller_id = p_seller_id
    AND gs.organization_id = v_caller_org
    AND gs.direction = 'client_to_seller'
    AND (gs.status IS NULL OR gs.status NOT IN ('cancelled', 'reversed'));

  v_sec_d_cust_debt := ROUND(GREATEST(0, (v_sec_d_client_obl + v_sec_a_legacy_g) - (v_sec_d_scrap_rec + v_sec_d_cash_eq + v_sec_d_usd_eq)), 4);

  -- Section E: Seller Holdings
  v_sec_e_cash_uzs := COALESCE(v_seller_acc.seller_till_cash_amount, 0);
  v_sec_e_cash_usd := COALESCE(v_seller_acc.seller_till_usd_amount, 0);
  v_sec_e_scrap_g  := COALESCE(v_seller_acc.seller_till_scrap_grams, 0);

  -- Section F: Settlements & Returns
  SELECT
    COALESCE(SUM(gs.scrap_weight_grams), 0),
    COALESCE(SUM(gs.cash_paid_amount), 0),
    COALESCE(SUM(gs.cash_equivalent_grams), 0),
    COALESCE(SUM(gs.usd_paid_amount), 0),
    COALESCE(SUM(gs.usd_equivalent_grams), 0)
  INTO v_sec_f_scrap_g, v_sec_f_cash_uzs, v_sec_f_cash_eq, v_sec_f_usd_amount, v_sec_f_usd_eq
  FROM public.gold_settlements gs
  WHERE gs.seller_id = p_seller_id
    AND gs.organization_id = v_caller_org
    AND gs.direction IN ('seller_to_manager', 'seller_to_factory')
    AND (gs.status IS NULL OR gs.status NOT IN ('reversed', 'cancelled'));

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(cp.weight_grams), 0),
    COALESCE(SUM(ROUND(cp.weight_grams * (1.0 + COALESCE(cp.seller_markup_pct, 12.0) / 100.0), 4)), 0)
  INTO v_sec_f_ret_count, v_sec_f_ret_orig_g, v_sec_f_ret_obl_g
  FROM public.consignment_pieces cp
  WHERE cp.seller_id = p_seller_id
    AND cp.organization_id = v_caller_org
    AND cp.status IN ('returned_to_manager', 'returned_to_factory');

  v_sec_f_total_ded := ROUND(v_sec_f_scrap_g + v_sec_f_cash_eq + v_sec_f_usd_eq + v_sec_f_ret_obl_g, 4);

  -- Section G: Final Signed Bozor Qarzi
  v_sec_g_signed_g   := COALESCE(v_seller_acc.bozor_qarzi_signed_g, 0);
  v_sec_g_owes_m_g   := COALESCE(v_seller_acc.seller_owes_manager_g, 0);
  v_sec_g_m_owes_s_g := COALESCE(v_seller_acc.manager_owes_seller_g, 0);

  v_expected_obl := ROUND(GREATEST(0, (v_sec_a_obl_g + v_sec_a_legacy_g) - v_sec_f_total_ded), 4);
  v_discrepancy  := ROUND(ABS(v_sec_g_owes_m_g - v_expected_obl), 4);
  v_is_reconciled := v_discrepancy < 0.001;

  RETURN jsonb_build_object(
    'status', 'ok',
    'seller_id', p_seller_id,
    'seller_name', COALESCE(v_seller.full_name, v_seller.name, 'Sotuvchi'),
    'as_of_date', to_char(NOW(), 'YYYY-MM-DD HH24:MI'),
    'section_a', jsonb_build_object(
      'title', 'A. Boshqaruvchidan Qabul Qilingan Tovar & Eski Qarzi',
      'item_count', v_sec_a_count,
      'original_grams', v_sec_a_orig_g,
      'seller_markup_obligation_grams', v_sec_a_obl_g,
      'legacy_debt_obligation_grams', v_sec_a_legacy_g,
      'total_obligation_grams', (v_sec_a_obl_g + v_sec_a_legacy_g)
    ),
    'section_b', jsonb_build_object(
      'title', 'B. Sotilmay Qolgan Tovar (Sotuvchi Javonida)',
      'item_count', v_sec_b_count,
      'original_grams', v_sec_b_orig_g,
      'seller_markup_equivalent_grams', v_sec_b_equiv_g,
      'pieces_on_shelf_grams', v_sec_b_pieces_g,
      'pieces_vs_stock_difference_grams', ROUND(v_sec_b_pieces_g - v_sec_b_auth_g, 4)
    ),
    'section_c', jsonb_build_object(
      'title', 'C. Mijozlarga Sotilgan Tovar',
      'item_count', v_sec_c_count,
      'original_grams', v_sec_c_orig_g,
      'seller_markup_equivalent_grams', v_sec_c_equiv_g
    ),
    'section_d', jsonb_build_object(
      'title', 'D. Mijozlar Nasiyasi & Tushumlar',
      'customer_markup_obligation_grams', (v_sec_d_client_obl + v_sec_a_legacy_g),
      'gross_client_obligation_grams', (v_sec_d_client_obl + v_sec_a_legacy_g),
      'scrap_collected_grams', v_sec_d_scrap_rec,
      'cash_collected_uzs', v_sec_d_cash_rec,
      'cash_collected_gold_equiv_grams', v_sec_d_cash_eq,
      'usd_collected_amount', v_sec_d_usd_rec,
      'usd_collected_gold_equiv_grams', v_sec_d_usd_eq,
      'outstanding_customer_debt_grams', v_sec_d_cust_debt,
      'net_client_debt_grams', v_sec_d_cust_debt
    ),
    'section_e', jsonb_build_object(
      'title', 'E. Sotuvchi Kassasidagi Mavjud Naqd & Lom',
      'cash_till_uzs', v_sec_e_cash_uzs,
      'cash_uzs', v_sec_e_cash_uzs,
      'cash_till_usd', v_sec_e_cash_usd,
      'scrap_till_grams', v_sec_e_scrap_g,
      'scrap_grams', v_sec_e_scrap_g
    ),
    'section_f', jsonb_build_object(
      'title', 'F. Boshqaruvchiga Topshirilgan Tushum & Qaytarilgan Tovar',
      'scrap_surrendered_grams', v_sec_f_scrap_g,
      'settlements_scrap_grams', v_sec_f_scrap_g,
      'cash_surrendered_uzs', v_sec_f_cash_uzs,
      'cash_surrendered_gold_equiv_grams', v_sec_f_cash_eq,
      'usd_surrendered_amount', v_sec_f_usd_amount,
      'usd_surrendered_gold_equiv_grams', v_sec_f_usd_eq,
      'returned_pieces_count', v_sec_f_ret_count,
      'returned_unsold_items_count', v_sec_f_ret_count,
      'returned_pieces_original_grams', v_sec_f_ret_orig_g,
      'returned_unsold_original_grams', v_sec_f_ret_orig_g,
      'returned_pieces_seller_obligation_grams', v_sec_f_ret_obl_g,
      'returned_unsold_seller_obligation_grams', v_sec_f_ret_obl_g,
      'returned_unsold_seller_markup_equivalent_grams', v_sec_f_ret_obl_g,
      'total_deducted_from_obligation_grams', v_sec_f_total_ded,
      'total_obligation_deductions_grams', v_sec_f_total_ded
    ),
    'section_g', jsonb_build_object(
      'title', 'G. Yakuniy Bozor Qarzi & Solishtirish',
      'bozor_qarzi_signed_grams', v_sec_g_signed_g,
      'seller_owes_manager_grams', v_sec_g_owes_m_g,
      'manager_owes_seller_grams', v_sec_g_m_owes_s_g,
      'expected_obligation_grams', v_expected_obl,
      'discrepancy_grams', v_discrepancy,
      'is_reconciled', v_is_reconciled
    )
  );
END;
$function$;
revoke all on function rpc_get_seller_reconciliation_statement(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_seller_reconciliation_statement(uuid) to authenticated;
grant execute on function rpc_get_seller_reconciliation_statement(uuid) to service_role;

-- parity: rpc_get_seller_sales_summary(uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_seller_sales_summary(p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_caller_role    text := public.current_employee_role_text();
  v_seller_uuid    uuid := p_seller_id;
  v_caller_emp_id  uuid;
  v_seller_acc     public.seller_gold_accounts%rowtype;
  v_active_consign integer;
  v_active_sales   integer;
  v_client_count   integer;
  v_total_cli_debt numeric(14, 4);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select id into v_caller_emp_id
    from public.employees
   where (user_id = auth.uid() or id = auth.uid())
     and organization_id = v_caller_org
   limit 1;

  if v_seller_uuid is null or v_caller_role not in ('admin', 'director', 'owner', 'direktor', 'rahbar') then
    v_seller_uuid := v_caller_emp_id;
  end if;

  select * into v_seller_acc
    from public.seller_gold_accounts
   where seller_id = v_seller_uuid
     and organization_id = v_caller_org;

  select count(*) into v_active_consign
    from public.seller_consignments
   where seller_id = v_seller_uuid
     and organization_id = v_caller_org
     and status = 'held_by_seller';

  select count(*) into v_active_sales
    from public.jewelry_sales
   where seller_id = v_seller_uuid
     and organization_id = v_caller_org
     and status in ('open_debt', 'partially_paid');

  select count(*), coalesce(sum(current_debt_grams), 0)
    into v_client_count, v_total_cli_debt
    from public.client_gold_accounts
   where seller_id = v_seller_uuid
     and organization_id = v_caller_org;

  return jsonb_build_object(
    'status', 'ok',
    'seller_id', v_seller_uuid,
    'current_factory_obligation_grams', coalesce(v_seller_acc.current_factory_obligation_grams, 0),
    'seller_till_scrap_grams', coalesce(v_seller_acc.seller_till_scrap_grams, 0),
    'seller_till_cash_amount', coalesce(v_seller_acc.seller_till_cash_amount, 0),
    'total_client_debt_grams', coalesce(v_total_cli_debt, 0),
    'active_consignments_count', coalesce(v_active_consign, 0),
    'active_sales_count', coalesce(v_active_sales, 0),
    'assigned_clients_count', coalesce(v_client_count, 0)
  );
end;
$function$;
revoke all on function rpc_get_seller_sales_summary(uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_seller_sales_summary(uuid) to authenticated;
grant execute on function rpc_get_seller_sales_summary(uuid) to service_role;

-- parity: rpc_get_three_tier_ledger_summary()
CREATE OR REPLACE FUNCTION public.rpc_get_three_tier_ledger_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org         uuid := public.current_organization_id();
  v_tier1_received_g   numeric(14, 4) := 0;
  v_tier1_factory_obl  numeric(14, 4) := 0;
  v_tier1_handed_over  numeric(14, 4) := 0;
  v_tier1_factory_due  numeric(14, 4) := 0;
  v_tier2_consigned_g  numeric(14, 4) := 0;
  v_tier2_seller_obl   numeric(14, 4) := 0;
  v_tier2_settled_g    numeric(14, 4) := 0;
  v_tier2_seller_due   numeric(14, 4) := 0;
  v_tier3_sales_due    numeric(14, 4) := 0;
  v_tier3_settled_g    numeric(14, 4) := 0;
  v_tier3_client_debt  numeric(14, 4) := 0;
  v_tier3_advance_g    numeric(14, 4) := 0;
  v_vault_scrap_g      numeric(14, 4) := 0;
  v_vault_cash         numeric(18, 2) := 0;
  v_vault_refined_585  numeric(14, 4) := 0;
  v_manager_avail_g    numeric(14, 4) := 0;
begin
  -- 070: company-wide balances are not visible to sellers
  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter', 'manager', 'production_manager', 'boshqaruvchi']);
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  -- Tier 1: Factory <-> Manager (Filter out reversed receipts!)
  select
    coalesce(sum(original_physical_g), 0),
    coalesce(sum(factory_obligation_g), 0),
    coalesce(sum(available_physical_g), 0)
  into v_tier1_received_g, v_tier1_factory_obl, v_manager_avail_g
  from public.factory_receipts
  where organization_id = v_caller_org and status <> 'reversed';

  select coalesce(sum(agreed_equivalent_g), 0)
  into v_tier1_handed_over
  from public.factory_gold_handovers
  where organization_id = v_caller_org;

  v_tier1_factory_due := round(greatest(0, v_tier1_factory_obl - v_tier1_handed_over), 4);

  -- Tier 2: Manager <-> Seller (Filter out cancelled/reversed consignments and settlements!)
  select
    coalesce(sum(base_weight_grams), 0),
    coalesce(sum(coalesce(seller_obligation_g, factory_gold_due_grams)), 0)
  into v_tier2_consigned_g, v_tier2_seller_obl
  from public.seller_consignments
  where organization_id = v_caller_org and status <> 'cancelled' and status <> 'reversed';

  select coalesce(sum(total_settled_grams), 0)
  into v_tier2_settled_g
  from public.gold_settlements
  where organization_id = v_caller_org and direction = 'seller_to_manager' and status <> 'reversed';

  v_tier2_seller_due := round(greatest(0, v_tier2_seller_obl - v_tier2_settled_g), 4);

  -- Tier 3: Seller <-> Customer (Filter out reversed sales and settlements!)
  select coalesce(sum(client_gold_due_grams), 0)
  into v_tier3_sales_due
  from public.jewelry_sales
  where organization_id = v_caller_org and status <> 'reversed';

  select coalesce(sum(total_settled_grams), 0)
  into v_tier3_settled_g
  from public.gold_settlements
  where organization_id = v_caller_org and direction = 'client_to_seller' and status <> 'reversed';

  select
    coalesce(sum(current_debt_grams), 0),
    coalesce(sum(advance_balance_grams), 0)
  into v_tier3_client_debt, v_tier3_advance_g
  from public.client_gold_accounts
  where organization_id = v_caller_org;

  -- Vault Snapshot
  select
    coalesce(manager_scrap_grams, 0),
    coalesce(manager_cash_amount, 0),
    coalesce(manager_refined_gold_grams, 0)
  into v_vault_scrap_g, v_vault_cash, v_vault_refined_585
  from public.manager_vault_account
  where organization_id = v_caller_org;

  return jsonb_build_object(
    'status', 'ok',
    'tier1_factory', jsonb_build_object(
      'total_obligation_grams', v_tier1_factory_obl,
      'total_handovers_grams', v_tier1_handed_over,
      'net_factory_debt_grams', v_tier1_factory_due,
      'available_stock_grams', v_manager_avail_g
    ),
    'tier1_factory_to_manager', jsonb_build_object(
      'total_received_physical_g', v_tier1_received_g,
      'total_factory_obligation_g', v_tier1_factory_obl,
      'total_handed_over_g', v_tier1_handed_over,
      'current_factory_gold_due_g', v_tier1_factory_due,
      'manager_available_stock_g', v_manager_avail_g
    ),
    'tier2_sellers', jsonb_build_object(
      'total_seller_obligation_grams', v_tier2_seller_obl,
      'total_settled_to_manager_grams', v_tier2_settled_g,
      'bozor_qarzi_signed_grams', -v_tier2_seller_due,
      'net_seller_due_grams', v_tier2_seller_due
    ),
    'tier2_manager_to_seller', jsonb_build_object(
      'total_consigned_physical_g', v_tier2_consigned_g,
      'total_seller_obligation_g', v_tier2_seller_obl,
      'total_surrendered_to_manager_g', v_tier2_settled_g,
      'current_seller_gold_due_g', v_tier2_seller_due
    ),
    'tier3_clients', jsonb_build_object(
      'total_purchased_grams', v_tier3_sales_due,
      'total_settled_grams', v_tier3_settled_g,
      'net_debt_grams', v_tier3_client_debt,
      'advance_balance_grams', v_tier3_advance_g
    ),
    'tier3_seller_to_customer', jsonb_build_object(
      'total_sales_obligation_g', v_tier3_sales_due,
      'total_settled_by_customers_g', v_tier3_settled_g,
      'current_customer_debt_g', v_tier3_client_debt,
      'current_customer_advance_g', v_tier3_advance_g
    ),
    'manager_vault', jsonb_build_object(
      'scrap_gold_585_g', v_vault_scrap_g,
      'refined_gold_585_equiv_g', v_vault_refined_585,
      'cash_amount_uzs', v_vault_cash
    )
  );
end;
$function$;
revoke all on function rpc_get_three_tier_ledger_summary() from public, anon, authenticated, service_role;
grant execute on function rpc_get_three_tier_ledger_summary() to authenticated;
grant execute on function rpc_get_three_tier_ledger_summary() to service_role;

-- parity: rpc_get_unified_customer_ledger(uuid,uuid)
CREATE OR REPLACE FUNCTION public.rpc_get_unified_customer_ledger(p_customer_id uuid DEFAULT NULL::uuid, p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_caller_role    text := public.current_employee_role_text();
  v_caller_emp_id  uuid := public.current_employee_id();
  v_filter_seller  uuid;
  v_cust_rec       record;
  v_gross_sales    numeric(14, 4);
  v_legacy_debt    numeric(14, 4);
  v_paid_scrap     numeric(14, 4);
  v_paid_cash_g    numeric(14, 4);
  v_paid_cash_uzs  numeric(18, 2);
  v_paid_usd_g     numeric(14, 4);
  v_paid_usd       numeric(18, 2);
  v_total_settled_sum numeric(14, 4);
  v_total_paid     numeric(14, 4);
  v_gross_debt     numeric(14, 4);
  v_net_debt       numeric(14, 4);
  v_avail_adv      numeric(14, 4);
  v_applied_adv    numeric(14, 4);
  v_tot_gross      numeric(14, 4) := 0;
  v_tot_paid       numeric(14, 4) := 0;
  v_tot_net        numeric(14, 4) := 0;
  v_tot_adv        numeric(14, 4) := 0;
  v_tot_cash_uzs   numeric(18, 2) := 0;
  v_tot_usd        numeric(18, 2) := 0;
  v_rows           jsonb := '[]'::jsonb;
begin
  -- 069: a signed-in, active employee of this organization is required (no fallbacks)
  if auth.uid() is null then
    raise exception 'Permission denied: authentication required' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi']);
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_caller_role in ('seller', 'sotuvchi', 'sales') then
    if p_seller_id is not null and p_seller_id <> v_caller_emp_id then
      raise exception 'Cross-seller violation: Sotuvchilar faqat o''z mijozlarini ko''ra oladi' using errcode = '42501';
    end if;
    v_filter_seller := v_caller_emp_id;

    if p_customer_id is not null then
      if not exists (
        select 1 from public.customers
        where id = p_customer_id
          and organization_id = v_caller_org
          and (seller_id = v_caller_emp_id or seller_id is null)
      ) then
        raise exception 'Cross-seller violation: Ushbu mijoz sizga biriktirilmagan' using errcode = '42501';
      end if;
    end if;
  else
    v_filter_seller := p_seller_id;
  end if;

  for v_cust_rec in
    select c.id, c.customer_code, c.contact_name, c.phone, c.company_name, c.seller_id,
           coalesce(e.full_name, e.name, 'Biriktirilmagan') as seller_name
    from public.customers c
    left join public.employees e on e.id = c.seller_id
    where c.organization_id = v_caller_org
      and (p_customer_id is null or c.id = p_customer_id)
      and (v_filter_seller is null or c.seller_id = v_filter_seller)
    order by c.contact_name asc
  loop
    -- 1. Total Unreversed Gross Sales Due
    select coalesce(sum(client_gold_due_grams), 0)
    into v_gross_sales
    from public.jewelry_sales
    where customer_id = v_cust_rec.id
      and organization_id = v_caller_org
      and status <> 'reversed';

    -- 2. Total Unreversed Legacy Debt / Advance (Signed Delta Sum)
    select coalesce(sum(delta_585_g), 0)
    into v_legacy_debt
    from public.client_legacy_debts
    where customer_id = v_cust_rec.id
      and organization_id = v_caller_org
      and status <> 'reversed';

    -- 3. Total Unreversed Scrap Gold Paid
    select coalesce(sum(coalesce(scrap_585_equiv_grams, scrap_weight_grams)), 0)
    into v_paid_scrap
    from public.gold_settlements
    where customer_id = v_cust_rec.id
      and organization_id = v_caller_org
      and direction = 'client_to_seller'
      and status <> 'reversed';

    -- 4. Total Unreversed Cash Equivalent Paid (UZS & USD BOTH INCLUDED!)
    select
      coalesce(sum(cash_equivalent_grams), 0),
      coalesce(sum(cash_paid_amount), 0),
      coalesce(sum(usd_equivalent_grams), 0),
      coalesce(sum(usd_paid_amount), 0),
      coalesce(sum(total_settled_grams), 0)
    into v_paid_cash_g, v_paid_cash_uzs, v_paid_usd_g, v_paid_usd, v_total_settled_sum
    from public.gold_settlements
    where customer_id = v_cust_rec.id
      and organization_id = v_caller_org
      and direction = 'client_to_seller'
      and status <> 'reversed';

    -- Total paid strictly combines Scrap + UZS Gold Eq + USD Gold Eq
    v_total_paid := round(v_paid_scrap + v_paid_cash_g + v_paid_usd_g, 4);

    -- Gross obligation combining sales and legacy debt
    if v_legacy_debt >= 0 then
      v_gross_debt := round(v_gross_sales + v_legacy_debt, 4);
      if v_gross_debt >= v_total_paid then
        v_net_debt := round((v_gross_debt - v_total_paid)::numeric, 4);
        v_avail_adv := 0;
      else
        v_net_debt := 0;
        v_avail_adv := round((v_total_paid - v_gross_debt)::numeric, 4);
      end if;
    else
      -- Negative legacy debt means customer had pre-existing advance
      v_gross_debt := v_gross_sales;
      if v_gross_sales >= (v_total_paid + abs(v_legacy_debt)) then
        v_net_debt := round((v_gross_sales - (v_total_paid + abs(v_legacy_debt)))::numeric, 4);
        v_avail_adv := 0;
      else
        v_net_debt := 0;
        v_avail_adv := round(((v_total_paid + abs(v_legacy_debt)) - v_gross_sales)::numeric, 4);
      end if;
    end if;

    -- Applied Advance
    select coalesce(sum(settled_gold_grams), 0)
    into v_applied_adv
    from public.jewelry_sales
    where customer_id = v_cust_rec.id
      and organization_id = v_caller_org
      and status <> 'reversed';

    v_rows := v_rows || jsonb_build_object(
      'customer_id', v_cust_rec.id,
      'customer_code', v_cust_rec.customer_code,
      'contact_name', v_cust_rec.contact_name,
      'phone', v_cust_rec.phone,
      'company_name', v_cust_rec.company_name,
      'seller_id', v_cust_rec.seller_id,
      'seller_name', v_cust_rec.seller_name,
      'gross_debt_g', v_gross_debt,
      'legacy_debt_g', v_legacy_debt,
      'paid_scrap_equivalent_g', v_paid_scrap,
      'paid_cash_equivalent_g', v_paid_cash_g,
      'paid_cash_amount_uzs', v_paid_cash_uzs,
      'paid_usd_equivalent_g', v_paid_usd_g,
      'paid_usd_amount', v_paid_usd,
      'total_paid_g', v_total_paid,
      'applied_advance_g', v_applied_adv,
      'available_advance_g', v_avail_adv,
      'net_debt_g', v_net_debt
    );

    v_tot_gross := v_tot_gross + v_gross_debt;
    v_tot_paid  := v_tot_paid + v_total_paid;
    v_tot_net   := v_tot_net + v_net_debt;
    v_tot_adv   := v_tot_adv + v_avail_adv;
    v_tot_cash_uzs := v_tot_cash_uzs + v_paid_cash_uzs;
    v_tot_usd      := v_tot_usd + v_paid_usd;

    -- Sync client_gold_accounts cache accurately
    insert into public.client_gold_accounts (
      customer_id, organization_id, seller_id, total_purchased_gold_grams,
      total_scrap_paid_grams, total_cash_paid_amount, total_cash_equiv_grams,
      total_usd_paid_amount, total_usd_equiv_grams, total_settled_grams,
      current_debt_grams, advance_balance_grams, updated_at
    ) values (
      v_cust_rec.id, v_caller_org, v_cust_rec.seller_id, v_gross_debt,
      v_paid_scrap, v_paid_cash_uzs, round(v_paid_cash_g + v_paid_usd_g, 4),
      v_paid_usd, v_paid_usd_g, v_total_paid,
      v_net_debt, v_avail_adv, now()
    )
    on conflict (customer_id) do update set
      seller_id = coalesce(excluded.seller_id, client_gold_accounts.seller_id),
      total_purchased_gold_grams = excluded.total_purchased_gold_grams,
      total_scrap_paid_grams = excluded.total_scrap_paid_grams,
      total_cash_paid_amount = excluded.total_cash_paid_amount,
      total_cash_equiv_grams = excluded.total_cash_equiv_grams,
      total_usd_paid_amount  = excluded.total_usd_paid_amount,
      total_usd_equiv_grams  = excluded.total_usd_equiv_grams,
      total_settled_grams = excluded.total_settled_grams,
      current_debt_grams = excluded.current_debt_grams,
      advance_balance_grams = excluded.advance_balance_grams,
      updated_at = now();
  end loop;

  return jsonb_build_object(
    'items', v_rows,
    'summary', jsonb_build_object(
      'total_gross_debt_g', v_tot_gross,
      'total_paid_g', v_tot_paid,
      'total_net_debt_g', v_tot_net,
      'total_advance_g', v_tot_adv,
      'total_cash_uzs', v_tot_cash_uzs,
      'total_usd', v_tot_usd
    )
  );
end;
$function$;
revoke all on function rpc_get_unified_customer_ledger(uuid,uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_get_unified_customer_ledger(uuid,uuid) to authenticated;
grant execute on function rpc_get_unified_customer_ledger(uuid,uuid) to service_role;

-- parity: rpc_inventory_transaction(text,text,numeric,numeric,numeric,text,text,text,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_inventory_transaction(p_item_id text, p_tx_type text, p_weight numeric, p_proba numeric DEFAULT 0, p_pure_gold numeric DEFAULT 0, p_from_location text DEFAULT 'safe'::text, p_to_location text DEFAULT 'safe'::text, p_description text DEFAULT ''::text, p_order_id text DEFAULT NULL::text, p_order_no text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org  uuid := public.current_organization_id();
  v_item        public.inventory_items%rowtype;
  v_res_row     public.inventory_reservations%rowtype;
  v_weight      numeric(14, 4);
  v_on_hand     numeric(14, 4);
  v_reserved    numeric(14, 4);
  v_avail       numeric(14, 4);
  v_fine        numeric(18, 6);
  v_existing    jsonb;
  v_payload     jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'warehouse', 'omborchi',
    'inventory_manager', 'manager', 'production_manager', 'production manager'
  ]);

  if p_weight is null or p_weight <= 0 then
    raise exception 'Inventory transaction weight must be greater than zero';
  end if;

  v_weight := round(p_weight::numeric, 4);

  v_payload := jsonb_build_object(
    'item_id', btrim(coalesce(p_item_id, '')),
    'tx_type', btrim(coalesce(p_tx_type, '')),
    'weight', v_weight,
    'order_id', btrim(coalesce(p_order_id, ''))
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_inventory_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_item_id), '') = '' then
    raise exception 'Inventory item ID is required';
  end if;

  select * into v_item
    from public.inventory_items
   where id::text = btrim(p_item_id)
     and organization_id = v_caller_org
     for update;

  if not found then
    raise exception 'Inventory item (%) not found in your organization', p_item_id using errcode = '42501';
  end if;

  v_on_hand  := coalesce(v_item.on_hand, v_item.quantity_on_hand, 0);
  v_reserved := coalesce(v_item.reserved, 0);
  v_avail    := v_on_hand - v_reserved;
  v_fine     := round(coalesce(p_pure_gold, public.calc_fine_gold_exact(v_weight, coalesce(nullif(p_proba, 0), v_item.proba, 0))), 6);

  if p_tx_type = 'kirim' then
    v_on_hand := v_on_hand + v_weight;
  elsif p_tx_type = 'chiqim' then
    if v_weight > v_avail then
      raise exception 'Insufficient available inventory: requested %g exceeds available %g (total on-hand %g, reserved %g)',
        v_weight, v_avail, v_on_hand, v_reserved;
    end if;
    v_on_hand := v_on_hand - v_weight;
  elsif p_tx_type = 'reserve' then
    if v_weight > v_avail then
      raise exception 'Cannot reserve %g: exceeds available on-hand %g', v_weight, v_avail;
    end if;
    v_reserved := v_reserved + v_weight;

    insert into public.inventory_reservations (
      inventory_item_id, order_id, order_no, reserved_grams, status, idempotency_key, created_by, organization_id
    ) values (
      v_item.id, p_order_id, p_order_no, v_weight, 'ACTIVE', nullif(btrim(p_idempotency_key), ''), auth.uid(), v_caller_org
    );

    if p_order_id is not null and btrim(p_order_id) <> '' then
      update public.orders
         set reserved_item_id = v_item.id,
             reserved_gold_gram = coalesce(reserved_gold_gram, 0) + v_weight
       where id::text = btrim(p_order_id)
         and organization_id = v_caller_org;
    end if;
  elsif p_tx_type = 'unreserve' then
    if v_weight > v_reserved then
      raise exception 'Cannot unreserve %g: only %g currently reserved', v_weight, v_reserved;
    end if;
    v_reserved := v_reserved - v_weight;

    if p_order_id is not null and btrim(p_order_id) <> '' then
      select * into v_res_row
        from public.inventory_reservations
       where inventory_item_id = v_item.id
         and order_id::text = btrim(p_order_id)
         and organization_id = v_caller_org
         and status = 'ACTIVE'
       order by created_at asc
       limit 1
         for update;

      if found then
        update public.inventory_reservations
           set released_grams = released_grams + least(v_weight, reserved_grams - consumed_grams - released_grams),
               status = case
                 when consumed_grams + released_grams + v_weight >= reserved_grams then 'RELEASED'
                 else 'ACTIVE'
               end,
               updated_at = now()
         where id = v_res_row.id;
      end if;

      update public.orders
         set reserved_gold_gram = greatest(0, coalesce(reserved_gold_gram, 0) - v_weight)
       where id::text = btrim(p_order_id)
         and organization_id = v_caller_org;
    end if;
  else
    raise exception 'Unsupported inventory transaction type: %', p_tx_type;
  end if;

  update public.inventory_items
     set on_hand = v_on_hand,
         quantity_on_hand = v_on_hand,
         reserved = v_reserved,
         updated_at = now()
   where id = v_item.id;

  insert into public.gold_transactions (
    transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, description, idempotency_key, performed_by, organization_id
  ) values (
    p_tx_type, p_from_location, p_to_location, v_item.name,
    v_weight, v_weight, coalesce(nullif(p_proba, 0), v_item.proba, 0), v_fine,
    p_description, nullif(btrim(p_idempotency_key), ''), public.current_employee_id(), v_caller_org
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'item_id', v_item.id::text,
    'on_hand', v_on_hand,
    'reserved', v_reserved,
    'available', v_on_hand - v_reserved,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_inventory_transaction', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_inventory_transaction(text,text,numeric,numeric,numeric,text,text,text,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_inventory_transaction(text,text,numeric,numeric,numeric,text,text,text,text,text,text) to authenticated;
grant execute on function rpc_inventory_transaction(text,text,numeric,numeric,numeric,text,text,text,text,text,text) to service_role;

-- parity: rpc_issue_barcode_consignment(uuid,numeric,jsonb,text,text,uuid,numeric)
CREATE OR REPLACE FUNCTION public.rpc_issue_barcode_consignment(p_seller_id uuid, p_factory_markup_pct numeric DEFAULT 0, p_pieces jsonb DEFAULT '[]'::jsonb, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_factory_receipt_id uuid DEFAULT NULL::uuid, p_seller_markup_pct numeric DEFAULT 12.00)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org        uuid := public.current_organization_id();
  v_seller            public.employees%rowtype;
  v_factory_pct       numeric(6, 2) := ROUND(COALESCE(p_factory_markup_pct, 0)::numeric, 2);
  v_seller_pct        numeric(6, 2) := ROUND(COALESCE(p_seller_markup_pct, 12.00)::numeric, 2);
  v_total_base_weight numeric(14, 4) := 0;
  v_total_qty         integer := 0;
  v_factory_due       numeric(14, 4) := 0;
  v_seller_due        numeric(14, 4) := 0;
  v_consignment_id    uuid;
  v_consignment_no    text;
  v_piece_elem        jsonb;
  v_piece_id          uuid;
  v_model_id          uuid;
  v_model_code        text;
  v_model_name        text;
  v_category          text;
  v_purity            numeric(6, 2);
  v_weight            numeric(14, 4);
  v_raw_barcode       text;
  v_piece_seller_obl  numeric(14, 4);
  v_inserted_pieces   jsonb := '[]'::jsonb;
  v_payload           jsonb;
  v_existing          jsonb;
  v_receipt_id        uuid := p_factory_receipt_id;
  v_receipt_rec       record;
  v_cur_receipt       record;
  v_total_avail       numeric(14, 4) := 0;
  v_rem_to_deduct     numeric(14, 4) := 0;
  v_take_g            numeric(14, 4) := 0;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'production_manager', 'manager', 'boshqaruvchi', 'inventory_manager'
  ]);

  IF JSONB_ARRAY_LENGTH(p_pieces) = 0 THEN
    RAISE EXCEPTION 'Kamida 1 ta mahsulot dona skaner qilinishi shart';
  END IF;

  SELECT * INTO v_seller
    FROM public.employees
   WHERE id = p_seller_id AND organization_id = v_caller_org
   LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sotuvchi xodimi topilmadi (%)', p_seller_id;
  END IF;

  v_payload := jsonb_build_object(
    'action', 'issue_barcode_consignment',
    'seller_id', p_seller_id,
    'factory_markup_pct', v_factory_pct,
    'seller_markup_pct', v_seller_pct,
    'piece_count', JSONB_ARRAY_LENGTH(p_pieces),
    'factory_receipt_id', p_factory_receipt_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_issue_barcode_consignment', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  -- Validate pieces weight and calculate totals
  FOR v_piece_elem IN SELECT * FROM jsonb_array_elements(p_pieces) LOOP
    v_weight := ROUND(COALESCE((v_piece_elem->>'weight_grams')::numeric, 0), 4);
    IF v_weight <= 0 OR v_weight > 1000.0 THEN
      RAISE EXCEPTION 'Noto''g''ri mahsulot vazni aniqlandi: % g (ruxsat: 0.05g - 1000g)', v_weight;
    END IF;
    v_total_base_weight := v_total_base_weight + v_weight;
    v_total_qty := v_total_qty + 1;
  END LOOP;

  v_total_base_weight := ROUND(v_total_base_weight, 4);
  v_factory_due := ROUND((v_total_base_weight * (1.0 + v_factory_pct / 100.0))::numeric, 4);
  v_seller_due  := ROUND((v_total_base_weight * (1.0 + v_seller_pct / 100.0))::numeric, 4);

  -- Deduct manager physical stock from factory_receipt(s)
  IF v_receipt_id IS NOT NULL THEN
    SELECT * INTO v_receipt_rec
      FROM public.factory_receipts
     WHERE id = v_receipt_id AND organization_id = v_caller_org AND status <> 'reversed'
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Belgilangan zavod kirim hujjati (%) topilmadi yoki bekor qilingan', v_receipt_id;
    END IF;

    IF COALESCE(v_receipt_rec.available_physical_g, 0) < v_total_base_weight THEN
      RAISE EXCEPTION 'Menejer omborida yetarli tovar yo''q: tanlangan kirimda mavjud % g, talab qilindi % g',
        COALESCE(v_receipt_rec.available_physical_g, 0), v_total_base_weight;
    END IF;

    UPDATE public.factory_receipts
       SET available_physical_g = ROUND((available_physical_g - v_total_base_weight)::numeric, 4),
           transferred_physical_g = ROUND((transferred_physical_g + v_total_base_weight)::numeric, 4),
           status = CASE WHEN ROUND((available_physical_g - v_total_base_weight)::numeric, 4) <= 0.0001 THEN 'fully_transferred' ELSE 'partially_transferred' END,
           updated_at = NOW()
     WHERE id = v_receipt_id;
  ELSE
    -- Automatic FIFO deduction across active factory receipts
    SELECT COALESCE(SUM(available_physical_g), 0) INTO v_total_avail
      FROM public.factory_receipts
     WHERE organization_id = v_caller_org AND status <> 'reversed';

    IF v_total_avail < v_total_base_weight THEN
      RAISE EXCEPTION 'Menejer omborida yetarli tovar yo''q: mavjud % g, talab qilindi % g',
        v_total_avail, v_total_base_weight;
    END IF;

    v_rem_to_deduct := v_total_base_weight;
    FOR v_cur_receipt IN
      SELECT * FROM public.factory_receipts
       WHERE organization_id = v_caller_org AND status <> 'reversed' AND available_physical_g > 0
       ORDER BY receipt_date ASC, created_at ASC
       FOR UPDATE
    LOOP
      v_take_g := LEAST(v_rem_to_deduct, v_cur_receipt.available_physical_g);

      UPDATE public.factory_receipts
         SET available_physical_g = ROUND((available_physical_g - v_take_g)::numeric, 4),
             transferred_physical_g = ROUND((transferred_physical_g + v_take_g)::numeric, 4),
             status = CASE WHEN ROUND((available_physical_g - v_take_g)::numeric, 4) <= 0.0001 THEN 'fully_transferred' ELSE 'partially_transferred' END,
             updated_at = NOW()
       WHERE id = v_cur_receipt.id;

      IF v_receipt_id IS NULL THEN
        v_receipt_id := v_cur_receipt.id;
      END IF;

      v_rem_to_deduct := ROUND((v_rem_to_deduct - v_take_g)::numeric, 4);
      IF v_rem_to_deduct <= 0.0001 THEN
        EXIT;
      END IF;
    END LOOP;

    IF v_rem_to_deduct > 0.0001 THEN
      RAISE EXCEPTION 'Menejer omborida FIFO bo''yicha yetarli tovar topilmadi: yetishmayotgan qoldiq % g', v_rem_to_deduct;
    END IF;
  END IF;

  v_consignment_no := 'CONS-BC-' || UPPER(SUBSTR(md5(random()::text || clock_timestamp()::text), 1, 8));

  INSERT INTO public.seller_consignments (
    organization_id, consignment_no, seller_id, factory_receipt_id, product_name,
    quantity, base_weight_grams, proba, factory_markup_pct, factory_gold_due_grams,
    factory_remaining_gold_grams, seller_markup_pct, seller_obligation_g, status, notes
  ) VALUES (
    v_caller_org, v_consignment_no, p_seller_id, v_receipt_id, 'Konsignatsiya Partiyasi',
    v_total_qty, v_total_base_weight, 585, v_factory_pct, v_factory_due,
    v_factory_due, v_seller_pct, v_seller_due, 'held_by_seller', p_notes
  ) RETURNING id INTO v_consignment_id;

  -- Insert piece rows
  FOR v_piece_elem IN SELECT * FROM jsonb_array_elements(p_pieces) LOOP
    v_piece_id := gen_random_uuid();
    v_model_id := NULLIF(v_piece_elem->>'model_id', '')::uuid;
    v_model_code := COALESCE(NULLIF(BTRIM(v_piece_elem->>'model_code'), ''), 'VAZN');
    v_model_name := COALESCE(NULLIF(BTRIM(v_piece_elem->>'model_name'), ''), 'Zargarlik Buyumi (Standart 585)');
    v_category := COALESCE(NULLIF(BTRIM(v_piece_elem->>'category'), ''), 'Buyum');
    v_purity := COALESCE((v_piece_elem->>'purity')::numeric, 585.00);
    v_weight := ROUND((v_piece_elem->>'weight_grams')::numeric, 4);
    v_raw_barcode := COALESCE(v_piece_elem->>'raw_barcode', v_piece_elem->>'weight_grams');
    v_piece_seller_obl := ROUND((v_weight * (1.0 + v_seller_pct / 100.0))::numeric, 4);

    INSERT INTO public.consignment_pieces (
      id, organization_id, consignment_id, model_id, model_code, model_name,
      category, purity, weight_grams, status, seller_id, raw_barcode, notes,
      seller_markup_pct, seller_obligation_grams
    ) VALUES (
      v_piece_id, v_caller_org, v_consignment_id, v_model_id, v_model_code, v_model_name,
      v_category, v_purity, v_weight, 'held_by_seller', p_seller_id, v_raw_barcode, p_notes,
      v_seller_pct, v_piece_seller_obl
    );

    v_inserted_pieces := v_inserted_pieces || jsonb_build_object(
      'id', v_piece_id,
      'piece_id', v_piece_id,
      'model_code', v_model_code,
      'weight_grams', v_weight,
      'seller_obligation_grams', v_piece_seller_obl
    );
  END LOOP;

  -- Sync seller gold account
  PERFORM public.recalc_seller_gold_account(p_seller_id, v_caller_org);

  -- Sync manager vault
  PERFORM public._get_or_create_manager_vault(v_caller_org);
  UPDATE public.manager_vault_account
     SET manager_physical_stock_g = public.get_manager_available_stock_grams(v_caller_org),
         updated_at = NOW()
   WHERE organization_id = v_caller_org;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'consignment_id', v_consignment_id,
    'consignment_no', v_consignment_no,
    'seller_id', p_seller_id,
    'quantity', v_total_qty,
    'pieces_count', v_total_qty,
    'item_count', v_total_qty,
    'base_weight_grams', v_total_base_weight,
    'factory_markup_pct', v_factory_pct,
    'factory_gold_due_grams', v_factory_due,
    'seller_markup_pct', v_seller_pct,
    'seller_obligation_g', v_seller_due,
    'pieces', v_inserted_pieces
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_issue_barcode_consignment', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_issue_barcode_consignment(uuid,numeric,jsonb,text,text,uuid,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_issue_barcode_consignment(uuid,numeric,jsonb,text,text,uuid,numeric) to authenticated;
grant execute on function rpc_issue_barcode_consignment(uuid,numeric,jsonb,text,text,uuid,numeric) to service_role;

-- parity: rpc_issue_seller_consignment(uuid,uuid,integer,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_issue_seller_consignment(p_seller_id uuid, p_product_id uuid, p_quantity integer DEFAULT 1, p_factory_markup_pct numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_prod          public.products%rowtype;
  v_seller        public.employees%rowtype;
  v_qty           integer := coalesce(p_quantity, 1);
  v_markup_pct    numeric(6, 2) := round(coalesce(p_factory_markup_pct, 0)::numeric, 2);
  v_base_w        numeric(14, 4);
  v_factory_due   numeric(14, 4);
  v_consignment_id uuid;
  v_consignment_no text;
  v_cur_stock     integer;
  v_payload       jsonb;
  v_existing      jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter', 'warehouse', 'omborchi'
  ]);

  if v_qty <= 0 then
    raise exception 'Consignment quantity must be greater than 0';
  end if;
  if v_markup_pct < 0 then
    raise exception 'Factory markup percentage cannot be negative';
  end if;

  v_payload := jsonb_build_object(
    'action', 'issue_consignment',
    'seller_id', p_seller_id,
    'product_id', p_product_id,
    'quantity', v_qty,
    'factory_markup_pct', v_markup_pct
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_issue_seller_consignment', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- Verify seller
  select * into v_seller
    from public.employees
   where id = p_seller_id
     and organization_id = v_caller_org
   limit 1;
  if not found then
    raise exception 'Seller (employee %) not found in your organization', p_seller_id;
  end if;

  -- Lock product and verify stock
  select * into v_prod
    from public.products
   where id = p_product_id
     and organization_id = v_caller_org
   for update;
  if not found then
    raise exception 'Product (%) not found in finished goods inventory', p_product_id;
  end if;

  v_cur_stock := coalesce(v_prod.stock, v_prod.quantity, 0);
  if v_qty > v_cur_stock then
    raise exception 'Insufficient stock for "%": available=%, requested=%', v_prod.name, v_cur_stock, v_qty;
  end if;

  -- Total base weight for given quantity
  v_base_w := round((coalesce(v_prod.weight, 0) * v_qty)::numeric, 4);
  if v_base_w <= 0 then
    raise exception 'Product weight must be greater than 0 for gold consignment';
  end if;

  -- Non-compounding: Factory gold due = base_weight * (1 + factory_markup / 100)
  v_factory_due := round((v_base_w * (1.0 + v_markup_pct / 100.0))::numeric, 4);

  -- Deduct product stock from factory vitrina
  update public.products
     set stock      = v_cur_stock - v_qty,
         quantity   = v_cur_stock - v_qty,
         updated_at = now()
   where id = v_prod.id;

  v_consignment_no := 'CONS-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  insert into public.seller_consignments (
    organization_id, consignment_no, seller_id, product_id, product_name,
    quantity, base_weight_grams, proba, factory_markup_pct,
    factory_gold_due_grams, factory_settled_gold_grams, factory_remaining_gold_grams,
    sold_quantity, status, idempotency_key, notes
  ) values (
    v_caller_org, v_consignment_no, v_seller.id, v_prod.id, v_prod.name,
    v_qty, v_base_w, coalesce(v_prod.proba, 585), v_markup_pct,
    v_factory_due, 0, v_factory_due,
    0, 'held_by_seller', nullif(btrim(p_idempotency_key), ''), p_notes
  ) returning id into v_consignment_id;

  -- Update seller factory obligation in seller_gold_accounts
  insert into public.seller_gold_accounts (
    seller_id, organization_id, total_consigned_gold_grams, current_factory_obligation_grams, updated_at
  ) values (
    v_seller.id, v_caller_org, v_factory_due, v_factory_due, now()
  )
  on conflict (seller_id) do update set
    total_consigned_gold_grams       = round((seller_gold_accounts.total_consigned_gold_grams + v_factory_due)::numeric, 4),
    current_factory_obligation_grams = round((seller_gold_accounts.current_factory_obligation_grams + v_factory_due)::numeric, 4),
    updated_at                       = now();

  v_existing := jsonb_build_object(
    'status', 'ok',
    'consignment_id', v_consignment_id,
    'consignment_no', v_consignment_no,
    'seller_id', v_seller.id,
    'product_name', v_prod.name,
    'quantity', v_qty,
    'base_weight_grams', v_base_w,
    'proba', coalesce(v_prod.proba, 585),
    'factory_markup_pct', v_markup_pct,
    'factory_gold_due_grams', v_factory_due,
    'remaining_stock', v_cur_stock - v_qty
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_issue_seller_consignment', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_issue_seller_consignment(uuid,uuid,integer,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_issue_seller_consignment(uuid,uuid,integer,numeric,text,text) to authenticated;
grant execute on function rpc_issue_seller_consignment(uuid,uuid,integer,numeric,text,text) to service_role;

-- parity: rpc_launch_order_production_chain(text,text,text,text,text,text,numeric,integer,numeric,numeric,text,date,text)
CREATE OR REPLACE FUNCTION public.rpc_launch_order_production_chain(p_order_id text, p_source_item_id text, p_batch_no text, p_product_name text, p_client_name text, p_master_name text, p_proba numeric, p_planned_qty integer, p_issued_gold_gram numeric, p_pure_gold numeric, p_priority text DEFAULT 'Normal'::text, p_deadline date DEFAULT NULL::date, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ord          public.orders%rowtype;
  v_src          public.inventory_items%rowtype;
  v_issued       numeric(14, 4) := round(coalesce(p_issued_gold_gram, 0)::numeric, 4);
  v_from_res     numeric(14, 4) := 0;
  v_from_avail   numeric(14, 4) := 0;
  v_avail        numeric(14, 4);
  v_batch_id     text;
  v_fine         numeric(18, 6);
  v_existing     jsonb;
  v_payload      jsonb;
begin
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  v_payload := jsonb_build_object(
    'order_id', btrim(coalesce(p_order_id, '')),
    'source_item_id', btrim(coalesce(p_source_item_id, '')),
    'batch_no', btrim(coalesce(p_batch_no, '')),
    'issued_gold_gram', v_issued
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_launch_order_production_chain', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_order_id), '') = '' or coalesce(btrim(p_source_item_id), '') = '' or coalesce(btrim(p_batch_no), '') = '' then
    raise exception 'Order ID, source gold item ID, and batch number are required';
  end if;

  select * into v_ord from public.orders where id::text = btrim(p_order_id) for update;
  if not found then
    raise exception 'Order (%) not found', p_order_id;
  end if;

  if coalesce(v_ord.batch_created, false) then
    raise exception 'Production batch has already been created for order %', coalesce(v_ord.order_no, p_order_id);
  end if;

  select * into v_src from public.inventory_items where id::text = btrim(p_source_item_id) for update;
  if not found then
    raise exception 'Source gold item not found';
  end if;

  -- Consume gold reserved specifically for this order first, then draw remainder from available
  if v_ord.reserved_item_id is not null and v_ord.reserved_item_id::text = v_src.id::text and coalesce(v_ord.reserved_gold_gram, 0) > 0 then
    v_from_res := least(v_issued, coalesce(v_ord.reserved_gold_gram, 0), coalesce(v_src.reserved, 0));
  end if;
  v_from_avail := v_issued - v_from_res;
  v_avail := coalesce(v_src.on_hand, v_src.quantity_on_hand, 0) - coalesce(v_src.reserved, 0);

  if v_from_avail > v_avail then
    raise exception 'Insufficient available gold for order: needed=%g (after %g reserved), available=%g',
      v_from_avail, v_from_res, v_avail;
  end if;

  update public.inventory_items
     set on_hand = coalesce(on_hand, quantity_on_hand, 0) - v_issued,
         quantity_on_hand = coalesce(on_hand, quantity_on_hand, 0) - v_issued,
         reserved = coalesce(reserved, 0) - v_from_res
   where id = v_src.id;

  if v_from_res > 0 then
    update public.inventory_reservations
       set consumed_grams = consumed_grams + v_from_res,
           status = case
             when consumed_grams + released_grams + v_from_res >= reserved_grams then 'CONSUMED'
             else 'ACTIVE'
           end,
           batch_no = btrim(p_batch_no),
           updated_at = now()
     where order_id::text = btrim(p_order_id)
       and inventory_item_id = v_src.id
       and status = 'ACTIVE';
  end if;

  update public.orders
     set batch_created = true,
         status = 'Ishlab chiqarishda',
         status_label = 'Ishlab chiqarishda',
         reserved_gold_gram = greatest(0, coalesce(reserved_gold_gram, 0) - v_from_res)
   where id = v_ord.id;

  v_fine := public.calc_fine_gold_exact(v_issued, p_proba);

  insert into public.batches (
    order_id, batch_number, batch_no, number, product_name, product,
    client_name, master_name, proba, planned_qty, planned_gram,
    issued_gold_gram, wip_gram, good_output_gram, sprue_gram, scrap_gram,
    rework_gram, loss_gram, finished_qty, credited_finished_qty,
    current_step, status, status_label, priority, priority_label, deadline, due_date
  ) values (
    v_ord.id, btrim(p_batch_no), btrim(p_batch_no), btrim(p_batch_no), btrim(p_product_name), btrim(p_product_name),
    btrim(p_client_name), btrim(p_master_name), p_proba, p_planned_qty, v_issued,
    v_issued, v_issued, 0, 0, 0,
    0, 0, 0, 0,
    '8. Quyish', 'Jarayonda', 'Jarayonda', p_priority, p_priority, p_deadline, p_deadline
  ) returning id::text into v_batch_id;

  insert into public.batch_stage_wip (
    batch_id, batch_no, stage_order, stage_name, department,
    available_qty, completed_qty, rework_qty, input_weight, output_weight, loss_weight,
    queue_status, assigned_worker
  ) values (
    v_batch_id, btrim(p_batch_no), 8, '8. Quyish', 'Quyish',
    p_planned_qty, 0, 0, v_issued, 0, 0,
    'NOW', btrim(p_master_name)
  );

  insert into public.gold_transactions (
    transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, batch_no, description, idempotency_key, performed_by
  ) values (
    'chiqim', 'SAFE', 'CASTING', v_src.name,
    v_issued, v_issued, p_proba, v_fine, btrim(p_batch_no),
    format('Order %s -> Batch %s (%s pcs / %sg, reserved_used=%sg)',
      coalesce(v_ord.order_no, p_order_id), btrim(p_batch_no), p_planned_qty, v_issued, v_from_res),
    nullif(btrim(p_idempotency_key), ''), public.current_employee_id()
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'order_id', v_ord.id::text,
    'batch_id', v_batch_id,
    'batch_no', btrim(p_batch_no),
    'issued_gold_gram', v_issued,
    'reserved_consumed_gram', v_from_res
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_launch_order_production_chain', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_launch_order_production_chain(text,text,text,text,text,text,numeric,integer,numeric,numeric,text,date,text) from public, anon, authenticated, service_role;
grant execute on function rpc_launch_order_production_chain(text,text,text,text,text,text,numeric,integer,numeric,numeric,text,date,text) to authenticated;
grant execute on function rpc_launch_order_production_chain(text,text,text,text,text,text,numeric,integer,numeric,numeric,text,date,text) to service_role;

-- parity: rpc_manage_sales_markup_preset(uuid,text,text,numeric,boolean,boolean,integer)
CREATE OR REPLACE FUNCTION public.rpc_manage_sales_markup_preset(p_preset_id uuid DEFAULT NULL::uuid, p_type text DEFAULT 'client_markup'::text, p_name text DEFAULT ''::text, p_percentage numeric DEFAULT 0, p_is_active boolean DEFAULT true, p_is_default boolean DEFAULT false, p_display_order integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org   uuid := public.current_organization_id();
  v_res_id       uuid;
  v_type         text := lower(btrim(coalesce(p_type, 'client_markup')));
  v_pct          numeric(6, 2) := round(coalesce(p_percentage, 0)::numeric, 2);
  v_clean_name   text := btrim(coalesce(p_name, ''));
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar']);

  if v_type not in ('factory_markup', 'client_markup') then
    raise exception 'Invalid markup type: must be "factory_markup" or "client_markup"';
  end if;
  if v_pct < 0 or v_pct > 100 then
    raise exception 'Percentage must be between 0 and 100';
  end if;
  if v_clean_name = '' then
    v_clean_name := case when v_type = 'factory_markup' then 'Zavod ' else 'Mijoz ' end || v_pct || '%';
  end if;

  if p_is_default then
    -- Reset previous default for this org and type
    update public.sales_markup_presets
       set is_default = false
     where organization_id = v_caller_org
       and type = v_type;
  end if;

  if p_preset_id is not null then
    update public.sales_markup_presets
       set name          = v_clean_name,
           percentage    = v_pct,
           is_active     = coalesce(p_is_active, is_active),
           is_default    = coalesce(p_is_default, is_default),
           display_order = coalesce(p_display_order, display_order),
           updated_at    = now()
     where id = p_preset_id
       and organization_id = v_caller_org
     returning id into v_res_id;
  else
    insert into public.sales_markup_presets (
      organization_id, type, name, percentage, is_active, is_default, display_order
    ) values (
      v_caller_org, v_type, v_clean_name, v_pct, coalesce(p_is_active, true), coalesce(p_is_default, false), coalesce(p_display_order, 0)
    )
    on conflict (organization_id, type, percentage)
    do update set
      name          = excluded.name,
      is_active     = excluded.is_active,
      is_default    = excluded.is_default,
      display_order = excluded.display_order,
      updated_at    = now()
    returning id into v_res_id;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'preset_id', v_res_id,
    'type', v_type,
    'name', v_clean_name,
    'percentage', v_pct,
    'is_active', coalesce(p_is_active, true),
    'is_default', coalesce(p_is_default, false)
  );
end;
$function$;
revoke all on function rpc_manage_sales_markup_preset(uuid,text,text,numeric,boolean,boolean,integer) from public, anon, authenticated, service_role;
grant execute on function rpc_manage_sales_markup_preset(uuid,text,text,numeric,boolean,boolean,integer) to authenticated;
grant execute on function rpc_manage_sales_markup_preset(uuid,text,text,numeric,boolean,boolean,integer) to service_role;

-- parity: rpc_move_partial_wip(text,integer,integer,text,text,integer,numeric,numeric,integer,numeric,numeric,numeric,text,text,text,boolean,text)
CREATE OR REPLACE FUNCTION public.rpc_move_partial_wip(p_batch_id text, p_from_stage_order integer, p_to_stage_order integer, p_to_stage_name text, p_to_department text, p_move_qty integer, p_move_gram numeric DEFAULT NULL::numeric, p_move_weight numeric DEFAULT NULL::numeric, p_rework_qty integer DEFAULT 0, p_sprue_gram numeric DEFAULT 0, p_scrap_gram numeric DEFAULT 0, p_loss_gram numeric DEFAULT 0, p_worker_name text DEFAULT ''::text, p_worker_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_allow_excess_loss boolean DEFAULT false, p_excess_loss_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org        uuid := public.current_organization_id();
  v_batch             public.batches%rowtype;
  v_cur_wip           public.batch_stage_wip%rowtype;
  v_nxt_wip           public.batch_stage_wip%rowtype;
  v_prod              public.products%rowtype;
  v_batch_code        text;
  v_rem_qty           integer;
  v_move_g            numeric(14, 4) := round(coalesce(p_move_weight, p_move_gram, 0)::numeric, 4);
  v_sprue_g           numeric(14, 4) := round(coalesce(p_sprue_gram, 0)::numeric, 4);
  v_scrap_g           numeric(14, 4) := round(coalesce(p_scrap_gram, 0)::numeric, 4);
  v_loss_g            numeric(14, 4) := round(coalesce(p_loss_gram, 0)::numeric, 4);
  v_new_sprue         numeric(14, 4);
  v_new_scrap         numeric(14, 4);
  v_new_loss          numeric(14, 4);
  v_new_good          numeric(14, 4);
  v_in_gold           numeric(14, 4);
  v_tot_out           numeric(14, 4);
  v_new_wip_g         numeric(14, 4);
  v_actual_target_st  integer := p_to_stage_order;
  v_actual_target_nm  text    := btrim(p_to_stage_name);
  v_actual_target_dp  text    := btrim(p_to_department);
  v_is_final          boolean;
  v_new_fin_qty       integer;
  v_credit_qty        integer := 0;
  v_done_all          boolean;
  v_existing          jsonb;
  v_payload           jsonb;

  -- Stage Loss Threshold Variables
  v_proc_weight       numeric(14, 4);
  v_max_loss_pct      numeric(6, 3);
  v_max_loss_gram     numeric(14, 4);
  v_loss_pct          numeric(6, 3);
  v_limit_by_pct      numeric(14, 4);
  v_effective_limit   numeric(14, 4);
  v_excess_loss_g     numeric(14, 4);
  v_avail_stage_g     numeric(14, 4);
  v_rem_stage_g       numeric(14, 4);
  v_caller_role       text := public.current_employee_role_text();
  v_org_code          text;

  -- batch_operations sync variables
  v_stage_uuid        uuid;
  v_dept_uuid         uuid;
  v_open_op_id        uuid;
  v_existing_op_id    uuid;
  v_next_attempt      integer;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  -- Resolve organization code for factory bypass verification
  select code into v_org_code from public.organizations where id = v_caller_org;

  -- GOLDIA FACTORY BYPASS RULES ENFORCEMENT:
  -- Ponza (Stage 9) and Zircon (Stage 13) are strictly bypassed in Goldia
  if v_org_code = 'goldia' or v_caller_org = '00000000-0000-0000-0000-000000000001'::uuid then
    if v_actual_target_st = 9 then
      v_actual_target_st := 10;
      v_actual_target_nm := '10. Yig''uv';
      v_actual_target_dp := 'Yig''uv';
    elsif v_actual_target_st = 13 then
      v_actual_target_st := 14;
      v_actual_target_nm := '14. Zakrepka';
      v_actual_target_dp := 'Zakrepka';
    end if;
  end if;

  v_is_final := (v_actual_target_st >= 25);

  v_payload := jsonb_build_object(
    'batch_id', btrim(coalesce(p_batch_id, '')),
    'from_stage_order', p_from_stage_order,
    'to_stage_order', v_actual_target_st,
    'move_qty', p_move_qty,
    'move_g', v_move_g,
    'rework_qty', p_rework_qty,
    'loss_gram', v_loss_g
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_move_partial_wip', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if p_move_qty < 0 or p_rework_qty < 0 or v_move_g < 0 or v_sprue_g < 0 or v_scrap_g < 0 or v_loss_g < 0 then
    raise exception 'Negative quantities or weights are not permitted';
  end if;
  if p_move_qty <= 0 and p_rework_qty <= 0 then
    raise exception 'Either moved quantity or rework quantity must be greater than 0';
  end if;

  select * into v_batch from public.batches where id::text = btrim(p_batch_id) for update;
  if not found then
    raise exception 'Batch (%) not found', p_batch_id;
  end if;

  -- Cross-tenant isolation verification
  if v_batch.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Batch does not belong to your organization' using errcode = '42501';
  end if;

  v_batch_code := coalesce(v_batch.batch_no, v_batch.batch_number, v_batch.number, p_batch_id);

  select * into v_cur_wip
    from public.batch_stage_wip
   where (batch_id = btrim(p_batch_id) or batch_no = v_batch_code)
     and stage_order = p_from_stage_order
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'WIP stage record (%) not found for batch %', p_from_stage_order, v_batch_code;
  end if;

  if (p_move_qty + p_rework_qty) > v_cur_wip.available_qty then
    raise exception 'Insufficient WIP in stage %: available=%, requested=%',
      p_from_stage_order, v_cur_wip.available_qty, (p_move_qty + p_rework_qty);
  end if;

  -- --------------------------------------------------------------------------
  -- SERVER-SIDE LOSS VALIDATION
  -- --------------------------------------------------------------------------
  if v_loss_g > 0 then
    v_proc_weight := (v_move_g + v_loss_g + v_sprue_g + v_scrap_g);

    select max_loss_pct, max_loss_gram
      into v_max_loss_pct, v_max_loss_gram
      from public.stage_loss_configs
     where stage_order = p_from_stage_order
       and (organization_id = v_caller_org or organization_id is null)
     order by case when organization_id = v_caller_org then 0 else 1 end
     limit 1;

    if not found then
      if p_from_stage_order in (16, 17, 18) then
        v_max_loss_pct  := 2.500;
        v_max_loss_gram := 1.5000;
      else
        v_max_loss_pct  := 1.000;
        v_max_loss_gram := 0.5000;
      end if;
    end if;

    if v_proc_weight > 0 then
      v_loss_pct := round((v_loss_g / v_proc_weight * 100)::numeric, 3);
      v_limit_by_pct := round((v_proc_weight * v_max_loss_pct / 100)::numeric, 4);
    else
      v_loss_pct := 0;
      v_limit_by_pct := v_max_loss_gram;
    end if;

    v_effective_limit := least(v_max_loss_gram, greatest(0.0100, v_limit_by_pct));

    if v_loss_g > v_effective_limit and (v_proc_weight = 0 or v_loss_pct > v_max_loss_pct) then
      v_excess_loss_g := round((v_loss_g - v_effective_limit)::numeric, 4);

      if not coalesce(p_allow_excess_loss, false) then
        raise exception 'EXCESSIVE_LOSS_DETECTED: Stage % loss (%g, %s%%) exceeds allowable threshold (%g, %s%%). Manager override required.',
          p_from_stage_order, v_loss_g, v_loss_pct, v_effective_limit, v_max_loss_pct
          using errcode = 'P0001';
      end if;

      if v_caller_role not in (
        'admin', 'director', 'owner', 'direktor', 'rahbar',
        'manager', 'production_manager', 'production manager',
        'bosh usta', 'supervisor', 'master'
      ) then
        raise exception 'Permission denied: Operator role "%" cannot authorize excessive stage loss override (+%sg)',
          v_caller_role, v_excess_loss_g using errcode = '42501';
      end if;

      insert into public.audit_logs (
        table_name, record_id, action, actor_id, actor_name, actor_role,
        reason, new_data, organization_id
      ) values (
        'batches',
        v_batch.id::text,
        'EXCESSIVE_LOSS_ALERT',
        auth.uid(),
        public.current_employee_name(),
        v_caller_role,
        coalesce(nullif(btrim(p_excess_loss_reason), ''), 'Stage loss exceeded standard threshold; manager override confirmed'),
        jsonb_build_object(
          'batch_no', v_batch_code,
          'stage_order', p_from_stage_order,
          'processed_weight_gram', v_proc_weight,
          'loss_gram', v_loss_g,
          'loss_pct', v_loss_pct,
          'effective_limit_gram', v_effective_limit,
          'excess_loss_gram', v_excess_loss_g,
          'worker_name', btrim(p_worker_name)
        ),
        v_caller_org
      );
    end if;
  end if;

  -- --------------------------------------------------------------------------
  -- MASS BALANCE & OUTPUT UPDATES
  -- --------------------------------------------------------------------------
  v_rem_qty   := v_cur_wip.available_qty - p_move_qty - p_rework_qty;
  v_new_sprue := round((coalesce(v_batch.sprue_gram, 0) + v_sprue_g)::numeric, 4);
  v_new_scrap := round((coalesce(v_batch.scrap_gram, 0) + v_scrap_g)::numeric, 4);
  v_new_loss  := round((coalesce(v_batch.loss_gram, 0) + v_loss_g)::numeric, 4);
  v_new_good  := case
                   when v_is_final then round((coalesce(v_batch.good_output_gram, 0) + v_move_g)::numeric, 4)
                   else round(coalesce(v_batch.good_output_gram, 0)::numeric, 4)
                 end;

  v_in_gold   := round(coalesce(v_batch.issued_gold_gram, v_batch.planned_gram, 0)::numeric, 4);
  v_tot_out   := round((v_new_good + v_new_sprue + v_new_scrap + v_new_loss)::numeric, 4);

  if v_in_gold <= 0 then
    raise exception 'Authoritative issued gold is missing or zero for batch %', v_batch_code;
  end if;

  if v_tot_out > (v_in_gold + 0.05) then
    raise exception 'Mass balance violation: total outputs (%g) exceeds issued gold (%g)', v_tot_out, v_in_gold;
  end if;

  -- Stage-level WIP mass balance check
  if coalesce(v_cur_wip.input_weight, 0) > 0 then
    v_avail_stage_g := round(greatest(0, coalesce(v_cur_wip.input_weight, 0) - coalesce(v_cur_wip.output_weight, 0) - coalesce(v_cur_wip.loss_weight, 0))::numeric, 4);
    if (v_move_g + v_sprue_g + v_scrap_g + v_loss_g) > (v_avail_stage_g + 0.05) then
      raise exception 'Mass balance violation: total outputs (%g) exceeds available stage WIP (%g)',
        (v_move_g + v_sprue_g + v_scrap_g + v_loss_g), v_avail_stage_g;
    end if;
    v_rem_stage_g := round(greatest(0, v_avail_stage_g - (v_move_g + v_sprue_g + v_scrap_g + v_loss_g))::numeric, 4);
  else
    v_rem_stage_g := round(greatest(0, v_in_gold - v_tot_out)::numeric, 4);
  end if;

  v_new_wip_g := v_rem_stage_g;

  update public.batch_stage_wip
     set available_qty = v_rem_qty,
         completed_qty = coalesce(completed_qty, 0) + p_move_qty,
         rework_qty    = coalesce(rework_qty, 0) + p_rework_qty,
         output_weight = coalesce(output_weight, 0) + v_move_g + v_sprue_g + v_scrap_g,
         loss_weight   = coalesce(loss_weight, 0) + v_loss_g,
         updated_at    = now()
   where id = v_cur_wip.id;

  if p_move_qty > 0 and not v_is_final then
    select * into v_nxt_wip
      from public.batch_stage_wip
     where (batch_id = btrim(p_batch_id) or batch_no = v_batch_code)
       and stage_order = v_actual_target_st
       and organization_id = v_caller_org
     for update;

    if found then
      update public.batch_stage_wip
         set available_qty = available_qty + p_move_qty,
             input_weight  = coalesce(input_weight, 0) + v_move_g,
             assigned_worker = coalesce(nullif(btrim(p_worker_name), ''), assigned_worker),
             updated_at    = now()
       where id = v_nxt_wip.id;
    else
      insert into public.batch_stage_wip (
        batch_id, batch_no, stage_order, stage_name, department,
        available_qty, completed_qty, rework_qty, input_weight, output_weight, loss_weight,
        queue_status, assigned_worker, organization_id
      ) values (
        btrim(p_batch_id), v_batch_code, v_actual_target_st, v_actual_target_nm, v_actual_target_dp,
        p_move_qty, 0, 0, v_move_g, 0, 0,
        'NOW', nullif(btrim(p_worker_name), ''), v_caller_org
      );
    end if;
  end if;

  v_new_fin_qty := coalesce(v_batch.finished_qty, 0);
  if v_is_final and p_move_qty > 0 then
    v_new_fin_qty := v_new_fin_qty + p_move_qty;
    v_credit_qty  := p_move_qty;

    select * into v_prod
      from public.products
     where (lower(btrim(name)) = lower(btrim(v_batch.product_name)) or lower(btrim(name)) = lower(btrim(coalesce(v_batch.product, ''))))
       and organization_id = v_caller_org
     limit 1
     for update;

    if found then
      update public.products
         set stock      = coalesce(stock, quantity, 0) + v_credit_qty,
             quantity   = coalesce(stock, quantity, 0) + v_credit_qty,
             updated_at = now()
       where id = v_prod.id;
    else
      -- Seamless auto-creation of finished jewelry in vitrina
      insert into public.products (
        organization_id,
        name,
        category,
        proba,
        stock,
        quantity,
        weight,
        created_at,
        updated_at
      ) values (
        v_caller_org,
        coalesce(nullif(btrim(v_batch.product_name), ''), nullif(btrim(coalesce(v_batch.product, '')), ''), 'Zargarlik buyumi'),
        'Komplekt',
        coalesce(v_batch.proba, 585),
        v_credit_qty,
        v_credit_qty,
        round((v_move_g / greatest(p_move_qty, 1))::numeric, 4),
        now(),
        now()
      );
    end if;
  end if;

  v_done_all := (v_new_fin_qty >= coalesce(v_batch.planned_qty, 0) and v_new_wip_g <= 0.05);

  update public.batches
     set sprue_gram            = v_new_sprue,
         scrap_gram            = v_new_scrap,
         loss_gram             = v_new_loss,
         good_output_gram      = v_new_good,
         wip_gram              = v_new_wip_g,
         finished_qty          = v_new_fin_qty,
         credited_finished_qty = coalesce(credited_finished_qty, 0) + v_credit_qty,
         current_step          = case when v_done_all then '25. Tayyor ombor' else v_actual_target_nm end,
         status                = case when v_done_all then 'Tugatildi' else 'Jarayonda' end,
         status_label          = case when v_done_all then 'Tugatildi' else 'Jarayonda' end,
         updated_at            = now()
   where id = v_batch.id;

  -- --------------------------------------------------------------------------
  -- BIDIRECTIONAL BATCH_OPERATIONS SYNCHRONIZATION
  -- --------------------------------------------------------------------------
  if to_regclass('public.batch_operations') is not null and public.try_cast_uuid(p_batch_id) is not null then
    select bo.id into v_open_op_id
      from public.batch_operations bo
     where bo.batch_id = public.try_cast_uuid(p_batch_id)
       and bo.status in ('queued', 'in_progress', 'paused', 'delayed')
     order by bo.queued_at desc
     limit 1;

    if v_open_op_id is not null then
      update public.batch_operations
         set status = 'completed',
             finished_at = coalesce(finished_at, now()),
             output_weight_grams = coalesce(output_weight_grams, v_move_g),
             updated_at = now()
       where id = v_open_op_id;
    end if;

    if not v_is_final and p_move_qty > 0 then
      select ws.id, ws.department_id into v_stage_uuid, v_dept_uuid
        from public.workflow_stages ws
       where (ws.sequence_order = v_actual_target_st
              or lower(trim(ws.name)) = lower(trim(v_actual_target_nm))
              or lower(trim(ws.code)) = lower(trim(v_actual_target_dp)))
         and ws.is_active = true
       limit 1;

      if v_stage_uuid is not null and v_dept_uuid is not null then
        select bo.id into v_existing_op_id
          from public.batch_operations bo
         where bo.batch_id = public.try_cast_uuid(p_batch_id)
           and bo.stage_id = v_stage_uuid
           and bo.status in ('queued', 'in_progress')
         order by bo.queued_at desc
         limit 1;

        if v_existing_op_id is not null then
          update public.batch_operations
             set input_weight_grams = coalesce(input_weight_grams, 0) + v_move_g,
                 updated_at = now()
           where id = v_existing_op_id;
        else
          select coalesce(max(attempt_number), 0) + 1 into v_next_attempt
            from public.batch_operations
           where batch_id = public.try_cast_uuid(p_batch_id)
             and stage_id = v_stage_uuid;

          insert into public.batch_operations (
            batch_id, stage_id, department_id, attempt_number,
            status, queued_at, input_weight_grams
          ) values (
            public.try_cast_uuid(p_batch_id),
            v_stage_uuid,
            v_dept_uuid,
            v_next_attempt,
            'queued',
            now(),
            v_move_g
          );
        end if;
      end if;
    end if;
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'batch_id', v_batch.id::text,
    'batch_no', v_batch_code,
    'from_stage_order', p_from_stage_order,
    'to_stage_order', v_actual_target_st,
    'to_stage_name', v_actual_target_nm,
    'moved_qty', p_move_qty,
    'moved_weight', v_move_g,
    'rework_qty', p_rework_qty,
    'loss_gram', v_loss_g,
    'wip_remaining_gram', v_new_wip_g,
    'remaining_wip_gram', v_new_wip_g,
    'finished_qty', v_new_fin_qty,
    'is_completed', v_done_all,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_move_partial_wip', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_move_partial_wip(text,integer,integer,text,text,integer,numeric,numeric,integer,numeric,numeric,numeric,text,text,text,boolean,text) from public, anon, authenticated, service_role;
grant execute on function rpc_move_partial_wip(text,integer,integer,text,text,integer,numeric,numeric,integer,numeric,numeric,numeric,text,text,text,boolean,text) to authenticated;
grant execute on function rpc_move_partial_wip(text,integer,integer,text,text,integer,numeric,numeric,integer,numeric,numeric,numeric,text,text,text,boolean,text) to service_role;

-- parity: rpc_override_stage_handover(text,text,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_override_stage_handover(p_handover_id text, p_supervisor_worker_id text, p_supervisor_worker_name text, p_override_reason text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org  uuid := public.current_organization_id();
  v_caller_role text := public.current_employee_role_text();
  v_h           public.two_party_handovers%rowtype;
  v_existing    jsonb;
  v_payload     jsonb;
  v_salary_res  jsonb := null;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta'
  ]);

  if p_override_reason is null or length(btrim(p_override_reason)) < 5 then
    raise exception 'Supervisor override requires a documented investigation reason (min 5 characters)';
  end if;

  v_payload := jsonb_build_object(
    'handover_id', btrim(coalesce(p_handover_id, '')),
    'supervisor_worker_id', btrim(coalesce(p_supervisor_worker_id, '')),
    'override_reason', btrim(p_override_reason)
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_override_stage_handover', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_h
    from public.two_party_handovers
   where id::text = btrim(p_handover_id)
     for update;

  if not found then
    raise exception 'Handover record not found: %', p_handover_id;
  end if;

  if v_h.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Handover does not belong to your organization' using errcode = '42501';
  end if;

  if v_h.status not in ('DISCREPANCY_FLAGGED', 'PENDING_ACCEPTANCE') then
    raise exception 'Handover % is not in a flagged state (current: %)', p_handover_id, v_h.status;
  end if;

  update public.two_party_handovers
     set status                     = 'SUPERVISOR_OVERRIDDEN',
         supervisor_override_id     = btrim(p_supervisor_worker_id),
         supervisor_override_reason = btrim(p_override_reason),
         resolved_at                = clock_timestamp()
   where id = v_h.id;

  -- Record supervisor override in audit logs
  insert into public.audit_logs (
    table_name, record_id, action, actor_id, actor_name, actor_role,
    reason, new_data, organization_id
  ) values (
    'two_party_handovers',
    v_h.id::text,
    'HANDOVER_OVERRIDE_ALERT',
    auth.uid(),
    btrim(p_supervisor_worker_name),
    v_caller_role,
    btrim(p_override_reason),
    jsonb_build_object(
      'handover_id', v_h.id::text,
      'batch_no', v_h.batch_no,
      'dispatched_weight_gram', v_h.dispatched_weight_gram,
      'received_weight_gram', v_h.received_weight_gram,
      'discrepancy_gram', v_h.weight_discrepancy_gram,
      'sender_worker', v_h.sender_worker_name,
      'receiver_worker', v_h.receiver_worker_name
    ),
    v_caller_org
  );

  -- Award piecework salary upon approved supervisor override
  v_salary_res := public.rpc_calculate_piecework_salary(
    p_handover_id     := v_h.id::text,
    p_worker_id       := v_h.sender_worker_id,
    p_worker_name     := v_h.sender_worker_name,
    p_batch_no        := v_h.batch_no,
    p_stage_name      := v_h.from_stage_name,
    p_stage_order     := v_h.from_stage_order,
    p_weight_done     := coalesce(v_h.received_weight_gram, v_h.dispatched_weight_gram),
    p_qty_done        := coalesce(v_h.received_qty, v_h.dispatched_qty),
    p_idempotency_key := 'earned-ho-' || v_h.id::text
  );

  v_existing := jsonb_build_object(
    'success', true,
    'handover_id', v_h.id::text,
    'status', 'SUPERVISOR_OVERRIDDEN',
    'piecework_earned', v_salary_res,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_override_stage_handover', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_override_stage_handover(text,text,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_override_stage_handover(text,text,text,text,text) to authenticated;
grant execute on function rpc_override_stage_handover(text,text,text,text,text) to service_role;

-- parity: rpc_preview_full_test_reset()
CREATE OR REPLACE FUNCTION public.rpc_preview_full_test_reset()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_preview_token  text;
  v_active_base    record;
  v_receipt_cnt    int;
  v_receipt_g      numeric(14, 4);
  v_consign_cnt    int;
  v_consign_g      numeric(14, 4);
  v_piece_cnt      int;
  v_sale_cnt       int;
  v_settle_cnt     int;
  v_refining_cnt   int;
  v_fintx_cnt      int;
  v_purch_cnt      int;
  v_cust_debt_g    numeric(14, 4);
  v_seller_till_g  numeric(14, 4);
  v_mgr_scrap_g    numeric(14, 4);
  v_mgr_fine_g     numeric(14, 4);
  v_mgr_cash       numeric(18, 2);
  v_mgr_usd        numeric(18, 2);
  v_preserved_emp  int;
  v_preserved_cus  int;
  v_preserved_mdl  int;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  v_preview_token := 'RESET-TOKEN-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  select id, baseline_no, baseline_date, net_assets_585_g into v_active_base
    from public.accounting_baselines
   where organization_id = v_caller_org and status = 'active'
   order by baseline_date desc, created_at desc limit 1;

  select count(*), coalesce(sum(available_physical_g), 0)
    into v_receipt_cnt, v_receipt_g
    from public.factory_receipts
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*), coalesce(sum(base_weight_grams), 0)
    into v_consign_cnt, v_consign_g
    from public.seller_consignments
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*) into v_piece_cnt
    from public.consignment_pieces
   where organization_id = v_caller_org and status <> 'cancelled';

  select count(*) into v_sale_cnt
    from public.jewelry_sales
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*) into v_settle_cnt
    from public.gold_settlements
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*) into v_refining_cnt
    from public.refining_batches
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*) into v_fintx_cnt
    from public.financial_transactions
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select count(*) into v_purch_cnt
    from public.gold_purchases
   where organization_id = v_caller_org and status not in ('cancelled', 'reversed');

  select coalesce(sum(current_debt_grams), 0) into v_cust_debt_g
    from public.client_gold_accounts
   where organization_id = v_caller_org;

  select coalesce(sum(seller_till_scrap_grams), 0) into v_seller_till_g
    from public.seller_gold_accounts
   where organization_id = v_caller_org;

  select coalesce(manager_scrap_grams, 0), coalesce(manager_refined_gold_grams, 0),
         coalesce(manager_cash_amount, 0), coalesce(manager_usd_amount, 0)
    into v_mgr_scrap_g, v_mgr_fine_g, v_mgr_cash, v_mgr_usd
    from public.manager_vault_account
   where organization_id = v_caller_org;

  select count(*) into v_preserved_emp from public.employees where organization_id = v_caller_org;
  select count(*) into v_preserved_cus from public.customers where organization_id = v_caller_org;
  select count(*) into v_preserved_mdl from public.jewelry_models where organization_id = v_caller_org;

  return jsonb_build_object(
    'status', 'ok',
    'preview_token', v_preview_token,
    'has_active_baseline', (v_active_base.id is not null),
    'active_baseline_no', v_active_base.baseline_no,
    'active_baseline_net_assets_g', v_active_base.net_assets_585_g,
    'affected_records', jsonb_build_object(
      'factory_receipts_count', v_receipt_cnt,
      'factory_receipts_grams', v_receipt_g,
      'seller_consignments_count', v_consign_cnt,
      'seller_consignments_grams', v_consign_g,
      'consignment_pieces_count', v_piece_cnt,
      'jewelry_sales_count', v_sale_cnt,
      'gold_settlements_count', v_settle_cnt,
      'refining_batches_count', v_refining_cnt,
      'financial_transactions_count', v_fintx_cnt,
      'gold_purchases_count', v_purch_cnt,
      'customer_active_debt_g', v_cust_debt_g,
      'seller_tills_scrap_g', v_seller_till_g,
      'manager_scrap_vault_g', v_mgr_scrap_g,
      'manager_refined_vault_g', v_mgr_fine_g,
      'manager_cash_vault_uzs', v_mgr_cash,
      'manager_usd_vault', v_mgr_usd
    ),
    'preserved_master_data', jsonb_build_object(
      'employees_count', v_preserved_emp,
      'customers_count', v_preserved_cus,
      'jewelry_models_count', v_preserved_mdl,
      'organizations_preserved', true,
      'audit_history_preserved', true
    ),
    'confirmation_code_required', 'RESET_TEST_ACCOUNT_2026'
  );
end;
$function$;
revoke all on function rpc_preview_full_test_reset() from public, anon, authenticated, service_role;
grant execute on function rpc_preview_full_test_reset() to authenticated;
grant execute on function rpc_preview_full_test_reset() to service_role;

-- parity: rpc_preview_selective_test_cleanup(uuid[])
CREATE OR REPLACE FUNCTION public.rpc_preview_selective_test_cleanup(p_receipt_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_preview_token  text;
  v_tot_phys_g     numeric(14, 4) := 0;
  v_tot_obl_g      numeric(14, 4) := 0;
  v_blocked_items  jsonb := '[]'::jsonb;
  v_clean_items    jsonb := '[]'::jsonb;
  v_r_id           uuid;
  v_r_rec          public.factory_receipts%rowtype;
  v_sold_count     int;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi'
  ]);

  if p_receipt_ids is null or array_length(p_receipt_ids, 1) = 0 then
    select coalesce(array_agg(id), array[]::uuid[])
    into p_receipt_ids
    from public.factory_receipts
    where organization_id = v_caller_org and status <> 'reversed';
  end if;

  v_preview_token := 'CLN-PREV-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  if p_receipt_ids is not null then
    foreach v_r_id in array p_receipt_ids loop
      select * into v_r_rec
      from public.factory_receipts
      where id = v_r_id and organization_id = v_caller_org;

      if found then
        if v_r_rec.status = 'reversed' then
          continue;
        end if;

        select count(*) into v_sold_count
        from public.consignment_pieces cp
        join public.seller_consignments sc on sc.id = cp.consignment_id
        where sc.factory_receipt_id = v_r_id and cp.status in ('sold', 'client_sale');

        if v_sold_count > 0 then
          v_blocked_items := v_blocked_items || jsonb_build_object(
            'receipt_id', v_r_rec.id,
            'receipt_no', v_r_rec.receipt_no,
            'product_name', v_r_rec.product_name,
            'blocked_reason', format('Ushbu partiyadan %s dona buyum mijozlarga sotilgan. Sotuv bekor qilinmasdan tozalash mumkin emas.', v_sold_count)
          );
        elsif v_r_rec.transferred_physical_g > 0.0001 then
          v_blocked_items := v_blocked_items || jsonb_build_object(
            'receipt_id', v_r_rec.id,
            'receipt_no', v_r_rec.receipt_no,
            'product_name', v_r_rec.product_name,
            'blocked_reason', format('Ushbu partiya sotuvchilarga tarqatilgan (%s g). Avval konsignatsiyani bekor qiling.', v_r_rec.transferred_physical_g)
          );
        else
          v_clean_items := v_clean_items || jsonb_build_object(
            'receipt_id', v_r_rec.id,
            'receipt_no', v_r_rec.receipt_no,
            'product_name', v_r_rec.product_name,
            'physical_g', v_r_rec.original_physical_g,
            'obligation_g', v_r_rec.factory_obligation_g,
            'status', v_r_rec.status
          );
          v_tot_phys_g := v_tot_phys_g + v_r_rec.original_physical_g;
          v_tot_obl_g  := v_tot_obl_g + v_r_rec.factory_obligation_g;
        end if;
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'preview_token', v_preview_token,
    'cleanable_items', v_clean_items,
    'blocked_items', v_blocked_items,
    'summary', jsonb_build_object(
      'cleanable_count', jsonb_array_length(v_clean_items),
      'blocked_count', jsonb_array_length(v_blocked_items),
      'inventory_reduction_585_g', v_tot_phys_g,
      'factory_obligation_reduction_g', v_tot_obl_g
    )
  );
end;
$function$;
revoke all on function rpc_preview_selective_test_cleanup(uuid[]) from public, anon, authenticated, service_role;
grant execute on function rpc_preview_selective_test_cleanup(uuid[]) to authenticated;
grant execute on function rpc_preview_selective_test_cleanup(uuid[]) to service_role;

-- parity: rpc_preview_staging_test_cleanup(text)
CREATE OR REPLACE FUNCTION public.rpc_preview_staging_test_cleanup(p_test_session_prefix text DEFAULT 'QA-'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org      uuid := public.current_organization_id();
  v_preview_token   text;
  v_target_receipts uuid[];
  v_target_consigns uuid[];
  v_target_sales    uuid[];
  v_target_settles  uuid[];
  v_tot_receipt_g   numeric(14, 4) := 0;
  v_tot_consign_g   numeric(14, 4) := 0;
  v_tot_sale_g      numeric(14, 4) := 0;
  v_tot_settle_g    numeric(14, 4) := 0;
  v_prefix          text := coalesce(p_test_session_prefix, 'QA-');
  v_report          jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  -- STRICT SAFETY GUARD: Verify this is Staging
  if current_database() <> 'postgres' and current_setting('app.is_staging', true) <> 'true' then
    -- Additional staging domain verification
    if current_database() = 'production' then
      raise exception 'CRITICAL ERROR: Test data cleanup is strictly forbidden on production environment!';
    end if;
  end if;

  v_preview_token := 'PREVIEW-STG-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 12));

  -- 1. Identify factory receipts created during test sessions
  select coalesce(array_agg(id), array[]::uuid[]),
         coalesce(sum(factory_obligation_g), 0)
    into v_target_receipts, v_tot_receipt_g
    from public.factory_receipts
   where organization_id = v_caller_org
     and (product_name like (v_prefix || '%') or notes like ('%' || v_prefix || '%'))
     and status <> 'reversed';

  -- 2. Identify consignments created during test sessions
  select coalesce(array_agg(id), array[]::uuid[]),
         coalesce(sum(seller_obligation_g), 0)
    into v_target_consigns, v_tot_consign_g
    from public.seller_consignments
   where organization_id = v_caller_org
     and (notes like ('%' || v_prefix || '%') or factory_receipt_id = any (v_target_receipts))
     and status <> 'cancelled';

  -- 3. Identify sales created during test sessions
  select coalesce(array_agg(id), array[]::uuid[]),
         coalesce(sum(client_gold_due_grams), 0)
    into v_target_sales, v_tot_sale_g
    from public.jewelry_sales
   where organization_id = v_caller_org
     and (notes like ('%' || v_prefix || '%') or consignment_id = any (v_target_consigns))
     and status <> 'reversed';

  -- 4. Identify settlements created during test sessions
  select coalesce(array_agg(id), array[]::uuid[]),
         coalesce(sum(total_settled_grams), 0)
    into v_target_settles, v_tot_settle_g
    from public.gold_settlements
   where organization_id = v_caller_org
     and (notes like ('%' || v_prefix || '%'))
     and status <> 'reversed';

  v_report := jsonb_build_object(
    'status', 'preview_ready',
    'preview_token', v_preview_token,
    'generated_at', now(),
    'environment', 'staging',
    'filter_prefix', v_prefix,
    'summary', jsonb_build_object(
      'factory_receipts_count', coalesce(array_length(v_target_receipts, 1), 0),
      'factory_receipts_obligation_g', v_tot_receipt_g,
      'consignments_count', coalesce(array_length(v_target_consigns, 1), 0),
      'consignments_obligation_g', v_tot_consign_g,
      'sales_count', coalesce(array_length(v_target_sales, 1), 0),
      'sales_gold_due_g', v_tot_sale_g,
      'settlements_count', coalesce(array_length(v_target_settles, 1), 0),
      'settlements_gold_g', v_tot_settle_g
    ),
    'target_ids', jsonb_build_object(
      'factory_receipt_ids', v_target_receipts,
      'consignment_ids', v_target_consigns,
      'sale_ids', v_target_sales,
      'settlement_ids', v_target_settles
    ),
    'confirmation_instructions', 'Ijro etish uchun rpc_execute_staging_test_cleanup(preview_token, confirmation_code="CONFIRM_STAGING_CLEANUP_2026") ni chaqiring. Baza hech qachon qattiq o''chirilmaydi.'
  );

  -- Store preview snapshot for audit
  insert into public.staging_backup_snapshots (
    organization_id, snapshot_type, preview_token, affected_tables,
    record_count, gold_impact_g, snapshot_data, created_by
  ) values (
    v_caller_org, 'CLEANUP_PREVIEW', v_preview_token,
    array['factory_receipts', 'seller_consignments', 'jewelry_sales', 'gold_settlements'],
    coalesce(array_length(v_target_receipts, 1), 0) + coalesce(array_length(v_target_consigns, 1), 0) + coalesce(array_length(v_target_sales, 1), 0) + coalesce(array_length(v_target_settles, 1), 0),
    v_tot_receipt_g + v_tot_sale_g + v_tot_settle_g,
    v_report, public.current_employee_id()
  );

  return v_report;
end;
$function$;
revoke all on function rpc_preview_staging_test_cleanup(text) from public, anon, authenticated, service_role;
grant execute on function rpc_preview_staging_test_cleanup(text) to authenticated;
grant execute on function rpc_preview_staging_test_cleanup(text) to service_role;

-- parity: rpc_reclassify_capital_transaction(uuid,text,text,numeric,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.rpc_reclassify_capital_transaction(p_transaction_id uuid, p_new_destination text, p_reason text, p_new_proba numeric DEFAULT NULL::numeric, p_seller_id uuid DEFAULT NULL::uuid, p_model_id uuid DEFAULT NULL::uuid, p_product_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_tx              public.financial_transactions%rowtype;
  v_today           date := (timezone('Asia/Tashkent', now()))::date;
  v_dest            text := lower(btrim(p_new_destination));
  v_equiv_585       numeric(14, 4);
  v_fine_g          numeric(14, 4);
  v_phys_w          numeric(14, 4);
  v_proba           numeric(6, 2);
  v_rec_no          text;
  v_receipt_id      uuid;
  v_vault           public.manager_vault_account%rowtype;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar'
  ]);

  if v_caller_emp_id is null then
    select id into v_caller_emp_id from public.employees where user_id = auth.uid() and organization_id = v_org_id limit 1;
  end if;

  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'ERR_REASON_REQUIRED: Qayta tasniflash sababini kiritish shart' using errcode = '22023';
  end if;

  select * into v_tx
    from public.financial_transactions
   where id = p_transaction_id and organization_id = v_org_id
     for update;

  if not found then
    raise exception 'Operatsiya topilmadi (%)', p_transaction_id;
  end if;

  if v_tx.status = 'reversed' then
    raise exception 'Bekor qilingan operatsiyani qayta tasniflab bo''lmaydi';
  end if;

  if v_tx.transaction_type not in ('capital_contribution', 'capital_in') then
    raise exception 'Faqat ta''sischi kapital operatsiyalarini qayta tasniflash mumkin';
  end if;

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  v_equiv_585 := v_tx.equiv_585_grams;

  -- 1. Reverse old allocation
  if v_tx.source_till = 'manager_vault_gold' then
    if v_vault.manager_refined_gold_grams < v_equiv_585 then
      raise exception 'Seyfda yetarli afinaj oltin mavjud emas qaytarish uchun';
    end if;
    update public.manager_vault_account
       set manager_refined_gold_grams = round(manager_refined_gold_grams - v_equiv_585, 4),
           manager_refined_gold_fine_grams = round(greatest(0, coalesce(manager_refined_gold_fine_grams, 0) - (v_equiv_585 * 0.585)), 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_tx.source_till in ('manager_scrap', 'scrap_gold') then
    update public.manager_vault_account
       set manager_scrap_585_eq_g = round(greatest(0, manager_scrap_585_eq_g - v_equiv_585), 4),
           manager_scrap_grams = round(greatest(0, manager_scrap_grams - v_equiv_585), 4),
           manager_scrap_physical_g = round(greatest(0, manager_scrap_physical_g - coalesce(v_tx.physical_weight_grams, v_equiv_585)), 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_tx.source_till in ('manager_fine_gold', 'fine_gold') then
    update public.manager_vault_account
       set manager_capital_pure_gold_g = round(greatest(0, manager_capital_pure_gold_g - v_equiv_585), 4),
           manager_capital_pure_gold_fine_g = round(greatest(0, coalesce(manager_capital_pure_gold_fine_g, 0) - (v_equiv_585 * 0.585)), 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_tx.source_till in ('manager_uzs', 'cash_uzs') then
    update public.manager_vault_account
       set manager_cash_amount = round(greatest(0, manager_cash_amount - v_tx.amount_num), 2),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_tx.source_till in ('manager_usd', 'cash_usd') then
    update public.manager_vault_account
       set manager_usd_amount = round(greatest(0, coalesce(manager_usd_amount, 0) - v_tx.amount_num), 2),
           updated_at = now()
     where organization_id = v_org_id;
  end if;

  -- 2. Apply new allocation
  if v_dest in ('manager_scrap', 'scrap_gold') then
    v_proba := coalesce(p_new_proba, 585.0);
    v_phys_w := round((v_equiv_585 * (585.0 / v_proba))::numeric, 4);

    update public.manager_vault_account
       set manager_scrap_physical_g = round(manager_scrap_physical_g + v_phys_w, 4),
           manager_scrap_585_eq_g = round(manager_scrap_585_eq_g + v_equiv_585, 4),
           manager_scrap_grams = round(manager_scrap_grams + v_equiv_585, 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_dest in ('manager_fine_gold', 'fine_gold') then
    v_proba := coalesce(p_new_proba, 995.0);
    v_phys_w := round((v_equiv_585 * (585.0 / v_proba))::numeric, 4);
    v_fine_g := round((v_phys_w * (v_proba / 1000.0))::numeric, 4);

    update public.manager_vault_account
       set manager_capital_pure_gold_g = round(manager_capital_pure_gold_g + v_equiv_585, 4),
           manager_capital_pure_gold_fine_g = round(coalesce(manager_capital_pure_gold_fine_g, 0) + v_fine_g, 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_dest in ('manager_finished', 'finished_goods') then
    v_phys_w := v_equiv_585;
    v_proba := 585.0;
    v_rec_no := 'CAP-REC-' || to_char(v_today, 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

    insert into public.factory_receipts (
      organization_id, receipt_no, receipt_date, model_id,
      product_name, proba, quantity, original_physical_g,
      factory_markup_pct, factory_obligation_g, transferred_physical_g,
      available_physical_g, status, notes
    ) values (
      v_org_id, v_rec_no, v_today, p_model_id,
      coalesce(p_product_name, 'Kapital Tayyor Mahsulot'), v_proba,
      1, v_phys_w,
      0, 0, 0,
      v_phys_w, 'in_manager_stock',
      'Audit tahrirlash: ' || p_reason
    ) returning id into v_receipt_id;

    -- manager_physical_stock_g is synced automatically by trg_sync_manager_vault_receipts
    update public.manager_vault_account
       set manager_finished_capital_g = round(manager_finished_capital_g + v_phys_w, 4),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_dest in ('manager_uzs', 'cash_uzs') then
    update public.manager_vault_account
       set manager_cash_amount = round(manager_cash_amount + (v_equiv_585 * v_tx.gold_rate_applied), 2),
           updated_at = now()
     where organization_id = v_org_id;

  elsif v_dest in ('manager_usd', 'cash_usd') then
    if coalesce(v_tx.usd_rate_applied, 0) <= 0 then
      raise exception 'USD kursi mavjud emas qayta tasniflash uchun';
    end if;
    update public.manager_vault_account
       set manager_usd_amount = round(coalesce(manager_usd_amount, 0) + ((v_equiv_585 * v_tx.gold_rate_applied) / v_tx.usd_rate_applied), 2),
           updated_at = now()
     where organization_id = v_org_id;

  else
    raise exception 'ERR_INVALID_DESTINATION: Noma''lum qayta tasniflash joylashuvi: %', v_dest;
  end if;

  -- 3. Update transaction record
  update public.financial_transactions
     set source_till = v_dest,
         currency = case
           when v_dest in ('manager_scrap', 'seller_till_scrap') then 'SCRAP_GOLD'
           when v_dest in ('manager_fine_gold') then 'FINE_GOLD'
           when v_dest in ('manager_finished') then 'FINISHED_GOODS'
           when v_dest in ('manager_uzs', 'seller_till_uzs') then 'UZS'
           when v_dest in ('manager_usd', 'seller_till_usd') then 'USD'
           else currency
         end,
         gold_proba = coalesce(p_new_proba, gold_proba),
         reclassification_reason = p_reason,
         notes = coalesce(notes, '') || ' [Audit Reclassified to ' || v_dest || ': ' || p_reason || ']',
         updated_at = now()
   where id = p_transaction_id;

  -- 4. Audit Log
  if to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs (
      organization_id, table_name, record_id, action,
      actor_id, old_data, new_data, reason
    ) values (
      v_org_id, 'financial_transactions', p_transaction_id::text, 'RECLASSIFY_CAPITAL',
      auth.uid(),
      jsonb_build_object('old_source_till', v_tx.source_till, 'equiv_585_g', v_tx.equiv_585_grams),
      jsonb_build_object('new_source_till', v_dest, 'reason', p_reason, 'equiv_585_g', v_equiv_585),
      p_reason
    );
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'transaction_id', p_transaction_id,
    'old_source_till', v_tx.source_till,
    'new_source_till', v_dest,
    'equiv_585_grams', v_equiv_585,
    'reason', p_reason
  );
end;
$function$;
revoke all on function rpc_reclassify_capital_transaction(uuid,text,text,numeric,uuid,uuid,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reclassify_capital_transaction(uuid,text,text,numeric,uuid,uuid,text) to authenticated;
grant execute on function rpc_reclassify_capital_transaction(uuid,text,text,numeric,uuid,uuid,text) to service_role;

-- parity: rpc_record_barcode_piece_sale(uuid,uuid,uuid,uuid,numeric,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_barcode_piece_sale(p_customer_id uuid, p_seller_id uuid DEFAULT NULL::uuid, p_piece_id uuid DEFAULT NULL::uuid, p_model_id uuid DEFAULT NULL::uuid, p_weight_grams numeric DEFAULT NULL::numeric, p_client_markup_pct numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org        uuid := public.current_organization_id();
  v_seller            public.employees%rowtype;
  v_customer          public.customers%rowtype;
  v_piece             public.consignment_pieces%rowtype;
  v_consign           public.seller_consignments%rowtype;
  v_client_pct        numeric(6, 2);
  v_base_w            numeric(14, 4);
  v_factory_due       numeric(14, 4);
  v_client_due        numeric(14, 4);
  v_spread            numeric(14, 4);
  v_client_acc        public.client_gold_accounts%rowtype;
  v_avail_adv         numeric(14, 4) := 0;
  v_apply_adv         numeric(14, 4) := 0;
  v_net_rem_due       numeric(14, 4);
  v_sale_id           uuid;
  v_sale_no           text;
  v_existing          jsonb;
  v_payload           jsonb;
  v_remaining_pieces  int;
  v_avail_stock       numeric(14, 4);
  v_caller_role       text := public.current_employee_role_text();
  v_caller_emp_id     uuid := public.current_employee_id();
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'sales', 'seller', 'sotuvchi', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  v_payload := jsonb_build_object(
    'action', 'record_barcode_piece_sale',
    'customer_id', p_customer_id,
    'piece_id', p_piece_id,
    'model_id', p_model_id,
    'weight_grams', p_weight_grams,
    'seller_id', p_seller_id
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_barcode_piece_sale', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_customer
    from public.customers
   where id = p_customer_id and organization_id = v_caller_org;
  if not found then
    raise exception 'Mijoz topilmadi (%)', p_customer_id;
  end if;

  -- Resolve seller
  if p_seller_id is not null then
    select * into v_seller from public.employees where id = p_seller_id and organization_id = v_caller_org limit 1;
  else
    select * into v_seller from public.employees where user_id = auth.uid() and organization_id = v_caller_org limit 1;
  end if;

  if v_seller.id is null and v_customer.seller_id is not null then
    select * into v_seller from public.employees where id = v_customer.seller_id and organization_id = v_caller_org limit 1;
  end if;

  if v_seller.id is null then
    raise exception 'Sotuvchi aniqlanmadi';
  end if;
  if public._goldia_is_seller_role(v_caller_role) and (v_caller_emp_id is null or v_seller.id <> v_caller_emp_id) then
    raise exception 'Ruxsat etilmadi: Sotuvchi faqat o''z nomidan sotuv qila oladi' using errcode = '42501';
  end if;
  -- 065: markup must be explicit (no hidden 15% server default) and within 0..100
  if p_client_markup_pct is null then
    raise exception 'ERR_MARKUP_REQUIRED: Mijoz ustama foizi aniq ko''rsatilishi shart';
  end if;
  v_client_pct := round(p_client_markup_pct::numeric, 2);
  if v_client_pct < 0 or v_client_pct > 100 then
    raise exception 'ERR_MARKUP_OUT_OF_RANGE: Mijoz ustama foizi 0 dan 100 gacha bo''lishi shart (kiritildi: %)', v_client_pct;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('goldia_seller_stock:' || v_seller.id::text, 0));

  -- Fetch piece
  if p_piece_id is not null then
    select * into v_piece
      from public.consignment_pieces
     where id = p_piece_id and organization_id = v_caller_org
     for update;
  elsif p_model_id is not null and p_weight_grams is not null then
    select cp.* into v_piece
      from public.consignment_pieces cp
      join public.seller_consignments sc on sc.id = cp.consignment_id
     where cp.model_id = p_model_id
       and cp.weight_grams = round(p_weight_grams::numeric, 4)
       and cp.seller_id = v_seller.id
       and cp.status = 'held_by_seller'
       and cp.sale_id is null
       and sc.status not in ('returned_to_manager', 'cancelled', 'reversed')
       and cp.organization_id = v_caller_org
     order by cp.created_at asc
     limit 1
     for update of cp;
  else
    raise exception 'Mahsulot donasini aniqlash uchun piece_id yoki (model_id + weight_grams) talab qilinadi';
  end if;

  if not found or v_piece.id is null then
    raise exception 'Tanlangan mahsulot donasi sotuvchi javonida mavjud emas yoki allaqachon sotilgan';
  end if;

  if v_piece.sale_id is not null or v_piece.status = 'sold' then
    raise exception 'Bu mahsulot donasi (% — % g) allaqachon sotilgan (Sotuv ID: %)',
      v_piece.model_code, v_piece.weight_grams, coalesce(v_piece.sale_id::text, 'MAVJUD');
  end if;

  if v_piece.status <> 'held_by_seller' then
    raise exception 'Mahsulot sotuvga yaroqsiz holatda (Joriy holat: %)', v_piece.status;
  end if;
  if v_piece.seller_id is distinct from v_seller.id then
    raise exception 'Ruxsat etilmadi: Ushbu mahsulot donasi boshqa sotuvchiga biriktirilgan' using errcode = '42501';
  end if;

  v_base_w := v_piece.weight_grams;

  select * into v_consign
    from public.seller_consignments
   where id = v_piece.consignment_id
   for update;

  if not found then
    raise exception 'Konsignatsiya yozuvi topilmadi';
  end if;

  v_factory_due := round((v_base_w * (1.0 + coalesce(v_consign.factory_markup_pct, 0) / 100.0))::numeric, 4);
  v_client_due  := round((v_base_w * (1.0 + v_client_pct / 100.0))::numeric, 4);
  v_spread      := round((v_client_due - v_factory_due)::numeric, 4);

  select * into v_client_acc
    from public.client_gold_accounts
   where customer_id = v_customer.id and organization_id = v_caller_org
   for update;

  v_avail_adv := coalesce(v_client_acc.advance_balance_grams, 0);
  v_apply_adv := round(least(v_avail_adv, v_client_due), 4);
  v_net_rem_due := round(v_client_due - v_apply_adv, 4);

  v_sale_no := 'SALE-BC-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  insert into public.jewelry_sales (
    organization_id, sale_no, seller_id, customer_id, consignment_id,
    product_name, quantity, base_weight_grams, proba, factory_markup_pct,
    factory_gold_due_grams, client_markup_pct, client_gold_due_grams,
    markup_spread_grams, settled_gold_grams, remaining_gold_grams,
    status, sale_date, notes, sale_type, model_id, model_code,
    category, purity, seller_profit_spread_grams
  ) values (
    v_caller_org, v_sale_no, v_seller.id, v_customer.id, v_consign.id,
    v_piece.model_name, 1, v_base_w, coalesce(v_piece.purity, 585), coalesce(v_consign.factory_markup_pct, 0),
    v_factory_due, v_client_pct, v_client_due,
    v_spread, v_apply_adv, v_net_rem_due,
    case when v_net_rem_due <= 0 then 'fully_paid' when v_apply_adv > 0 then 'partially_paid' else 'open_debt' end,
    public._goldia_business_date(), p_notes, 'piece', v_piece.model_id, v_piece.model_code,
    v_piece.category, v_piece.purity, v_spread
  ) returning id into v_sale_id;

  update public.consignment_pieces
     set status = 'sold',
         sale_id = v_sale_id,
         sold_at = now(),
         updated_at = now()
   where id = v_piece.id;

  -- Update consignment sold quantity
  select count(*)::int into v_remaining_pieces
    from public.consignment_pieces
   where consignment_id = v_consign.id and status = 'held_by_seller';
  update public.seller_consignments
     set sold_quantity = coalesce(sold_quantity, 0) + 1,
         status = case
                    when v_remaining_pieces = 0 then 'fully_sold'
                    else 'partially_sold'
                  end,
         updated_at = now()
   where id = v_consign.id;

  -- Recalculate seller responsibility
  perform public.recalc_seller_gold_account(v_seller.id, v_caller_org);

  -- Update client account
  insert into public.client_gold_accounts (
    organization_id, customer_id, seller_id, total_purchased_gold_grams,
    total_settled_grams, current_debt_grams, advance_balance_grams, updated_at
  ) values (
    v_caller_org, v_customer.id, v_seller.id, v_client_due,
    v_apply_adv, v_net_rem_due, round(greatest(0, v_avail_adv - v_apply_adv), 4), now()
  )
  on conflict (customer_id) do update set
    total_purchased_gold_grams = round((client_gold_accounts.total_purchased_gold_grams + v_client_due)::numeric, 4),
    total_settled_grams        = round((client_gold_accounts.total_settled_grams + v_apply_adv)::numeric, 4),
    current_debt_grams         = round((client_gold_accounts.current_debt_grams + v_net_rem_due)::numeric, 4),
    advance_balance_grams      = round(greatest(0, client_gold_accounts.advance_balance_grams - v_apply_adv)::numeric, 4),
    updated_at                 = now();

  -- Return complete payload with model_name, weight_grams, and client_markup_pct
  v_existing := jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale_id,
    'sale_no', v_sale_no,
    'model_name', v_piece.model_name,
    'model_code', v_piece.model_code,
    'weight_grams', v_base_w,
    'client_markup_pct', v_client_pct,
    'client_gold_due_grams', v_client_due,
    'gross_gold_due_grams', v_client_due,
    'advance_applied_grams', v_apply_adv,
    'net_remaining_debt_grams', v_net_rem_due,
    'remaining_gold_grams', v_net_rem_due,
    'piece_id', v_piece.id
  );

  if p_idempotency_key is not null then
    perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_barcode_piece_sale', v_existing, v_payload);
  end if;

  return v_existing;
end;
$function$;
revoke all on function rpc_record_barcode_piece_sale(uuid,uuid,uuid,uuid,numeric,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_barcode_piece_sale(uuid,uuid,uuid,uuid,numeric,numeric,text,text) to authenticated;
grant execute on function rpc_record_barcode_piece_sale(uuid,uuid,uuid,uuid,numeric,numeric,text,text) to service_role;

-- parity: rpc_record_client_jewelry_sale(uuid,uuid,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_client_jewelry_sale(p_customer_id uuid, p_consignment_id uuid, p_client_markup_pct numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org      uuid := public.current_organization_id();
  v_cons            public.seller_consignments%rowtype;
  v_cust            public.customers%rowtype;
  v_client_acc      public.client_gold_accounts%rowtype;
  v_caller_emp_id   uuid;
  v_caller_role     text := public.current_employee_role_text();
  v_client_markup   numeric(6, 2) := round(coalesce(p_client_markup_pct, 0)::numeric, 2);
  v_client_gold_due numeric(14, 4);
  v_markup_spread   numeric(14, 4);
  v_avail_adv       numeric(14, 4) := 0;
  v_apply_adv       numeric(14, 4) := 0;
  v_net_rem_due     numeric(14, 4);
  v_sale_id         uuid;
  v_sale_no         text;
  v_payload         jsonb;
  v_existing        jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  select id into v_caller_emp_id
    from public.employees
   where (user_id = auth.uid() or id = auth.uid())
     and organization_id = v_caller_org
   limit 1;

  if v_client_markup < 0 then
    raise exception 'Client markup percentage cannot be negative';
  end if;

  v_payload := jsonb_build_object(
    'action', 'record_client_sale',
    'customer_id', p_customer_id,
    'consignment_id', p_consignment_id,
    'client_markup_pct', v_client_markup
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_client_jewelry_sale', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- Lock consignment
  select * into v_cons
    from public.seller_consignments
   where id = p_consignment_id
     and organization_id = v_caller_org
   for update;
  if not found then
    raise exception 'Consignment (%) not found', p_consignment_id;
  end if;

  -- 070: only an untouched consignment may be sold as a whole; any weight sale, return or partial piece
  -- consumption means base_weight_grams no longer matches what the seller physically holds.
  if p_client_markup_pct is null or p_client_markup_pct < 0 or p_client_markup_pct > 100 then
    raise exception 'ERR_MARKUP_OUT_OF_RANGE: Mijoz ustama foizi 0 dan 100 gacha aniq ko''rsatilishi shart (kiritildi: %)', p_client_markup_pct;
  end if;
  if v_cons.status <> 'held_by_seller'
     or exists (select 1 from public.weight_sale_allocations w where w.consignment_id = v_cons.id and w.reversed_at is null)
     or exists (select 1 from public.jewelry_sales js where js.consignment_id = v_cons.id and js.status not in ('reversed', 'cancelled'))
     or (exists (select 1 from public.consignment_pieces p where p.consignment_id = v_cons.id)
         and abs(coalesce((select sum(p.weight_grams) from public.consignment_pieces p
                            where p.consignment_id = v_cons.id and p.status = 'held_by_seller'), 0) - v_cons.base_weight_grams) > 0.0001) then
    raise exception 'ERR_CONSIGNMENT_PARTIALLY_USED: Partiya % qisman sotilgan yoki qaytarilgan; donalab yoki vazn bo''yicha sotuvdan foydalaning', v_cons.consignment_no;
  end if;
  if v_cons.status in ('fully_sold', 'returned_to_factory', 'closed') or coalesce(v_cons.sold_quantity, 0) >= coalesce(v_cons.quantity, 0) then
    raise exception 'Consignment % is already closed or fully sold', v_cons.consignment_no;
  end if;

  -- P0-2: Check if pieces exist for this consignment in consignment_pieces and whether any piece was already sold
  if exists (
    select 1 from public.consignment_pieces
    where consignment_id = v_cons.id
      and status in ('sold', 'returned_to_factory', 'returned_to_manager')
  ) then
    raise exception 'Ushbu partiyadagi donalardan ayrimlari allaqachon sotilgan yoki qaytarilgan. Donalab sotuvdan foydalaning.';
  end if;

  -- Ensure seller owns this consignment unless privileged
  if v_caller_role not in ('admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi') then
    if v_cons.seller_id <> v_caller_emp_id then
      raise exception 'Cross-seller violation: You can only sell consignments allocated to your account' using errcode = '42501';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('goldia_seller_stock:' || v_cons.seller_id::text, 0));
  -- Verify customer
  select * into v_cust
    from public.customers
   where id = p_customer_id
     and organization_id = v_caller_org
   limit 1;
  if not found then
    raise exception 'Customer (%) not found in your organization', p_customer_id;
  end if;

  -- Non-compounding: Client gold due is calculated strictly from base weight
  v_client_gold_due := round((v_cons.base_weight_grams * (1.0 + v_client_markup / 100.0))::numeric, 4);
  v_markup_spread   := round((v_client_gold_due - v_cons.factory_gold_due_grams)::numeric, 4);

  -- Check existing advance balance
  select * into v_client_acc
    from public.client_gold_accounts
   where customer_id = v_cust.id
     and organization_id = v_caller_org
   for update;

  v_avail_adv := coalesce(v_client_acc.advance_balance_grams, 0);
  if v_avail_adv > 0 then
    v_apply_adv   := round(least(v_avail_adv, v_client_gold_due)::numeric, 4);
    v_net_rem_due := round((v_client_gold_due - v_apply_adv)::numeric, 4);
  else
    v_apply_adv   := 0;
    v_net_rem_due := v_client_gold_due;
  end if;

  v_sale_no := 'SALE-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  insert into public.jewelry_sales (
    organization_id, sale_no, seller_id, customer_id, consignment_id,
    product_id, product_name, quantity, base_weight_grams, proba,
    factory_markup_pct, factory_gold_due_grams,
    client_markup_pct, client_gold_due_grams, markup_spread_grams,
    settled_gold_grams, remaining_gold_grams, status,
    sale_date, idempotency_key, notes
  ) values (
    v_caller_org, v_sale_no, v_cons.seller_id, v_cust.id, v_cons.id,
    v_cons.product_id, v_cons.product_name, v_cons.quantity, v_cons.base_weight_grams, v_cons.proba,
    v_cons.factory_markup_pct, v_cons.factory_gold_due_grams,
    v_client_markup, v_client_gold_due, v_markup_spread,
    v_apply_adv, v_net_rem_due,
    case when v_net_rem_due <= 0.0001 then 'fully_paid' else 'open_debt' end,
    public._goldia_business_date(), nullif(btrim(p_idempotency_key), ''), p_notes
  ) returning id into v_sale_id;

  -- P0-2: ATOMICALLY UPDATE ALL PIECES in this consignment to 'sold' with sale_id
  update public.consignment_pieces
     set status = 'sold',
         sale_id = v_sale_id,
         sold_at = now(),
         updated_at = now()
   where consignment_id = v_cons.id
     and status = 'held_by_seller';

  -- Update parent consignment status
  update public.seller_consignments
     set sold_quantity = quantity,
         status        = 'fully_sold',
         updated_at    = now()
   where id = v_cons.id;

  -- Update client running debt in client_gold_accounts
  insert into public.client_gold_accounts (
    customer_id, organization_id, seller_id, total_purchased_gold_grams,
    current_debt_grams, advance_balance_grams, total_settled_grams, updated_at
  ) values (
    v_cust.id, v_caller_org, v_cons.seller_id, v_client_gold_due,
    v_net_rem_due, greatest(0, v_avail_adv - v_apply_adv), v_apply_adv, now()
  )
  on conflict (customer_id) do update set
    total_purchased_gold_grams = round((client_gold_accounts.total_purchased_gold_grams + v_client_gold_due)::numeric, 4),
    current_debt_grams         = round((client_gold_accounts.current_debt_grams + v_net_rem_due)::numeric, 4),
    advance_balance_grams      = round(greatest(0, client_gold_accounts.advance_balance_grams - v_apply_adv)::numeric, 4),
    total_settled_grams        = round((client_gold_accounts.total_settled_grams + v_apply_adv)::numeric, 4),
    seller_id                  = coalesce(client_gold_accounts.seller_id, v_cons.seller_id),
    updated_at                 = now();

  -- Update seller's total client debt tracking
  insert into public.seller_gold_accounts (
    seller_id, organization_id, total_client_debt_grams, updated_at
  ) values (
    v_cons.seller_id, v_caller_org, v_net_rem_due, now()
  )
  on conflict (seller_id) do update set
    total_client_debt_grams = round((seller_gold_accounts.total_client_debt_grams + v_net_rem_due)::numeric, 4),
    updated_at              = now();

  v_existing := jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale_id,
    'sale_no', v_sale_no,
    'seller_id', v_cons.seller_id,
    'customer_id', v_cust.id,
    'product_name', v_cons.product_name,
    'base_weight_grams', v_cons.base_weight_grams,
    'factory_gold_due_grams', v_cons.factory_gold_due_grams,
    'client_markup_pct', v_client_markup,
    'gross_gold_due_grams', v_client_gold_due,
    'client_gold_due_grams', v_client_gold_due,
    'advance_applied_grams', v_apply_adv,
    'net_remaining_debt_grams', v_net_rem_due,
    'remaining_gold_grams', v_net_rem_due,
    'markup_spread_grams', v_markup_spread
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_client_jewelry_sale', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_record_client_jewelry_sale(uuid,uuid,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_client_jewelry_sale(uuid,uuid,numeric,text,text) to authenticated;
grant execute on function rpc_record_client_jewelry_sale(uuid,uuid,numeric,text,text) to service_role;

-- parity: rpc_record_client_legacy_debt(uuid,text,numeric,date,text,text,numeric,text,uuid)
CREATE OR REPLACE FUNCTION public.rpc_record_client_legacy_debt(p_customer_id uuid, p_balance_type text, p_amount_585_g numeric, p_as_of_date date, p_notes text DEFAULT NULL::text, p_entry_type text DEFAULT 'initial'::text, p_target_final_balance numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org           uuid := public.current_organization_id();
  v_caller_emp_id        uuid := public.current_employee_id();
  v_customer             public.customers%rowtype;
  v_seller_id            uuid;
  v_client_acc           public.client_gold_accounts%rowtype;
  v_cur_debt             numeric(14, 4) := 0;
  v_cur_adv              numeric(14, 4) := 0;
  v_target               numeric(14, 4);
  v_delta                numeric(14, 4) := 0;
  v_new_debt             numeric(14, 4) := 0;
  v_new_adv              numeric(14, 4) := 0;
  v_amt                  numeric(14, 4);
  v_entry_type           text := coalesce(nullif(btrim(p_entry_type), ''), 'initial');
  v_bal_type             text := coalesce(nullif(btrim(p_balance_type), ''), 'debt');
  v_legacy_id            uuid;
  v_payload              jsonb;
  v_existing             jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter'
  ]);

  if p_customer_id is null then
    raise exception 'Mijoz tanlanishi shart';
  end if;

  if p_as_of_date is null then
    raise exception 'Qarz qaysi sanadagi holat ekani ko''rsatilishi shart';
  end if;

  if v_bal_type not in ('debt', 'advance') then
    raise exception 'Qoldiq turi faqat "debt" (qarz) yoki "advance" (avans) bo''lishi mumkin';
  end if;

  select * into v_customer
  from public.customers
  where id = p_customer_id and organization_id = v_caller_org
  for update;

  if not found then
    raise exception 'Mijoz topilmadi: %', p_customer_id;
  end if;

  v_seller_id := coalesce(p_seller_id, v_customer.seller_id);

  if p_idempotency_key is not null and btrim(p_idempotency_key) <> '' then
    v_payload := jsonb_build_object(
      'action', 'record_client_legacy_debt',
      'customer_id', p_customer_id,
      'balance_type', v_bal_type,
      'amount_585_g', p_amount_585_g,
      'target_balance', p_target_final_balance,
      'as_of_date', p_as_of_date
    );

    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_client_legacy_debt', v_payload);
    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  select * into v_client_acc
  from public.client_gold_accounts
  where customer_id = p_customer_id and organization_id = v_caller_org
  for update;

  if found then
    v_cur_debt := coalesce(v_client_acc.current_debt_grams, 0);
    v_cur_adv  := coalesce(v_client_acc.advance_balance_grams, 0);
  end if;

  if p_target_final_balance is not null then
    v_target := round(greatest(0, p_target_final_balance)::numeric, 4);

    if v_bal_type = 'debt' then
      v_new_debt := v_target;
      v_new_adv  := 0;
      v_delta    := round(v_new_debt - (v_cur_debt - v_cur_adv), 4);
    else
      v_new_debt := 0;
      v_new_adv  := v_target;
      v_delta    := round((-v_new_adv) - (v_cur_debt - v_cur_adv), 4);
    end if;

    v_amt := abs(v_delta);
    if abs(v_delta) < 0.0001 then
      return jsonb_build_object(
        'status', 'ok',
        'no_change_needed', true,
        'current_debt_585_g', v_cur_debt,
        'current_advance_585_g', v_cur_adv,
        'target_balance', v_target,
        'delta_585_g', 0
      );
    end if;

  else
    v_amt := round(greatest(0, coalesce(p_amount_585_g, 0))::numeric, 4);
    if v_amt <= 0 then
      raise exception 'Qarz yoki avans miqdori 0 dan katta bo''lishi shart';
    end if;

    if v_bal_type = 'debt' then
      v_delta := v_amt;
      if v_cur_adv > 0 then
        if v_cur_adv >= v_amt then
          v_new_adv  := round(v_cur_adv - v_amt, 4);
          v_new_debt := v_cur_debt;
        else
          v_new_debt := round(v_cur_debt + (v_amt - v_cur_adv), 4);
          v_new_adv  := 0;
        end if;
      else
        v_new_debt := round(v_cur_debt + v_amt, 4);
        v_new_adv  := 0;
      end if;
    else
      v_delta := -v_amt;
      if v_cur_debt > 0 then
        if v_cur_debt >= v_amt then
          v_new_debt := round(v_cur_debt - v_amt, 4);
          v_new_adv  := v_cur_adv;
        else
          v_new_adv  := round(v_cur_adv + (v_amt - v_cur_debt), 4);
          v_new_debt := 0;
        end if;
      else
        v_new_adv  := round(v_cur_adv + v_amt, 4);
        v_new_debt := 0;
      end if;
    end if;
  end if;

  insert into public.client_legacy_debts (
    organization_id, customer_id, seller_id, balance_type,
    amount_585_g, previous_debt_585_g, previous_advance_585_g, delta_585_g,
    new_debt_585_g, new_advance_585_g, as_of_date, notes,
    entry_type, status, created_by
  ) values (
    v_caller_org, p_customer_id, v_seller_id, v_bal_type,
    v_amt, v_cur_debt, v_cur_adv, v_delta,
    v_new_debt, v_new_adv, p_as_of_date, p_notes,
    v_entry_type, 'confirmed', v_caller_emp_id
  ) returning id into v_legacy_id;

  insert into public.client_gold_accounts (
    customer_id, organization_id, seller_id,
    total_purchased_gold_grams, total_scrap_paid_grams,
    total_cash_paid_amount, total_cash_equiv_grams, total_settled_grams,
    current_debt_grams, advance_balance_grams, updated_at
  ) values (
    p_customer_id, v_caller_org, v_seller_id,
    0, 0, 0, 0, 0,
    v_new_debt, v_new_adv, now()
  )
  on conflict (customer_id) do update set
    seller_id = coalesce(client_gold_accounts.seller_id, excluded.seller_id),
    current_debt_grams = v_new_debt,
    advance_balance_grams = v_new_adv,
    updated_at = now();

  if v_seller_id is not null then
    perform public.recalc_seller_gold_account(v_seller_id, v_caller_org);
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'legacy_debt_id', v_legacy_id,
    'customer_id', p_customer_id,
    'seller_id', v_seller_id,
    'balance_type', v_bal_type,
    'delta_585_g', v_delta,
    'previous_debt_585_g', v_cur_debt,
    'previous_advance_585_g', v_cur_adv,
    'new_debt_585_g', v_new_debt,
    'new_advance_585_g', v_new_adv,
    'as_of_date', p_as_of_date
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_client_legacy_debt', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_record_client_legacy_debt(uuid,text,numeric,date,text,text,numeric,text,uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_record_client_legacy_debt(uuid,text,numeric,date,text,text,numeric,text,uuid) to authenticated;
grant execute on function rpc_record_client_legacy_debt(uuid,text,numeric,date,text,text,numeric,text,uuid) to service_role;

-- parity: rpc_record_client_settlement(uuid,uuid,numeric,numeric,numeric,numeric,date,text,text,uuid,numeric,numeric)
CREATE OR REPLACE FUNCTION public.rpc_record_client_settlement(p_customer_id uuid, p_sale_id uuid DEFAULT NULL::uuid, p_scrap_weight numeric DEFAULT 0, p_scrap_proba numeric DEFAULT NULL::numeric, p_cash_amount numeric DEFAULT 0, p_rate_per_gram numeric DEFAULT NULL::numeric, p_settlement_date date DEFAULT _goldia_business_date(), p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_seller_id uuid DEFAULT NULL::uuid, p_usd_amount numeric DEFAULT 0, p_usd_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_org        uuid := public.current_organization_id();
  v_seller            public.employees%rowtype;
  v_customer          public.customers%rowtype;
  v_rate              numeric(18, 2);
  v_usd_rate          numeric(18, 2);
  v_physical_scrap    numeric(14, 4);
  v_proba             numeric(6, 2);
  v_fine_gold         numeric(14, 4) := 0;
  v_scrap_585_eq      numeric(14, 4) := 0;
  v_cash              numeric(18, 2);
  v_usd               numeric(18, 2);
  v_cash_equiv        numeric(14, 4) := 0;
  v_usd_equiv         numeric(14, 4) := 0;
  v_total_settled     numeric(14, 4);
  v_settle_id         uuid;
  v_settle_no         text;
  v_client_acc        public.client_gold_accounts%rowtype;
  v_prev_debt         numeric(14, 4) := 0;
  v_applied_to_debt   numeric(14, 4) := 0;
  v_excess_advance    numeric(14, 4) := 0;
  v_rem_debt          numeric(14, 4) := 0;
  v_new_advance       numeric(14, 4) := 0;
  v_payload           jsonb;
  v_existing          jsonb;
  v_caller_role       text := public.current_employee_role_text();
  v_caller_emp_id     uuid := public.current_employee_id();
  v_official_rate     numeric(18, 2);
  v_seller_rate       public.seller_rates%rowtype;
  v_own_usd_rate      numeric(18, 2);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi'
  ]);

  v_physical_scrap := round(greatest(0, coalesce(p_scrap_weight, 0))::numeric, 4);
  v_cash := round(greatest(0, coalesce(p_cash_amount, 0))::numeric, 2);
  v_usd  := round(greatest(0, coalesce(p_usd_amount, 0))::numeric, 2);

  if v_physical_scrap <= 0 and v_cash <= 0 and v_usd <= 0 then
    raise exception 'To''lov uchun lom vazni, naqd so''m yoki dollar summasi kiritilishi shart';
  end if;

  -- 1. Scrap validation
  if v_physical_scrap > 0 then
    if p_scrap_proba is null or p_scrap_proba <= 0 then
      raise exception 'Lom oltin probasi aniq ko''rsatilishi shart (masalan: 375, 585, 750, 995, 999.9)';
    end if;
    v_proba := round(p_scrap_proba::numeric, 2);
    if v_proba < 300.0 or v_proba > 1000.0 then
      raise exception 'Noto''g''ri proba kiritildi: % (ruxsat: 300 - 1000)', v_proba;
    end if;

    v_fine_gold := round((v_physical_scrap * (v_proba / 1000.0))::numeric, 4);
    v_scrap_585_eq := round((v_physical_scrap * (v_proba / 585.0))::numeric, 4);
  else
    v_proba := 585.0;
    v_fine_gold := 0;
    v_scrap_585_eq := 0;
  end if;

  -- 2. 585 Gold rate determination.
  v_official_rate := public._goldia_official_585_rate(v_caller_org);
  if public._goldia_is_seller_role(v_caller_role) and (v_cash > 0 or v_usd > 0) then
    -- 072: a seller's cash / USD payment uses the seller's OWN stored rates; the browser value is only checked.
    -- A retry of an already recorded payment returns the original response (original rate snapshot).
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_client_settlement',
      jsonb_build_object('action', 'record_client_settlement', 'customer_id', p_customer_id,
                         'scrap_weight', v_physical_scrap, 'cash_amount', v_cash, 'usd_amount', v_usd));
    if v_existing is not null then
      return v_existing;
    end if;
    select * into v_seller_rate from public.seller_rates
     where seller_id = v_caller_emp_id and organization_id = v_caller_org
     for share;
    v_rate := coalesce(v_seller_rate.lom_rate_uzs, v_official_rate);  -- no own LOM rate: official rate (pre-072 rule)
    if v_rate is null or v_rate <= 0 then
      raise exception 'ERR_DAILY_RATE_NOT_SET: LOM kursingiz belgilanmagan. Avval o''z kursingizni kiriting.';
    end if;
    if p_rate_per_gram is not null and p_rate_per_gram > 0 and abs(round(p_rate_per_gram::numeric, 2) - v_rate) > 0.01 then
      raise exception 'ERR_RATE_MISMATCH: Sizning joriy LOM kursingiz % UZS/g. Yuborilgan kurs: % UZS/g. Sahifani yangilang.',
        v_rate, p_rate_per_gram using errcode = '42501';
    end if;
    if v_usd > 0 then
      if v_seller_rate.usd_rate_uzs is null then
        raise exception 'ERR_USD_RATE_NOT_SET: Dollar qabul qilish uchun avval o''z USD kursingizni belgilang.';
      end if;
      if p_usd_rate is not null and p_usd_rate > 0 and abs(round(p_usd_rate::numeric, 2) - v_seller_rate.usd_rate_uzs) > 0.01 then
        raise exception 'ERR_RATE_MISMATCH: Sizning joriy USD kursingiz % UZS. Yuborilgan kurs: % UZS. Sahifani yangilang.',
          v_seller_rate.usd_rate_uzs, p_usd_rate using errcode = '42501';
      end if;
      v_own_usd_rate := v_seller_rate.usd_rate_uzs;
    end if;
  else
    if p_rate_per_gram is not null and p_rate_per_gram > 0 then
      v_rate := round(p_rate_per_gram::numeric, 2);
    else
      v_rate := v_official_rate;
    end if;
    perform public._goldia_assert_seller_rate(v_caller_role, v_rate, v_official_rate, (v_cash > 0 or v_usd > 0));
  end if;

  if (v_cash > 0 or v_usd > 0) and (v_rate is null or v_rate <= 0) then
    raise exception 'ERR_DAILY_RATE_NOT_SET: Naqd pul yoki dollarni qabul qilish uchun 585 oltin kursi kiritilishi shart! Avval kunlik kursni belgilang.';
  end if;

  -- Sentinel rate for scrap-only to satisfy DB check constraint
  if v_rate is null or v_rate <= 0 then
    v_rate := 1.0;
  end if;

  -- 3. USD rate determination (NO SILENT 12,850 FALLBACK!)
  if v_usd > 0 then
    if v_own_usd_rate is not null then
      v_usd_rate := v_own_usd_rate;
    elsif p_usd_rate is not null and p_usd_rate > 0 then
      v_usd_rate := round(p_usd_rate::numeric, 2);
    else
      raise exception 'ERR_USD_RATE_NOT_SET: Dollar (USD) to''lovini hisoblash uchun USD kursi (CBU yoki qo''lda) kiritilishi shart!';
    end if;

    -- USD -> UZS -> 585 Gold Grams
    v_usd_equiv := round(((v_usd * v_usd_rate) / v_rate)::numeric, 4);
  else
    v_usd_rate := null;
    v_usd_equiv := 0;
  end if;

  if v_cash > 0 then
    v_cash_equiv := round((v_cash / v_rate)::numeric, 4);
  else
    v_cash_equiv := 0;
  end if;

  -- 4. Total settled grams = scrap (in 585 eq) + UZS equiv + USD equiv
  v_total_settled := round(v_scrap_585_eq + v_cash_equiv + v_usd_equiv, 4);

  -- 5. Customer lookup
  select * into v_customer
  from public.customers
  where id = p_customer_id and organization_id = v_caller_org
  limit 1;
  if not found then
    raise exception 'Mijoz (%) topilmadi', p_customer_id;
  end if;

  -- 6. Seller lookup
  if p_seller_id is not null then
    select * into v_seller
    from public.employees
    where id = p_seller_id and organization_id = v_caller_org
    limit 1;
  elsif v_customer.seller_id is not null then
    select * into v_seller
    from public.employees
    where id = v_customer.seller_id and organization_id = v_caller_org
    limit 1;
  else
    select * into v_seller
    from public.employees
    where user_id = auth.uid() and organization_id = v_caller_org
    limit 1;
  end if;

  if v_seller.id is null then
    raise exception 'Sotuvchi aniqlanmadi';
  end if;

  -- 065: sellers may only collect for themselves and their own customers
  if public._goldia_is_seller_role(v_caller_role) then
    if v_caller_emp_id is null or v_seller.id <> v_caller_emp_id then
      raise exception 'Ruxsat etilmadi: Sotuvchi faqat o''z kassasiga to''lov qabul qila oladi' using errcode = '42501';
    end if;
    if v_customer.seller_id is not null and v_customer.seller_id <> v_caller_emp_id then
      raise exception 'Ruxsat etilmadi: Ushbu mijoz sizga biriktirilmagan' using errcode = '42501';
    end if;
  end if;

  if p_sale_id is not null and not exists (
    select 1 from public.jewelry_sales s
     where s.id = p_sale_id and s.organization_id = v_caller_org and s.customer_id = v_customer.id
       and s.status not in ('reversed', 'cancelled')
  ) then
    raise exception 'Savdo hujjati ushbu mijozga tegishli emas yoki bekor qilingan (%)', p_sale_id;
  end if;

  v_payload := jsonb_build_object(
    'action', 'record_client_settlement',
    'customer_id', p_customer_id,
    'scrap_weight', v_physical_scrap,
    'cash_amount', v_cash,
    'usd_amount', v_usd
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_client_settlement', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- 7. Lock client gold account FOR UPDATE (070: create the row first so concurrent first payments serialize)
  insert into public.client_gold_accounts (customer_id, organization_id, seller_id)
  values (v_customer.id, v_caller_org, v_seller.id)
  on conflict (customer_id) do nothing;
  select * into v_client_acc
  from public.client_gold_accounts
  where customer_id = p_customer_id and organization_id = v_caller_org
  for update;

  if found then
    v_prev_debt := coalesce(v_client_acc.current_debt_grams, 0);
  else
    v_prev_debt := 0;
  end if;

  -- Debt reduction math
  if v_total_settled <= v_prev_debt then
    v_applied_to_debt := v_total_settled;
    v_excess_advance  := 0;
    v_rem_debt        := round((v_prev_debt - v_total_settled)::numeric, 4);
    v_new_advance     := coalesce(v_client_acc.advance_balance_grams, 0);
  else
    v_applied_to_debt := v_prev_debt;
    v_excess_advance  := round((v_total_settled - v_prev_debt)::numeric, 4);
    v_rem_debt        := 0;
    v_new_advance     := round((coalesce(v_client_acc.advance_balance_grams, 0) + v_excess_advance)::numeric, 4);
  end if;

  v_settle_no := 'SETTL-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

  insert into public.gold_settlements (
    organization_id, settlement_no, direction, seller_id, customer_id, sale_id,
    settlement_date, gold_rate_applied,
    scrap_weight_grams, physical_scrap_grams, scrap_proba, fine_gold_grams, scrap_585_equiv_grams,
    cash_paid_amount, currency, cash_equivalent_grams,
    usd_paid_amount, applied_usd_rate, usd_equivalent_grams,
    total_settled_grams, applied_to_debt_grams, excess_gold_grams,
    previous_debt_grams, remaining_debt_grams,
    status, notes, recorded_by, idempotency_key
  ) values (
    v_caller_org, v_settle_no, 'client_to_seller', v_seller.id, v_customer.id, p_sale_id,
    coalesce(p_settlement_date, public._goldia_business_date()), v_rate,
    v_scrap_585_eq, v_physical_scrap, v_proba, v_fine_gold, v_scrap_585_eq,
    v_cash, 'UZS', v_cash_equiv,
    v_usd, v_usd_rate, v_usd_equiv,
    v_total_settled, v_applied_to_debt, v_excess_advance,
    v_prev_debt, v_rem_debt,
    'confirmed', p_notes, coalesce(public.current_employee_id(), v_seller.id), nullif(btrim(p_idempotency_key), '')
  ) returning id into v_settle_id;

  -- 8. Update client_gold_accounts atomically
  insert into public.client_gold_accounts (
    customer_id, organization_id, seller_id, total_purchased_gold_grams,
    total_scrap_paid_grams, total_cash_paid_amount, total_cash_equiv_grams, total_settled_grams,
    current_debt_grams, advance_balance_grams, updated_at
  ) values (
    v_customer.id, v_caller_org, v_seller.id, 0,
    v_scrap_585_eq, v_cash, round(v_cash_equiv + v_usd_equiv, 4), v_total_settled,
    v_rem_debt, v_new_advance, now()
  )
  on conflict (customer_id) do update set
    total_scrap_paid_grams = round((client_gold_accounts.total_scrap_paid_grams + v_scrap_585_eq)::numeric, 4),
    total_cash_paid_amount = round((client_gold_accounts.total_cash_paid_amount + v_cash)::numeric, 2),
    total_cash_equiv_grams = round((client_gold_accounts.total_cash_equiv_grams + v_cash_equiv + v_usd_equiv)::numeric, 4),
    total_usd_paid_amount  = round((coalesce(client_gold_accounts.total_usd_paid_amount, 0) + v_usd)::numeric, 2),
    total_usd_equiv_grams  = round((coalesce(client_gold_accounts.total_usd_equiv_grams, 0) + v_usd_equiv)::numeric, 4),
    total_settled_grams    = round((client_gold_accounts.total_settled_grams + v_total_settled)::numeric, 4),
    current_debt_grams     = v_rem_debt,
    advance_balance_grams  = v_new_advance,
    updated_at             = now();

  -- 9. Update seller till with received scrap (PHYSICAL and 585 EQ), cash UZS and cash USD
  insert into public.seller_gold_accounts (
    seller_id, organization_id,
    seller_till_scrap_grams, seller_till_scrap_physical_g, seller_till_scrap_585_eq_g,
    seller_till_cash_amount, seller_till_usd_amount, updated_at
  ) values (
    v_seller.id, v_caller_org,
    v_scrap_585_eq, v_physical_scrap, v_scrap_585_eq,
    v_cash, v_usd, now()
  )
  on conflict (seller_id) do update set
    seller_till_scrap_grams        = round((seller_gold_accounts.seller_till_scrap_grams + v_scrap_585_eq)::numeric, 4),
    seller_till_scrap_physical_g   = round((coalesce(seller_gold_accounts.seller_till_scrap_physical_g, 0) + v_physical_scrap)::numeric, 4),
    seller_till_scrap_585_eq_g     = round((coalesce(seller_gold_accounts.seller_till_scrap_585_eq_g, 0) + v_scrap_585_eq)::numeric, 4),
    seller_till_cash_amount        = round((seller_gold_accounts.seller_till_cash_amount + v_cash)::numeric, 2),
    seller_till_usd_amount         = round((coalesce(seller_gold_accounts.seller_till_usd_amount, 0) + v_usd)::numeric, 2),
    updated_at                     = now();

  -- If linked to specific sale, update settled amount on sale
  if p_sale_id is not null then
    update public.jewelry_sales
    set settled_gold_grams = round((coalesce(settled_gold_grams, 0) + v_applied_to_debt)::numeric, 4),
        remaining_gold_grams = round(greatest(0, remaining_gold_grams - v_applied_to_debt)::numeric, 4),
        status = case
          when round(greatest(0, remaining_gold_grams - v_applied_to_debt)::numeric, 4) <= 0.0001 then 'fully_paid'
          else 'partially_paid'
        end,
        updated_at = now()
    where id = p_sale_id and organization_id = v_caller_org;
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settle_id,
    'settlement_no', v_settle_no,
    'physical_scrap_grams', v_physical_scrap,
    'scrap_weight_grams', v_physical_scrap,
    'scrap_proba', v_proba,
    'fine_gold_grams', v_fine_gold,
    'scrap_585_equiv_grams', v_scrap_585_eq,
    'cash_paid_amount', v_cash,
    'usd_paid_amount', v_usd,
    'usd_rate_applied', v_usd_rate,
    'rate_applied', v_rate,
    'cash_equivalent_grams', v_cash_equiv,
    'usd_equivalent_grams', v_usd_equiv,
    'total_settled_585_grams', v_total_settled,
    'total_settled_grams', v_total_settled,
    'previous_debt_grams', v_prev_debt,
    'applied_to_debt_grams', v_applied_to_debt,
    'excess_gold_advance_grams', v_excess_advance,
    'excess_gold_grams', v_excess_advance,
    'remaining_debt_grams', v_rem_debt,
    'advance_balance_grams', v_new_advance,
    'seller_id', v_seller.id,
    'customer_id', v_customer.id
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_client_settlement', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_client_settlement(uuid,uuid,numeric,numeric,numeric,numeric,date,text,text,uuid,numeric,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_record_client_settlement(uuid,uuid,numeric,numeric,numeric,numeric,date,text,text,uuid,numeric,numeric) to authenticated;
grant execute on function rpc_record_client_settlement(uuid,uuid,numeric,numeric,numeric,numeric,date,text,text,uuid,numeric,numeric) to service_role;

-- parity: rpc_record_debt_repayment(text,text,numeric,numeric,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_debt_repayment(p_sale_id text DEFAULT NULL::text, p_order_id text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_repaid_amount numeric DEFAULT NULL::numeric, p_payment_type text DEFAULT 'Naqd pul'::text, p_note text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_sale          public.sales%rowtype;
  v_order         public.orders%rowtype;
  v_pay_amount    numeric(18, 2) := round(coalesce(nullif(p_repaid_amount, 0), p_amount, 0)::numeric, 2);
  v_prev_debt     numeric(18, 2);
  v_new_debt      numeric(18, 2);
  v_client        text;
  v_label         text;
  v_repayment_id  uuid;
  v_existing      jsonb;
  v_payload       jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'accountant', 'buxgalter', 'hisobchi', 'sales', 'manager', 'production_manager', 'production manager'
  ]);

  v_payload := jsonb_build_object(
    'sale_id', btrim(coalesce(p_sale_id, '')),
    'order_id', btrim(coalesce(p_order_id, '')),
    'amount', v_pay_amount
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_debt_repayment', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if v_pay_amount <= 0 then
    raise exception 'Debt repayment amount must be greater than 0';
  end if;

  if (coalesce(btrim(p_sale_id), '') = '' and coalesce(btrim(p_order_id), '') = '')
     or (coalesce(btrim(p_sale_id), '') <> '' and coalesce(btrim(p_order_id), '') <> '') then
    raise exception 'Specify exactly one of p_sale_id or p_order_id for debt repayment';
  end if;

  if coalesce(btrim(p_sale_id), '') <> '' then
    select * into v_sale from public.sales where id::text = btrim(p_sale_id) for update;
    if not found then
      raise exception 'Original sale (%) not found', p_sale_id;
    end if;

    if v_sale.organization_id is distinct from v_caller_org then
      raise exception 'Cross-tenant violation: Sale does not belong to your organization' using errcode = '42501';
    end if;

    v_prev_debt := round(coalesce(v_sale.debt_amount, 0)::numeric, 2);
    if v_prev_debt <= 0 then
      raise exception 'Sale (%) has no outstanding debt', p_sale_id;
    end if;
    if v_pay_amount > v_prev_debt then
      raise exception 'Repayment (%s) exceeds outstanding sale debt (%s)', v_pay_amount, v_prev_debt;
    end if;

    v_new_debt := round(v_prev_debt - v_pay_amount, 2);
    v_client   := v_sale.client_name;
    v_label    := format('Qarz to''lovi (%s)', v_sale.product_name);

    update public.sales
       set total_amount = round(coalesce(total_amount, 0) + v_pay_amount, 2),
           debt_amount  = v_new_debt
     where id = v_sale.id;
  else
    select * into v_order from public.orders where id::text = btrim(p_order_id) for update;
    if not found then
      raise exception 'Order (%) not found', p_order_id;
    end if;

    if v_order.organization_id is distinct from v_caller_org then
      raise exception 'Cross-tenant violation: Order does not belong to your organization' using errcode = '42501';
    end if;

    if lower(coalesce(v_order.status::text, '')) in ('cancelled', 'bekor qilindi')
       or lower(coalesce(v_order.status_label, '')) = 'bekor qilindi' then
      raise exception 'Cannot record debt repayment on a cancelled order (%)', coalesce(v_order.order_no, p_order_id);
    end if;

    v_prev_debt := round(greatest(0, coalesce(v_order.total_price, 0) - coalesce(v_order.advance, 0))::numeric, 2);
    if v_prev_debt <= 0 then
      raise exception 'Order (%) has no outstanding debt', coalesce(v_order.order_no, p_order_id);
    end if;
    if v_pay_amount > v_prev_debt then
      raise exception 'Repayment (%s) exceeds outstanding order debt (%s)', v_pay_amount, v_prev_debt;
    end if;

    v_new_debt := round(v_prev_debt - v_pay_amount, 2);
    v_client   := coalesce(v_order.client_name, v_order.customer_name, 'Mijoz');
    v_label    := format('Buyurtma Qarz To''lovi (%s)', coalesce(v_order.order_no, p_order_id));

    update public.orders
       set advance     = round(coalesce(advance, 0) + v_pay_amount, 2),
           paid_amount = round(coalesce(advance, 0) + v_pay_amount, 2),
           debt_amount = v_new_debt
     where id = v_order.id;
  end if;

  insert into public.debt_repayments (
    sale_id, order_id, client_name, amount, payment_type,
    previous_debt, remaining_debt, note, idempotency_key, recorded_by, organization_id
  ) values (
    nullif(btrim(p_sale_id), ''), nullif(btrim(p_order_id), ''), v_client, v_pay_amount, p_payment_type,
    v_prev_debt, v_new_debt, p_note, nullif(btrim(p_idempotency_key), ''), auth.uid(), v_caller_org
  ) returning id into v_repayment_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'repayment_id', v_repayment_id,
    'sale_id', nullif(btrim(p_sale_id), ''),
    'order_id', nullif(btrim(p_order_id), ''),
    'paid_amount', v_pay_amount,
    'previous_debt', v_prev_debt,
    'remaining_debt', v_new_debt,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_debt_repayment', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_debt_repayment(text,text,numeric,numeric,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_debt_repayment(text,text,numeric,numeric,text,text,text) to authenticated;
grant execute on function rpc_record_debt_repayment(text,text,numeric,numeric,text,text,text) to service_role;

-- parity: rpc_record_factory_gold_handover(text,numeric,numeric,numeric,text,text,text,numeric,uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.rpc_record_factory_gold_handover(p_source_type text DEFAULT 'refined_gold'::text, p_physical_weight_g numeric DEFAULT NULL::numeric, p_proba numeric DEFAULT 585.0, p_agreed_equivalent_g numeric DEFAULT NULL::numeric, p_factory_recipient text DEFAULT 'Zavod'::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_gross_weight_grams numeric DEFAULT NULL::numeric, p_capital_tx_id uuid DEFAULT NULL::uuid, p_refining_batch_id uuid DEFAULT NULL::uuid, p_purchase_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id           uuid := public.current_organization_id();
  v_emp_id           uuid := public.current_employee_id();
  v_notes            text := nullif(btrim(p_notes), '');
  v_cap_tx_id        uuid := p_capital_tx_id;
  v_ref_batch_id     uuid := p_refining_batch_id;
  v_purchase_id      uuid := p_purchase_id;
  v_phys_w           numeric(14, 4);
  v_pr               numeric(6, 2);
  v_computed_eq      numeric(14, 4);
  v_fine_w           numeric(14, 4);
  v_agreed_eq        numeric(14, 4);
  v_src_type         text;
  v_handover_no      text;
  v_handover_id      uuid;
  v_vault            public.manager_vault_account%rowtype;
  v_existing         jsonb;
  v_new_handed_over  numeric(14, 4);
  v_net_balance      numeric(14, 4);
  v_new_obligation   numeric(14, 4);
  v_new_advance      numeric(14, 4);
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_emp_id is null then
    select id into v_emp_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_org_id
    limit 1;
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi',
    'accountant', 'buxgalter'
  ]);

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'handover_id', id,
      'handover_no', handover_no,
      'agreed_equivalent_g', agreed_equivalent_g,
      'equivalent_585_grams', agreed_equivalent_g,
      'current_factory_obligation_g', (select current_factory_obligation_g from public.manager_vault_account where organization_id = v_org_id),
      'current_factory_advance_g', (select current_factory_advance_g from public.manager_vault_account where organization_id = v_org_id)
    ) into v_existing
    from public.factory_gold_handovers
    where idempotency_key = p_idempotency_key and organization_id = v_org_id;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_phys_w := round(coalesce(p_physical_weight_g, p_gross_weight_grams, 0)::numeric, 4);
  v_pr := round(coalesce(p_proba, 585.0)::numeric, 2);

  if v_phys_w <= 0 then
    raise exception 'Invalid physical weight: must be > 0';
  end if;

  v_computed_eq := round(v_phys_w * (v_pr / 585.0), 4);
  v_fine_w := round((v_phys_w * (v_pr / 1000.0))::numeric, 4);
  v_agreed_eq := round(coalesce(p_agreed_equivalent_g, v_computed_eq)::numeric, 4);
  v_src_type := lower(coalesce(p_source_type, 'refined_gold'));

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  if v_src_type = 'capital_pure_gold' then
    if coalesce(v_vault.manager_capital_pure_gold_g, 0) < v_agreed_eq then
      raise exception 'ERR_INSUFFICIENT_VAULT_CAPITAL_PURE: Boshqaruvchi seyfida yetarli toza oltin kapitali yo''q (Mavjud: % g 585 eq, Talab: % g)',
        coalesce(v_vault.manager_capital_pure_gold_g, 0), v_agreed_eq;
    end if;

    update public.manager_vault_account
    set manager_capital_pure_gold_g = round(greatest(0, coalesce(manager_capital_pure_gold_g, 0) - v_agreed_eq)::numeric, 4),
        manager_capital_pure_gold_fine_g = round(greatest(0, coalesce(manager_capital_pure_gold_fine_g, 0) - v_fine_w)::numeric, 4),
        updated_at = now()
    where organization_id = v_org_id;

  elsif v_src_type = 'refined_gold' then
    if coalesce(v_vault.manager_refined_gold_grams, 0) < v_agreed_eq then
      raise exception 'ERR_INSUFFICIENT_VAULT_REFINED: Boshqaruvchi seyfida yetarli afinaj qilingan toza oltin yo''q (Mavjud: % g 585 eq, Talab: % g)',
        coalesce(v_vault.manager_refined_gold_grams, 0), v_agreed_eq;
    end if;

    update public.manager_vault_account
    set manager_refined_gold_grams = round(greatest(0, manager_refined_gold_grams - v_agreed_eq)::numeric, 4),
        manager_refined_gold_fine_grams = round(greatest(0, coalesce(manager_refined_gold_fine_grams, 0) - v_fine_w)::numeric, 4),
        updated_at = now()
    where organization_id = v_org_id;

  elsif v_src_type = 'purchased_gold' then
    if coalesce(v_vault.manager_purchased_gold_grams, 0) < v_agreed_eq then
      raise exception 'ERR_INSUFFICIENT_VAULT_PURCHASED: Boshqaruvchi seyfida yetarli xarid qilingan oltin yo''q (Mavjud: % g, Talab: % g)',
        coalesce(v_vault.manager_purchased_gold_grams, 0), v_agreed_eq;
    end if;

    update public.manager_vault_account
    set manager_purchased_gold_grams = round(greatest(0, manager_purchased_gold_grams - v_agreed_eq)::numeric, 4),
        updated_at = now()
    where organization_id = v_org_id;

  elsif v_src_type = 'scrap_gold' then
    if coalesce(v_vault.manager_scrap_grams, 0) < v_phys_w then
      raise exception 'ERR_INSUFFICIENT_VAULT_SCRAP: Boshqaruvchi seyfida yetarli lom oltin yo''q (Mavjud: % g, Talab: % g)',
        coalesce(v_vault.manager_scrap_grams, 0), v_phys_w;
    end if;

    update public.manager_vault_account
    set manager_scrap_grams = round(greatest(0, manager_scrap_grams - v_phys_w)::numeric, 4),
        manager_scrap_physical_g = round(greatest(0, coalesce(manager_scrap_physical_g, 0) - v_phys_w)::numeric, 4),
        manager_scrap_585_eq_g = round(greatest(0, coalesce(manager_scrap_585_eq_g, 0) - v_agreed_eq)::numeric, 4),
        updated_at = now()
    where organization_id = v_org_id;
  end if;

  v_handover_no := 'HND-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.factory_gold_handovers (
    organization_id, handover_no, source_type,
    physical_weight_g, proba, agreed_equivalent_g,
    factory_recipient, handover_date, notes, idempotency_key, recorded_by,
    capital_tx_id, refining_batch_id, purchase_id
  ) values (
    v_org_id, v_handover_no, v_src_type,
    v_phys_w, v_pr, v_agreed_eq,
    p_factory_recipient, public._goldia_business_date(), v_notes, p_idempotency_key, v_emp_id,
    v_cap_tx_id, v_ref_batch_id, v_purchase_id
  ) returning id into v_handover_id;

  -- Update factory total obligation vs handovers
  select coalesce(sum(agreed_equivalent_g), 0) into v_new_handed_over
  from public.factory_gold_handovers
  where organization_id = v_org_id and status <> 'reversed';

  v_net_balance := coalesce(v_vault.total_factory_obligation_g, 0) - v_new_handed_over;

  if v_net_balance >= 0 then
    v_new_obligation := round(v_net_balance, 4);
    v_new_advance := 0;
  else
    v_new_obligation := 0;
    v_new_advance := round(abs(v_net_balance), 4);
  end if;

  update public.manager_vault_account
  set total_factory_handed_over_g = v_new_handed_over,
      current_factory_obligation_g = v_new_obligation,
      current_factory_advance_g = v_new_advance,
      updated_at = now()
  where organization_id = v_org_id;

  -- Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) values (
    v_org_id, 'factory_gold_handovers', v_handover_id::text,
    'CREATE_FACTORY_GOLD_HANDOVER', auth.uid(),
    null,
    jsonb_build_object(
      'handover_no', v_handover_no,
      'source_type', v_src_type,
      'physical_weight_g', v_phys_w,
      'agreed_equivalent_g', v_agreed_eq,
      'current_factory_obligation_g', v_new_obligation,
      'current_factory_advance_g', v_new_advance
    ),
    v_notes
  );

  return jsonb_build_object(
    'status', 'ok',
    'handover_id', v_handover_id,
    'handover_no', v_handover_no,
    'source_type', v_src_type,
    'physical_weight_g', v_phys_w,
    'agreed_equivalent_g', v_agreed_eq,
    'equivalent_585_grams', v_agreed_eq,
    'current_factory_obligation_g', v_new_obligation,
    'current_factory_advance_g', v_new_advance
  );
end;
$function$;
revoke all on function rpc_record_factory_gold_handover(text,numeric,numeric,numeric,text,text,text,numeric,uuid,uuid,uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_record_factory_gold_handover(text,numeric,numeric,numeric,text,text,text,numeric,uuid,uuid,uuid) to authenticated;
grant execute on function rpc_record_factory_gold_handover(text,numeric,numeric,numeric,text,text,text,numeric,uuid,uuid,uuid) to service_role;

-- parity: rpc_record_factory_receipt(text,integer,numeric,numeric,numeric,uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_factory_receipt(p_product_name text, p_quantity integer DEFAULT 1, p_original_physical_g numeric DEFAULT 0, p_proba numeric DEFAULT 585, p_factory_markup_pct numeric DEFAULT 8.0, p_product_id uuid DEFAULT NULL::uuid, p_model_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_org_id          uuid := public.current_organization_id();
  v_caller_role     text := public.current_employee_role_text();
  v_receipt_no      text;
  v_receipt_id      uuid;
  v_phys_g          numeric(14, 4);
  v_pr              numeric(6, 2);
  v_base_585_g      numeric(14, 4);
  v_f_pct           numeric(6, 2);
  v_f_due_g         numeric(14, 4);
  v_vault           public.manager_vault_account;
  v_existing        jsonb;
  v_new_obligation  numeric(14, 4);
  v_net_balance     numeric(14, 4);
  v_cur_obligation  numeric(14, 4);
  v_cur_advance     numeric(14, 4);
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  IF v_caller_role IN ('seller', 'sotuvchi', 'sales', 'worker', 'viewer') OR v_caller_role IS NULL THEN
    RAISE EXCEPTION 'Ruxsat etilmadi: Sotuvchi yoki begona foydalanuvchi zavod tovar kirimini saqlay olmaydi (Rol: %)', v_caller_role
      USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'production_manager', 'manager', 'boshqaruvchi', 'accountant', 'buxgalter'
  ]);

  v_phys_g := ROUND(COALESCE(p_original_physical_g, 0)::numeric, 4);
  IF v_phys_g <= 0 THEN
    RAISE EXCEPTION 'Zavod kirimi fizik vazni 0 dan katta bo''lishi shart';
  END IF;

  v_pr := ROUND(COALESCE(p_proba, 585.0)::numeric, 2);
  IF v_pr <> 585.0 THEN
    RAISE EXCEPTION 'JewelryFlow Sales tayyor mahsulotlar ombori faqat 585 proba uchun mo''ljallangan. Kiritilgan proba: %. Boshqa probalar (750/999) qabul qilinmaydi.', v_pr;
  END IF;

  v_base_585_g := v_phys_g;
  v_f_pct      := ROUND(COALESCE(p_factory_markup_pct, 8.0)::numeric, 2);
  v_f_due_g    := ROUND((v_base_585_g * (1.0 + v_f_pct / 100.0))::numeric, 4);

  IF p_idempotency_key IS NOT NULL THEN
    SELECT jsonb_build_object(
      'action', 'record_factory_receipt',
      'product_name', p_product_name,
      'physical_weight_g', v_phys_g,
      'original_physical_g', v_phys_g,
      'proba', v_pr
    ) INTO v_existing;
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_factory_receipt', v_existing);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  v_receipt_no := 'ZVD-' || to_char(NOW(), 'YYYYMMDD') || '-' || UPPER(SUBSTR(md5(random()::text || clock_timestamp()::text), 1, 6));

  INSERT INTO public.factory_receipts (
    organization_id, receipt_no, product_id, model_id, product_name,
    quantity, original_physical_g, available_physical_g, transferred_physical_g,
    proba, factory_markup_pct, factory_obligation_g, status, notes, idempotency_key
  ) VALUES (
    v_org_id, v_receipt_no, p_product_id, p_model_id, p_product_name,
    GREATEST(1, COALESCE(p_quantity, 1)), v_phys_g, v_phys_g, 0,
    v_pr, v_f_pct, v_f_due_g, 'in_manager_stock', p_notes, NULLIF(BTRIM(p_idempotency_key), '')
  ) RETURNING id INTO v_receipt_id;

  PERFORM public._get_or_create_manager_vault(v_org_id);
  SELECT * INTO v_vault FROM public.manager_vault_account WHERE organization_id = v_org_id FOR UPDATE;

  v_new_obligation := ROUND(v_vault.total_factory_obligation_g + v_f_due_g, 4);
  v_net_balance := ROUND(v_new_obligation - v_vault.total_factory_handed_over_g, 4);

  IF v_net_balance >= 0 THEN
    v_cur_obligation := v_net_balance;
    v_cur_advance := 0;
  ELSE
    v_cur_obligation := 0;
    v_cur_advance := ROUND(ABS(v_net_balance), 4);
  END IF;

  UPDATE public.manager_vault_account
     SET total_factory_received_g     = ROUND(total_factory_received_g + v_phys_g, 4),
         total_factory_obligation_g   = v_new_obligation,
         current_factory_obligation_g = v_cur_obligation,
         current_factory_advance_g    = v_cur_advance,
         manager_physical_stock_g     = public.get_manager_available_stock_grams(v_org_id),
         updated_at                   = clock_timestamp()
   WHERE organization_id = v_org_id;

  -- Audit log
  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) VALUES (
    v_org_id, 'factory_receipts', v_receipt_id::text, 'RECORD_RECEIPT', auth.uid(),
    NULL,
    jsonb_build_object(
      'receipt_no', v_receipt_no,
      'product_name', p_product_name,
      'physical_weight_g', v_phys_g,
      'original_physical_g', v_phys_g,
      'proba', v_pr,
      'factory_markup_pct', v_f_pct,
      'factory_obligation_g', v_f_due_g
    ),
    'Factory finished goods receipt'
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'receipt_id', v_receipt_id,
    'receipt_no', v_receipt_no,
    'physical_weight_g', v_phys_g,
    'original_physical_g', v_phys_g,
    'proba', v_pr,
    'factory_markup_pct', v_f_pct,
    'factory_obligation_g', v_f_due_g,
    'new_total_obligation_g', v_new_obligation
  );
  -- 070: the key was checked but never stored before, so a retried request created a second receipt
  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_record_factory_receipt', v_existing,
      jsonb_build_object('action', 'record_factory_receipt', 'product_name', p_product_name,
        'physical_weight_g', v_phys_g, 'original_physical_g', v_phys_g, 'proba', v_pr));
  END IF;
  RETURN v_existing;
END;
$function$;
revoke all on function rpc_record_factory_receipt(text,integer,numeric,numeric,numeric,uuid,uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_factory_receipt(text,integer,numeric,numeric,numeric,uuid,uuid,text,text) to authenticated;
grant execute on function rpc_record_factory_receipt(text,integer,numeric,numeric,numeric,uuid,uuid,text,text) to service_role;

-- parity: rpc_record_financial_transaction(text,text,numeric,text,text,text,numeric,numeric,text,numeric,numeric,numeric,uuid,uuid,text,integer)
CREATE OR REPLACE FUNCTION public.rpc_record_financial_transaction(p_transaction_type text, p_source_till text, p_amount numeric, p_currency text, p_category text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_gold_rate numeric DEFAULT NULL::numeric, p_usd_rate numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_physical_weight numeric DEFAULT NULL::numeric, p_physical_weight_g numeric DEFAULT NULL::numeric, p_gold_proba numeric DEFAULT NULL::numeric, p_seller_id uuid DEFAULT NULL::uuid, p_model_id uuid DEFAULT NULL::uuid, p_product_name text DEFAULT NULL::text, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_today           date := (timezone('Asia/Tashkent', now()))::date;
  v_tx_id           uuid;
  v_tx_no           text;
  v_amt             numeric(18, 4);
  v_cur             text := upper(btrim(p_currency));
  v_type            text := lower(btrim(p_transaction_type));
  v_till            text := lower(btrim(p_source_till));
  v_rate_585        numeric(18, 2);
  v_rate_usd        numeric(18, 2);
  v_equiv_585       numeric(14, 4);
  v_fine_g          numeric(14, 4);
  v_phys_w          numeric(14, 4);
  v_proba           numeric(6, 2);
  v_vault           public.manager_vault_account%rowtype;
  v_existing        jsonb;
  v_payload         jsonb;
  v_rec_no          text;
  v_receipt_id      uuid;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  -- Normalize currency representations
  if v_cur in ('GRAMS_585', '585', 'G585') then
    v_cur := '585_GOLD';
  elsif v_cur in ('GRAMS_FINE', 'FINE', '995', '9999', 'PURE', 'PURE_GOLD') then
    v_cur := 'FINE_GOLD';
  elsif v_cur in ('SCRAP', 'LOM') then
    v_cur := 'SCRAP_GOLD';
  elsif v_cur in ('FINISHED') then
    v_cur := 'FINISHED_GOODS';
  elsif v_cur in ('CASH_UZS') then
    v_cur := 'UZS';
  elsif v_cur in ('CASH_USD') then
    v_cur := 'USD';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if v_caller_emp_id is null then
    select id into v_caller_emp_id from public.employees where user_id = auth.uid() and organization_id = v_org_id limit 1;
  end if;

  v_amt := round(coalesce(p_amount, 0)::numeric, 4);
  if v_amt <= 0 then
    raise exception 'Tranzaksiya summasi yoki miqdori 0 dan katta bo''lishi shart';
  end if;

  -- Unified physical weight resolution (accepts both p_physical_weight and p_physical_weight_g)
  v_phys_w := round(coalesce(p_physical_weight, p_physical_weight_g, v_amt)::numeric, 4);
  v_proba  := round(coalesce(p_gold_proba, 585.0)::numeric, 2);

  v_payload := jsonb_build_object(
    'type', v_type,
    'source_till', v_till,
    'amount', v_amt,
    'currency', v_cur,
    'physical_weight', v_phys_w,
    'gold_proba', v_proba
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_financial_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- Gold and USD rate resolution
  if p_gold_rate is not null and p_gold_rate > 0 then
    v_rate_585 := round(p_gold_rate::numeric, 2);
  else
    select rate_per_gram into v_rate_585
      from public.daily_gold_rates
     where organization_id = v_org_id
     order by rate_date desc, created_at desc limit 1;
    v_rate_585 := coalesce(v_rate_585, 880000);
  end if;

  if p_usd_rate is not null and p_usd_rate > 0 then
    v_rate_usd := round(p_usd_rate::numeric, 2);
  else
    -- 070: public.currency_rates is not created by any migration; query it only when it exists and
    -- never value a USD amount with a silent default rate.
    if to_regclass('public.currency_rates') is not null then
      execute 'select rate_to_uzs from public.currency_rates where organization_id = $1 and from_currency = ''USD'' order by rate_date desc, created_at desc limit 1'
        into v_rate_usd using v_org_id;
    end if;
    if v_rate_usd is null and v_cur in ('USD', 'CASH_USD') then
      raise exception 'ERR_USD_RATE_NOT_SET: USD summasi uchun USD kursi (p_usd_rate) kiritilishi shart';
    end if;
    v_rate_usd := coalesce(v_rate_usd, 12800); -- only reached for non-USD amounts (stored for reference)
  end if;

  -- 585 Gold Equivalent Calculation
  if v_cur in ('UZS', 'CASH_UZS') then
    v_equiv_585 := round((v_amt / v_rate_585)::numeric, 4);
    v_fine_g    := round((v_equiv_585 * 0.585)::numeric, 4);
  elsif v_cur in ('USD', 'CASH_USD') then
    v_equiv_585 := round(((v_amt * v_rate_usd) / v_rate_585)::numeric, 4);
    v_fine_g    := round((v_equiv_585 * 0.585)::numeric, 4);
  elsif v_cur in ('SCRAP_GOLD', '585_GOLD') then
    v_equiv_585 := round(v_phys_w * (v_proba / 585.0), 4);
    v_fine_g    := round((v_phys_w * (v_proba / 1000.0))::numeric, 4);
  elsif v_cur in ('FINE_GOLD', 'PURE_GOLD', '995_GOLD', '999_GOLD') then
    v_proba     := coalesce(p_gold_proba, 995.0);
    v_fine_g    := round((v_phys_w * (v_proba / 1000.0))::numeric, 4);
    v_equiv_585 := round((v_phys_w * (v_proba / 585.0))::numeric, 4);
  elsif v_cur in ('FINISHED_GOODS') then
    v_equiv_585 := round(v_phys_w * (v_proba / 585.0), 4);
    v_fine_g    := round((v_phys_w * (v_proba / 1000.0))::numeric, 4);
  else
    v_equiv_585 := round(v_amt::numeric, 4);
    v_fine_g    := round((v_equiv_585 * 0.585)::numeric, 4);
  end if;

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  -- 1. Apply asset balance updates atomically (No fake profit!)
  if v_type in ('capital_in', 'capital_contribution') then
    if v_till in ('manager_fine_gold', 'manager_capital_pure_gold', 'manager_vault_pure_gold') or v_cur in ('FINE_GOLD', 'PURE_GOLD') then
      -- Pure cast gold goes to pure gold capital safe (NOT affinage output!)
      update public.manager_vault_account
         set manager_capital_pure_gold_g      = round(manager_capital_pure_gold_g + v_equiv_585, 4),
             manager_capital_pure_gold_fine_g = round(manager_capital_pure_gold_fine_g + v_phys_w, 4),
             updated_at                       = now()
       where organization_id = v_org_id;

    elsif v_till in ('manager_scrap', 'manager_vault_scrap') then
      update public.manager_vault_account
         set manager_scrap_grams    = round(manager_scrap_grams + v_equiv_585, 4),
             manager_scrap_physical_g = round(coalesce(manager_scrap_physical_g, 0) + v_phys_w, 4),
             manager_scrap_585_eq_g   = round(coalesce(manager_scrap_585_eq_g, 0) + v_equiv_585, 4),
             updated_at             = now()
       where organization_id = v_org_id;

    elsif v_till in ('seller_till_scrap') and p_seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_scrap_grams      = round(seller_till_scrap_grams + v_equiv_585, 4),
             seller_till_scrap_physical_g = round(coalesce(seller_till_scrap_physical_g, 0) + v_phys_w, 4),
             seller_till_scrap_585_eq_g   = round(coalesce(seller_till_scrap_585_eq_g, 0) + v_equiv_585, 4),
             updated_at                   = now()
       where seller_id = p_seller_id and organization_id = v_org_id;

    elsif v_till in ('manager_finished', 'manager_stock') or v_cur = 'FINISHED_GOODS' then
      v_rec_no := 'CAP-FIN-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));
      insert into public.factory_receipts (
        organization_id, receipt_no, product_name, quantity, original_physical_g,
        available_physical_g, transferred_physical_g, proba, factory_markup_pct,
        factory_obligation_g, status, notes
      ) values (
        v_org_id, v_rec_no, coalesce(p_product_name, 'Kapital Tayyor Mahsulot'),
        greatest(1, coalesce(p_quantity, 1)), v_phys_w, v_phys_w, 0,
        v_proba, 0.0, 0.0, 'in_manager_stock',
        'KAPITAL KIRIMI: Ta''sischi hissasi sifatida kiritilgan mahsulot (Zavod qarzi yaratilmaydi)'
      ) returning id into v_receipt_id;

      update public.manager_vault_account
         set manager_finished_capital_g = round(coalesce(manager_finished_capital_g, 0) + v_phys_w, 4),
             manager_physical_stock_g   = public.get_manager_available_stock_grams(v_org_id),
             updated_at                 = now()
       where organization_id = v_org_id;

    elsif v_till in ('manager_uzs', 'manager_cash') then
      update public.manager_vault_account
         set manager_cash_amount = round(manager_cash_amount + v_amt, 2),
             updated_at          = now()
       where organization_id = v_org_id;

    elsif v_till in ('seller_till_uzs') and p_seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_cash_amount = round(seller_till_cash_amount + v_amt, 2),
             updated_at              = now()
       where seller_id = p_seller_id and organization_id = v_org_id;

    elsif v_till in ('manager_usd') then
      update public.manager_vault_account
         set manager_usd_amount = round(manager_usd_amount + v_amt, 2),
             updated_at         = now()
       where organization_id = v_org_id;

    elsif v_till in ('seller_till_usd') and p_seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_usd_amount = round(coalesce(seller_till_usd_amount, 0) + v_amt, 2),
             updated_at             = now()
       where seller_id = p_seller_id and organization_id = v_org_id;

    else
      -- Default to manager vault gold
      update public.manager_vault_account
         set manager_capital_pure_gold_g = round(manager_capital_pure_gold_g + v_equiv_585, 4),
             updated_at                  = now()
       where organization_id = v_org_id;
    end if;

  elsif v_type in ('capital_out', 'capital_distribution', 'expense', 'business_expense') then
    if v_till in ('manager_uzs', 'manager_cash') then
      if v_vault.manager_cash_amount < v_amt then
        raise exception 'Boshqaruvchi kassasida yetarli naqd pul yo''q (Mavjud: % UZS, Talab: % UZS)',
          v_vault.manager_cash_amount, v_amt;
      end if;
      update public.manager_vault_account
         set manager_cash_amount = round(manager_cash_amount - v_amt, 2),
             updated_at          = now()
       where organization_id = v_org_id;

    elsif v_till in ('manager_usd') then
      if v_vault.manager_usd_amount < v_amt then
        raise exception 'Boshqaruvchi kassasida yetarli USD yo''q (Mavjud: $% , Talab: $%)',
          v_vault.manager_usd_amount, v_amt;
      end if;
      update public.manager_vault_account
         set manager_usd_amount = round(manager_usd_amount - v_amt, 2),
             updated_at         = now()
       where organization_id = v_org_id;

    elsif v_till in ('manager_scrap') then
      if v_vault.manager_scrap_grams < v_equiv_585 then
        raise exception 'Boshqaruvchi seyfida yetarli lom yo''q (Mavjud: % g, Talab: % g)',
          v_vault.manager_scrap_grams, v_equiv_585;
      end if;
      update public.manager_vault_account
         set manager_scrap_grams = round(manager_scrap_grams - v_equiv_585, 4),
             updated_at          = now()
       where organization_id = v_org_id;
    end if;
  end if;

  -- 2. Insert transaction record
  v_tx_no := 'FTX-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));

  insert into public.financial_transactions (
    organization_id, transaction_no, transaction_date, transaction_type,
    source_till, amount_num, currency, gold_rate_applied, usd_rate_applied,
    equiv_585_grams, category, notes, recorded_by, idempotency_key,
    physical_weight_grams, gold_proba, seller_id, status
  ) values (
    v_org_id, v_tx_no, v_today, v_type,
    v_till, v_amt, v_cur, v_rate_585, v_rate_usd,
    v_equiv_585, p_category, p_notes, v_caller_emp_id, p_idempotency_key,
    v_phys_w, v_proba, p_seller_id, 'confirmed'
  ) returning id into v_tx_id;

  -- 3. Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, new_data
  ) values (
    v_org_id, 'financial_transactions', v_tx_id::text, 'RECORD_FINANCIAL_TRANSACTION', auth.uid(),
    jsonb_build_object(
      'transaction_no', v_tx_no,
      'type', v_type,
      'source_till', v_till,
      'amount', v_amt,
      'currency', v_cur,
      'equiv_585_grams', v_equiv_585,
      'physical_weight_grams', v_phys_w,
      'gold_proba', v_proba
    )
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'id', v_tx_id,
    'transaction_id', v_tx_id,
    'transaction_no', v_tx_no,
    'equiv_585_grams', v_equiv_585,
    'fine_gold_grams', v_fine_g,
    'physical_weight_g', v_phys_w,
    'gold_proba', v_proba
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_financial_transaction', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_record_financial_transaction(text,text,numeric,text,text,text,numeric,numeric,text,numeric,numeric,numeric,uuid,uuid,text,integer) from public, anon, authenticated, service_role;
grant execute on function rpc_record_financial_transaction(text,text,numeric,text,text,text,numeric,numeric,text,numeric,numeric,numeric,uuid,uuid,text,integer) to authenticated;
grant execute on function rpc_record_financial_transaction(text,text,numeric,text,text,text,numeric,numeric,text,numeric,numeric,numeric,uuid,uuid,text,integer) to service_role;

-- parity: rpc_record_gold_purchase(text,numeric,numeric,numeric,numeric,text,text,text,numeric,numeric)
CREATE OR REPLACE FUNCTION public.rpc_record_gold_purchase(p_supplier_name text, p_cash_spent_uzs numeric DEFAULT 0, p_rate_per_gram numeric DEFAULT NULL::numeric, p_gold_weight_grams numeric DEFAULT NULL::numeric, p_proba numeric DEFAULT 585.0, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_currency text DEFAULT 'UZS'::text, p_usd_spent numeric DEFAULT 0, p_usd_rate numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id         uuid := public.current_organization_id();
  v_emp_id         uuid := public.current_employee_id();
  v_cash_spent     numeric(18, 2);
  v_usd_spent      numeric(18, 2);
  v_usd_rate       numeric(14, 2);
  v_rate           numeric(18, 2);
  v_gold_w         numeric(14, 4);
  v_pr             numeric(6, 2);
  v_equiv_585      numeric(14, 4);
  v_purch_no       text;
  v_purch_id       uuid;
  v_vault          public.manager_vault_account;
  v_existing       jsonb;
  v_currency       text;
  v_total_cost_uzs numeric(18, 2);
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_emp_id is null then
    select id into v_emp_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_org_id
    limit 1;
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'inventory_manager', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  -- Strict validation of inputs without silent greatest(0, ...)
  if p_cash_spent_uzs is not null and p_cash_spent_uzs < 0 then
    raise exception 'Sarflangan UZS summasi manfiy bo''lishi mumkin emas (%)', p_cash_spent_uzs;
  end if;

  if p_usd_spent is not null and p_usd_spent < 0 then
    raise exception 'Sarflangan USD summasi manfiy bo''lishi mumkin emas (%)', p_usd_spent;
  end if;

  if p_gold_weight_grams is not null and p_gold_weight_grams < 0 then
    raise exception 'Olingan oltin vazni manfiy bo''lishi mumkin emas (%)', p_gold_weight_grams;
  end if;

  if p_rate_per_gram is not null and p_rate_per_gram < 0 then
    raise exception 'Gramm kursi manfiy bo''lishi mumkin emas (%)', p_rate_per_gram;
  end if;

  v_cash_spent := round(coalesce(p_cash_spent_uzs, 0)::numeric, 2);
  v_usd_spent  := round(coalesce(p_usd_spent, 0)::numeric, 2);
  v_gold_w     := round(coalesce(p_gold_weight_grams, 0)::numeric, 4);
  v_pr         := round(coalesce(p_proba, 585.0)::numeric, 2);
  v_rate       := round(coalesce(p_rate_per_gram, 0)::numeric, 2);

  if v_cash_spent > 0 and v_usd_spent > 0 then
    v_currency := 'MIXED';
  elsif v_usd_spent > 0 then
    v_currency := 'USD';
  else
    v_currency := 'UZS';
  end if;

  if v_cash_spent <= 0 and v_usd_spent <= 0 then
    raise exception 'Xarid uchun UZS yoki USD summasi kiritilishi shart (ikkalasi ham 0 bo''lishi mumkin emas)';
  end if;

  if v_gold_w <= 0 then
    raise exception 'Oltin vazni 0 dan katta bo''lishi shart';
  end if;

  if v_pr <= 0 or v_pr > 1000 then
    raise exception 'Oltin probasi noto''g''ri (%): 1 dan 1000 gacha bo''lishi shart', v_pr;
  end if;

  -- Mandatory positive USD rate check for USD or MIXED purchases
  if v_usd_spent > 0 then
    if p_usd_rate is null or p_usd_rate <= 0 then
      raise exception 'USD yoki MIXED xarid uchun musbat USD/UZS kursi (p_usd_rate) kiritilishi majburiy!';
    end if;
    v_usd_rate := round(p_usd_rate::numeric, 2);
    v_total_cost_uzs := round(v_cash_spent + (v_usd_spent * v_usd_rate), 2);
  else
    v_usd_rate := null;
    v_total_cost_uzs := v_cash_spent;
  end if;

  if v_total_cost_uzs <= 0 then
    raise exception 'Jami xarid qiymati (UZS) 0 dan katta bo''lishi shart!';
  end if;

  if v_rate <= 0 and v_gold_w > 0 then
    v_rate := round((v_total_cost_uzs / v_gold_w)::numeric, 2);
  end if;

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'purchase_id', id,
      'purchase_no', purchase_no,
      'gold_weight_grams', gold_weight_grams,
      'equiv_585_grams', equiv_585_grams,
      'currency', currency
    ) into v_existing
    from public.gold_purchases
    where idempotency_key = p_idempotency_key;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_equiv_585 := round(v_gold_w * (v_pr / 585.0), 4);

  -- Check and lock manager vault
  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  if v_cash_spent > 0 and coalesce(v_vault.manager_cash_amount, 0) < v_cash_spent then
    raise exception 'ERR_INSUFFICIENT_VAULT_CASH: Boshqaruvchi seyfida yetarli naqd pul (UZS) mavjud emas (Mavjud: % UZS, Talab: % UZS)',
      coalesce(v_vault.manager_cash_amount, 0), v_cash_spent;
  end if;

  if v_usd_spent > 0 and coalesce(v_vault.manager_usd_amount, 0) < v_usd_spent then
    raise exception 'ERR_INSUFFICIENT_VAULT_USD: Boshqaruvchi seyfida yetarli valyuta (USD) mavjud emas (Mavjud: $% USD, Talab: $% USD)',
      coalesce(v_vault.manager_usd_amount, 0), v_usd_spent;
  end if;

  v_purch_no := 'BUY-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));

  insert into public.gold_purchases (
    organization_id, purchase_no, supplier_name, cash_spent_uzs,
    rate_per_gram, gold_weight_grams, proba, equiv_585_grams,
    currency, usd_spent, usd_rate, total_cost_uzs,
    recorded_by, notes, idempotency_key, status
  ) values (
    v_org_id, v_purch_no, coalesce(p_supplier_name, 'Bozor / Noma''lum Ta''minotchi'),
    v_cash_spent, v_rate, v_gold_w, v_pr, v_equiv_585,
    v_currency, v_usd_spent, v_usd_rate, v_total_cost_uzs,
    v_emp_id, p_notes, p_idempotency_key, 'confirmed'
  ) returning id into v_purch_id;

  -- Deduct exact currencies and add purchased gold to safe
  update public.manager_vault_account
     set manager_cash_amount          = round(manager_cash_amount - v_cash_spent, 2),
         manager_usd_amount           = round(manager_usd_amount - v_usd_spent, 2),
         manager_purchased_gold_grams = round(manager_purchased_gold_grams + v_equiv_585, 4),
         updated_at                   = clock_timestamp()
   where organization_id = v_org_id;

  return jsonb_build_object(
    'status', 'ok',
    'purchase_id', v_purch_id,
    'purchase_no', v_purch_no,
    'gold_weight_grams', v_gold_w,
    'equiv_585_grams', v_equiv_585,
    'currency', v_currency,
    'cash_spent_uzs', v_cash_spent,
    'usd_spent', v_usd_spent,
    'usd_rate', v_usd_rate,
    'total_cost_uzs', v_total_cost_uzs
  );
end;
$function$;
revoke all on function rpc_record_gold_purchase(text,numeric,numeric,numeric,numeric,text,text,text,numeric,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_record_gold_purchase(text,numeric,numeric,numeric,numeric,text,text,text,numeric,numeric) to authenticated;
grant execute on function rpc_record_gold_purchase(text,numeric,numeric,numeric,numeric,text,text,text,numeric,numeric) to service_role;

-- parity: rpc_record_login_audit(uuid,text,text,text,text,text,text,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_login_audit(p_employee_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_role text DEFAULT 'unknown'::text, p_login_method text DEFAULT 'password'::text, p_telegram_user_id text DEFAULT NULL::text, p_status text DEFAULT 'success'::text, p_failure_reason text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid;
  v_id uuid;
begin
  if p_employee_id is not null then
    select organization_id into v_org_id from public.employees where id = p_employee_id;
  end if;

  if v_org_id is null then
    select id into v_org_id from public.organizations limit 1;
  end if;

  insert into public.sales_login_audit_logs (
    organization_id,
    employee_id,
    email,
    role,
    login_method,
    telegram_user_id,
    ip_address,
    user_agent,
    status,
    failure_reason
  ) values (
    v_org_id,
    p_employee_id,
    p_email,
    p_role,
    p_login_method,
    p_telegram_user_id,
    coalesce(p_ip_address, p_ip),
    p_user_agent,
    p_status,
    p_failure_reason
  )
  returning id into v_id;

  return v_id;
end;
$function$;
revoke all on function rpc_record_login_audit(uuid,text,text,text,text,text,text,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_login_audit(uuid,text,text,text,text,text,text,text,text,text) to authenticated;
grant execute on function rpc_record_login_audit(uuid,text,text,text,text,text,text,text,text,text) to service_role;

-- parity: rpc_record_manager_seller_settlement(uuid,numeric,numeric,numeric,text,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_manager_seller_settlement(p_seller_id uuid, p_physical_scrap_grams numeric DEFAULT 0, p_scrap_proba numeric DEFAULT 585, p_cash_amount numeric DEFAULT 0, p_currency text DEFAULT 'UZS'::text, p_rate_per_gram numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id             uuid := public.current_organization_id();
  v_caller_role        text := public.current_employee_role_text();
  v_settlement_no      text;
  v_settlement_id      uuid;
  v_scrap_g            numeric(14, 4);
  v_p                  numeric(6, 2);
  v_scrap_585_eq       numeric(14, 4);
  v_cash               numeric(18, 2);
  v_rate               numeric(18, 2);
  v_cash_585_eq        numeric(14, 4);
  v_total_deducted_g   numeric(14, 4);
  v_seller_acc         public.seller_gold_accounts;
  v_vault              public.manager_vault_account;
  v_existing           jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_caller_role in ('seller', 'worker', 'viewer') or v_caller_role is null then
    raise exception 'Ruxsat etilmadi: Sotuvchi o''zining tushumini tasdiqlay olmaydi (Rol: %)', v_caller_role
      using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'production_manager', 'manager', 'boshqaruvchi', 'accountant', 'buxgalter']);

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'settlement_id', id,
      'settlement_no', settlement_no,
      'total_deducted_585_eq_grams', total_deducted_585_eq_grams
    ) into v_existing
    from public.manager_seller_settlements
    where idempotency_key = p_idempotency_key;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_scrap_g := round(greatest(0, coalesce(p_physical_scrap_grams, 0))::numeric, 4);
  v_p := round(coalesce(p_scrap_proba, 585)::numeric, 2);
  v_cash := round(greatest(0, coalesce(p_cash_amount, 0))::numeric, 2);

  if v_scrap_g = 0 and v_cash = 0 then
    raise exception 'Invalid settlement: must provide at least scrap gold or cash';
  end if;

  v_scrap_585_eq := round((v_scrap_g * v_p) / 585.0, 4);

  if v_cash > 0 then
    if p_rate_per_gram is not null and p_rate_per_gram > 0 then
      v_rate := round(p_rate_per_gram::numeric, 2);
    else
      select rate_per_gram into v_rate
      from public.daily_gold_rates
      where organization_id = v_org_id and proba = 585
      order by rate_date desc limit 1;

      if v_rate is null or v_rate <= 0 then
        raise exception 'Cannot convert cash: No active 585 daily gold rate found';
      end if;
    end if;
    v_cash_585_eq := round(v_cash / v_rate, 4);
  else
    v_rate := 0;
    v_cash_585_eq := 0;
  end if;

  v_total_deducted_g := round(v_scrap_585_eq + v_cash_585_eq, 4);
  v_settlement_no := 'STL-MGR-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.manager_seller_settlements (
    organization_id,
    settlement_no,
    seller_id,
    physical_scrap_grams,
    scrap_proba,
    scrap_585_equiv_grams,
    cash_amount,
    currency,
    rate_per_gram,
    cash_585_equiv_grams,
    total_deducted_585_eq_grams,
    notes,
    idempotency_key
  ) values (
    v_org_id,
    v_settlement_no,
    p_seller_id,
    v_scrap_g,
    v_p,
    v_scrap_585_eq,
    v_cash,
    coalesce(p_currency, 'UZS'),
    v_rate,
    v_cash_585_eq,
    v_total_deducted_g,
    p_notes,
    p_idempotency_key
  ) returning id into v_settlement_id;

  -- Update seller gold account
  update public.seller_gold_accounts
  set total_settled_to_manager_g = round(total_settled_to_manager_g + v_total_deducted_g, 4),
      seller_till_scrap_grams = round(greatest(0, seller_till_scrap_grams - v_scrap_g), 4),
      seller_till_cash_amount = round(greatest(0, seller_till_cash_amount - v_cash), 2),
      seller_owes_manager_g = round(greatest(0, seller_owes_manager_g - v_total_deducted_g), 4),
      current_factory_obligation_grams = round(greatest(0, current_factory_obligation_grams - v_total_deducted_g), 4),
      bozor_qarzi_signed_g = round(bozor_qarzi_signed_g + v_total_deducted_g, 4),
      updated_at = now()
  where seller_id = p_seller_id and organization_id = v_org_id
  returning * into v_seller_acc;

  -- Update manager vault
  perform public._get_or_create_manager_vault(v_org_id);

  update public.manager_vault_account
  set total_received_from_sellers_g = round(total_received_from_sellers_g + v_total_deducted_g, 4),
      vault_scrap_gold_g = round(vault_scrap_gold_g + v_scrap_585_eq, 4),
      vault_cash_amount = round(vault_cash_amount + v_cash, 2),
      updated_at = now()
  where organization_id = v_org_id
  returning * into v_vault;

  return jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settlement_id,
    'settlement_no', v_settlement_no,
    'total_deducted_585_eq_grams', v_total_deducted_g,
    'seller_remaining_obligation_g', v_seller_acc.seller_owes_manager_g,
    'seller_bozor_qarzi_signed_g', v_seller_acc.bozor_qarzi_signed_g
  );
end;
$function$;
revoke all on function rpc_record_manager_seller_settlement(uuid,numeric,numeric,numeric,text,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_manager_seller_settlement(uuid,numeric,numeric,numeric,text,numeric,text,text) to authenticated;
grant execute on function rpc_record_manager_seller_settlement(uuid,numeric,numeric,numeric,text,numeric,text,text) to service_role;

-- parity: rpc_record_qc_inspection(text,text,text,integer,integer,integer,integer,text,integer,text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_qc_inspection(p_batch_id text, p_batch_no text, p_operation_name text, p_current_stage_order integer, p_checked_qty integer, p_passed_qty integer, p_rework_qty integer, p_defect_code text DEFAULT NULL::text, p_rework_stage_order integer DEFAULT NULL::integer, p_inspector_name text DEFAULT ''::text, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org      uuid := public.current_organization_id();
  v_caller_role     text := public.current_employee_role_text();
  v_cur_wip         public.batch_stage_wip%rowtype;
  v_rw_wip          public.batch_stage_wip%rowtype;
  v_qc_id           uuid;
  v_payload         jsonb;
  v_existing        jsonb;
  v_effective_bno   text := btrim(coalesce(p_batch_no, ''));
  v_target_rw_st    integer := coalesce(p_rework_stage_order, 8);
  v_init_status     text := case when coalesce(p_rework_qty, 0) > 0 then 'IN_REWORK' else 'PASSED' end;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'quality_inspector', 'quality_control', 'qc', 'otk', 'supervisor', 'master'
  ]);

  if p_checked_qty < 0 or p_passed_qty < 0 or p_rework_qty < 0 then
    raise exception 'Negative inspection quantities are not permitted';
  end if;

  if (p_passed_qty + p_rework_qty) > p_checked_qty then
    raise exception 'Sum of passed (%) and rework (%) quantities exceeds checked quantity (%)',
      p_passed_qty, p_rework_qty, p_checked_qty;
  end if;

  v_payload := jsonb_build_object(
    'batch_no', v_effective_bno,
    'operation_name', p_operation_name,
    'checked_qty', p_checked_qty,
    'passed_qty', p_passed_qty,
    'rework_qty', p_rework_qty,
    'defect_code', p_defect_code
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_qc_inspection', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- 1. Insert into public.quality_control
  insert into public.quality_control (
    organization_id,
    batch_id,
    batch_no,
    operation_name,
    checked_qty,
    passed_qty,
    rework_qty,
    defect_code,
    rework_stage_order,
    inspector_name,
    reason,
    status,
    created_at
  ) values (
    v_caller_org,
    btrim(p_batch_id),
    v_effective_bno,
    btrim(p_operation_name),
    p_checked_qty,
    p_passed_qty,
    p_rework_qty,
    p_defect_code,
    v_target_rw_st,
    coalesce(nullif(btrim(p_inspector_name), ''), public.current_employee_name()),
    p_reason,
    v_init_status,
    now()
  )
  returning id into v_qc_id;

  -- 2. If rework is flagged, update WIP records
  if p_rework_qty > 0 then
    -- Find current stage WIP
    select * into v_cur_wip
      from public.batch_stage_wip
     where (batch_id = btrim(p_batch_id) or batch_no = v_effective_bno)
       and stage_order = p_current_stage_order
       and organization_id = v_caller_org
     for update;

    if found then
      update public.batch_stage_wip
         set available_qty = greatest(0, coalesce(available_qty, 0) - p_rework_qty),
             rework_qty    = coalesce(rework_qty, 0) + p_rework_qty,
             updated_at    = now()
       where id = v_cur_wip.id;
    else
      -- Ensure current stage WIP row exists
      insert into public.batch_stage_wip (
        organization_id, batch_id, batch_no, stage_order, stage_name, department,
        available_qty, completed_qty, rework_qty, queue_status
      ) values (
        v_caller_org, btrim(p_batch_id), v_effective_bno, p_current_stage_order, btrim(p_operation_name), 'QC',
        greatest(0, p_checked_qty - p_rework_qty), p_passed_qty, p_rework_qty, 'NOW'
      );
    end if;

    -- Route rework pieces to target rework stage
    select * into v_rw_wip
      from public.batch_stage_wip
     where (batch_id = btrim(p_batch_id) or batch_no = v_effective_bno)
       and stage_order = v_target_rw_st
       and organization_id = v_caller_org
     for update;

    if found then
      update public.batch_stage_wip
         set available_qty = coalesce(available_qty, 0) + p_rework_qty,
             updated_at    = now()
       where id = v_rw_wip.id;
    else
      insert into public.batch_stage_wip (
        organization_id, batch_id, batch_no, stage_order, stage_name, department,
        available_qty, completed_qty, rework_qty, queue_status
      ) values (
        v_caller_org, btrim(p_batch_id), v_effective_bno, v_target_rw_st, '8. Quyish (Rework)', 'Quyish',
        p_rework_qty, 0, 0, 'NOW'
      );
    end if;
  end if;

  -- 3. Record audit trail
  insert into public.audit_logs (
    table_name, record_id, action, actor_id, actor_name, actor_role,
    reason, new_data, organization_id
  ) values (
    'quality_control',
    v_qc_id::text,
    'QC_INSPECTION',
    auth.uid(),
    public.current_employee_name(),
    v_caller_role,
    coalesce(p_reason, 'Quality control inspection completed'),
    jsonb_build_object(
      'batch_no', v_effective_bno,
      'checked_qty', p_checked_qty,
      'passed_qty', p_passed_qty,
      'rework_qty', p_rework_qty,
      'defect_code', p_defect_code,
      'target_rework_stage', v_target_rw_st,
      'status', v_init_status
    ),
    v_caller_org
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'qcId', v_qc_id::text,
    'batchNo', v_effective_bno,
    'checkedQty', p_checked_qty,
    'passedQty', p_passed_qty,
    'reworkQty', p_rework_qty,
    'targetReworkStage', v_target_rw_st,
    'qcStatus', v_init_status
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_qc_inspection', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_qc_inspection(text,text,text,integer,integer,integer,integer,text,integer,text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_qc_inspection(text,text,text,integer,integer,integer,integer,text,integer,text,text,text) to authenticated;
grant execute on function rpc_record_qc_inspection(text,text,text,integer,integer,integer,integer,text,integer,text,text,text) to service_role;

-- parity: rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric)
CREATE OR REPLACE FUNCTION public.rpc_record_refining_batch(p_input_scrap_grams numeric, p_melted_weight_grams numeric, p_output_fine_grams numeric, p_output_fine_proba numeric DEFAULT 995.0, p_operator_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_physical_scrap_grams numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id         uuid := public.current_organization_id();
  v_emp_id         uuid := coalesce(p_operator_id, public.current_employee_id());
  v_in_w           numeric(14, 4);
  v_melt_w         numeric(14, 4);
  v_out_fine_g     numeric(14, 4);
  v_out_proba      numeric(6, 2);
  v_out_585_eq     numeric(14, 4);
  v_loss_g         numeric(14, 4);
  v_loss_pct       numeric(6, 3);
  v_batch_no       text;
  v_batch_id       uuid;
  v_vault          public.manager_vault_account;
  v_existing       jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'inventory_manager'
  ]);

  if v_emp_id is null then
    select id into v_emp_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_org_id
    limit 1;
  end if;

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'batch_id', id,
      'batch_no', batch_no,
      'total_loss_grams', total_loss_grams
    ) into v_existing
    from public.refining_batches
    where idempotency_key = p_idempotency_key and organization_id = v_org_id;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_in_w := round(coalesce(p_input_scrap_grams, 0)::numeric, 4);
  v_melt_w := round(coalesce(p_melted_weight_grams, 0)::numeric, 4);
  v_out_fine_g := round(coalesce(p_output_fine_grams, 0)::numeric, 4);
  v_out_proba := round(coalesce(p_output_fine_proba, 995.0)::numeric, 2);

  if v_in_w <= 0 or v_melt_w <= 0 or v_out_fine_g <= 0 then
    raise exception 'Invalid refining inputs: input scrap, melted weight and output fine gold must be > 0';
  end if;

  if v_melt_w > v_in_w then
    raise exception 'Physical anomaly: melted weight cannot exceed input scrap weight';
  end if;

  v_out_585_eq := round(v_out_fine_g * (v_out_proba / 585.0), 4);
  v_loss_g := round(greatest(0, v_in_w - v_out_585_eq), 4);
  v_loss_pct := round(((v_loss_g / v_in_w) * 100.0), 3);

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  if v_vault.manager_scrap_grams < v_in_w then
    raise exception 'Yetarli lom oltin yo''q: mavjud % g, talab qilindi % g',
      v_vault.manager_scrap_grams, v_in_w;
  end if;

  -- Deduct scrap, add refined fine gold and 585 equivalent. Loss is borne exclusively by manager!
  update public.manager_vault_account
  set manager_scrap_grams = round(manager_scrap_grams - v_in_w, 4),
      manager_scrap_585_eq_g = round(greatest(0, coalesce(manager_scrap_585_eq_g, 0) - v_in_w), 4),
      manager_scrap_physical_g = round(greatest(0, coalesce(manager_scrap_physical_g, 0) - coalesce(p_physical_scrap_grams, v_in_w)), 4),
      manager_refined_gold_grams = round(manager_refined_gold_grams + v_out_585_eq, 4),
      manager_refined_gold_fine_grams = round(coalesce(manager_refined_gold_fine_grams, 0) + v_out_fine_g, 4),
      updated_at = now()
  where organization_id = v_org_id
  returning * into v_vault;

  v_batch_no := 'REF-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.refining_batches (
    organization_id, batch_no, input_scrap_grams, melted_weight_grams,
    output_fine_grams, output_fine_proba, output_585_equiv_grams,
    total_loss_grams, loss_pct, operator_id, status, notes, idempotency_key
  ) values (
    v_org_id, v_batch_no, v_in_w, v_melt_w,
    v_out_fine_g, v_out_proba, v_out_585_eq,
    v_loss_g, v_loss_pct, v_emp_id, 'completed', p_notes, p_idempotency_key
  ) returning id into v_batch_id;

  return jsonb_build_object(
    'status', 'ok',
    'batch_id', v_batch_id,
    'batch_no', v_batch_no,
    'input_scrap_grams', v_in_w,
    'output_fine_grams', v_out_fine_g,
    'output_fine_proba', v_out_proba,
    'output_585_equiv_grams', v_out_585_eq,
    'total_loss_grams', v_loss_g,
    'loss_pct', v_loss_pct,
    'manager_scrap_grams', v_vault.manager_scrap_grams,
    'manager_refined_gold_585_equiv_grams', v_vault.manager_refined_gold_grams,
    'manager_refined_gold_fine_grams', v_vault.manager_refined_gold_fine_grams
  );
end;
$function$;
revoke all on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric) to authenticated;
grant execute on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric) to service_role;

-- parity: rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric,numeric)
CREATE OR REPLACE FUNCTION public.rpc_record_refining_batch(p_input_scrap_grams numeric, p_melted_weight_grams numeric, p_output_fine_grams numeric, p_output_fine_proba numeric DEFAULT 995.0, p_operator_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_physical_scrap_grams numeric DEFAULT NULL::numeric, p_input_scrap_proba numeric DEFAULT 585.0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_emp_id          uuid := coalesce(p_operator_id, public.current_employee_id());
  v_vault           public.manager_vault_account%rowtype;
  v_batch_id        uuid;
  v_batch_no        text;
  v_in_w            numeric(14, 4);
  v_in_proba        numeric(6, 2);
  v_in_585_eq       numeric(14, 4);
  v_melt_w          numeric(14, 4);
  v_out_fine_g      numeric(14, 4);
  v_out_proba       numeric(6, 2);
  v_out_585_eq      numeric(14, 4);
  v_loss_g          numeric(14, 4);
  v_loss_pct        numeric(6, 3);
  v_existing        jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'batch_id', id,
      'batch_no', batch_no,
      'total_loss_grams', total_loss_grams
    ) into v_existing
    from public.refining_batches
    where idempotency_key = p_idempotency_key and organization_id = v_org_id;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_in_w       := round(coalesce(p_input_scrap_grams, 0)::numeric, 4);
  v_in_proba   := round(coalesce(p_input_scrap_proba, 585.0)::numeric, 2);
  v_melt_w     := round(coalesce(p_melted_weight_grams, 0)::numeric, 4);
  v_out_fine_g := round(coalesce(p_output_fine_grams, 0)::numeric, 4);
  v_out_proba  := round(coalesce(p_output_fine_proba, 995.0)::numeric, 2);

  if v_in_w <= 0 or v_melt_w <= 0 or v_out_fine_g <= 0 then
    raise exception 'Invalid refining inputs: input scrap, melted weight and output fine gold must be > 0';
  end if;

  if v_melt_w > v_in_w then
    raise exception 'Physical anomaly: melted weight cannot exceed input scrap weight';
  end if;

  -- 585 Equivalent Mass Balance:
  v_in_585_eq  := round((v_in_w * (v_in_proba / 585.0))::numeric, 4);
  v_out_585_eq := round((v_out_fine_g * (v_out_proba / 585.0))::numeric, 4);
  v_loss_g     := round((v_in_585_eq - v_out_585_eq)::numeric, 4);

  if v_loss_g < 0 then
    raise exception 'Anomalous refining result: Chiqqan oltin (% g 585 ekv) kirgan lomdan (% g 585 ekv) ko''p bo''lishi mumkin emas. Probalar va vaznlarni tekshiring!',
      v_out_585_eq, v_in_585_eq using errcode = '22023';
  end if;

  v_loss_pct := round(((v_loss_g / v_in_585_eq) * 100.0), 3);

  perform public._get_or_create_manager_vault(v_org_id);
  select * into v_vault from public.manager_vault_account where organization_id = v_org_id for update;

  if v_vault.manager_scrap_grams < v_in_585_eq then
    raise exception 'Yetarli lom oltin yo''q: mavjud % g (585 ekv), talab qilindi % g',
      v_vault.manager_scrap_grams, v_in_585_eq;
  end if;

  -- Deduct scrap, add refined fine gold and 585 equivalent. Loss is borne exclusively by manager!
  update public.manager_vault_account
  set manager_scrap_grams = round(manager_scrap_grams - v_in_585_eq, 4),
      manager_scrap_585_eq_g = round(greatest(0, coalesce(manager_scrap_585_eq_g, 0) - v_in_585_eq), 4),
      manager_scrap_physical_g = round(greatest(0, coalesce(manager_scrap_physical_g, 0) - coalesce(p_physical_scrap_grams, v_in_w)), 4),
      manager_refined_gold_grams = round(manager_refined_gold_grams + v_out_585_eq, 4),
      manager_refined_gold_fine_grams = round(coalesce(manager_refined_gold_fine_grams, 0) + v_out_fine_g, 4),
      updated_at = now()
  where organization_id = v_org_id
  returning * into v_vault;

  v_batch_no := 'REF-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.refining_batches (
    organization_id, batch_no, input_scrap_grams, input_scrap_proba,
    input_585_equiv_grams, melted_weight_grams,
    output_fine_grams, output_fine_proba, output_585_equiv_grams,
    total_loss_grams, loss_pct, operator_id, status, notes, idempotency_key
  ) values (
    v_org_id, v_batch_no, v_in_w, v_in_proba,
    v_in_585_eq, v_melt_w,
    v_out_fine_g, v_out_proba, v_out_585_eq,
    v_loss_g, v_loss_pct, v_emp_id, 'completed', p_notes, p_idempotency_key
  ) returning id into v_batch_id;

  return jsonb_build_object(
    'status', 'ok',
    'batch_id', v_batch_id,
    'batch_no', v_batch_no,
    'input_scrap_grams', v_in_w,
    'input_scrap_proba', v_in_proba,
    'input_585_equiv_grams', v_in_585_eq,
    'output_fine_grams', v_out_fine_g,
    'output_fine_proba', v_out_proba,
    'output_585_equiv_grams', v_out_585_eq,
    'total_loss_grams', v_loss_g,
    'loss_pct', v_loss_pct,
    'manager_scrap_grams', v_vault.manager_scrap_grams,
    'manager_refined_gold_585_equiv_grams', v_vault.manager_refined_gold_grams,
    'manager_refined_gold_fine_grams', v_vault.manager_refined_gold_fine_grams
  );
end;
$function$;
revoke all on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric,numeric) to authenticated;
grant execute on function rpc_record_refining_batch(numeric,numeric,numeric,numeric,uuid,text,text,numeric,numeric) to service_role;

-- parity: rpc_record_salary_transaction(text,text,text,text,text,numeric,numeric,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_salary_transaction(p_employee_id text DEFAULT NULL::text, p_worker_name text DEFAULT ''::text, p_batch_no text DEFAULT ''::text, p_stage_name text DEFAULT ''::text, p_tx_type text DEFAULT 'EARNED'::text, p_weight_done numeric DEFAULT 0, p_rate numeric DEFAULT 0, p_amount numeric DEFAULT 0, p_note text DEFAULT ''::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_emp        public.employees%rowtype;
  v_amount     numeric(18, 2) := round(coalesce(p_amount, 0)::numeric, 2);
  v_weight     numeric(14, 4) := round(coalesce(p_weight_done, 0)::numeric, 4);
  v_rate       numeric(18, 2) := round(coalesce(p_rate, 0)::numeric, 2);
  v_new_bal    numeric(18, 2);
  v_ledger_id  uuid;
  v_worker_nm  text;
  v_existing   jsonb;
  v_payload    jsonb;
begin
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'accountant', 'buxgalter', 'hisobchi', 'manager', 'production_manager', 'production manager'
  ]);

  v_payload := jsonb_build_object(
    'employee_id', btrim(coalesce(p_employee_id, '')),
    'worker_name', lower(btrim(coalesce(p_worker_name, ''))),
    'batch_no', upper(btrim(coalesce(p_batch_no, ''))),
    'stage_name', lower(btrim(coalesce(p_stage_name, ''))),
    'tx_type', p_tx_type,
    'amount', v_amount
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_salary_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if v_amount <= 0 or v_weight < 0 or v_rate < 0 or p_tx_type not in ('EARNED', 'PAID') then
    raise exception 'Invalid salary transaction parameters';
  end if;

  if p_employee_id is not null and btrim(p_employee_id) <> '' then
    select * into v_emp from public.employees where id::text = btrim(p_employee_id) for update;
  else
    select * into v_emp
      from public.employees
     where lower(btrim(coalesce(name, full_name, ''))) = lower(btrim(p_worker_name))
     limit 1
       for update;
  end if;

  if not found then
    raise exception 'Employee (%) not found', coalesce(nullif(btrim(p_employee_id), ''), p_worker_name);
  end if;

  v_worker_nm := coalesce(v_emp.name, v_emp.full_name, btrim(p_worker_name));

  -- Explicit duplicate check before insert (backed by idx_salary_ledger_unique_earned)
  if p_tx_type = 'EARNED' and exists (
    select 1 from public.salary_ledger s
     where (s.employee_id::text = v_emp.id::text or lower(btrim(s.worker_name)) = lower(btrim(v_worker_nm)))
       and upper(btrim(s.batch_no)) = upper(btrim(p_batch_no))
       and lower(btrim(s.stage_name)) = lower(btrim(p_stage_name))
       and s.tx_type = 'EARNED'
  ) then
    raise exception 'Duplicate salary guard: EARNED entry already exists for % on batch % stage %',
      v_worker_nm, p_batch_no, p_stage_name
      using errcode = '23505';
  end if;

  insert into public.salary_ledger (
    employee_id, worker_name, batch_no, stage_name, tx_type,
    weight_done, rate, amount, payment_status, note, idempotency_key
  ) values (
    v_emp.id::text, v_worker_nm, btrim(p_batch_no), btrim(p_stage_name), p_tx_type,
    v_weight, v_rate, v_amount,
    case when p_tx_type = 'PAID' then 'PAID' else 'UNPAID' end,
    coalesce(nullif(p_note, ''), format('%s - %s', btrim(p_batch_no), btrim(p_stage_name))),
    nullif(btrim(p_idempotency_key), '')
  ) returning id into v_ledger_id;

  v_new_bal := case
    when p_tx_type = 'EARNED' then round(coalesce(v_emp.balance, 0) + v_amount, 2)
    else round(coalesce(v_emp.balance, 0) - v_amount, 2)
  end;

  -- Mark trusted RPC context so trg_prevent_employee_privilege_escalation permits accountant balance update
  perform set_config('app.in_salary_rpc', 'true', true);
  update public.employees
     set balance = v_new_bal
   where id = v_emp.id;
  perform set_config('app.in_salary_rpc', 'false', true);

  v_existing := jsonb_build_object(
    'status', 'ok',
    'ledger_id', v_ledger_id,
    'employee_id', v_emp.id::text,
    'worker_name', v_worker_nm,
    'new_balance', v_new_bal
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_salary_transaction', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_salary_transaction(text,text,text,text,text,numeric,numeric,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_salary_transaction(text,text,text,text,text,numeric,numeric,numeric,text,text) to authenticated;
grant execute on function rpc_record_salary_transaction(text,text,text,text,text,numeric,numeric,numeric,text,text) to service_role;

-- parity: rpc_record_sale_with_stock_deduction(text,text,text,integer,numeric,numeric,text,numeric,numeric,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_sale_with_stock_deduction(p_product_id text, p_client_name text, p_product_name text, p_quantity integer, p_weight numeric, p_proba numeric, p_payment_type text, p_paid_amount numeric, p_debt_amount numeric, p_order_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_prod       public.products%rowtype;
  v_cur_stock  integer;
  v_paid       numeric(18, 2) := round(coalesce(p_paid_amount, 0)::numeric, 2);
  v_debt       numeric(18, 2) := round(coalesce(p_debt_amount, 0)::numeric, 2);
  v_sale_total numeric(18, 2) := round(v_paid + v_debt, 2);
  v_sale_id    text;
  v_existing   jsonb;
  v_payload    jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'accountant', 'buxgalter', 'hisobchi', 'sales', 'manager', 'production_manager', 'production manager'
  ]);

  v_payload := jsonb_build_object(
    'product_id', btrim(coalesce(p_product_id, '')),
    'client_name', btrim(coalesce(p_client_name, '')),
    'quantity', p_quantity,
    'paid_amount', v_paid,
    'debt_amount', v_debt
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_sale_with_stock_deduction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if p_quantity <= 0 or v_paid < 0 or v_debt < 0 or v_sale_total <= 0 then
    raise exception 'Invalid sale quantity or amounts';
  end if;

  select * into v_prod from public.products where id::text = btrim(p_product_id) for update;
  if not found then
    raise exception 'Product (%) not found in finished goods inventory', p_product_id;
  end if;

  -- Cross-tenant isolation verification
  if v_prod.organization_id is distinct from v_caller_org then
    raise exception 'Cross-tenant violation: Product does not belong to your organization' using errcode = '42501';
  end if;

  v_cur_stock := coalesce(v_prod.stock, v_prod.quantity, 0);
  if p_quantity > v_cur_stock then
    raise exception 'Insufficient finished goods stock for "%": available=%, requested=%',
      v_prod.name, v_cur_stock, p_quantity;
  end if;

  update public.products
     set stock      = v_cur_stock - p_quantity,
         quantity   = v_cur_stock - p_quantity,
         updated_at = now()
   where id = v_prod.id;

  insert into public.sales (
    order_id, product_id, client_name, product_name, quantity,
    weight, proba, payment_type, sale_total_amount, total_amount,
    debt_amount, tx_type, idempotency_key, organization_id
  ) values (
    p_order_id, v_prod.id::text, btrim(p_client_name), v_prod.name, p_quantity,
    round(coalesce(p_weight, v_prod.weight, 0)::numeric, 4),
    coalesce(p_proba, v_prod.proba, 585),
    p_payment_type, v_sale_total, v_paid,
    v_debt, 'kirim', nullif(btrim(p_idempotency_key), ''), v_caller_org
  ) returning id::text into v_sale_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale_id,
    'product_id', v_prod.id::text,
    'remaining_stock', v_cur_stock - p_quantity,
    'paid_amount', v_paid,
    'debt_amount', v_debt,
    'organization_id', v_caller_org
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_sale_with_stock_deduction', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_sale_with_stock_deduction(text,text,text,integer,numeric,numeric,text,numeric,numeric,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_sale_with_stock_deduction(text,text,text,integer,numeric,numeric,text,numeric,numeric,text,text) to authenticated;
grant execute on function rpc_record_sale_with_stock_deduction(text,text,text,integer,numeric,numeric,text,numeric,numeric,text,text) to service_role;

-- parity: rpc_record_seller_to_factory_settlement(uuid,numeric,numeric,numeric,date,text,text)
CREATE OR REPLACE FUNCTION public.rpc_record_seller_to_factory_settlement(p_seller_id uuid, p_scrap_weight numeric DEFAULT 0, p_cash_amount numeric DEFAULT 0, p_rate_per_gram numeric DEFAULT NULL::numeric, p_settlement_date date DEFAULT _goldia_business_date(), p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_caller_emp_id   uuid;
  v_rate            numeric(18, 2);
  v_scrap_w         numeric(14, 4);
  v_cash            numeric(18, 2);
  v_cash_equiv      numeric(14, 4) := 0;
  v_total_settled   numeric(14, 4);
  v_settle_no       text;
  v_settle_id       uuid;
  v_seller_acc      public.seller_gold_accounts;
  v_existing        jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'warehouse', 'omborchi', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'settlement_id', id,
      'settlement_no', settlement_no,
      'total_settled_grams', total_settled_grams
    ) into v_existing
    from public.gold_settlements
    where idempotency_key = p_idempotency_key;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_scrap_w := round(greatest(0, coalesce(p_scrap_weight, 0))::numeric, 4);
  v_cash    := round(greatest(0, coalesce(p_cash_amount, 0))::numeric, 2);

  if v_scrap_w <= 0 and v_cash <= 0 then
    raise exception 'Settlement must include either scrap gold grams or cash amount';
  end if;

  if p_rate_per_gram is not null and p_rate_per_gram > 0 then
    v_rate := round(p_rate_per_gram::numeric, 2);
  else
    select rate_per_gram into v_rate
    from public.daily_gold_rates
    where organization_id = v_org_id
    order by rate_date desc, created_at desc
    limit 1;

    if v_rate is null or v_rate <= 0 then
      v_rate := 900000;
    end if;
  end if;

  if v_cash > 0 then
    v_cash_equiv := round((v_cash / v_rate)::numeric, 4);
  end if;

  v_total_settled := round(v_scrap_w + v_cash_equiv, 4);

  select id into v_caller_emp_id
  from public.employees
  where user_id = auth.uid() and organization_id = v_org_id
  limit 1;

  if v_caller_emp_id is null then
    v_caller_emp_id := p_seller_id;
  end if;

  -- Deduct from seller till
  update public.seller_gold_accounts
  set seller_till_scrap_grams = round(greatest(0, seller_till_scrap_grams - v_scrap_w), 4),
      seller_till_cash_amount = round(greatest(0, seller_till_cash_amount - v_cash), 2),
      updated_at = now()
  where seller_id = p_seller_id;

  v_settle_no := 'STL-FCT-' || to_char(coalesce(p_settlement_date, public._goldia_business_date()), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.gold_settlements (
    organization_id,
    settlement_no,
    direction,
    seller_id,
    gold_rate_applied,
    scrap_weight_grams,
    scrap_proba,
    cash_paid_amount,
    currency,
    cash_equivalent_grams,
    total_settled_grams,
    applied_to_debt_grams,
    excess_gold_grams,
    previous_debt_grams,
    remaining_debt_grams,
    notes,
    recorded_by,
    idempotency_key,
    settlement_date
  ) values (
    v_org_id,
    v_settle_no,
    'seller_to_factory',
    p_seller_id,
    v_rate,
    v_scrap_w,
    585,
    v_cash,
    'UZS',
    v_cash_equiv,
    v_total_settled,
    v_total_settled,
    0,
    0,
    0,
    p_notes,
    v_caller_emp_id,
    p_idempotency_key,
    coalesce(p_settlement_date, public._goldia_business_date())
  ) returning id into v_settle_id;

  select * into v_seller_acc
  from public.seller_gold_accounts
  where seller_id = p_seller_id;

  return jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settle_id,
    'settlement_no', v_settle_no,
    'scrap_weight_grams', v_scrap_w,
    'cash_paid_amount', v_cash,
    'rate_applied', v_rate,
    'cash_equivalent_grams', v_cash_equiv,
    'total_settled_grams', v_total_settled,
    'bozor_qarzi_signed_g', v_seller_acc.bozor_qarzi_signed_g
  );
end;
$function$;
revoke all on function rpc_record_seller_to_factory_settlement(uuid,numeric,numeric,numeric,date,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_seller_to_factory_settlement(uuid,numeric,numeric,numeric,date,text,text) to authenticated;
grant execute on function rpc_record_seller_to_factory_settlement(uuid,numeric,numeric,numeric,date,text,text) to service_role;

-- parity: rpc_record_seller_to_manager_settlement(uuid,numeric,numeric,numeric,text,text,numeric,numeric,numeric)
CREATE OR REPLACE FUNCTION public.rpc_record_seller_to_manager_settlement(p_seller_id uuid, p_scrap_weight_grams numeric DEFAULT 0, p_cash_paid_amount numeric DEFAULT 0, p_rate_per_gram numeric DEFAULT NULL::numeric, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_usd_paid_amount numeric DEFAULT 0, p_usd_rate numeric DEFAULT NULL::numeric, p_physical_scrap_g numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_rate            numeric(18, 2);
  v_usd_rate        numeric(18, 2);
  v_scrap_585_eq    numeric(14, 4);
  v_scrap_phys      numeric(14, 4);
  v_cash            numeric(18, 2);
  v_usd             numeric(18, 2);
  v_cash_equiv      numeric(14, 4) := 0;
  v_usd_equiv       numeric(14, 4) := 0;
  v_total_settled   numeric(14, 4);
  v_settle_no       text;
  v_settle_id       uuid;
  v_seller_acc      public.seller_gold_accounts%rowtype;
  v_vault           public.manager_vault_account%rowtype;
  v_existing        jsonb;
  v_payload         jsonb;
  v_caller_role     text := public.current_employee_role_text();
  v_official_rate   numeric(18, 2);
  v_pool_uzs        numeric(18, 2) := 0;
  v_pool_uzs_g      numeric(18, 6) := 0;
  v_pool_usd        numeric(18, 2) := 0;
  v_pool_usd_g      numeric(18, 6) := 0;
  v_val_cash        numeric(18, 2) := 0;
  v_val_cash_g      numeric(18, 6) := 0;
  v_val_usd         numeric(18, 2) := 0;
  v_val_usd_g       numeric(18, 6) := 0;
  v_leg_cash        numeric(18, 2) := 0;
  v_leg_usd         numeric(18, 2) := 0;
  v_rate_applied    numeric(18, 2);
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter',
    'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi'
  ]);
  -- 065: a seller can only hand over their own till
  if public._goldia_is_seller_role(v_caller_role) and (v_caller_emp_id is null or p_seller_id is distinct from v_caller_emp_id) then
    raise exception 'Ruxsat etilmadi: Sotuvchi faqat o''z kassasini topshira oladi' using errcode = '42501';
  end if;

  v_scrap_585_eq := round(greatest(0, coalesce(p_scrap_weight_grams, 0))::numeric, 4);
  v_scrap_phys   := round(greatest(0, coalesce(p_physical_scrap_g, p_scrap_weight_grams, 0))::numeric, 4);
  v_cash := round(greatest(0, coalesce(p_cash_paid_amount, 0))::numeric, 2);
  v_usd  := round(greatest(0, coalesce(p_usd_paid_amount, 0))::numeric, 2);

  if v_scrap_585_eq <= 0 and v_cash <= 0 and v_usd <= 0 then
    raise exception 'Settlement must include either scrap gold grams, UZS cash, or USD cash';
  end if;

  v_payload := jsonb_build_object(
    'action', 'record_seller_to_manager_settlement',
    'seller_id', p_seller_id,
    'scrap_w', v_scrap_585_eq,
    'scrap_phys', v_scrap_phys,
    'cash', v_cash,
    'usd', v_usd
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_seller_to_manager_settlement', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- 1. STRICT LOCK ORDER HIERARCHY: Lock Manager Vault FIRST
  perform public._get_or_create_manager_vault(v_org_id);

  select * into v_vault
  from public.manager_vault_account
  where organization_id = v_org_id
  for update;

  -- 2. STRICT LOCK ORDER HIERARCHY: Lock Seller Gold Account SECOND
  select * into v_seller_acc
  from public.seller_gold_accounts
  where seller_id = p_seller_id and organization_id = v_org_id
  for update;

  if not found then
    raise exception 'Sotuvchi oltin hisobi topilmadi: %', p_seller_id;
  end if;

  -- 3. HARD BALANCE CHECK (F03):
  if v_scrap_585_eq > 0 and v_seller_acc.seller_till_scrap_grams < v_scrap_585_eq then
    raise exception 'ERR_INSUFFICIENT_SCRAP_BALANCE: Sotuvchi kassasida yetarli lom mavjud emas (Kassada: % g, Talab: % g)',
      v_seller_acc.seller_till_scrap_grams, v_scrap_585_eq;
  end if;

  if v_cash > 0 and v_seller_acc.seller_till_cash_amount < v_cash then
    raise exception 'ERR_INSUFFICIENT_CASH_BALANCE: Sotuvchi kassasida yetarli naqd pul (UZS) mavjud emas (Kassada: % UZS, Talab: % UZS)',
      v_seller_acc.seller_till_cash_amount, v_cash;
  end if;

  if v_usd > 0 and coalesce(v_seller_acc.seller_till_usd_amount, 0) < v_usd then
    raise exception 'ERR_INSUFFICIENT_USD_BALANCE: Sotuvchi kassasida yetarli dollar (USD) mavjud emas (Kassada: % USD, Talab: % USD)',
      coalesce(v_seller_acc.seller_till_usd_amount, 0), v_usd;
  end if;

  -- 072: cash / USD collected since 072 carries the grams it was credited at (valued till pool). That part
  -- closes the obligation with exactly those grams (pool average); the pool never exceeds what is in the till.
  v_pool_uzs := least(coalesce(v_seller_acc.till_valued_cash_uzs, 0), greatest(0, coalesce(v_seller_acc.seller_till_cash_amount, 0)));
  if v_pool_uzs > 0 then
    v_pool_uzs_g := v_seller_acc.till_valued_cash_585_g * v_pool_uzs / v_seller_acc.till_valued_cash_uzs;
  end if;
  v_pool_usd := least(coalesce(v_seller_acc.till_valued_usd, 0), greatest(0, coalesce(v_seller_acc.seller_till_usd_amount, 0)));
  if v_pool_usd > 0 then
    v_pool_usd_g := v_seller_acc.till_valued_usd_585_g * v_pool_usd / v_seller_acc.till_valued_usd;
  end if;
  v_val_cash := least(v_cash, v_pool_uzs);
  v_val_cash_g := case when v_pool_uzs > 0 then round(v_pool_uzs_g * v_val_cash / v_pool_uzs, 6) else 0 end;
  v_val_usd := least(v_usd, v_pool_usd);
  v_val_usd_g := case when v_pool_usd > 0 then round(v_pool_usd_g * v_val_usd / v_pool_usd, 6) else 0 end;
  v_leg_cash := v_cash - v_val_cash;  -- pre-072 cash without a captured value
  v_leg_usd  := v_usd - v_val_usd;

  -- 4. Gold Rate determination for the pre-072 part. Sellers must use the official confirmed rate (065).
  v_official_rate := public._goldia_official_585_rate(v_org_id);
  if p_rate_per_gram is not null and p_rate_per_gram > 0 then
    v_rate := round(p_rate_per_gram::numeric, 2);
  else
    v_rate := v_official_rate;
  end if;
  if (v_leg_cash > 0 or v_leg_usd > 0) and (v_rate is null or v_rate <= 0) then
    raise exception 'ERR_DAILY_RATE_NOT_SET: Bugungi 585 oltin kursi belgilanmagan! Naqd pul topshirish uchun avval kunlik kursni kiriting.';
  end if;
  -- a rate the seller sends must still be the official one (065), even when the captured value is used
  perform public._goldia_assert_seller_rate(v_caller_role, v_rate, v_official_rate,
    (v_leg_cash > 0 or v_leg_usd > 0) or ((v_cash > 0 or v_usd > 0) and p_rate_per_gram is not null and p_rate_per_gram > 0));
  if v_rate is null or v_rate <= 0 then
    v_rate := 1.0; -- Safe sentinel rate for DB check constraint (gold_rate_applied > 0) when cash is 0
  end if;
  -- 5. USD Rate determination (only the pre-072 USD needs a rate now)
  if v_leg_usd > 0 then
    if p_usd_rate is not null and p_usd_rate > 0 then
      v_usd_rate := round(p_usd_rate::numeric, 2);
    else
      raise exception 'ERR_USD_RATE_NOT_SET: Dollar (USD) topshirish uchun USD kursi kiritilishi shart!';
    end if;
  else
    v_usd_rate := null;
  end if;
  v_usd_equiv := case when v_usd > 0
    then round((v_val_usd_g + case when v_leg_usd > 0 then (v_leg_usd * v_usd_rate) / v_rate else 0 end)::numeric, 4) else 0 end;
  v_cash_equiv := case when v_cash > 0
    then round((v_val_cash_g + case when v_leg_cash > 0 then v_leg_cash / v_rate else 0 end)::numeric, 4) else 0 end;
  -- recorded rate = the effective UZS per gram of this handover (gold_rate_applied * cash_equivalent = cash)
  v_rate_applied := case when v_cash > 0 and v_cash_equiv > 0 then round(v_cash / v_cash_equiv, 2) else v_rate end;

  v_total_settled := round(v_scrap_585_eq + v_cash_equiv + v_usd_equiv, 4);

  if v_caller_emp_id is null then
    select id into v_caller_emp_id
    from public.employees
    where user_id = auth.uid() and organization_id = v_org_id
    limit 1;
    if v_caller_emp_id is null then
      v_caller_emp_id := p_seller_id;
    end if;
  end if;

  -- 6. Deduct exactly from seller till (both physical and 585 eq scrap)
  update public.seller_gold_accounts
  set seller_till_scrap_grams        = round(seller_till_scrap_grams - v_scrap_585_eq, 4),
      seller_till_scrap_585_eq_g     = round(greatest(0, coalesce(seller_till_scrap_585_eq_g, 0) - v_scrap_585_eq), 4),
      seller_till_scrap_physical_g   = round(greatest(0, coalesce(seller_till_scrap_physical_g, 0) - v_scrap_phys), 4),
      seller_till_cash_amount        = round(seller_till_cash_amount - v_cash, 2),
      seller_till_usd_amount         = round(coalesce(seller_till_usd_amount, 0) - v_usd, 2),
      updated_at = now()
  where seller_id = p_seller_id;

  -- 7. Add to manager vault (both physical and 585 eq scrap)
  update public.manager_vault_account
  set manager_scrap_grams        = round(manager_scrap_grams + v_scrap_585_eq, 4),
      manager_scrap_585_eq_g     = round(coalesce(manager_scrap_585_eq_g, 0) + v_scrap_585_eq, 4),
      manager_scrap_physical_g   = round(coalesce(manager_scrap_physical_g, 0) + v_scrap_phys, 4),
      manager_cash_amount        = round(manager_cash_amount + v_cash, 2),
      manager_usd_amount         = round(coalesce(manager_usd_amount, 0) + v_usd, 2),
      updated_at = now()
  where organization_id = v_org_id
  returning * into v_vault;

  -- 8. Insert gold settlement
  v_settle_no := 'STL-MGR-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.gold_settlements (
    organization_id,
    settlement_no,
    direction,
    seller_id,
    gold_rate_applied,
    scrap_weight_grams,
    physical_scrap_grams,
    scrap_proba,
    scrap_585_equiv_grams,
    cash_paid_amount,
    currency,
    cash_equivalent_grams,
    usd_paid_amount,
    applied_usd_rate,
    usd_equivalent_grams,
    total_settled_grams,
    till_pool_cash_uzs,
    till_pool_cash_585_g,
    till_pool_usd,
    till_pool_usd_585_g,
    applied_to_debt_grams,
    excess_gold_grams,
    previous_debt_grams,
    remaining_debt_grams,
    status,
    notes,
    recorded_by,
    idempotency_key
  ) values (
    v_org_id,
    v_settle_no,
    'seller_to_manager',
    p_seller_id,
    v_rate_applied,
    v_scrap_585_eq,
    v_scrap_phys,
    585,
    v_scrap_585_eq,
    v_cash,
    'UZS',
    v_cash_equiv,
    v_usd,
    v_usd_rate,
    v_usd_equiv,
    v_total_settled,
    v_val_cash,
    v_val_cash_g,
    v_val_usd,
    v_val_usd_g,
    v_total_settled,
    0,
    coalesce(v_seller_acc.seller_owes_manager_g, v_seller_acc.current_factory_obligation_grams, 0),
    round(greatest(0, coalesce(v_seller_acc.seller_owes_manager_g, v_seller_acc.current_factory_obligation_grams, 0) - v_total_settled), 4),
    'confirmed',
    p_notes,
    v_caller_emp_id,
    p_idempotency_key
  ) returning id into v_settle_id;

  -- 9. Read synced seller gold account
  select * into v_seller_acc
  from public.seller_gold_accounts
  where seller_id = p_seller_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settle_id,
    'settlement_no', v_settle_no,
    'scrap_grams_settled', v_scrap_585_eq,
    'scrap_weight_grams', v_scrap_585_eq,
    'scrap_physical_grams', v_scrap_phys,
    'cash_amount_settled', v_cash,
    'usd_amount_settled', v_usd,
    'applied_usd_rate', v_usd_rate,
    'applied_rate_per_gram', v_rate_applied,
    'valued_cash_uzs', v_val_cash,
    'valued_usd', v_val_usd,
    'cash_equivalent_grams', v_cash_equiv,
    'usd_equivalent_grams', v_usd_equiv,
    'total_settled_grams', v_total_settled,
    'remaining_seller_obligation_g', v_seller_acc.seller_owes_manager_g,
    'seller_owes_manager_g', v_seller_acc.seller_owes_manager_g,
    'bozor_qarzi_signed_g', v_seller_acc.bozor_qarzi_signed_g,
    'seller_till_scrap_grams', v_seller_acc.seller_till_scrap_grams,
    'seller_till_scrap_physical_g', v_seller_acc.seller_till_scrap_physical_g,
    'seller_till_cash_amount', v_seller_acc.seller_till_cash_amount,
    'seller_till_usd_amount', v_seller_acc.seller_till_usd_amount,
    'manager_scrap_grams', v_vault.manager_scrap_grams,
    'manager_scrap_physical_g', v_vault.manager_scrap_physical_g,
    'manager_cash_amount', v_vault.manager_cash_amount,
    'manager_usd_amount', v_vault.manager_usd_amount
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_seller_to_manager_settlement', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_seller_to_manager_settlement(uuid,numeric,numeric,numeric,text,text,numeric,numeric,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_record_seller_to_manager_settlement(uuid,numeric,numeric,numeric,text,text,numeric,numeric,numeric) to authenticated;
grant execute on function rpc_record_seller_to_manager_settlement(uuid,numeric,numeric,numeric,text,text,numeric,numeric,numeric) to service_role;

-- parity: rpc_record_stage_consumption(text,text,text,numeric,numeric,numeric,numeric,numeric,text,boolean,text)
CREATE OR REPLACE FUNCTION public.rpc_record_stage_consumption(p_batch_no text, p_department text, p_master_name text, p_proba numeric, p_given_weight numeric, p_returned_weight numeric, p_sprue_gram numeric DEFAULT 0, p_scrap_gram numeric DEFAULT 0, p_master_id text DEFAULT NULL::text, p_sync_batch boolean DEFAULT true, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_batch     public.batches%rowtype;
  v_given     numeric(14, 4) := round(coalesce(p_given_weight, 0)::numeric, 4);
  v_ret       numeric(14, 4) := round(coalesce(p_returned_weight, 0)::numeric, 4);
  v_sprue     numeric(14, 4) := round(coalesce(p_sprue_gram, 0)::numeric, 4);
  v_scrap     numeric(14, 4) := round(coalesce(p_scrap_gram, 0)::numeric, 4);
  v_loss      numeric(14, 4);
  v_cons_id   text;
  v_existing  jsonb;
  v_payload   jsonb;
begin
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator', 'inventory_manager', 'warehouse'
  ]);

  v_payload := jsonb_build_object(
    'batch_no', btrim(coalesce(p_batch_no, '')),
    'department', btrim(coalesce(p_department, '')),
    'given_weight', v_given,
    'returned_weight', v_ret,
    'sprue_gram', v_sprue,
    'scrap_gram', v_scrap
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_stage_consumption', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if v_given <= 0 or v_ret < 0 or v_sprue < 0 or v_scrap < 0 then
    raise exception 'Invalid consumption weights';
  end if;

  v_loss := round(v_given - v_ret - v_sprue - v_scrap, 4);
  if v_loss < 0 then
    raise exception 'Returned product + sprue + scrap (%g) cannot exceed given gold (%g)',
      (v_ret + v_sprue + v_scrap), v_given;
  end if;

  select * into v_batch
    from public.batches
   where batch_no = btrim(p_batch_no) or number = btrim(p_batch_no) or batch_number = btrim(p_batch_no)
   limit 1
     for update;

  insert into public.consumption (
    batch_id, batch_no, master_name, master_employee_id, department, proba,
    given_weight, returned_weight, sprue_gram, scrap_gram, loss_weight,
    sent_to_refinery, idempotency_key
  ) values (
    v_batch.id::text, btrim(p_batch_no), btrim(p_master_name), p_master_id, btrim(p_department), p_proba,
    v_given, v_ret, v_sprue, v_scrap, v_loss,
    false, nullif(btrim(p_idempotency_key), '')
  ) returning id::text into v_cons_id;

  if found and p_sync_batch then
    update public.batches
       set sprue_gram = round(coalesce(sprue_gram, 0) + v_sprue, 4),
           scrap_gram = round(coalesce(scrap_gram, 0) + v_scrap, 4),
           loss_gram  = round(coalesce(loss_gram, 0) + v_loss, 4),
           wip_gram   = greatest(0, round(coalesce(wip_gram, issued_gold_gram, 0) - v_sprue - v_scrap - v_loss, 4))
     where id = v_batch.id;
  end if;

  if v_loss > 0 then
    insert into public.gold_transactions (
      transaction_type, from_location, to_location, material_name,
      weight_grams, gross_weight, proba, pure_gold, batch_no, description, performed_by
    ) values (
      'yoqotish', 'WIP', 'LOSS', format('Pateriya (%s - %s)', btrim(p_department), btrim(p_batch_no)),
      v_loss, v_loss, p_proba, public.calc_fine_gold_exact(v_loss, p_proba), btrim(p_batch_no),
      format('Master: %s | Given: %sg, Returned: %sg, Sprue: %sg, Scrap: %sg',
        btrim(p_master_name), v_given, v_ret, v_sprue, v_scrap),
      public.current_employee_id()
    );
  end if;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'consumption_id', v_cons_id,
    'batch_no', btrim(p_batch_no),
    'loss_weight', v_loss,
    'sprue_gram', v_sprue,
    'scrap_gram', v_scrap
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_stage_consumption', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_record_stage_consumption(text,text,text,numeric,numeric,numeric,numeric,numeric,text,boolean,text) from public, anon, authenticated, service_role;
grant execute on function rpc_record_stage_consumption(text,text,text,numeric,numeric,numeric,numeric,numeric,text,boolean,text) to authenticated;
grant execute on function rpc_record_stage_consumption(text,text,text,numeric,numeric,numeric,numeric,numeric,text,boolean,text) to service_role;

-- parity: rpc_record_weight_sale(uuid,uuid,numeric,numeric,text,text,uuid[])
CREATE OR REPLACE FUNCTION public.rpc_record_weight_sale(p_customer_id uuid, p_seller_id uuid DEFAULT NULL::uuid, p_weight_grams numeric DEFAULT NULL::numeric, p_client_markup_pct numeric DEFAULT 0, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_piece_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_caller_role   text := public.current_employee_role_text();
  v_caller_emp_id uuid := public.current_employee_id();
  v_seller        public.employees%rowtype;
  v_customer      public.customers%rowtype;
  v_seller_acc    public.seller_gold_accounts%rowtype;
  v_client_acc    public.client_gold_accounts%rowtype;
  v_weight        numeric(14, 4);
  v_markup        numeric(6, 2);
  v_avail_stock   numeric(14, 4);
  v_client_due    numeric(14, 4);
  v_avail_adv     numeric(14, 4);
  v_apply_adv     numeric(14, 4);
  v_net_rem_due   numeric(14, 4);
  v_sale_no       text;
  v_sale_id       uuid;
  v_existing      jsonb;
  v_payload       jsonb;
  v_consign       public.seller_consignments%rowtype;
  v_piece         public.consignment_pieces%rowtype;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'sales', 'seller', 'sotuvchi', 'manager', 'production_manager', 'boshqaruvchi'
  ]);
  v_weight := round(greatest(0, coalesce(p_weight_grams, 0))::numeric, 4);
  if p_client_markup_pct is null then
    raise exception 'ERR_MARKUP_REQUIRED: Mijoz ustama foizi aniq ko''rsatilishi shart';
  end if;
  v_markup := round(p_client_markup_pct::numeric, 2);
  if v_markup < 0 or v_markup > 100 then
    raise exception 'ERR_MARKUP_OUT_OF_RANGE: Mijoz ustama foizi 0 dan 100 gacha bo''lishi shart (kiritildi: %)', v_markup;
  end if;

  if v_weight <= 0 then
    raise exception 'Sotilayotgan mahsulot vazni 0 dan katta bo''lishi shart';
  end if;

  -- Seller determination
  if v_caller_role in ('seller', 'sotuvchi', 'sales') then
    select * into v_seller from public.employees
    where id = v_caller_emp_id and organization_id = v_caller_org limit 1;
  elsif p_seller_id is not null then
    select * into v_seller from public.employees
    where id = p_seller_id and organization_id = v_caller_org limit 1;
  else
    select * into v_seller from public.employees
    where organization_id = v_caller_org and lower(role::text) in ('seller', 'sotuvchi', 'sales')
    order by created_at asc limit 1;
  end if;

  if v_seller.id is null then
    raise exception 'Sotuvchi aniqlanmadi';
  end if;

  select * into v_customer from public.customers
   where id = p_customer_id and organization_id = v_caller_org limit 1;
  if not found then
    raise exception 'Mijoz (%) topilmadi', p_customer_id;
  end if;

  -- Check available physical stock via canonical helper.
  -- 065: serialize stock-changing sales per seller before checking availability
  perform pg_advisory_xact_lock(hashtextextended('goldia_seller_stock:' || v_seller.id::text, 0));
  -- 070: a retried request (same key) must return the original result even when the stock is now used up
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_weight_sale', jsonb_build_object(
    'action', 'record_weight_sale', 'customer_id', p_customer_id, 'seller_id', v_seller.id,
    'weight_grams', v_weight, 'markup_pct', v_markup, 'piece_ids', to_jsonb(p_piece_ids)));
  if v_existing is not null then
    return v_existing;
  end if;
  v_avail_stock := public.get_seller_available_stock_grams(v_seller.id);

  if v_avail_stock < v_weight then
    raise exception 'ERR_INSUFFICIENT_SELLER_STOCK: Sotuvchi omborida yetarli oltin mavjud emas (Mavjud: % g, Talab: % g)',
      v_avail_stock, v_weight;
  end if;

  -- 073: a weight sale must name the physical piece(s) it is cut from whenever the seller holds barcode pieces.
  -- Model code + weight cannot identify an individual item, so an unspecified partial cut is refused.
  if p_piece_ids is null or cardinality(p_piece_ids) = 0 then
    if exists (select 1 from public.consignment_pieces cp
                where cp.seller_id = v_seller.id and cp.organization_id = v_caller_org
                  and cp.status = 'held_by_seller' and cp.sale_id is null) then
      raise exception 'ERR_PIECE_REQUIRED: Vazn bo''yicha sotuvda qaysi donadan sotilayotganini tanlang';
    end if;
  else
    if cardinality(p_piece_ids) <> (select count(distinct x) from unnest(p_piece_ids) x) then
      raise exception 'ERR_PIECE_DUPLICATE: Bir dona ikki marta tanlangan';
    end if;
    perform 1 from public.consignment_pieces cp
      where cp.id = any(p_piece_ids) order by cp.id for update;
    if (select count(*) from public.consignment_pieces cp
         where cp.id = any(p_piece_ids) and cp.seller_id = v_seller.id and cp.organization_id = v_caller_org
           and cp.status = 'held_by_seller' and cp.sale_id is null) <> cardinality(p_piece_ids) then
      raise exception 'ERR_PIECE_NOT_AVAILABLE: Tanlangan donalardan biri sotuvchida mavjud emas yoki allaqachon sotilgan';
    end if;
    if (select coalesce(sum(cp.weight_grams), 0) from public.consignment_pieces cp where cp.id = any(p_piece_ids)) < v_weight - 0.00005 then
      raise exception 'ERR_PIECES_TOO_LIGHT: Tanlangan donalar jami vazni sotilayotgan vazndan kam';
    end if;
    if cardinality(p_piece_ids) > 1 and (select coalesce(sum(cp.weight_grams), 0) from public.consignment_pieces cp
         where cp.id = any(p_piece_ids[1:cardinality(p_piece_ids) - 1])) >= v_weight - 0.00005 then
      raise exception 'ERR_PIECE_EXTRA: Oxirgi tanlangan dona kerak emas — faqat oxirgi dona qisman kesilishi mumkin';
    end if;
  end if;

  v_payload := jsonb_build_object(
    'action', 'record_weight_sale',
    'customer_id', p_customer_id,
    'seller_id', v_seller.id,
    'weight_grams', v_weight,
    'markup_pct', v_markup,
    'piece_ids', to_jsonb(p_piece_ids)
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_record_weight_sale', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- Math: Client gross gold due = weight * (1 + markup / 100)
  v_client_due := round((v_weight * (1.0 + v_markup / 100.0))::numeric, 4);

  -- Lock client account and check advance
  select * into v_client_acc
    from public.client_gold_accounts
   where customer_id = v_customer.id and organization_id = v_caller_org
   for update;

  v_avail_adv := coalesce(v_client_acc.advance_balance_grams, 0);

  if v_avail_adv > 0 then
    v_apply_adv   := round(least(v_avail_adv, v_client_due)::numeric, 4);
    v_net_rem_due := round((v_client_due - v_apply_adv)::numeric, 4);
  else
    v_apply_adv   := 0;
    v_net_rem_due := v_client_due;
  end if;

  -- FIFO: Link sale to seller's active consignment (073: the consignment of the first selected piece)
  if p_piece_ids is not null and cardinality(p_piece_ids) > 0 then
    select sc.* into v_consign from public.seller_consignments sc
      join public.consignment_pieces cp on cp.consignment_id = sc.id
     where cp.id = p_piece_ids[1]
     for update of sc;
  else
  select * into v_consign
    from public.seller_consignments
   where seller_id = v_seller.id and organization_id = v_caller_org
     and status in ('held_by_seller', 'partially_sold')
   order by created_at asc
   limit 1
   for update;
  end if;

  v_sale_no := 'SALE-W-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.jewelry_sales (
    organization_id, sale_no, seller_id, customer_id, consignment_id,
    product_name, quantity, base_weight_grams, proba,
    factory_markup_pct, factory_gold_due_grams,
    client_markup_pct, client_gold_due_grams,
    markup_spread_grams, settled_gold_grams, remaining_gold_grams,
    status, sale_date, idempotency_key, notes, sale_type
  ) values (
    v_caller_org, v_sale_no, v_seller.id, v_customer.id, v_consign.id,
    'Standart 585 Oltin (Vazn bo''yicha)', 1, v_weight, 585.00,
    0.00, v_weight,
    v_markup, v_client_due,
    round((v_client_due - v_weight)::numeric, 4), v_apply_adv, v_net_rem_due,
    case when v_net_rem_due <= 0.0001 then 'fully_paid' else 'open_debt' end,
    public._goldia_business_date(), nullif(btrim(p_idempotency_key), ''), p_notes, 'weight'
  ) returning id into v_sale_id;

  -- If a consignment was linked, update sold info and pieces
  if v_consign.id is not null then
    update public.seller_consignments
       set status = 'partially_sold',
           sold_quantity = coalesce(sold_quantity, 0) + 1,
           updated_at = now()
     where id = v_consign.id;

    -- 068: consume the full sold weight across every held piece (this consignment first)
    if p_piece_ids is not null and cardinality(p_piece_ids) > 0 then
      perform public._goldia_consume_selected_pieces(v_sale_id, v_seller.id, p_piece_ids, v_weight, v_caller_org);
    else
      perform public._goldia_consume_weight_sale_pieces(v_sale_id, v_seller.id, v_consign.id, v_weight, v_caller_org);
    end if;
  end if;

  -- Update client_gold_accounts atomically
  insert into public.client_gold_accounts (
    customer_id, organization_id, seller_id, total_purchased_gold_grams,
    current_debt_grams, advance_balance_grams, total_settled_grams, updated_at
  ) values (
    v_customer.id, v_caller_org, v_seller.id, v_client_due,
    v_net_rem_due, round(greatest(0, v_avail_adv - v_apply_adv)::numeric, 4), v_apply_adv, now()
  )
  on conflict (customer_id) do update set
    total_purchased_gold_grams = round((client_gold_accounts.total_purchased_gold_grams + v_client_due)::numeric, 4),
    current_debt_grams         = round((client_gold_accounts.current_debt_grams + v_net_rem_due)::numeric, 4),
    advance_balance_grams      = round(greatest(0, client_gold_accounts.advance_balance_grams - v_apply_adv)::numeric, 4),
    total_settled_grams        = round((client_gold_accounts.total_settled_grams + v_apply_adv)::numeric, 4),
    seller_id                  = coalesce(client_gold_accounts.seller_id, v_seller.id),
    updated_at                 = now();

  -- Recalculate seller gold account
  perform public.recalc_seller_gold_account(v_seller.id, v_caller_org);

  v_avail_stock := public.get_seller_available_stock_grams(v_seller.id);

  v_existing := jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale_id,
    'sale_no', v_sale_no,
    'seller_id', v_seller.id,
    'customer_id', v_customer.id,
    'base_weight_grams', v_weight,
    'weight_grams', v_weight,
    'client_markup_pct', v_markup,
    'client_gold_due_grams', v_client_due,
    'advance_applied_grams', v_apply_adv,
    'remaining_debt_grams', v_net_rem_due,
    'remaining_physical_stock_g', v_avail_stock
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_record_weight_sale', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_record_weight_sale(uuid,uuid,numeric,numeric,text,text,uuid[]) from public, anon, authenticated, service_role;
grant execute on function rpc_record_weight_sale(uuid,uuid,numeric,numeric,text,text,uuid[]) to authenticated;
grant execute on function rpc_record_weight_sale(uuid,uuid,numeric,numeric,text,text,uuid[]) to service_role;

-- parity: rpc_register_or_get_customer(text,text,text,uuid)
CREATE OR REPLACE FUNCTION public.rpc_register_or_get_customer(p_contact_name text, p_phone text DEFAULT NULL::text, p_company_name text DEFAULT NULL::text, p_seller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_cust       public.customers%rowtype;
  v_seller_uuid uuid := p_seller_id;
  v_clean_name text := btrim(coalesce(p_contact_name, ''));
  v_clean_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_code       text;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  if v_clean_name = '' then
    raise exception 'Customer contact name cannot be empty';
  end if;

  -- Default seller to caller if not specified
  if v_seller_uuid is null then
    select id into v_seller_uuid
      from public.employees
     where (user_id = auth.uid() or id = auth.uid())
       and organization_id = v_caller_org
     limit 1;
  end if;

  -- Find by phone or unique customer code first
  if v_clean_phone is not null then
    select * into v_cust
      from public.customers
     where organization_id = v_caller_org
       and phone = v_clean_phone
     limit 1;
  end if;

  if v_cust.id is null then
    v_code := 'CUST-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 6));

    insert into public.customers (
      organization_id, customer_code, contact_name, company_name, phone, seller_id, is_active
    ) values (
      v_caller_org, v_code, v_clean_name, nullif(btrim(coalesce(p_company_name, '')), ''), v_clean_phone, v_seller_uuid, true
    ) returning * into v_cust;

    -- Ensure client gold account row exists
    insert into public.client_gold_accounts (customer_id, organization_id, seller_id)
    values (v_cust.id, v_caller_org, v_seller_uuid)
    on conflict (customer_id) do nothing;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'customer_id', v_cust.id,
    'customer_code', v_cust.customer_code,
    'contact_name', v_cust.contact_name,
    'phone', v_cust.phone,
    'seller_id', v_cust.seller_id
  );
end;
$function$;
revoke all on function rpc_register_or_get_customer(text,text,text,uuid) from public, anon, authenticated, service_role;
grant execute on function rpc_register_or_get_customer(text,text,text,uuid) to authenticated;
grant execute on function rpc_register_or_get_customer(text,text,text,uuid) to service_role;

-- parity: rpc_reinspect_qc(text,boolean,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reinspect_qc(p_qc_id text, p_passed boolean, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org    uuid := public.current_organization_id();
  v_qc            public.quality_control%rowtype;
  v_existing      jsonb;
  v_payload       jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'supervisor', 'qc_inspector', 'quality_inspector'
  ]);

  v_payload := jsonb_build_object(
    'qc_id', btrim(p_qc_id),
    'passed', p_passed,
    'notes', p_notes
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reinspect_qc', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_qc
    from public.quality_control
   where (id::text = btrim(p_qc_id) or batch_id = btrim(p_qc_id))
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'QC record % not found in current organization', p_qc_id;
  end if;

  if p_passed then
    update public.quality_control
       set status = 'APPROVED',
           reason = coalesce(reason, '') || case when p_notes is not null then ' [Qayta tekshiruv: O''TDI - ' || p_notes || ']' else ' [Qayta tekshiruv: O''TDI]' end,
           notes = coalesce(notes, '') || case when p_notes is not null then ' [Qayta tekshiruv: O''TDI - ' || p_notes || ']' else ' [Qayta tekshiruv: O''TDI]' end,
           updated_at = now()
     where id = v_qc.id;
  else
    update public.quality_control
       set status = 'IN_REWORK',
           reason = coalesce(reason, '') || case when p_notes is not null then ' [Qayta tekshiruv: RAD ETILDI - ' || p_notes || ']' else ' [Qayta tekshiruv: RAD ETILDI]' end,
           notes = coalesce(notes, '') || case when p_notes is not null then ' [Qayta tekshiruv: RAD ETILDI - ' || p_notes || ']' else ' [Qayta tekshiruv: RAD ETILDI]' end,
           updated_at = now()
     where id = v_qc.id;
  end if;

  v_existing := jsonb_build_object(
    'success', true,
    'qc_id', v_qc.id,
    'status', case when p_passed then 'APPROVED' else 'IN_REWORK' end,
    'passed', p_passed
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_reinspect_qc', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_reinspect_qc(text,boolean,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reinspect_qc(text,boolean,text,text) to authenticated;
grant execute on function rpc_reinspect_qc(text,boolean,text,text) to service_role;

-- parity: rpc_release_machine_station(text)
CREATE OR REPLACE FUNCTION public.rpc_release_machine_station(p_machine_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_machine    public.machines%rowtype;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_operator'
  ]);

  update public.machines
     set current_batch = null,
         status        = 'IDLE',
         updated_at    = now()
   where id::text = btrim(p_machine_id)
     and organization_id = v_caller_org
  returning * into v_machine;

  if not found then
    select * into v_machine from public.machines where id::text = btrim(p_machine_id);
    if not found then
      raise exception 'Machine station (%) not found', p_machine_id;
    end if;
    if v_machine.organization_id is distinct from v_caller_org then
      raise exception 'Cross-tenant violation: Machine station does not belong to your organization' using errcode = '42501';
    end if;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'machine_id', v_machine.id::text,
    'machine_name', v_machine.name,
    'machine_status', 'IDLE',
    'current_batch', null,
    'organization_id', v_caller_org
  );
end;
$function$;
revoke all on function rpc_release_machine_station(text) from public, anon, authenticated, service_role;
grant execute on function rpc_release_machine_station(text) to authenticated;
grant execute on function rpc_release_machine_station(text) to service_role;

-- parity: rpc_return_piece_to_factory(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_return_piece_to_factory(p_piece_id uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  -- Unsold goods flow SELLER -> MANAGER (-> refining / factory). The old implementation
  -- always failed on a non-existent audit_logs column and never reduced the real obligation.
  v_result := public.rpc_return_piece_to_manager(p_piece_id, p_notes, p_idempotency_key);
  return v_result || jsonb_build_object(
    'factory_due_deducted_grams', coalesce((v_result->>'seller_obligation_deducted_g')::numeric, 0),
    'routed_to', 'manager'
  );
end;
$function$;
revoke all on function rpc_return_piece_to_factory(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_return_piece_to_factory(uuid,text,text) to authenticated;
grant execute on function rpc_return_piece_to_factory(uuid,text,text) to service_role;

-- parity: rpc_return_piece_to_manager(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_return_piece_to_manager(p_piece_id uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org    uuid := public.current_organization_id();
  v_caller_role   text := public.current_employee_role_text();
  v_piece         public.consignment_pieces%rowtype;
  v_seller        public.employees%rowtype;
  v_consign       public.seller_consignments%rowtype;
  v_seller_markup numeric(6, 2);
  v_deduct_obl    numeric(14, 4);
  v_existing      jsonb;
  v_payload       jsonb;
  v_seller_acc    public.seller_gold_accounts%rowtype;
  v_new_rem_qty   integer;
  v_new_rem_w     numeric(14, 4);
  v_new_rem_obl   numeric(14, 4);
  v_new_status    text;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  v_payload := jsonb_build_object(
    'action', 'return_piece_to_manager',
    'piece_id', p_piece_id
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_return_piece_to_manager', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  -- 1. Lock and fetch piece
  SELECT * INTO v_piece
    FROM public.consignment_pieces
   WHERE id = p_piece_id
     AND organization_id = v_caller_org
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Qaytariladigan mahsulot donasi topilmadi (%)', p_piece_id;
  END IF;

  IF v_piece.status <> 'held_by_seller' THEN
    RAISE EXCEPTION 'Faqat sotuvchi javonidagi (sotilmagan) mahsulotni boshqaruvchiga qaytarish mumkin. Hozirgi holat: %', v_piece.status;
  END IF;

  -- 2. Seller authorization check
  SELECT * INTO v_seller
    FROM public.employees
   WHERE id = v_piece.seller_id
     AND organization_id = v_caller_org
   LIMIT 1;

  IF v_caller_role NOT IN ('admin', 'director', 'owner', 'direktor', 'rahbar', 'warehouse', 'omborchi', 'inventory_manager', 'manager', 'production_manager', 'boshqaruvchi') THEN
    IF v_seller.user_id IS NOT NULL AND v_seller.user_id <> auth.uid() THEN
      RAISE EXCEPTION 'Ruxsat etilmadi: Faqat o''zingizga biriktirilgan mahsulotni qaytara olasiz' USING errcode = '42501';
    END IF;
  END IF;

  -- 3. Lock parent consignment
  SELECT * INTO v_consign
    FROM public.seller_consignments
   WHERE id = v_piece.consignment_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ushbu donaga tegishli konsignatsiya yozuvi topilmadi';
  END IF;

  -- Dynamic seller markup from piece or consignment
  v_seller_markup := COALESCE(v_piece.seller_markup_pct, v_consign.seller_markup_pct, 12.00);
  v_deduct_obl := ROUND((v_piece.weight_grams * (1.0 + v_seller_markup / 100.0))::numeric, 4);

  -- 4. Update piece status to returned_to_manager
  UPDATE public.consignment_pieces
     SET status                 = 'returned_to_manager',
         returned_to_manager_at = NOW(),
         notes                  = COALESCE(notes, '') || CASE WHEN notes IS NOT NULL THEN ' | ' ELSE '' END ||
                                  'BOSHQARUVCHIGA QAYTARILDI: ' || COALESCE(p_notes, 'Sotilmagan tovar qaytarildi') || ' (' || to_char(NOW(), 'YYYY-MM-DD HH24:MI') || ')',
         updated_at             = NOW()
   WHERE id = v_piece.id;

  -- 5. Calculate new active balances for parent consignment
  v_new_rem_w   := ROUND(GREATEST(0, COALESCE(v_consign.base_weight_grams, 0) - v_piece.weight_grams)::numeric, 4);
  v_new_rem_obl := ROUND(GREATEST(0, COALESCE(v_consign.seller_obligation_g, 0) - v_deduct_obl)::numeric, 4);

  -- Count remaining held pieces in parent consignment
  SELECT COUNT(*)::integer
    INTO v_new_rem_qty
    FROM public.consignment_pieces
   WHERE consignment_id = v_consign.id
     AND status = 'held_by_seller';

  IF v_new_rem_w <= 0 OR v_new_rem_qty = 0 THEN
    IF COALESCE(v_consign.sold_quantity, 0) > 0 THEN
      v_new_status := 'fully_sold';
    ELSE
      v_new_status := 'returned_to_manager';
    END IF;
  ELSIF COALESCE(v_consign.sold_quantity, 0) > 0 THEN
    v_new_status := 'partially_sold';
  ELSE
    v_new_status := 'held_by_seller';
  END IF;

  UPDATE public.seller_consignments
     SET returned_quantity              = COALESCE(returned_quantity, 0) + 1,
         returned_to_factory_quantity   = COALESCE(returned_to_factory_quantity, 0) + 1,
         returned_weight_grams          = ROUND((COALESCE(returned_weight_grams, 0) + v_piece.weight_grams)::numeric, 4),
         returned_to_factory_gold_grams = ROUND((COALESCE(returned_to_factory_gold_grams, 0) + v_piece.weight_grams)::numeric, 4),
         returned_seller_obligation_g   = ROUND((COALESCE(returned_seller_obligation_g, 0) + v_deduct_obl)::numeric, 4),
         base_weight_grams              = v_new_rem_w,
         seller_obligation_g            = v_new_rem_obl,
         quantity                       = v_new_rem_qty,
         status                         = v_new_status,
         updated_at                     = NOW()
   WHERE id = v_consign.id;

  -- 6. Restore manager physical stock on factory receipt (if linked)
  IF v_consign.factory_receipt_id IS NOT NULL THEN
    UPDATE public.factory_receipts
       SET available_physical_g = ROUND((available_physical_g + v_piece.weight_grams)::numeric, 4),
           status = CASE
                      WHEN ROUND((available_physical_g + v_piece.weight_grams)::numeric, 4) >= original_physical_g THEN 'in_manager_stock'
                      ELSE 'partially_transferred'
                    END,
           updated_at = NOW()
     WHERE id = v_consign.factory_receipt_id;
  END IF;

  -- 7. Atomically synchronize manager physical vault stock
  PERFORM public._get_or_create_manager_vault(v_caller_org);
  UPDATE public.manager_vault_account
     SET manager_physical_stock_g = public.get_manager_available_stock_grams(v_caller_org),
         updated_at = NOW()
   WHERE organization_id = v_caller_org;

  -- 8. Recalculate seller responsibility atomically
  PERFORM public.recalc_seller_gold_account(v_piece.seller_id, v_caller_org);

  SELECT * INTO v_seller_acc
    FROM public.seller_gold_accounts
   WHERE seller_id = v_piece.seller_id AND organization_id = v_caller_org;

  -- 9. Audit log
  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, new_data
  ) VALUES (
    v_caller_org, 'consignment_pieces', v_piece.id::text, 'RETURN_PIECE_TO_MANAGER', auth.uid(),
    jsonb_build_object(
      'piece_id', v_piece.id,
      'model_code', v_piece.model_code,
      'model_name', v_piece.model_name,
      'weight_grams', v_piece.weight_grams,
      'seller_markup_pct', v_seller_markup,
      'seller_obligation_deducted_g', v_deduct_obl,
      'seller_id', v_piece.seller_id,
      'new_seller_owes_manager_g', COALESCE(v_seller_acc.seller_owes_manager_g, 0),
      'new_bozor_qarzi_signed_g', COALESCE(v_seller_acc.bozor_qarzi_signed_g, 0),
      'consignment_new_status', v_new_status,
      'notes', p_notes
    )
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'piece_id', v_piece.id,
    'model_code', v_piece.model_code,
    'model_name', v_piece.model_name,
    'weight_grams', v_piece.weight_grams,
    'seller_markup_pct', v_seller_markup,
    'seller_obligation_deducted_g', v_deduct_obl,
    'seller_id', v_piece.seller_id,
    'seller_owes_manager_g', COALESCE(v_seller_acc.seller_owes_manager_g, 0),
    'bozor_qarzi_signed_g', COALESCE(v_seller_acc.bozor_qarzi_signed_g, 0),
    'new_status', 'returned_to_manager',
    'consignment_status', v_new_status
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_return_piece_to_manager', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_return_piece_to_manager(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_return_piece_to_manager(uuid,text,text) to authenticated;
grant execute on function rpc_return_piece_to_manager(uuid,text,text) to service_role;

-- parity: rpc_return_sprue_to_scrap_inventory(text,text,text,numeric,numeric,numeric,text)
CREATE OR REPLACE FUNCTION public.rpc_return_sprue_to_scrap_inventory(p_consumption_id text, p_scrap_item_id text, p_batch_no text, p_sprue_weight numeric, p_proba numeric, p_pure_gold numeric, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cons      public.consumption%rowtype;
  v_scrap     public.inventory_items%rowtype;
  v_weight    numeric(14, 4);
  v_fine      numeric(18, 6);
  v_existing  jsonb;
  v_payload   jsonb;
begin
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'warehouse', 'omborchi', 'inventory_manager',
    'manager', 'production_manager', 'production manager', 'master', 'supervisor', 'bosh usta', 'usta', 'department_head'
  ]);

  v_payload := jsonb_build_object(
    'consumption_id', btrim(coalesce(p_consumption_id, '')),
    'scrap_item_id', btrim(coalesce(p_scrap_item_id, '')),
    'sprue_weight', round(coalesce(p_sprue_weight, 0)::numeric, 4)
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_return_sprue_to_scrap_inventory', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  if coalesce(btrim(p_consumption_id), '') = '' or coalesce(btrim(p_scrap_item_id), '') = '' then
    raise exception 'Consumption ID and Scrap item ID are required';
  end if;

  select * into v_cons from public.consumption where id::text = btrim(p_consumption_id) for update;
  if not found then
    raise exception 'Consumption record (%) not found', p_consumption_id;
  end if;

  if v_cons.sent_to_refinery then
    raise exception 'Sprue/scrap for consumption record % has already been returned to inventory', p_consumption_id;
  end if;

  v_weight := round(coalesce(nullif(p_sprue_weight, 0), v_cons.sprue_gram + coalesce(v_cons.scrap_gram, 0)), 4);
  if v_weight <= 0 then
    raise exception 'No recoverable sprue/scrap weight to return';
  end if;

  select * into v_scrap from public.inventory_items where id::text = btrim(p_scrap_item_id) for update;
  if not found then
    raise exception 'Target Scrap/Lom inventory item not found';
  end if;

  update public.consumption
     set sent_to_refinery = true
   where id = v_cons.id;

  update public.inventory_items
     set on_hand = coalesce(on_hand, quantity_on_hand, 0) + v_weight,
         quantity_on_hand = coalesce(on_hand, quantity_on_hand, 0) + v_weight
   where id = v_scrap.id;

  v_fine := public.calc_fine_gold_exact(v_weight, coalesce(nullif(p_proba, 0), v_cons.proba, 585));

  insert into public.gold_transactions (
    transaction_type, from_location, to_location, material_name,
    weight_grams, gross_weight, proba, pure_gold, batch_no, description, idempotency_key, performed_by
  ) values (
    'kirim', 'WIP_SPRUE', 'SCRAP_SAFE', v_scrap.name,
    v_weight, v_weight, coalesce(nullif(p_proba, 0), v_cons.proba, 585), v_fine,
    coalesce(p_batch_no, v_cons.batch_no),
    format('Returned sprue/scrap from %s to %s', coalesce(p_batch_no, v_cons.batch_no), v_scrap.name),
    nullif(btrim(p_idempotency_key), ''), public.current_employee_id()
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'consumption_id', v_cons.id::text,
    'scrap_item_id', v_scrap.id::text,
    'returned_weight', v_weight,
    'pure_gold', v_fine
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_return_sprue_to_scrap_inventory', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_return_sprue_to_scrap_inventory(text,text,text,numeric,numeric,numeric,text) from public, anon, authenticated, service_role;
grant execute on function rpc_return_sprue_to_scrap_inventory(text,text,text,numeric,numeric,numeric,text) to authenticated;
grant execute on function rpc_return_sprue_to_scrap_inventory(text,text,text,numeric,numeric,numeric,text) to service_role;

-- parity: rpc_reverse_barcode_consignment(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_barcode_consignment(p_consignment_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_clean_reason     text := nullif(btrim(p_reason), '');
  v_consign          public.seller_consignments%rowtype;
  v_sold_count       integer := 0;
  v_factory_rcp      public.factory_receipts%rowtype;
  v_active_weight    numeric(14, 4);
  v_payload          jsonb;
  v_existing         jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if v_clean_reason is null then
    raise exception 'Konsignatsiyani bekor qilish sababi kiritilishi shart';
  end if;

  v_payload := jsonb_build_object(
    'action', 'reverse_barcode_consignment',
    'consignment_id', p_consignment_id,
    'reason', v_clean_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_barcode_consignment', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_consign
    from public.seller_consignments
   where id = p_consignment_id
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'Konsignatsiya topilmadi (%)', p_consignment_id;
  end if;

  if v_consign.status = 'cancelled' then
    raise exception 'Ushbu konsignatsiya allaqachon bekor qilingan (%s)', v_consign.consignment_no;
  end if;

  -- Dependency Guard: Check if ANY piece is sold or returned to factory
  select count(*) into v_sold_count
    from public.consignment_pieces
   where consignment_id = p_consignment_id
     and status in ('sold', 'returned_to_factory');

  if v_sold_count > 0 then
    raise exception 'Konsignatsiyani bekor qilib bo''lmaydi: % ta mahsulot allaqachon sotilgan yoki zavodga qaytarilgan. Avval savdolarni bekor qiling.', v_sold_count;
  end if;

  v_active_weight := round((v_consign.base_weight_grams - v_consign.returned_weight_grams)::numeric, 4);

  -- 1. Update all pieces to returned_to_manager
  update public.consignment_pieces
     set status                 = 'returned_to_manager',
         returned_to_manager_at = now(),
         notes                  = coalesce(notes, '') || ' | KONSIGNATSIYA BEKOR QILINDI: ' || v_clean_reason,
         updated_at             = now()
   where consignment_id = p_consignment_id
     and status = 'held_by_seller';

  -- 2. Restore factory physical stock if linked
  if v_consign.factory_receipt_id is not null and v_active_weight > 0 then
    select * into v_factory_rcp
      from public.factory_receipts
     where id = v_consign.factory_receipt_id
       and organization_id = v_caller_org
     for update;

    if found then
      update public.factory_receipts
         set available_physical_g   = round((available_physical_g + v_active_weight)::numeric, 4),
             transferred_physical_g = round(greatest(0, transferred_physical_g - v_active_weight)::numeric, 4),
             status = case
                        when round((available_physical_g + v_active_weight)::numeric, 4) >= original_physical_g then 'in_manager_stock'
                        else 'partially_transferred'
                      end,
             updated_at = now()
       where id = v_consign.factory_receipt_id;
    end if;
  end if;

  -- 3. Mark consignment cancelled
  update public.seller_consignments
     set status              = 'cancelled',
         cancelled_at        = now(),
         cancelled_by        = v_caller_emp_id,
         cancellation_reason = v_clean_reason,
         updated_at          = now()
   where id = p_consignment_id;

  -- 4. Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, old_data, new_data, reason
  ) values (
    v_caller_org, 'seller_consignments', v_consign.id::text, 'CANCEL_CONSIGNMENT', auth.uid(),
    jsonb_build_object(
      'consignment_no', v_consign.consignment_no,
      'seller_id', v_consign.seller_id,
      'base_weight_g', v_consign.base_weight_grams,
      'pieces_count', v_consign.quantity
    ),
    jsonb_build_object(
      'status', 'cancelled',
      'restored_physical_g', v_active_weight
    ),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'consignment_id', v_consign.id,
    'consignment_no', v_consign.consignment_no,
    'restored_weight_grams', v_active_weight,
    'reason', v_clean_reason
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_barcode_consignment', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_barcode_consignment(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_barcode_consignment(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_barcode_consignment(uuid,text,text) to service_role;

-- parity: rpc_reverse_barcode_piece_sale(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_barcode_piece_sale(p_piece_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org uuid := public.current_organization_id();
  v_piece      public.consignment_pieces%rowtype;
begin
  select * into v_piece
    from public.consignment_pieces
   where id = p_piece_id and organization_id = v_caller_org;

  if not found then
    raise exception 'Mahsulot donasi topilmadi (%)', p_piece_id;
  end if;

  if v_piece.sale_id is null then
    raise exception 'Ushbu donaga bog''langan savdo hujjati topilmadi';
  end if;

  return public.rpc_reverse_client_sale(v_piece.sale_id, p_reason, p_idempotency_key);
end;
$function$;
revoke all on function rpc_reverse_barcode_piece_sale(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_barcode_piece_sale(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_barcode_piece_sale(uuid,text,text) to service_role;

-- parity: rpc_reverse_client_legacy_debt(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_client_legacy_debt(p_legacy_debt_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org      uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_clean_reason    text := nullif(btrim(p_reason), '');
  v_rec             public.client_legacy_debts%rowtype;
  v_client_acc      public.client_gold_accounts%rowtype;
  v_cur_debt        numeric(14, 4);
  v_cur_adv         numeric(14, 4);
  v_rev_net         numeric(14, 4);
  v_rev_debt        numeric(14, 4);
  v_rev_adv         numeric(14, 4);
  v_payload         jsonb;
  v_existing        jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter'
  ]);

  if v_clean_reason is null then
    raise exception 'Eski qarzni bekor qilish sababi kiritilishi shart';
  end if;

  v_payload := jsonb_build_object(
    'action', 'reverse_client_legacy_debt',
    'legacy_debt_id', p_legacy_debt_id,
    'reason', v_clean_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_client_legacy_debt', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_rec
  from public.client_legacy_debts
  where id = p_legacy_debt_id and organization_id = v_caller_org
  for update;

  if not found then
    raise exception 'Eski qarz yozuvi topilmadi: %', p_legacy_debt_id;
  end if;

  if v_rec.status = 'reversed' then
    raise exception 'Ushbu eski qarz yozuvi allaqachon bekor qilingan';
  end if;

  -- Lock client gold account
  select * into v_client_acc
  from public.client_gold_accounts
  where customer_id = v_rec.customer_id and organization_id = v_caller_org
  for update;

  v_cur_debt := coalesce(v_client_acc.current_debt_grams, 0);
  v_cur_adv  := coalesce(v_client_acc.advance_balance_grams, 0);

  -- Reversing delta mathematically: Net position = (debt - advance) - delta
  v_rev_net := round((v_cur_debt - v_cur_adv) - v_rec.delta_585_g, 4);
  if v_rev_net >= 0 then
    v_rev_debt := v_rev_net;
    v_rev_adv  := 0;
  else
    v_rev_debt := 0;
    v_rev_adv  := abs(v_rev_net);
  end if;

  -- Update client_gold_accounts
  update public.client_gold_accounts
     set current_debt_grams = v_rev_debt,
         advance_balance_grams = v_rev_adv,
         updated_at = now()
   where customer_id = v_rec.customer_id and organization_id = v_caller_org;

  -- Mark legacy debt row as reversed
  update public.client_legacy_debts
     set status = 'reversed',
         reversed_at = now(),
         reversed_by = v_caller_emp_id,
         reversal_reason = v_clean_reason,
         updated_at = now()
   where id = p_legacy_debt_id;

  -- Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) values (
    v_caller_org, 'client_legacy_debts', p_legacy_debt_id::text,
    'REVERSE_CLIENT_LEGACY_DEBT', auth.uid(),
    jsonb_build_object('status', 'confirmed', 'debt_g', v_cur_debt, 'advance_g', v_cur_adv),
    jsonb_build_object('status', 'reversed', 'debt_g', v_rev_debt, 'advance_g', v_rev_adv),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'legacy_debt_id', p_legacy_debt_id,
    'customer_id', v_rec.customer_id,
    'reversed_delta_g', v_rec.delta_585_g,
    'new_debt_585_g', v_rev_debt,
    'new_advance_585_g', v_rev_adv,
    'reason', v_clean_reason
  );

  if p_idempotency_key is not null then
    perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_client_legacy_debt', v_existing, v_payload);
  end if;

  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_client_legacy_debt(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_client_legacy_debt(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_client_legacy_debt(uuid,text,text) to service_role;

-- parity: rpc_reverse_client_sale(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_client_sale(p_sale_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org       uuid := public.current_organization_id();
  v_caller_role      text := public.current_employee_role_text();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_clean_reason     text := NULLIF(btrim(p_reason), '');
  v_sale             public.jewelry_sales%rowtype;
  v_cust_acc         public.client_gold_accounts%rowtype;
  v_seller_acc       public.seller_gold_accounts%rowtype;
  v_net_sale_debt    numeric(14, 4);
  v_new_cust_debt    numeric(14, 4);
  v_new_cust_adv     numeric(14, 4);
  v_new_seller_debt  numeric(14, 4);
  v_piece            public.consignment_pieces%rowtype;
  v_consign          public.seller_consignments%rowtype;
  v_payload          jsonb;
  v_existing         jsonb;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi', 'sales', 'seller', 'sotuvchi'
  ]);

  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'Savdoni bekor qilish sababi kiritilishi shart';
  END IF;

  v_payload := jsonb_build_object(
    'action', 'reverse_client_sale',
    'sale_id', p_sale_id,
    'reason', v_clean_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_client_sale', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  -- 1. Lock and fetch sale
  SELECT * INTO v_sale
    FROM public.jewelry_sales
   WHERE id = p_sale_id AND organization_id = v_caller_org
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Savdo hujjati topilmadi (%)', p_sale_id;
  END IF;

  IF v_sale.status IN ('reversed', 'cancelled') THEN
    RAISE EXCEPTION 'Ushbu savdo allaqachon bekor qilingan (%s)', v_sale.sale_no;
  END IF;

  -- Cross-seller sale reversal authorization check
  IF v_caller_role IN ('seller', 'sotuvchi', 'sales') THEN
    IF v_sale.seller_id IS DISTINCT FROM v_caller_emp_id THEN
      RAISE EXCEPTION 'Ruxsat etilmadi: Sotuvchilar faqat o''zi amalga oshirgan savdoni bekor qila oladi' USING errcode = '42501';
    END IF;
  END IF;

  -- 2. Lock client_gold_accounts
  SELECT * INTO v_cust_acc
    FROM public.client_gold_accounts
   WHERE customer_id = v_sale.customer_id AND organization_id = v_caller_org
   FOR UPDATE;

  -- 3. Lock seller_gold_accounts
  SELECT * INTO v_seller_acc
    FROM public.seller_gold_accounts
   WHERE seller_id = v_sale.seller_id AND organization_id = v_caller_org
   FOR UPDATE;

  -- Net customer debt that was added by this sale
  v_net_sale_debt := ROUND((v_sale.client_gold_due_grams - COALESCE(v_sale.settled_gold_grams, 0))::numeric, 4);

  -- Adjust customer debt and restore any applied advance
  -- 070: payments are applied at customer-account level (sale rows are usually not updated), so the
  -- reversal must remove the full sale amount from the account's net position. Whatever the customer
  -- has already paid beyond the remaining debt becomes an advance (credit) instead of disappearing.
  v_new_cust_debt := ROUND((COALESCE(v_cust_acc.current_debt_grams, 0) - COALESCE(v_cust_acc.advance_balance_grams, 0)
                            - v_sale.client_gold_due_grams)::numeric, 4);
  IF v_new_cust_debt >= 0 THEN
    v_new_cust_adv := 0;
  ELSE
    v_new_cust_adv  := ROUND(-v_new_cust_debt, 4);
    v_new_cust_debt := 0;
  END IF;

  UPDATE public.client_gold_accounts
     SET total_purchased_gold_grams = ROUND(GREATEST(0, total_purchased_gold_grams - v_sale.client_gold_due_grams)::numeric, 4),
         current_debt_grams         = v_new_cust_debt,
         advance_balance_grams      = v_new_cust_adv,
         updated_at                 = NOW()
   WHERE customer_id = v_sale.customer_id;

  -- Adjust seller's total client debt
  v_new_seller_debt := ROUND(GREATEST(0, COALESCE(v_seller_acc.total_client_debt_grams, 0) - v_net_sale_debt)::numeric, 4);
  UPDATE public.seller_gold_accounts
     SET total_client_debt_grams = v_new_seller_debt,
         updated_at              = NOW()
   WHERE seller_id = v_sale.seller_id;

  -- Mark sale as reversed
  UPDATE public.jewelry_sales
     SET status          = 'reversed',
         notes           = COALESCE(notes, '') || ' [BEKOR QILINDI: ' || v_clean_reason || ']',
         updated_at      = NOW()
   WHERE id = v_sale.id;

  -- 4. If a physical piece or weight stock was sold, restore it onto consignment_pieces
  -- 068: weight sales recorded with allocations are restored exactly piece by piece
  IF EXISTS (SELECT 1 FROM public.weight_sale_allocations WHERE sale_id = v_sale.id AND reversed_at IS NULL) THEN
    PERFORM public._goldia_restore_weight_sale_allocations(v_sale.id);
  ELSE
  SELECT * INTO v_piece
    FROM public.consignment_pieces
   WHERE sale_id = v_sale.id AND organization_id = v_caller_org
   FOR UPDATE;

  IF FOUND THEN
    UPDATE public.consignment_pieces
       SET status = 'held_by_seller',
           sale_id = NULL,
           sold_at = NULL,
           updated_at = NOW()
     WHERE id = v_piece.id;
    -- 065: the parent consignment must give back the sold count as well
    UPDATE public.seller_consignments
       SET sold_quantity = GREATEST(0, COALESCE(sold_quantity, 1) - 1),
           status = CASE
                      WHEN GREATEST(0, COALESCE(sold_quantity, 1) - 1) <= 0 THEN 'held_by_seller'
                      ELSE 'partially_sold'
                    END,
           updated_at = NOW()
     WHERE id = v_piece.consignment_id;
  ELSIF v_sale.consignment_id IS NOT NULL THEN
    -- 065: restore weight onto the exact piece the weight sale reduced, when known
    SELECT * INTO v_piece
      FROM public.consignment_pieces
     WHERE consignment_id = v_sale.consignment_id AND status = 'held_by_seller'
     ORDER BY (id = v_sale.source_piece_id) DESC, updated_at DESC
     LIMIT 1
     FOR UPDATE;

    IF FOUND THEN
      UPDATE public.consignment_pieces
         SET weight_grams = ROUND((weight_grams + v_sale.base_weight_grams)::numeric, 4),
             updated_at = NOW()
       WHERE id = v_piece.id;
    ELSE
      -- All pieces in this consignment were marked sold/unassigned. Re-create / re-open an active held piece with restored weight!
      INSERT INTO public.consignment_pieces (
        organization_id, consignment_id, model_code, model_name, category,
        purity, weight_grams, status, seller_id, notes
      ) VALUES (
        v_caller_org, v_sale.consignment_id, COALESCE(v_sale.model_code, 'VAZN'), COALESCE(v_sale.product_name, 'Qaytarilgan VAZN'),
        COALESCE(v_sale.category, 'Buyum'), COALESCE(v_sale.purity, 585), v_sale.base_weight_grams,
        'held_by_seller', v_sale.seller_id, 'Restored from reversed sale ' || v_sale.sale_no
      );
    END IF;

    SELECT * INTO v_consign
      FROM public.seller_consignments
     WHERE id = v_sale.consignment_id
     FOR UPDATE;

    IF FOUND THEN
      UPDATE public.seller_consignments
         SET sold_quantity = GREATEST(0, COALESCE(sold_quantity, 1) - 1),
             status = CASE
                        WHEN GREATEST(0, COALESCE(sold_quantity, 1) - 1) <= 0 THEN 'held_by_seller'
                        ELSE 'partially_sold'
                      END,
             updated_at = NOW()
       WHERE id = v_consign.id;
    END IF;
  END IF;
  END IF;

  -- Recalculate seller gold account physical stock
  PERFORM public.recalc_seller_gold_account(v_sale.seller_id, v_caller_org);

  -- Audit log
  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, old_data, new_data, reason
  ) VALUES (
    v_caller_org, 'jewelry_sales', v_sale.id::text, 'REVERSE_CLIENT_SALE', auth.uid(),
    jsonb_build_object(
      'sale_no', v_sale.sale_no,
      'base_weight_grams', v_sale.base_weight_grams,
      'client_gold_due_grams', v_sale.client_gold_due_grams,
      'customer_id', v_sale.customer_id,
      'seller_id', v_sale.seller_id
    ),
    jsonb_build_object('status', 'reversed'),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale.id,
    'sale_no', v_sale.sale_no,
    'restored_weight_g', v_sale.base_weight_grams,
    'reversed_debt_g', v_net_sale_debt
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_client_sale', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_reverse_client_sale(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_client_sale(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_client_sale(uuid,text,text) to service_role;

-- parity: rpc_reverse_client_settlement(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_client_settlement(p_settlement_id uuid, p_reason text DEFAULT 'Audited Compensating Reversal'::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_settle           public.gold_settlements%rowtype;
  v_seller_acc       public.seller_gold_accounts%rowtype;
  v_client_acc       public.client_gold_accounts%rowtype;
  v_payload          jsonb;
  v_existing         jsonb;
  v_scrap_phys       numeric(14, 4);
  v_scrap_585        numeric(14, 4);
  v_cash_uzs         numeric(18, 2);
  v_cash_usd         numeric(18, 2);
  v_adv_shortfall    numeric(14, 4) := 0;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  v_payload := jsonb_build_object(
    'action', 'reverse_client_settlement',
    'settlement_id', p_settlement_id,
    'reason', p_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_client_settlement', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_settle
    from public.gold_settlements
   where id = p_settlement_id
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'To''lov yozuvi (%) topilmadi', p_settlement_id;
  end if;

  if v_settle.status = 'reversed' then
    return jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'settlement_id', v_settle.id,
      'message', 'To''lov avval bekor qilingan'
    );
  end if;

  v_scrap_phys := round(coalesce(v_settle.physical_scrap_grams, v_settle.scrap_weight_grams, 0)::numeric, 4);
  v_scrap_585  := round(coalesce(v_settle.scrap_585_equiv_grams, v_settle.scrap_weight_grams, 0)::numeric, 4);
  v_cash_uzs   := round(coalesce(v_settle.cash_paid_amount, 0)::numeric, 2);
  v_cash_usd   := round(coalesce(v_settle.usd_paid_amount, 0)::numeric, 2);

  -- Verify seller till has sufficient scrap, UZS cash, and USD
  select * into v_seller_acc
    from public.seller_gold_accounts
   where seller_id = v_settle.seller_id
     and organization_id = v_caller_org
   for update;

  if found then
    if v_scrap_phys > 0 and coalesce(v_seller_acc.seller_till_scrap_physical_g, v_seller_acc.seller_till_scrap_grams, 0) < v_scrap_phys then
      raise exception 'To''lovni bekor qilib bo''lmaydi: Sotuvchi kassasidagi fizik lom yetarli emas (Mavjud: % g, Talab: % g). Avval boshqaruvchiga topshirilgan lomni qaytaring.',
        coalesce(v_seller_acc.seller_till_scrap_physical_g, v_seller_acc.seller_till_scrap_grams, 0), v_scrap_phys;
    end if;

    if v_cash_uzs > 0 and coalesce(v_seller_acc.seller_till_cash_amount, 0) < v_cash_uzs then
      raise exception 'To''lovni bekor qilib bo''lmaydi: Sotuvchi kassasidagi naqd so''m yetarli emas (Mavjud: % UZS, Talab: % UZS).',
        v_seller_acc.seller_till_cash_amount, v_cash_uzs;
    end if;

    if v_cash_usd > 0 and coalesce(v_seller_acc.seller_till_usd_amount, 0) < v_cash_usd then
      raise exception 'To''lovni bekor qilib bo''lmaydi: Sotuvchi kassasidagi naqd USD yetarli emas (Mavjud: % USD, Talab: % USD).',
        v_seller_acc.seller_till_usd_amount, v_cash_usd;
    end if;

    -- Deduct ALL till holdings
    update public.seller_gold_accounts
       set seller_till_scrap_grams       = round(greatest(0, seller_till_scrap_grams - coalesce(v_settle.scrap_weight_grams, 0))::numeric, 4),
           seller_till_scrap_physical_g  = round(greatest(0, coalesce(seller_till_scrap_physical_g, 0) - v_scrap_phys)::numeric, 4),
           seller_till_scrap_585_eq_g    = round(greatest(0, coalesce(seller_till_scrap_585_eq_g, 0) - v_scrap_585)::numeric, 4),
           seller_till_cash_amount       = round(greatest(0, seller_till_cash_amount - v_cash_uzs)::numeric, 2),
           seller_till_usd_amount        = round(greatest(0, coalesce(seller_till_usd_amount, 0) - v_cash_usd)::numeric, 2),
           updated_at                    = now()
     where seller_id = v_settle.seller_id;
  end if;

  -- Restore customer debt and reverse excess advance in client_gold_accounts
  select * into v_client_acc
    from public.client_gold_accounts
   where customer_id = v_settle.customer_id
     and organization_id = v_caller_org
   for update;

  if found then
    -- 065: advance already spent on later sales turns back into debt instead of disappearing
    v_adv_shortfall := round(greatest(0, coalesce(v_settle.excess_gold_grams, 0) - coalesce(v_client_acc.advance_balance_grams, 0))::numeric, 4);
    update public.client_gold_accounts
       set current_debt_grams    = round((current_debt_grams + v_settle.applied_to_debt_grams + v_adv_shortfall)::numeric, 4),
           advance_balance_grams = round(greatest(0, advance_balance_grams - v_settle.excess_gold_grams)::numeric, 4),
           total_settled_grams   = round(greatest(0, total_settled_grams - v_settle.total_settled_grams)::numeric, 4),
           total_scrap_paid_grams= round(greatest(0, total_scrap_paid_grams - coalesce(v_settle.scrap_weight_grams, 0))::numeric, 4),
           total_cash_paid_amount= round(greatest(0, total_cash_paid_amount - v_cash_uzs)::numeric, 2),
           total_cash_equiv_grams= round(greatest(0, total_cash_equiv_grams - coalesce(v_settle.cash_equivalent_grams, 0) - coalesce(v_settle.usd_equivalent_grams, 0))::numeric, 4),
           updated_at            = now()
     where customer_id = v_settle.customer_id;
  end if;

  -- Also reverse advance on customers table
  update public.customers
     set advance_balance_gold_grams = round(greatest(0, coalesce(advance_balance_gold_grams, 0) - v_settle.excess_gold_grams)::numeric, 4)
   where id = v_settle.customer_id;

  -- If linked to a specific piece sale, restore sale's settled and remaining gold balance
  if v_settle.sale_id is not null then
    update public.jewelry_sales
       set settled_gold_grams   = round(greatest(0, settled_gold_grams - v_settle.applied_to_debt_grams)::numeric, 4),
           remaining_gold_grams = round((remaining_gold_grams + v_settle.applied_to_debt_grams)::numeric, 4),
           status               = case
             when round((remaining_gold_grams + v_settle.applied_to_debt_grams)::numeric, 4) <= 0.0001 then 'fully_paid'
             when round(greatest(0, settled_gold_grams - v_settle.applied_to_debt_grams)::numeric, 4) > 0.0001 then 'partially_paid'
             else 'open_debt'
           end,
           updated_at           = now()
     where id = v_settle.sale_id;
  end if;

  -- Mark settlement as reversed
  update public.gold_settlements
     set status          = 'reversed',
         reversed_at     = now(),
         reversed_by     = v_caller_emp_id,
         reversal_reason = p_reason
   where id = p_settlement_id;

  -- Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, old_data, new_data, reason
  ) values (
    v_caller_org, 'gold_settlements', v_settle.id::text, 'REVERSE_CLIENT_SETTLEMENT', auth.uid(),
    jsonb_build_object(
      'settlement_no', v_settle.settlement_no,
      'total_settled_grams', v_settle.total_settled_grams,
      'physical_scrap_grams', v_scrap_phys,
      'cash_paid_amount', v_cash_uzs,
      'usd_paid_amount', v_cash_usd
    ),
    jsonb_build_object('status', 'reversed'),
    p_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settle.id,
    'settlement_no', v_settle.settlement_no,
    'restored_debt_grams', v_settle.applied_to_debt_grams,
    'deducted_advance_grams', v_settle.excess_gold_grams,
    'advance_shortfall_added_to_debt_grams', v_adv_shortfall,
    'deducted_seller_scrap_g', v_scrap_phys,
    'deducted_seller_cash_uzs', v_cash_uzs,
    'deducted_seller_cash_usd', v_cash_usd,
    'reason', p_reason
  );

  if p_idempotency_key is not null then
    perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_client_settlement', v_existing, v_payload);
  end if;

  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_client_settlement(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_client_settlement(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_client_settlement(uuid,text,text) to service_role;

-- parity: rpc_reverse_customer_settlement(uuid,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_customer_settlement(p_settlement_id uuid, p_reversal_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org     uuid := public.current_organization_id();
  v_caller_role    text := public.current_employee_role_text();
  v_caller_emp_id  uuid := public.current_employee_id();
  v_settle         public.gold_settlements%rowtype;
  v_seller_acc     public.seller_gold_accounts%rowtype;
  v_client_acc     public.client_gold_accounts%rowtype;
  v_clean_reason   text := nullif(btrim(p_reversal_reason), '');
  v_cash_uzs       numeric(18, 2);
  v_cash_usd       numeric(18, 2);
  v_scrap_phys     numeric(14, 4);
  v_scrap_585      numeric(14, 4);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'accountant', 'buxgalter'
  ]);

  if v_clean_reason is null then
    raise exception 'Mijoz to''lovini bekor qilish sababi (audit uchun) kiritilishi shart';
  end if;

  select * into v_settle
    from public.gold_settlements
   where id = p_settlement_id
     and organization_id = v_caller_org
     and direction = 'client_to_seller'
   for update;

  if not found then
    raise exception 'Mijoz to''lovi topilmadi (id: %)', p_settlement_id;
  end if;

  if v_settle.status in ('reversed', 'cancelled') then
    raise exception 'Ushbu to''lov allaqachon bekor qilingan (status: %)', v_settle.status;
  end if;

  v_cash_uzs   := coalesce(v_settle.cash_paid_amount, 0);
  v_cash_usd   := coalesce(v_settle.usd_paid_amount, 0);
  v_scrap_phys := coalesce(v_settle.physical_scrap_grams, v_settle.scrap_weight_grams, 0);
  v_scrap_585  := coalesce(v_settle.scrap_585_equiv_grams, v_settle.scrap_weight_grams, 0);

  -- Deduct from seller till
  if v_settle.seller_id is not null then
    select * into v_seller_acc
      from public.seller_gold_accounts
     where seller_id = v_settle.seller_id and organization_id = v_caller_org
     for update;

    update public.seller_gold_accounts
       set seller_till_scrap_grams       = round(greatest(0, seller_till_scrap_grams - coalesce(v_settle.scrap_weight_grams, 0))::numeric, 4),
           seller_till_scrap_physical_g  = round(greatest(0, coalesce(seller_till_scrap_physical_g, 0) - v_scrap_phys)::numeric, 4),
           seller_till_scrap_585_eq_g    = round(greatest(0, coalesce(seller_till_scrap_585_eq_g, 0) - v_scrap_585)::numeric, 4),
           seller_till_cash_amount       = round(greatest(0, seller_till_cash_amount - v_cash_uzs)::numeric, 2),
           seller_till_usd_amount        = round(greatest(0, coalesce(seller_till_usd_amount, 0) - v_cash_usd)::numeric, 2),
           updated_at                    = now()
     where seller_id = v_settle.seller_id;
  end if;

  -- Restore customer debt in client_gold_accounts
  select * into v_client_acc
    from public.client_gold_accounts
   where customer_id = v_settle.customer_id
     and organization_id = v_caller_org
   for update;

  if found then
    update public.client_gold_accounts
       set current_debt_grams    = round((current_debt_grams + v_settle.applied_to_debt_grams)::numeric, 4),
           advance_balance_grams = round(greatest(0, advance_balance_grams - v_settle.excess_gold_grams)::numeric, 4),
           total_settled_grams   = round(greatest(0, total_settled_grams - v_settle.total_settled_grams)::numeric, 4),
           total_scrap_paid_grams= round(greatest(0, total_scrap_paid_grams - coalesce(v_settle.scrap_weight_grams, 0))::numeric, 4),
           total_cash_paid_amount= round(greatest(0, total_cash_paid_amount - v_cash_uzs)::numeric, 2),
           total_cash_equiv_grams= round(greatest(0, total_cash_equiv_grams - coalesce(v_settle.cash_equivalent_grams, 0) - coalesce(v_settle.usd_equivalent_grams, 0))::numeric, 4),
           total_usd_paid_amount = round(greatest(0, coalesce(total_usd_paid_amount, 0) - v_cash_usd)::numeric, 2),
           total_usd_equiv_grams = round(greatest(0, coalesce(total_usd_equiv_grams, 0) - coalesce(v_settle.usd_equivalent_grams, 0))::numeric, 4),
           updated_at            = now()
     where customer_id = v_settle.customer_id;
  end if;

  update public.customers
     set advance_balance_gold_grams = round(greatest(0, coalesce(advance_balance_gold_grams, 0) - v_settle.excess_gold_grams)::numeric, 4)
   where id = v_settle.customer_id;

  if v_settle.sale_id is not null then
    update public.jewelry_sales
       set settled_gold_grams   = round(greatest(0, settled_gold_grams - v_settle.applied_to_debt_grams)::numeric, 4),
           remaining_gold_grams = round((remaining_gold_grams + v_settle.applied_to_debt_grams)::numeric, 4),
           status = 'open_debt',
           updated_at = now()
     where id = v_settle.sale_id and organization_id = v_caller_org;
  end if;

  update public.gold_settlements
     set status = 'reversed',
         reversed_at = now(),
         reversed_by = v_caller_emp_id,
         reversal_reason = v_clean_reason,
         updated_at = now()
   where id = v_settle.id;

  if v_settle.seller_id is not null then
    perform public.recalc_seller_gold_account(v_settle.seller_id, v_caller_org);
  end if;

  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) values (
    v_caller_org, 'gold_settlements', v_settle.id::text,
    'REVERSE_CLIENT_SETTLEMENT', auth.uid(),
    jsonb_build_object(
      'settlement_no', v_settle.settlement_no,
      'total_settled_grams', v_settle.total_settled_grams,
      'physical_scrap_grams', v_scrap_phys,
      'cash_paid_amount', v_cash_uzs,
      'usd_paid_amount', v_cash_usd
    ),
    jsonb_build_object('status', 'reversed'),
    v_clean_reason
  );

  return jsonb_build_object(
    'status', 'ok',
    'settlement_id', v_settle.id,
    'settlement_no', v_settle.settlement_no,
    'restored_customer_debt_g', v_settle.applied_to_debt_grams
  );
end;
$function$;
revoke all on function rpc_reverse_customer_settlement(uuid,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_customer_settlement(uuid,text) to authenticated;
grant execute on function rpc_reverse_customer_settlement(uuid,text) to service_role;

-- parity: rpc_reverse_factory_gold_handover(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_factory_gold_handover(p_handover_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org      uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_clean_reason    text := NULLIF(btrim(p_reason), '');
  v_hnd             public.factory_gold_handovers%rowtype;
  v_vault           public.manager_vault_account%rowtype;
  v_payload         jsonb;
  v_existing        jsonb;
  v_src             text;
  v_fine_g          numeric(14, 4);
  v_new_handed_over numeric(14, 4);
  v_net_balance     numeric(14, 4);
  v_new_obligation  numeric(14, 4);
  v_new_advance     numeric(14, 4);
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi'
  ]);

  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'Zavodga topshirishni bekor qilish sababi kiritilishi shart';
  END IF;

  v_payload := jsonb_build_object(
    'action', 'reverse_factory_gold_handover',
    'handover_id', p_handover_id,
    'reason', v_clean_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_factory_gold_handover', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_hnd
  FROM public.factory_gold_handovers
  WHERE id = p_handover_id AND organization_id = v_caller_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Zavodga oltin topshirish hujjati topilmadi: %', p_handover_id;
  END IF;

  IF v_hnd.status IN ('reversed', 'cancelled') THEN
    RAISE EXCEPTION 'Ushbu zavodga topshirish hujjati allaqachon bekor qilingan (%s)', v_hnd.handover_no;
  END IF;

  PERFORM public._get_or_create_manager_vault(v_caller_org);
  SELECT * INTO v_vault
  FROM public.manager_vault_account
  WHERE organization_id = v_caller_org
  FOR UPDATE;

  v_src := COALESCE(v_hnd.source_type, 'refined_gold');
  v_fine_g := ROUND((COALESCE(v_hnd.physical_weight_g, 0) * (COALESCE(v_hnd.proba, 999.0) / 1000.0))::numeric, 4);

  -- Restore handed-over gold to manager vault according to source_type
  IF v_src = 'refined_gold' THEN
    UPDATE public.manager_vault_account
       SET manager_refined_gold_grams = ROUND((manager_refined_gold_grams + v_hnd.agreed_equivalent_g)::numeric, 4),
           manager_refined_gold_fine_grams = ROUND((COALESCE(manager_refined_gold_fine_grams, 0) + v_fine_g)::numeric, 4),
           updated_at = NOW()
     WHERE organization_id = v_caller_org;
  ELSIF v_src = 'purchased_gold' THEN
    UPDATE public.manager_vault_account
       SET manager_purchased_gold_grams = ROUND((manager_purchased_gold_grams + v_hnd.agreed_equivalent_g)::numeric, 4),
           updated_at = NOW()
     WHERE organization_id = v_caller_org;
  ELSIF v_src = 'capital_pure_gold' THEN
    UPDATE public.manager_vault_account
       SET manager_capital_pure_gold_g = ROUND((COALESCE(manager_capital_pure_gold_g, 0) + v_hnd.agreed_equivalent_g)::numeric, 4),
           manager_capital_pure_gold_fine_g = ROUND((COALESCE(manager_capital_pure_gold_fine_g, 0) + v_fine_g)::numeric, 4),
           updated_at = NOW()
     WHERE organization_id = v_caller_org;
  ELSE -- scrap_gold or scrap
    UPDATE public.manager_vault_account
       SET manager_scrap_grams = ROUND((manager_scrap_grams + COALESCE(v_hnd.physical_weight_g, v_hnd.agreed_equivalent_g))::numeric, 4),
           manager_scrap_physical_g = ROUND((COALESCE(manager_scrap_physical_g, 0) + COALESCE(v_hnd.physical_weight_g, v_hnd.agreed_equivalent_g))::numeric, 4),
           manager_scrap_585_eq_g = ROUND((COALESCE(manager_scrap_585_eq_g, 0) + v_hnd.agreed_equivalent_g)::numeric, 4),
           updated_at = NOW()
     WHERE organization_id = v_caller_org;
  END IF;

  -- Atomically recalculate obligation and advance:
  v_new_handed_over := ROUND(GREATEST(0, v_vault.total_factory_handed_over_g - v_hnd.agreed_equivalent_g), 4);
  v_net_balance := ROUND(v_vault.total_factory_obligation_g - v_new_handed_over, 4);

  IF v_net_balance >= 0 THEN
    v_new_obligation := v_net_balance;
    v_new_advance := 0;
  ELSE
    v_new_obligation := 0;
    v_new_advance := ABS(v_net_balance);
  END IF;

  UPDATE public.manager_vault_account
     SET total_factory_handed_over_g = v_new_handed_over,
         current_factory_obligation_g = v_new_obligation,
         current_factory_advance_g = v_new_advance,
         updated_at = NOW()
   WHERE organization_id = v_caller_org;

  UPDATE public.factory_gold_handovers
     SET status = 'reversed',
         reversed_at = NOW(),
         reversed_by = v_caller_emp_id,
         reversal_reason = v_clean_reason
   WHERE id = p_handover_id;

  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) VALUES (
    v_caller_org, 'factory_gold_handovers', p_handover_id::text,
    'REVERSE_FACTORY_GOLD_HANDOVER', auth.uid(),
    jsonb_build_object('handover_no', v_hnd.handover_no, 'agreed_equivalent_g', v_hnd.agreed_equivalent_g),
    jsonb_build_object('status', 'reversed'),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'handover_id', p_handover_id,
    'handover_no', v_hnd.handover_no,
    'restored_gold_grams', v_hnd.agreed_equivalent_g,
    'reason', v_clean_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_factory_gold_handover', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_reverse_factory_gold_handover(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_factory_gold_handover(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_factory_gold_handover(uuid,text,text) to service_role;

-- parity: rpc_reverse_factory_receipt(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_factory_receipt(p_receipt_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_clean_reason     text := nullif(btrim(p_reason), '');
  v_rcp              public.factory_receipts%rowtype;
  v_vault            public.manager_vault_account%rowtype;
  v_payload          jsonb;
  v_existing         jsonb;
  v_new_obligation   numeric(14, 4);
  v_net_balance      numeric(14, 4);
  v_cur_obligation   numeric(14, 4);
  v_cur_advance      numeric(14, 4);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi'
  ]);

  if v_clean_reason is null then
    raise exception 'Fabrika qabulini bekor qilish sababi kiritilishi shart';
  end if;

  v_payload := jsonb_build_object(
    'action', 'reverse_factory_receipt',
    'receipt_id', p_receipt_id,
    'reason', v_clean_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_factory_receipt', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_rcp
    from public.factory_receipts
   where id = p_receipt_id
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'Fabrika qabuli topilmadi (%)', p_receipt_id;
  end if;

  if v_rcp.status = 'reversed' then
    raise exception 'Ushbu fabrika qabuli allaqachon bekor qilingan (%s)', v_rcp.receipt_no;
  end if;

  if coalesce(v_rcp.transferred_physical_g, 0) > 0.0001 or v_rcp.available_physical_g < (v_rcp.original_physical_g - 0.0001) then
    raise exception 'Fabrika qabulini bekor qilib bo''lmaydi: ushbu partiyadan tovarlar allaqachon konsignatsiyaga tarqatilgan (% g). Avval bog''langan konsignatsiyalarni bekor qiling.',
      v_rcp.transferred_physical_g;
  end if;

  update public.factory_receipts
     set status          = 'reversed',
         available_physical_g = 0,
         reversed_at     = now(),
         reversed_by     = v_caller_emp_id,
         reversal_reason = v_clean_reason,
         updated_at      = now()
   where id = p_receipt_id;

  perform public._get_or_create_manager_vault(v_caller_org);
  select * into v_vault from public.manager_vault_account where organization_id = v_caller_org for update;

  v_new_obligation := round(greatest(0, v_vault.total_factory_obligation_g - v_rcp.factory_obligation_g), 4);
  v_net_balance := round(v_new_obligation - v_vault.total_factory_handed_over_g, 4);

  if v_net_balance >= 0 then
    v_cur_obligation := v_net_balance;
    v_cur_advance := 0;
  else
    v_cur_obligation := 0;
    v_cur_advance := abs(v_net_balance);
  end if;

  update public.manager_vault_account
     set total_factory_received_g   = round(greatest(0, total_factory_received_g - v_rcp.original_physical_g), 4),
         total_factory_obligation_g = v_new_obligation,
         current_factory_obligation_g = v_cur_obligation,
         current_factory_advance_g  = v_cur_advance,
         manager_physical_stock_g   = round(greatest(0, coalesce(manager_physical_stock_g, 0) - v_rcp.original_physical_g), 4),
         updated_at = now()
   where organization_id = v_caller_org
   returning * into v_vault;

  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, old_data, new_data, reason
  ) values (
    v_caller_org, 'factory_receipts', v_rcp.id::text, 'REVERSE_FACTORY_RECEIPT', auth.uid(),
    jsonb_build_object(
      'receipt_no', v_rcp.receipt_no,
      'original_physical_g', v_rcp.original_physical_g,
      'factory_obligation_g', v_rcp.factory_obligation_g,
      'product_name', v_rcp.product_name
    ),
    jsonb_build_object(
      'status', 'reversed',
      'available_physical_g', 0
    ),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'receipt_id', v_rcp.id,
    'receipt_no', v_rcp.receipt_no,
    'deducted_obligation_grams', v_rcp.factory_obligation_g,
    'deducted_physical_grams', v_rcp.original_physical_g,
    'reason', v_clean_reason,
    'current_factory_obligation_g', v_vault.current_factory_obligation_g,
    'current_factory_advance_g', v_vault.current_factory_advance_g
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_factory_receipt', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_factory_receipt(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_factory_receipt(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_factory_receipt(uuid,text,text) to service_role;

-- parity: rpc_reverse_financial_transaction(uuid,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_financial_transaction(p_transaction_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id uuid := public.current_organization_id();
  v_tx     public.financial_transactions%rowtype;
  v_reason text := nullif(btrim(p_reason), '');
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if v_reason is null then
    raise exception 'Tranzaksiyani bekor qilish sababi (reason) kiritilishi shart';
  end if;

  select * into v_tx
    from public.financial_transactions
   where id = p_transaction_id and organization_id = v_org_id
   for update;

  if not found then
    raise exception 'Bekor qilinadigan operatsiya topilmadi (%)', p_transaction_id;
  end if;

  if v_tx.status in ('reversed', 'cancelled') then
    raise exception 'Ushbu operatsiya allaqachon bekor qilingan';
  end if;

  -- Reverse asset update
  if v_tx.transaction_type in ('capital_in', 'capital_contribution') then
    if v_tx.source_till in ('manager_fine_gold', 'manager_capital_pure_gold') or v_tx.currency in ('FINE_GOLD', 'PURE_GOLD') then
      update public.manager_vault_account
         set manager_capital_pure_gold_g = round(greatest(0, manager_capital_pure_gold_g - v_tx.equiv_585_grams), 4),
             manager_capital_pure_gold_fine_g = round(greatest(0, manager_capital_pure_gold_fine_g - coalesce(v_tx.physical_weight_grams, v_tx.amount_num)), 4),
             updated_at = now()
       where organization_id = v_org_id;

    elsif v_tx.source_till in ('manager_scrap') then
      update public.manager_vault_account
         set manager_scrap_grams = round(greatest(0, manager_scrap_grams - v_tx.equiv_585_grams), 4),
             updated_at = now()
       where organization_id = v_org_id;

    elsif v_tx.source_till in ('seller_till_scrap') and v_tx.seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_scrap_grams = round(greatest(0, seller_till_scrap_grams - v_tx.equiv_585_grams), 4),
             updated_at = now()
       where seller_id = v_tx.seller_id and organization_id = v_org_id;

    elsif v_tx.source_till in ('manager_uzs', 'manager_cash') then
      update public.manager_vault_account
         set manager_cash_amount = round(greatest(0, manager_cash_amount - v_tx.amount_num), 2),
             updated_at = now()
       where organization_id = v_org_id;

    elsif v_tx.source_till in ('seller_till_uzs') and v_tx.seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_cash_amount = round(greatest(0, seller_till_cash_amount - v_tx.amount_num), 2),
             updated_at = now()
       where seller_id = v_tx.seller_id and organization_id = v_org_id;

    elsif v_tx.source_till in ('manager_usd') then
      update public.manager_vault_account
         set manager_usd_amount = round(greatest(0, manager_usd_amount - v_tx.amount_num), 2),
             updated_at = now()
       where organization_id = v_org_id;

    elsif v_tx.source_till in ('seller_till_usd') and v_tx.seller_id is not null then
      update public.seller_gold_accounts
         set seller_till_usd_amount = round(greatest(0, seller_till_usd_amount - v_tx.amount_num), 2),
             updated_at = now()
       where seller_id = v_tx.seller_id and organization_id = v_org_id;
    end if;

  elsif v_tx.transaction_type in ('capital_out', 'capital_distribution', 'expense', 'business_expense') then
    if v_tx.source_till in ('manager_uzs', 'manager_cash') then
      update public.manager_vault_account
         set manager_cash_amount = round(manager_cash_amount + v_tx.amount_num, 2),
             updated_at = now()
       where organization_id = v_org_id;
    elsif v_tx.source_till in ('manager_usd') then
      update public.manager_vault_account
         set manager_usd_amount = round(manager_usd_amount + v_tx.amount_num, 2),
             updated_at = now()
       where organization_id = v_org_id;
    end if;
  end if;

  update public.financial_transactions
     set status = 'reversed',
         reversed_at = now(),
         reversed_by = auth.uid(),
         reversal_reason = v_reason,
         updated_at = now()
   where id = v_tx.id;

  return jsonb_build_object(
    'status', 'ok',
    'transaction_id', v_tx.id,
    'message', 'Operatsiya bekor qilindi'
  );
end;
$function$;
revoke all on function rpc_reverse_financial_transaction(uuid,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_financial_transaction(uuid,text) to authenticated;
grant execute on function rpc_reverse_financial_transaction(uuid,text) to service_role;

-- parity: rpc_reverse_financial_transaction(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_financial_transaction(p_transaction_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org      uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_clean_reason    text := nullif(btrim(p_reason), '');
  v_tx              public.financial_transactions%rowtype;
  v_vault           public.manager_vault_account%rowtype;
  v_payload         jsonb;
  v_existing        jsonb;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter'
  ]);

  if v_clean_reason is null then
    raise exception 'Moliyaviy operatsiyani bekor qilish sababi kiritilishi shart';
  end if;

  v_payload := jsonb_build_object(
    'action', 'reverse_financial_transaction',
    'transaction_id', p_transaction_id,
    'reason', v_clean_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_financial_transaction', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_tx
  from public.financial_transactions
  where id = p_transaction_id and organization_id = v_caller_org
  for update;

  if not found then
    raise exception 'Moliyaviy operatsiya topilmadi: %', p_transaction_id;
  end if;

  if v_tx.status = 'reversed' then
    raise exception 'Ushbu moliyaviy operatsiya allaqachon bekor qilingan (%s)', v_tx.transaction_no;
  end if;

  -- Lock manager vault
  perform public._get_or_create_manager_vault(v_caller_org);
  select * into v_vault
  from public.manager_vault_account
  where organization_id = v_caller_org
  for update;

  -- Reversal math based on transaction type
  if v_tx.transaction_type = 'capital_contribution' then
    -- Original injected capital into till -> reversal DEDUCTS from till!
    if v_tx.source_till = 'manager_uzs' then
      if v_vault.manager_cash_amount < v_tx.amount_num then
        raise exception 'Operatsiyani bekor qilib bo''lmaydi: seyfda yetarli naqd pul (UZS) mavjud emas (Mavjud: % UZS, Talab: % UZS)',
          v_vault.manager_cash_amount, v_tx.amount_num;
      end if;
      update public.manager_vault_account
         set manager_cash_amount = round((manager_cash_amount - v_tx.amount_num)::numeric, 2), updated_at = now()
       where organization_id = v_caller_org;

    elsif v_tx.source_till = 'manager_usd' then
      if coalesce(v_vault.manager_usd_amount, 0) < v_tx.amount_num then
        raise exception 'Operatsiyani bekor qilib bo''lmaydi: seyfda yetarli dollar (USD) mavjud emas (Mavjud: % USD, Talab: % USD)',
          coalesce(v_vault.manager_usd_amount, 0), v_tx.amount_num;
      end if;
      update public.manager_vault_account
         set manager_usd_amount = round((coalesce(manager_usd_amount, 0) - v_tx.amount_num)::numeric, 2), updated_at = now()
       where organization_id = v_caller_org;

    elsif v_tx.source_till = 'manager_vault_gold' then
      if v_vault.manager_refined_gold_grams < v_tx.equiv_585_grams then
        raise exception 'Operatsiyani bekor qilib bo''lmaydi: seyfda yetarli oltin mavjud emas (Mavjud: % g, Talab: % g)',
          v_vault.manager_refined_gold_grams, v_tx.equiv_585_grams;
      end if;
      update public.manager_vault_account
         set manager_refined_gold_grams = round((manager_refined_gold_grams - v_tx.equiv_585_grams)::numeric, 4), updated_at = now()
       where organization_id = v_caller_org;
    end if;

  elsif v_tx.transaction_type in ('capital_distribution', 'business_expense') then
    -- Original deducted cash/gold from till -> reversal RESTORES to till!
    if v_tx.source_till = 'manager_uzs' then
      update public.manager_vault_account
         set manager_cash_amount = round((manager_cash_amount + v_tx.amount_num)::numeric, 2), updated_at = now()
       where organization_id = v_caller_org;
    elsif v_tx.source_till = 'manager_usd' then
      update public.manager_vault_account
         set manager_usd_amount = round((coalesce(manager_usd_amount, 0) + v_tx.amount_num)::numeric, 2), updated_at = now()
       where organization_id = v_caller_org;
    elsif v_tx.source_till = 'manager_vault_gold' then
      update public.manager_vault_account
         set manager_refined_gold_grams = round((manager_refined_gold_grams + v_tx.equiv_585_grams)::numeric, 4), updated_at = now()
       where organization_id = v_caller_org;
    end if;
  end if;

  -- Mark financial transaction as reversed
  update public.financial_transactions
     set status = 'reversed',
         reversed_at = now(),
         reversed_by = v_caller_emp_id,
         reversal_reason = v_clean_reason
   where id = p_transaction_id;

  -- Audit log
  insert into public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) values (
    v_caller_org, 'financial_transactions', p_transaction_id::text,
    'REVERSE_FINANCIAL_TRANSACTION', auth.uid(),
    jsonb_build_object('tx_no', v_tx.transaction_no, 'amount', v_tx.amount_num, 'type', v_tx.transaction_type),
    jsonb_build_object('status', 'reversed'),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'transaction_id', p_transaction_id,
    'transaction_no', v_tx.transaction_no,
    'transaction_type', v_tx.transaction_type,
    'amount_num', v_tx.amount_num,
    'currency', v_tx.currency,
    'reason', v_clean_reason
  );

  if p_idempotency_key is not null then
    perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_financial_transaction', v_existing, v_payload);
  end if;

  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_financial_transaction(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_financial_transaction(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_financial_transaction(uuid,text,text) to service_role;

-- parity: rpc_reverse_gold_purchase(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_gold_purchase(p_purchase_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org      uuid := public.current_organization_id();
  v_caller_emp_id   uuid := public.current_employee_id();
  v_clean_reason    text := NULLIF(btrim(p_reason), '');
  v_purch           public.gold_purchases%rowtype;
  v_vault           public.manager_vault_account%rowtype;
  v_active_hnd_no   text;
  v_payload         jsonb;
  v_existing        jsonb;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi'
  ]);

  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'Oltin xaridini bekor qilish sababi kiritilishi shart';
  END IF;

  v_payload := jsonb_build_object(
    'action', 'reverse_gold_purchase',
    'purchase_id', p_purchase_id,
    'reason', v_clean_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_gold_purchase', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_purch
  FROM public.gold_purchases
  WHERE id = p_purchase_id AND organization_id = v_caller_org
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Oltin xaridi topilmadi: %', p_purchase_id;
  END IF;

  IF v_purch.status = 'reversed' THEN
    RAISE EXCEPTION 'Ushbu oltin xaridi allaqachon bekor qilingan (%s)', v_purch.purchase_no;
  END IF;

  -- DEPENDENCY CHECK: Check if there are active factory handovers linked to this purchase via purchase_id, source_purchase_id OR notes reference!
  SELECT handover_no INTO v_active_hnd_no
  FROM public.factory_gold_handovers
  WHERE (purchase_id = p_purchase_id OR source_purchase_id = p_purchase_id OR (v_purch.purchase_no IS NOT NULL AND notes LIKE '%' || v_purch.purchase_no || '%'))
    AND organization_id = v_caller_org
    AND status NOT IN ('reversed', 'cancelled')
  LIMIT 1;

  IF v_active_hnd_no IS NOT NULL THEN
    RAISE EXCEPTION 'Oltin xaridini bekor qilib bo''lmaydi: Ushbu oltin xaridi (%s) bo''yicha faol zavodga topshirish (%s) mavjud. Avval ushbu topshirishni bekor qiling.',
      v_purch.purchase_no, v_active_hnd_no;
  END IF;

  -- Lock manager vault
  PERFORM public._get_or_create_manager_vault(v_caller_org);
  SELECT * INTO v_vault
  FROM public.manager_vault_account
  WHERE organization_id = v_caller_org
  FOR UPDATE;

  -- Check if purchased gold is still in vault
  IF COALESCE(v_vault.manager_purchased_gold_grams, 0) < v_purch.equiv_585_grams THEN
    RAISE EXCEPTION 'Oltin xaridini bekor qilib bo''lmaydi: xarid qilingan oltin allaqachon zavodga topshirilgan yoki ishlatilgan (Mavjud: % g, Talab: % g).',
      COALESCE(v_vault.manager_purchased_gold_grams, 0), v_purch.equiv_585_grams;
  END IF;

  -- Revert vault balance: deduct purchased gold, restore BOTH cash and USD
  UPDATE public.manager_vault_account
     SET manager_purchased_gold_grams = ROUND((manager_purchased_gold_grams - v_purch.equiv_585_grams)::numeric, 4),
         manager_cash_amount = ROUND((COALESCE(manager_cash_amount, 0) + COALESCE(v_purch.cash_spent_uzs, 0))::numeric, 2),
         manager_usd_amount = ROUND((COALESCE(manager_usd_amount, 0) + COALESCE(v_purch.usd_spent, 0))::numeric, 2),
         updated_at = NOW()
   WHERE organization_id = v_caller_org;

  -- Mark gold purchase as reversed
  UPDATE public.gold_purchases
     SET status = 'reversed',
         reversed_at = NOW(),
         reversed_by = v_caller_emp_id,
         reversal_reason = v_clean_reason
   WHERE id = p_purchase_id;

  -- Audit log
  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id,
    old_data, new_data, reason
  ) VALUES (
    v_caller_org, 'gold_purchases', p_purchase_id::text,
    'REVERSE_GOLD_PURCHASE', auth.uid(),
    jsonb_build_object('purchase_no', v_purch.purchase_no, 'equiv_585_g', v_purch.equiv_585_grams, 'currency', v_purch.currency),
    jsonb_build_object('status', 'reversed'),
    v_clean_reason
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'purchase_id', p_purchase_id,
    'purchase_no', v_purch.purchase_no,
    'restored_cash_uzs', COALESCE(v_purch.cash_spent_uzs, 0),
    'restored_usd', COALESCE(v_purch.usd_spent, 0),
    'deducted_purchased_gold_grams', v_purch.equiv_585_grams,
    'reason', v_clean_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_gold_purchase', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_reverse_gold_purchase(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_gold_purchase(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_gold_purchase(uuid,text,text) to service_role;

-- parity: rpc_reverse_jewelry_sale(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_jewelry_sale(p_sale_id uuid, p_reversal_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org    uuid := public.current_organization_id();
  v_caller_role   text := public.current_employee_role_text();
  v_caller_emp_id uuid := public.current_employee_id();
  v_sale          public.jewelry_sales%rowtype;
  v_client_acc    public.client_gold_accounts%rowtype;
  v_reason        text := NULLIF(btrim(p_reversal_reason), '');
  v_piece         public.consignment_pieces%rowtype;
  v_consign       public.seller_consignments%rowtype;
  v_applied_sett  public.gold_settlements%rowtype;
  v_existing      jsonb;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar',
    'production_manager', 'manager', 'boshqaruvchi',
    'accountant', 'buxgalter', 'sales', 'seller', 'sotuvchi'
  ]);

  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Savdoni bekor qilish sababi (reversal reason) kiritilishi shart';
  END IF;

  SELECT * INTO v_sale
    FROM public.jewelry_sales
   WHERE id = p_sale_id AND organization_id = v_caller_org
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bekor qilinadigan savdo yozuvi topilmadi (%)', p_sale_id;
  END IF;

  IF v_sale.status IN ('cancelled', 'reversed') THEN
    RAISE EXCEPTION 'Ushbu savdo allaqachon bekor qilingan (Holat: %)', v_sale.status;
  END IF;

  -- Cross-seller sale reversal authorization check
  IF v_caller_role IN ('seller', 'sotuvchi', 'sales') THEN
    IF v_sale.seller_id IS DISTINCT FROM v_caller_emp_id THEN
      RAISE EXCEPTION 'Ruxsat etilmadi: Sotuvchilar faqat o''zi amalga oshirgan savdoni bekor qila oladi' USING errcode = '42501';
    END IF;
  END IF;

  -- 1. Check if customer made active payments specifically applied to this sale
  FOR v_applied_sett IN
    SELECT * FROM public.gold_settlements
     WHERE sale_id = v_sale.id
       AND organization_id = v_caller_org
       AND status NOT IN ('reversed', 'cancelled')
  LOOP
    RAISE EXCEPTION 'Savdoni bekor qilib bo''lmaydi: Ushbu savdoga to''lov bog''langan (% — % g). Avval to''lovni bekor qiling.',
      v_applied_sett.settlement_no, v_applied_sett.applied_to_debt_grams;
  END LOOP;

  -- 2. Deduct customer debt generated by this sale
  SELECT * INTO v_client_acc
    FROM public.client_gold_accounts
   WHERE customer_id = v_sale.customer_id AND organization_id = v_caller_org
   FOR UPDATE;

  IF FOUND THEN
    UPDATE public.client_gold_accounts
       SET current_debt_grams = ROUND(GREATEST(0, current_debt_grams - v_sale.remaining_gold_grams)::numeric, 4),
           total_purchased_gold_grams = ROUND(GREATEST(0, total_purchased_gold_grams - v_sale.client_gold_due_grams)::numeric, 4),
           updated_at = NOW()
     WHERE customer_id = v_client_acc.customer_id;
  END IF;

  -- 3. If a physical piece or weight stock was sold, restore it
  -- 068: weight sales recorded with allocations are restored exactly piece by piece
  IF EXISTS (SELECT 1 FROM public.weight_sale_allocations WHERE sale_id = v_sale.id AND reversed_at IS NULL) THEN
    PERFORM public._goldia_restore_weight_sale_allocations(v_sale.id);
  ELSE
  SELECT * INTO v_piece
    FROM public.consignment_pieces
   WHERE sale_id = v_sale.id AND organization_id = v_caller_org
   FOR UPDATE;

  IF FOUND THEN
    UPDATE public.consignment_pieces
       SET status = 'held_by_seller',
           sale_id = NULL,
           sold_at = NULL,
           updated_at = NOW()
     WHERE id = v_piece.id;

    -- Reopen parent consignment if it was marked fully_sold
    IF v_piece.consignment_id IS NOT NULL THEN
      SELECT * INTO v_consign
        FROM public.seller_consignments
       WHERE id = v_piece.consignment_id
       FOR UPDATE;

      IF FOUND THEN
        UPDATE public.seller_consignments
           SET sold_quantity = GREATEST(0, COALESCE(sold_quantity, 1) - 1),
               status = CASE
                          WHEN GREATEST(0, COALESCE(sold_quantity, 1) - 1) <= 0 THEN 'held_by_seller'
                          ELSE 'partially_sold'
                        END,
               updated_at = NOW()
         WHERE id = v_consign.id;
      END IF;
    END IF;
  ELSIF v_sale.consignment_id IS NOT NULL THEN
    -- Weight sale partial deduction: restore weight_grams back on active consignment_piece
    -- 065: restore weight onto the exact piece the weight sale reduced, when known
    SELECT * INTO v_piece
      FROM public.consignment_pieces
     WHERE consignment_id = v_sale.consignment_id AND status = 'held_by_seller'
     ORDER BY (id = v_sale.source_piece_id) DESC, updated_at DESC
     LIMIT 1
     FOR UPDATE;

    IF FOUND THEN
      UPDATE public.consignment_pieces
         SET weight_grams = ROUND((weight_grams + v_sale.base_weight_grams)::numeric, 4),
             updated_at = NOW()
       WHERE id = v_piece.id;
    ELSE
      -- All pieces in this consignment were marked sold/unassigned. Re-create / re-open an active held piece with restored weight!
      INSERT INTO public.consignment_pieces (
        organization_id, consignment_id, model_code, model_name, category,
        purity, weight_grams, status, seller_id, notes
      ) VALUES (
        v_caller_org, v_sale.consignment_id, COALESCE(v_sale.model_code, 'VAZN'), COALESCE(v_sale.product_name, 'Qaytarilgan VAZN'),
        COALESCE(v_sale.category, 'Buyum'), COALESCE(v_sale.purity, 585), v_sale.base_weight_grams,
        'held_by_seller', v_sale.seller_id, 'Restored from reversed sale ' || v_sale.sale_no
      );
    END IF;

    SELECT * INTO v_consign
      FROM public.seller_consignments
     WHERE id = v_sale.consignment_id
     FOR UPDATE;

    IF FOUND THEN
      UPDATE public.seller_consignments
         SET sold_quantity = GREATEST(0, COALESCE(sold_quantity, 1) - 1),
             status = CASE
                        WHEN GREATEST(0, COALESCE(sold_quantity, 1) - 1) <= 0 THEN 'held_by_seller'
                        ELSE 'partially_sold'
                      END,
             updated_at = NOW()
       WHERE id = v_consign.id;
    END IF;
  END IF;
  END IF;

  -- 4. Mark sale as reversed
  UPDATE public.jewelry_sales
     SET status = 'reversed',
         notes = COALESCE(notes, '') || ' [BEKOR QILINDI: ' || v_reason || ' (' || to_char(NOW(), 'YYYY-MM-DD HH24:MI') || ')]',
         updated_at = NOW()
   WHERE id = v_sale.id;

  -- 5. Recalculate seller responsibility
  PERFORM public.recalc_seller_gold_account(v_sale.seller_id, v_caller_org);

  -- 6. Audit log
  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, new_data
  ) VALUES (
    v_caller_org, 'jewelry_sales', v_sale.id::text, 'REVERSE_SALE', auth.uid(),
    jsonb_build_object(
      'sale_id', v_sale.id,
      'sale_no', v_sale.sale_no,
      'customer_id', v_sale.customer_id,
      'seller_id', v_sale.seller_id,
      'reversed_debt_g', v_sale.remaining_gold_grams,
      'reason', v_reason
    )
  );

  RETURN jsonb_build_object(
    'status', 'ok',
    'sale_id', v_sale.id,
    'sale_no', v_sale.sale_no,
    'reversed_debt_g', v_sale.remaining_gold_grams,
    'restored_piece_id', v_piece.id,
    'message', 'Savdo muvaffaqiyatli bekor qilindi'
  );
END;
$function$;
revoke all on function rpc_reverse_jewelry_sale(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_jewelry_sale(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_jewelry_sale(uuid,text,text) to service_role;

-- parity: rpc_reverse_refining_batch(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_refining_batch(p_batch_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller_org    uuid := public.current_organization_id();
  v_caller_emp_id uuid := public.current_employee_id();
  v_batch         public.refining_batches%rowtype;
  v_vault         public.manager_vault_account%rowtype;
  v_reason        text := NULLIF(btrim(p_reason), '');
  v_payload       jsonb;
  v_existing      jsonb;
BEGIN
  IF v_caller_org IS NULL THEN
    RAISE EXCEPTION 'Permission denied: User must belong to an active organization' USING errcode = '42501';
  END IF;

  PERFORM public.assert_erp_permission(ARRAY[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'Afinajni bekor qilish sababi (reason) kiritilishi shart';
  END IF;

  v_payload := jsonb_build_object(
    'action', 'reverse_refining_batch',
    'batch_id', p_batch_id,
    'reason', v_reason
  );

  IF p_idempotency_key IS NOT NULL THEN
    v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_refining_batch', v_payload);
    IF v_existing IS NOT NULL THEN
      RETURN v_existing;
    END IF;
  END IF;

  SELECT * INTO v_batch
    FROM public.refining_batches
   WHERE id = p_batch_id AND organization_id = v_caller_org
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Bekor qilinadigan afinaj partiyasi topilmadi (%)', p_batch_id;
  END IF;

  IF v_batch.status IN ('reversed', 'cancelled') THEN
    RAISE EXCEPTION 'Ushbu afinaj partiyasi allaqachon bekor qilingan';
  END IF;

  PERFORM public._get_or_create_manager_vault(v_caller_org);
  SELECT * INTO v_vault FROM public.manager_vault_account WHERE organization_id = v_caller_org FOR UPDATE;

  IF COALESCE(v_vault.manager_refined_gold_grams, 0) < v_batch.output_585_equiv_grams THEN
    RAISE EXCEPTION 'Afinajni bekor qilib bo''lmaydi: Seyfda yetarli toza oltin yo''q (Mavjud: % g, Talab: % g)',
      v_vault.manager_refined_gold_grams, v_batch.output_585_equiv_grams;
  END IF;

  -- Restore input scrap, deduct produced fine gold and 585 eq.
  UPDATE public.manager_vault_account
     SET manager_scrap_grams             = ROUND(manager_scrap_grams + v_batch.input_scrap_grams, 4),
         manager_scrap_physical_g        = ROUND(COALESCE(manager_scrap_physical_g, 0) + v_batch.input_scrap_grams, 4),
         manager_scrap_585_eq_g          = ROUND(COALESCE(manager_scrap_585_eq_g, 0) + COALESCE(v_batch.input_585_equiv_grams, v_batch.input_scrap_grams), 4),
         manager_refined_gold_grams      = ROUND(GREATEST(0, manager_refined_gold_grams - v_batch.output_585_equiv_grams), 4),
         manager_refined_gold_fine_grams = ROUND(GREATEST(0, COALESCE(manager_refined_gold_fine_grams, 0) - v_batch.output_fine_grams), 4),
         updated_at                      = NOW()
   WHERE organization_id = v_caller_org;

  UPDATE public.refining_batches
     SET status          = 'reversed',
         reversed_at     = NOW(),
         reversed_by     = v_caller_emp_id,
         reversal_reason = v_reason,
         updated_at      = NOW()
   WHERE id = v_batch.id;

  INSERT INTO public.audit_logs (
    organization_id, table_name, record_id, action, actor_id, new_data
  ) VALUES (
    v_caller_org, 'refining_batches', v_batch.id::text, 'REVERSE_REFINING_BATCH', auth.uid(),
    jsonb_build_object(
      'batch_no', v_batch.batch_no,
      'reversed_loss_grams', v_batch.total_loss_grams,
      'restored_scrap_grams', v_batch.input_scrap_grams,
      'deducted_refined_grams', v_batch.output_585_equiv_grams,
      'reason', v_reason
    )
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'batch_id', v_batch.id,
    'batch_no', v_batch.batch_no,
    'reversed_loss_grams', v_batch.total_loss_grams,
    'message', 'Afinaj partiyasi muvaffaqiyatli bekor qilindi va lom seyfga qaytarildi'
  );

  IF p_idempotency_key IS NOT NULL THEN
    PERFORM public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_refining_batch', v_existing, v_payload);
  END IF;

  RETURN v_existing;
END;
$function$;
revoke all on function rpc_reverse_refining_batch(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_reverse_refining_batch(uuid,text,text) to authenticated;
grant execute on function rpc_reverse_refining_batch(uuid,text,text) to service_role;

-- parity: rpc_reverse_seller_to_manager_settlement(uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_reverse_seller_to_manager_settlement(p_settlement_id uuid, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org       uuid := public.current_organization_id();
  v_caller_emp_id    uuid := public.current_employee_id();
  v_clean_reason     text := nullif(btrim(p_reason), '');
  v_settle           public.gold_settlements%rowtype;
  v_vault            public.manager_vault_account%rowtype;
  v_seller_acc       public.seller_gold_accounts%rowtype;
  v_comp_settle_no   text;
  v_comp_settle_id   uuid;
  v_payload          jsonb;
  v_existing         jsonb;
  v_usd              numeric(18, 2);
  v_scrap_phys       numeric(14, 4);
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi'
  ]);

  if v_clean_reason is null then
    raise exception 'Tushumni bekor qilish sababi kiritilishi shart';
  end if;

  v_payload := jsonb_build_object(
    'action', 'reverse_seller_to_manager_settlement',
    'settlement_id', p_settlement_id,
    'reason', v_clean_reason
  );

  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_reverse_seller_to_manager_settlement', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  -- 1. STRICT LOCK ORDER HIERARCHY: Lock Manager Vault FIRST
  perform public._get_or_create_manager_vault(v_caller_org);

  select * into v_vault
    from public.manager_vault_account
   where organization_id = v_caller_org
   for update;

  -- 2. Inspect settlement record
  select * into v_settle
    from public.gold_settlements
   where id = p_settlement_id
     and organization_id = v_caller_org
   for update;

  if not found then
    raise exception 'Tushum kvitansiyasi topilmadi (%)', p_settlement_id;
  end if;

  if v_settle.direction <> 'seller_to_manager' then
    raise exception 'Ushbu operatsiya orqali faqat boshqaruvchi qabulini bekor qilish mumkin';
  end if;

  if v_settle.status = 'reversed' then
    raise exception 'Ushbu tushum kvitansiyasi allaqachon bekor qilingan (%s)', v_settle.settlement_no;
  end if;

  v_usd := coalesce(v_settle.usd_paid_amount, 0);
  v_scrap_phys := coalesce(v_settle.physical_scrap_grams, v_settle.scrap_weight_grams, 0);

  -- 3. STRICT LOCK ORDER HIERARCHY: Lock Seller Gold Account SECOND
  select * into v_seller_acc
    from public.seller_gold_accounts
   where seller_id = v_settle.seller_id and organization_id = v_caller_org
   for update;

  if v_settle.scrap_weight_grams > 0 and v_vault.manager_scrap_grams < v_settle.scrap_weight_grams then
    raise exception 'Boshqaruvchi seyfida yetarli lom mavjud emas (Seyfda: % g, talab: % g). Lom allaqachon affinajga yoki zavodga yuborilgan.',
      v_vault.manager_scrap_grams, v_settle.scrap_weight_grams;
  end if;

  if v_settle.cash_paid_amount > 0 and v_vault.manager_cash_amount < v_settle.cash_paid_amount then
    raise exception 'Boshqaruvchi seyfida yetarli naqd pul (UZS) mavjud emas (Seyfda: % UZS, talab: % UZS).',
      v_vault.manager_cash_amount, v_settle.cash_paid_amount;
  end if;

  if v_usd > 0 and coalesce(v_vault.manager_usd_amount, 0) < v_usd then
    raise exception 'Boshqaruvchi seyfida yetarli dollar (USD) mavjud emas (Seyfda: % USD, talab: % USD).',
      coalesce(v_vault.manager_usd_amount, 0), v_usd;
  end if;

  -- 4. Deduct scrap, UZS & USD from manager vault
  update public.manager_vault_account
     set manager_scrap_grams      = round(manager_scrap_grams - v_settle.scrap_weight_grams, 4),
         manager_scrap_585_eq_g   = round(greatest(0, coalesce(manager_scrap_585_eq_g, 0) - v_settle.scrap_weight_grams), 4),
         manager_scrap_physical_g = round(greatest(0, coalesce(manager_scrap_physical_g, 0) - v_scrap_phys), 4),
         manager_cash_amount      = round(manager_cash_amount - v_settle.cash_paid_amount, 2),
         manager_usd_amount       = round(coalesce(manager_usd_amount, 0) - v_usd, 2),
         updated_at               = now()
   where organization_id = v_caller_org
  returning * into v_vault;

  -- 5. Return scrap, UZS & USD to seller till
  update public.seller_gold_accounts
     set seller_till_scrap_grams        = round(seller_till_scrap_grams + v_settle.scrap_weight_grams, 4),
         seller_till_scrap_585_eq_g     = round(coalesce(seller_till_scrap_585_eq_g, 0) + v_settle.scrap_weight_grams, 4),
         seller_till_scrap_physical_g   = round(coalesce(seller_till_scrap_physical_g, 0) + v_scrap_phys, 4),
         seller_till_cash_amount        = round(seller_till_cash_amount + v_settle.cash_paid_amount, 2),
         seller_till_usd_amount         = round(coalesce(seller_till_usd_amount, 0) + v_usd, 2),
         updated_at                     = now()
   where seller_id = v_settle.seller_id;

  -- 6. Mark original settlement as reversed
  update public.gold_settlements
     set status          = 'reversed',
         reversed_at     = now(),
         reversed_by     = v_caller_emp_id,
         reversal_reason = v_clean_reason
   where id = v_settle.id;

  -- 7. Insert compensating record with explicit reversal link
  v_comp_settle_no := 'STL-REV-MGR-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.gold_settlements (
    organization_id, settlement_no, direction, seller_id,
    gold_rate_applied, scrap_weight_grams, physical_scrap_grams, scrap_585_equiv_grams,
    cash_paid_amount, cash_equivalent_grams,
    usd_paid_amount, applied_usd_rate, usd_equivalent_grams,
    total_settled_grams, status, reversal_of_id, reversal_reason,
    previous_debt_grams, remaining_debt_grams,
    notes, recorded_by
  ) values (
    v_caller_org, v_comp_settle_no, 'seller_to_manager', v_settle.seller_id,
    v_settle.gold_rate_applied, v_settle.scrap_weight_grams, v_scrap_phys, v_settle.scrap_weight_grams,
    v_settle.cash_paid_amount, coalesce(v_settle.cash_equivalent_grams, 0),
    v_usd, v_settle.applied_usd_rate, coalesce(v_settle.usd_equivalent_grams, 0),
    v_settle.total_settled_grams, 'reversed', v_settle.id, v_clean_reason,
    coalesce(v_settle.remaining_debt_grams, 0), coalesce(v_settle.previous_debt_grams, 0),
    'KOMPENSATSIYA: Boshqaruvchi tushumi ' || v_settle.settlement_no || ' bekor qilindi. Sabab: ' || v_clean_reason, v_caller_emp_id
  ) returning id into v_comp_settle_id;

  -- 8. Audit log
  if to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs (
      organization_id, table_name, record_id, action, actor_id, old_data, new_data, reason
    ) values (
      v_caller_org, 'gold_settlements', v_settle.id::text, 'REVERSE_MANAGER_SETTLEMENT', auth.uid(),
      jsonb_build_object(
        'settlement_no', v_settle.settlement_no,
        'scrap_weight_g', v_settle.scrap_weight_grams,
        'cash_paid_uzs', v_settle.cash_paid_amount,
        'usd_paid', v_usd,
        'seller_id', v_settle.seller_id
      ),
      jsonb_build_object(
        'original_status', 'reversed',
        'compensating_settle_no', v_comp_settle_no
      ),
      v_clean_reason
    );
  end if;

  -- 9. Read back restored seller account
  select * into v_seller_acc
    from public.seller_gold_accounts
   where seller_id = v_settle.seller_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'reversal_id', v_comp_settle_id,
    'reversal_no', v_comp_settle_no,
    'original_settlement_no', v_settle.settlement_no,
    'scrap_returned_grams', v_settle.scrap_weight_grams,
    'scrap_physical_returned_grams', v_scrap_phys,
    'cash_returned_amount', v_settle.cash_paid_amount,
    'usd_returned_amount', v_usd,
    'restored_seller_obligation_g', v_seller_acc.seller_owes_manager_g,
    'bozor_qarzi_signed_g', v_seller_acc.bozor_qarzi_signed_g,
    'seller_till_scrap_grams', v_seller_acc.seller_till_scrap_grams,
    'seller_till_scrap_physical_g', v_seller_acc.seller_till_scrap_physical_g,
    'seller_till_cash_amount', v_seller_acc.seller_till_cash_amount,
    'seller_till_usd_amount', v_seller_acc.seller_till_usd_amount,
    'manager_scrap_grams', v_vault.manager_scrap_grams,
    'manager_cash_amount', v_vault.manager_cash_amount,
    'manager_usd_amount', v_vault.manager_usd_amount
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_reverse_seller_to_manager_settlement', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_reverse_seller_to_manager_settlement(uuid,text,text) from public, anon, authenticated, service_role;
