-- parity: rpc_set_daily_gold_rate(numeric,numeric,date,text,text,text,numeric)
CREATE OR REPLACE FUNCTION public.rpc_set_daily_gold_rate(p_rate_per_gram numeric, p_proba numeric DEFAULT 585, p_rate_date date DEFAULT _goldia_business_date(), p_currency text DEFAULT 'UZS'::text, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_purity numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_caller_org  uuid := public.current_organization_id();
  v_caller_id   uuid := public.current_employee_id(); -- 070: employees(id), not auth.uid()
  v_rate        numeric(18, 2);
  v_pr          numeric(6, 2);
  v_dt          date := coalesce(p_rate_date, public._goldia_business_date());
  v_cur         text := upper(trim(coalesce(p_currency, 'UZS')));
  v_payload     jsonb;
  v_existing    jsonb;
  v_rate_id     uuid;
begin
  if v_caller_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'direktor', 'rahbar', 'production_manager', 'manager', 'boshqaruvchi', 'accountant', 'buxgalter'
  ]);

  v_rate := round(coalesce(p_rate_per_gram, 0)::numeric, 2);
  if v_rate <= 0 then
    raise exception 'Lom kursi 0 dan katta bo''lishi shart (kiritildi: %)', p_rate_per_gram;
  end if;

  -- Support both p_proba and p_purity
  v_pr := round(coalesce(p_purity, p_proba, 585)::numeric, 2);
  if v_pr <= 0 or v_pr > 1000 then
    raise exception 'Proba 1 dan 1000 oralig''ida bo''lishi shart (kiritildi: %)', v_pr;
  end if;

  v_payload := jsonb_build_object(
    'action', 'set_daily_gold_rate',
    'rate_date', v_dt,
    'proba', v_pr,
    'purity', v_pr,
    'rate_per_gram', v_rate
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_set_daily_gold_rate', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  insert into public.daily_gold_rates (
    organization_id, rate_date, proba, purity, rate_per_gram, currency, is_confirmed, set_by, notes, updated_at
  ) values (
    v_caller_org, v_dt, v_pr, v_pr, v_rate, v_cur, true, v_caller_id, p_notes, now()
  )
  on conflict (organization_id, rate_date, proba)
  do update set
    rate_per_gram = excluded.rate_per_gram,
    purity        = excluded.purity,
    currency      = excluded.currency,
    is_confirmed  = true,
    set_by        = excluded.set_by,
    notes         = coalesce(excluded.notes, daily_gold_rates.notes),
    updated_at    = now()
  returning id into v_rate_id;

  v_existing := jsonb_build_object(
    'status', 'ok',
    'rate_id', v_rate_id,
    'rate_date', v_dt,
    'proba', v_pr,
    'purity', v_pr,
    'rate_per_gram', v_rate,
    'currency', v_cur
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_set_daily_gold_rate', v_existing, v_payload);
  return v_existing;
end;
$function$;
revoke all on function rpc_set_daily_gold_rate(numeric,numeric,date,text,text,text,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_set_daily_gold_rate(numeric,numeric,date,text,text,text,numeric) to authenticated;
grant execute on function rpc_set_daily_gold_rate(numeric,numeric,date,text,text,text,numeric) to service_role;

-- parity: rpc_set_my_seller_rates(numeric,numeric,text)
CREATE OR REPLACE FUNCTION public.rpc_set_my_seller_rates(p_lom_rate_uzs numeric DEFAULT NULL::numeric, p_usd_rate_uzs numeric DEFAULT NULL::numeric, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org     uuid := public.current_organization_id();
  v_role    text := public.current_employee_role_text();
  v_emp     uuid := public.current_employee_id();
  v_lim     public.seller_rate_limits%rowtype;
  v_old     public.seller_rates%rowtype;
  v_lom     numeric(18, 2);
  v_usd     numeric(18, 2);
  v_off     numeric(18, 2);
begin
  if v_org is null or v_emp is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  -- Only a seller sets rates, and only their own (the seller id is never taken from the request).
  perform public.assert_erp_permission(array['sales', 'seller', 'sotuvchi']);
  if not public._goldia_is_seller_role(v_role) then
    raise exception 'Ruxsat etilmadi: kursni faqat sotuvchi o''zi uchun belgilaydi' using errcode = '42501';
  end if;
  if p_lom_rate_uzs is null and p_usd_rate_uzs is null then
    raise exception 'ERR_RATE_INVALID: LOM yoki USD kursidan kamida bittasi kiritilishi shart' using errcode = '22023';
  end if;

  v_lim := public._goldia_seller_rate_limits(v_org);

  insert into public.seller_rates (seller_id, organization_id, updated_by)
  values (v_emp, v_org, v_emp)
  on conflict (seller_id) do nothing;
  select * into v_old from public.seller_rates where seller_id = v_emp and organization_id = v_org for update;
  if not found then
    raise exception 'Ruxsat etilmadi' using errcode = '42501';
  end if;

  v_lom := v_old.lom_rate_uzs;
  v_usd := v_old.usd_rate_uzs;
  if p_lom_rate_uzs is not null then
    v_lom := public._goldia_validate_rate_value(p_lom_rate_uzs, v_lim.lom_min_uzs, v_lim.lom_max_uzs, 'LOM kursi (UZS/g)');
    v_off := public._goldia_official_585_rate(v_org);
    if v_lim.max_lom_deviation_pct is not null and v_off is not null and v_off > 0
       and abs(v_lom - v_off) > v_off * v_lim.max_lom_deviation_pct / 100.0 then
      raise exception 'ERR_RATE_OUT_OF_RANGE: LOM kursi rasmiy 585 kursidan (% UZS/g) % foizdan ortiq farq qila olmaydi',
        v_off, v_lim.max_lom_deviation_pct using errcode = '22023';
    end if;
  end if;
  if p_usd_rate_uzs is not null then
    v_usd := public._goldia_validate_rate_value(p_usd_rate_uzs, v_lim.usd_min_uzs, v_lim.usd_max_uzs, 'USD kursi (UZS)');
  end if;

  update public.seller_rates
     set lom_rate_uzs = v_lom, usd_rate_uzs = v_usd, updated_by = v_emp, updated_at = now()
   where seller_id = v_emp;

  insert into public.seller_rate_history (organization_id, seller_id, old_lom_rate_uzs, new_lom_rate_uzs,
                                          old_usd_rate_uzs, new_usd_rate_uzs, changed_by, reason)
  values (v_org, v_emp, v_old.lom_rate_uzs, v_lom, v_old.usd_rate_uzs, v_usd, v_emp, p_reason);

  insert into public.audit_logs (table_name, record_id, action, actor_id, actor_role, old_data, new_data, reason, organization_id)
  values ('seller_rates', v_emp::text, 'SET_SELLER_RATES', v_emp, v_role,
          jsonb_build_object('lom_rate_uzs', v_old.lom_rate_uzs, 'usd_rate_uzs', v_old.usd_rate_uzs),
          jsonb_build_object('lom_rate_uzs', v_lom, 'usd_rate_uzs', v_usd), p_reason, v_org);

  return jsonb_build_object('status', 'ok', 'seller_id', v_emp, 'lom_rate_uzs', v_lom, 'usd_rate_uzs', v_usd,
                            'previous_lom_rate_uzs', v_old.lom_rate_uzs, 'previous_usd_rate_uzs', v_old.usd_rate_uzs);
end;
$function$;
revoke all on function rpc_set_my_seller_rates(numeric,numeric,text) from public, anon, authenticated, service_role;
grant execute on function rpc_set_my_seller_rates(numeric,numeric,text) to authenticated;
grant execute on function rpc_set_my_seller_rates(numeric,numeric,text) to service_role;

-- parity: rpc_set_seller_rate_limits(numeric,numeric,numeric,numeric,numeric)
CREATE OR REPLACE FUNCTION public.rpc_set_seller_rate_limits(p_lom_min_uzs numeric, p_lom_max_uzs numeric, p_usd_min_uzs numeric, p_usd_max_uzs numeric, p_max_lom_deviation_pct numeric DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org  uuid := public.current_organization_id();
  v_emp  uuid := public.current_employee_id();
  v_old  public.seller_rate_limits%rowtype;
begin
  if v_org is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;
  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'manager', 'production_manager', 'boshqaruvchi']);
  v_old := public._goldia_seller_rate_limits(v_org);
  insert into public.seller_rate_limits (organization_id, lom_min_uzs, lom_max_uzs, usd_min_uzs, usd_max_uzs, max_lom_deviation_pct, updated_by, updated_at)
  values (v_org, p_lom_min_uzs, p_lom_max_uzs, p_usd_min_uzs, p_usd_max_uzs, p_max_lom_deviation_pct, v_emp, now())
  on conflict (organization_id) do update set
    lom_min_uzs = excluded.lom_min_uzs, lom_max_uzs = excluded.lom_max_uzs,
    usd_min_uzs = excluded.usd_min_uzs, usd_max_uzs = excluded.usd_max_uzs,
    max_lom_deviation_pct = excluded.max_lom_deviation_pct, updated_by = v_emp, updated_at = now();
  insert into public.audit_logs (table_name, record_id, action, actor_id, actor_role, old_data, new_data, organization_id)
  values ('seller_rate_limits', v_org::text, 'SET_SELLER_RATE_LIMITS', v_emp, public.current_employee_role_text(),
          to_jsonb(v_old), jsonb_build_object('lom_min_uzs', p_lom_min_uzs, 'lom_max_uzs', p_lom_max_uzs,
            'usd_min_uzs', p_usd_min_uzs, 'usd_max_uzs', p_usd_max_uzs, 'max_lom_deviation_pct', p_max_lom_deviation_pct), v_org);
  return jsonb_build_object('status', 'ok');
end;
$function$;
revoke all on function rpc_set_seller_rate_limits(numeric,numeric,numeric,numeric,numeric) from public, anon, authenticated, service_role;
grant execute on function rpc_set_seller_rate_limits(numeric,numeric,numeric,numeric,numeric) to authenticated;
grant execute on function rpc_set_seller_rate_limits(numeric,numeric,numeric,numeric,numeric) to service_role;

-- parity: rpc_split_batch(text,integer,text,integer,text)
CREATE OR REPLACE FUNCTION public.rpc_split_batch(p_parent_batch_id text, p_split_qty integer, p_child_batch_no text DEFAULT NULL::text, p_stage_order integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_parent      public.batches%rowtype;
  v_wip         public.batch_stage_wip%rowtype;
  v_parent_no   text;
  v_child_no    text;
  v_child_id    text;
  v_tot_qty     integer;
  v_rem_qty     integer;
  v_tot_gold    numeric(14, 4);
  v_cur_wip_g   numeric(14, 4);
  v_ratio       numeric(18, 8);
  v_child_gold  numeric(14, 4);
  v_parent_gold numeric(14, 4);
  v_child_wip_g numeric(14, 4);
  v_parent_wip_g numeric(14, 4);
  v_wip_in_child numeric(14, 4);
  v_wip_in_parent numeric(14, 4);
  v_idx         integer := 1;
  v_existing    jsonb;
  v_payload     jsonb;
begin
  perform public.assert_erp_permission(array[
    'admin', 'director', 'owner', 'manager', 'production_manager', 'production manager',
    'master', 'supervisor', 'bosh usta', 'usta', 'department_head', 'department_operator'
  ]);

  v_payload := jsonb_build_object(
    'parent_batch_id', btrim(coalesce(p_parent_batch_id, '')),
    'split_qty', p_split_qty,
    'stage_order', p_stage_order
  );
  v_existing := public.check_and_lock_idempotency(p_idempotency_key, 'rpc_split_batch', v_payload);
  if v_existing is not null then
    return v_existing;
  end if;

  select * into v_parent from public.batches where id::text = btrim(p_parent_batch_id) for update;
  if not found then
    raise exception 'Parent batch (%) not found', p_parent_batch_id;
  end if;

  v_parent_no := coalesce(v_parent.batch_no, v_parent.number, v_parent.batch_number);
  v_tot_qty   := coalesce(v_parent.planned_qty, 0);
  v_tot_gold  := round(coalesce(v_parent.issued_gold_gram, v_parent.planned_gram, 0), 4);
  v_cur_wip_g := round(coalesce(v_parent.wip_gram, v_tot_gold), 4);

  if p_split_qty <= 0 or p_split_qty >= v_tot_qty or v_tot_gold <= 0 then
    raise exception 'Invalid split quantity (%) for batch % (total qty=%)', p_split_qty, v_parent_no, v_tot_qty;
  end if;

  -- Lock the active stage WIP row to split its available_qty & input_weight
  if p_stage_order is not null then
    select * into v_wip
      from public.batch_stage_wip
     where batch_no = v_parent_no and stage_order = p_stage_order
       for update;
  else
    select * into v_wip
      from public.batch_stage_wip
     where batch_no = v_parent_no and available_qty >= p_split_qty
     order by stage_order asc
     limit 1
       for update;
  end if;

  if not found or v_wip.available_qty < p_split_qty then
    raise exception 'Active stage WIP row does not have enough available units (%) to split % units',
      coalesce(v_wip.available_qty, 0), p_split_qty;
  end if;

  v_rem_qty      := v_tot_qty - p_split_qty;
  v_ratio        := p_split_qty::numeric / v_tot_qty::numeric;
  v_child_gold   := round(v_tot_gold * v_ratio, 4);
  v_parent_gold  := round(v_tot_gold - v_child_gold, 4);
  v_child_wip_g  := round(v_cur_wip_g * v_ratio, 4);
  v_parent_wip_g := round(v_cur_wip_g - v_child_wip_g, 4);

  v_wip_in_child  := round(coalesce(v_wip.input_weight, v_cur_wip_g) * (p_split_qty::numeric / v_wip.available_qty::numeric), 4);
  v_wip_in_parent := round(coalesce(v_wip.input_weight, v_cur_wip_g) - v_wip_in_child, 4);

  if coalesce(btrim(p_child_batch_no), '') <> '' then
    v_child_no := btrim(p_child_batch_no);
  else
    loop
      v_child_no := format('%s-S%s', v_parent_no, v_idx);
      exit when not exists (
        select 1 from public.batches
         where batch_no = v_child_no or number = v_child_no or batch_number = v_child_no
      );
      v_idx := v_idx + 1;
    end loop;
  end if;

  -- 1. Update parent batch
  update public.batches
     set planned_qty      = v_rem_qty,
         planned_gram     = v_parent_gold,
         issued_gold_gram = v_parent_gold,
         wip_gram         = v_parent_wip_g
   where id = v_parent.id;

  -- 2. Create child batch
  insert into public.batches (
    order_id, batch_number, batch_no, number, parent_batch_no,
    product_id, product_name, product, client_name, master_name,
    proba, planned_qty, planned_gram, issued_gold_gram, wip_gram,
    good_output_gram, sprue_gram, scrap_gram, rework_gram, loss_gram,
    finished_qty, credited_finished_qty, current_step, status, status_label, priority, priority_label, deadline, due_date
  ) values (
    v_parent.order_id, v_child_no, v_child_no, v_child_no, v_parent_no,
    v_parent.product_id, v_parent.product_name, v_parent.product, v_parent.client_name, v_parent.master_name,
    v_parent.proba, p_split_qty, v_child_gold, v_child_gold, v_child_wip_g,
    0, 0, 0, 0, 0,
    0, 0, v_wip.stage_name, 'Jarayonda', 'Jarayonda', coalesce(v_parent.priority_label, 'Normal'), coalesce(v_parent.priority_label, 'Normal'), v_parent.deadline, v_parent.due_date
  ) returning id::text into v_child_id;

  -- 3. Update parent stage WIP & insert child stage WIP
  update public.batch_stage_wip
     set available_qty = v_wip.available_qty - p_split_qty,
         input_weight  = v_wip_in_parent,
         queue_status  = case when (v_wip.available_qty - p_split_qty) = 0 then 'DONE' else 'NOW' end,
         updated_at    = now()
   where id = v_wip.id;

  insert into public.batch_stage_wip (
    batch_id, batch_no, stage_order, stage_name, department,
    available_qty, completed_qty, rework_qty, input_weight, output_weight, loss_weight,
    queue_status, assigned_worker, assigned_employee_id
  ) values (
    public.try_cast_uuid(v_child_id), v_child_no, v_wip.stage_order, v_wip.stage_name, v_wip.department,
    p_split_qty, 0, 0, v_wip_in_child, 0, 0,
    'NOW', v_wip.assigned_worker, v_wip.assigned_employee_id
  );

  v_existing := jsonb_build_object(
    'status', 'ok',
    'parent_batch_no', v_parent_no,
    'child_batch_id', v_child_id,
    'child_batch_no', v_child_no,
    'parent_qty', v_rem_qty,
    'child_qty', p_split_qty,
    'parent_gold_gram', v_parent_gold,
    'child_gold_gram', v_child_gold,
    'parent_wip_gram', v_parent_wip_g,
    'child_wip_gram', v_child_wip_g
  );

  perform public.save_idempotency_response(p_idempotency_key, 'rpc_split_batch', v_existing, v_payload);

  return v_existing;
end;
$function$;
revoke all on function rpc_split_batch(text,integer,text,integer,text) from public, anon, authenticated, service_role;
grant execute on function rpc_split_batch(text,integer,text,integer,text) to authenticated;
grant execute on function rpc_split_batch(text,integer,text,integer,text) to service_role;

-- parity: rpc_transfer_to_seller(uuid,numeric,numeric,numeric,text,integer,uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.rpc_transfer_to_seller(p_seller_id uuid, p_original_physical_g numeric, p_seller_markup_pct numeric DEFAULT 12.0, p_factory_markup_pct numeric DEFAULT 8.0, p_product_name text DEFAULT 'Zargarlik buyumi'::text, p_quantity integer DEFAULT 1, p_factory_receipt_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_org_id          uuid := public.current_organization_id();
  v_seller_role     text;
  v_phys_g          numeric(14, 4);
  v_s_pct           numeric(6, 2);
  v_f_pct           numeric(6, 2);
  v_s_due_g         numeric(14, 4);
  v_f_due_g         numeric(14, 4);
  v_spread_g        numeric(14, 4);
  v_consign_no      text;
  v_consign_id      uuid;
  v_receipt_rec     record;
  v_seller_account  public.seller_gold_accounts;
  v_existing        jsonb;
begin
  if v_org_id is null then
    raise exception 'Permission denied: User must belong to an active organization' using errcode = '42501';
  end if;

  perform public.assert_erp_permission(array['admin', 'director', 'owner', 'direktor', 'rahbar', 'accountant', 'buxgalter', 'inventory_manager']);

  -- Verify seller is not director/admin
  select lower(coalesce(role::text, '')) into v_seller_role
  from public.employees
  where id = p_seller_id and organization_id = v_org_id;

  if v_seller_role is null then
    raise exception 'Seller not found or does not belong to active organization';
  end if;

  if v_seller_role in ('admin', 'director', 'owner', 'direktor', 'rahbar') then
    raise exception 'Invalid recipient: Cannot consign products to director or admin. Select an active sales seller.';
  end if;

  if p_idempotency_key is not null then
    select jsonb_build_object(
      'status', 'ok',
      'idempotent_replay', true,
      'consignment_id', id,
      'consignment_no', consignment_no,
      'seller_obligation_g', seller_obligation_g
    ) into v_existing
    from public.seller_consignments
    where idempotency_key = p_idempotency_key;

    if v_existing is not null then
      return v_existing;
    end if;
  end if;

  v_phys_g := round(coalesce(p_original_physical_g, 0)::numeric, 4);
  v_s_pct := round(greatest(0, coalesce(p_seller_markup_pct, 12.0))::numeric, 2);
  v_f_pct := round(greatest(0, coalesce(p_factory_markup_pct, 8.0))::numeric, 2);

  if v_phys_g <= 0 then
    raise exception 'Invalid physical weight: must be greater than 0';
  end if;

  -- Non-compounding rule: Both markups calculate from original physical weight
  v_s_due_g := round(v_phys_g * (1.0 + (v_s_pct / 100.0)), 4);
  v_f_due_g := round(v_phys_g * (1.0 + (v_f_pct / 100.0)), 4);
  v_spread_g := round(v_s_due_g - v_f_due_g, 4);

  -- Deduct physical stock from factory_receipt if supplied or available
  if p_factory_receipt_id is not null then
    select * into v_receipt_rec
    from public.factory_receipts
    where id = p_factory_receipt_id and organization_id = v_org_id for update;

    if not found then
      raise exception 'Factory receipt not found';
    end if;

    if v_receipt_rec.available_physical_g < v_phys_g then
      raise exception 'Insufficient manager stock in factory receipt: available %g, requested %g',
        v_receipt_rec.available_physical_g, v_phys_g;
    end if;

    update public.factory_receipts
    set available_physical_g = round(available_physical_g - v_phys_g, 4),
        transferred_physical_g = round(transferred_physical_g + v_phys_g, 4),
        status = case
          when round(available_physical_g - v_phys_g, 4) <= 0.0001 then 'fully_transferred'
          else 'partially_transferred'
        end,
        updated_at = now()
    where id = p_factory_receipt_id;
  end if;

  v_consign_no := 'CNS-' || to_char(public._goldia_business_date(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.seller_consignments (
    organization_id,
    consignment_no,
    seller_id,
    factory_receipt_id,
    product_id,
    product_name,
    quantity,
    base_weight_grams,
    proba,
    factory_markup_pct,
    factory_gold_due_grams,
    factory_settled_gold_grams,
    factory_remaining_gold_grams,
    seller_markup_pct,
    seller_obligation_g,
    sold_quantity,
    status,
    notes,
    idempotency_key
  ) values (
    v_org_id,
    v_consign_no,
    p_seller_id,
    p_factory_receipt_id,
    p_product_id,
    coalesce(nullif(btrim(p_product_name), ''), 'Zargarlik buyumi'),
    greatest(1, coalesce(p_quantity, 1)),
    v_phys_g,
    585,
    v_f_pct,
    v_f_due_g,
    0,
    v_f_due_g,
    v_s_pct,
    v_s_due_g,
    0,
    'held_by_seller',
    p_notes,
    p_idempotency_key
  ) returning id into v_consign_id;

  -- Read seller account updated automatically by fn_sync_seller_gold_account trigger
  select * into v_seller_account
  from public.seller_gold_accounts
  where seller_id = p_seller_id;

  return jsonb_build_object(
    'status', 'ok',
    'consignment_id', v_consign_id,
    'consignment_no', v_consign_no,
    'base_weight_grams', v_phys_g,
    'seller_markup_pct', v_s_pct,
    'seller_obligation_g', v_s_due_g,
    'factory_markup_pct', v_f_pct,
    'factory_gold_due_grams', v_f_due_g,
    'markup_spread_grams', v_spread_g,
    'seller_owes_manager_g', v_seller_account.seller_owes_manager_g,
    'bozor_qarzi_signed_g', v_seller_account.bozor_qarzi_signed_g
  );
end;
$function$;
revoke all on function rpc_transfer_to_seller(uuid,numeric,numeric,numeric,text,integer,uuid,uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_transfer_to_seller(uuid,numeric,numeric,numeric,text,integer,uuid,uuid,text,text) to authenticated;
grant execute on function rpc_transfer_to_seller(uuid,numeric,numeric,numeric,text,integer,uuid,uuid,text,text) to service_role;

