-- parity: rpc_verify_and_link_telegram(text,text,text)
CREATE OR REPLACE FUNCTION public.rpc_verify_and_link_telegram(p_link_code text, p_telegram_user_id text, p_telegram_username text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_emp record;
begin
  if p_link_code is null or length(trim(p_link_code)) = 0 then
    raise exception 'Tasdiqlash kodi kiritilishi shart!';
  end if;

  if p_telegram_user_id is null or length(trim(p_telegram_user_id)) = 0 then
    raise exception 'Telegram User ID kiritilishi shart!';
  end if;

  -- Check if telegram_user_id is already linked to another employee
  select id, full_name into v_emp
  from public.employees
  where telegram_user_id = trim(p_telegram_user_id);

  if found then
    raise exception 'Ushbu Telegram hisobi allaqachon boshqa xodimga (%) ulangan!', v_emp.full_name;
  end if;

  -- Verify active OTP
  select id, full_name, role, organization_id, email into v_emp
  from public.employees
  where telegram_link_code = trim(p_link_code)
    and telegram_link_expires_at > now()
    and is_active = true;

  if not found then
    raise exception 'Noto''g''ri yoki muddati o''tgan tasdiqlash kodi!';
  end if;

  -- Link Telegram identity and clear single-use token
  update public.employees
  set telegram_user_id = trim(p_telegram_user_id),
      telegram_username = nullif(trim(p_telegram_username), ''),
      telegram_linked_at = now(),
      telegram_link_code = null,
      telegram_link_expires_at = null
  where id = v_emp.id;

  return jsonb_build_object(
    'success', true,
    'employee_id', v_emp.id,
    'full_name', v_emp.full_name,
    'role', v_emp.role::text,
    'organization_id', v_emp.organization_id,
    'email', v_emp.email,
    'telegram_user_id', p_telegram_user_id,
    'telegram_username', p_telegram_username,
    'linked_at', now()
  );
end;
$function$;
revoke all on function rpc_verify_and_link_telegram(text,text,text) from public, anon, authenticated, service_role;
grant execute on function rpc_verify_and_link_telegram(text,text,text) to authenticated;
grant execute on function rpc_verify_and_link_telegram(text,text,text) to service_role;

-- parity: save_idempotency_response(text,text,jsonb,jsonb)
CREATE OR REPLACE FUNCTION public.save_idempotency_response(p_key text, p_operation text, p_response jsonb, p_payload jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key   text := nullif(btrim(coalesce(p_key, '')), '');
  v_store jsonb;
begin
  if v_key is null then
    return;
  end if;

  if p_payload is not null then
    v_store := coalesce(p_response, '{}'::jsonb) || jsonb_build_object('_request_hash', md5(p_payload::text));
  else
    v_store := coalesce(p_response, '{}'::jsonb);
  end if;

  insert into public.idempotency_keys (idempotency_key, operation_name, actor_id, response_data)
  values (v_key, p_operation, auth.uid(), v_store);
end;
$function$;
revoke all on function save_idempotency_response(text,text,jsonb,jsonb) from public, anon, authenticated, service_role;
grant execute on function save_idempotency_response(text,text,jsonb,jsonb) to authenticated;
grant execute on function save_idempotency_response(text,text,jsonb,jsonb) to service_role;

-- parity: sync_batch_current_stage()
CREATE OR REPLACE FUNCTION public.sync_batch_current_stage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  update public.batches
  set
    current_stage_id = new.stage_id,
    current_department_id = new.department_id,
    assigned_employee_id = coalesce(new.assigned_employee_id, batches.assigned_employee_id),
    status = case
      when new.status = 'in_progress' then 'in_progress'
      when new.status = 'delayed' then 'delayed'
      when new.status = 'queued' then 'queued'
      else coalesce(batches.status::text, 'queued')
    end,
    started_at = case when new.status = 'in_progress' and batches.started_at is null then new.started_at else batches.started_at end
  where id = new.batch_id;
  return new;
end;
$function$;
revoke all on function sync_batch_current_stage() from public, anon, authenticated, service_role;
