grant execute on function sync_batch_current_stage() to service_role;

-- parity: trg_goldia_cap_valued_pool()
CREATE OR REPLACE FUNCTION public.trg_goldia_cap_valued_pool()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.valued_cash_uzs > greatest(coalesce(new.manager_cash_amount, 0), 0) then
    new.valued_cash_585_g := case when new.valued_cash_uzs > 0
      then round(new.valued_cash_585_g * greatest(coalesce(new.manager_cash_amount, 0), 0) / new.valued_cash_uzs, 6) else 0 end;
    new.valued_cash_uzs := greatest(coalesce(new.manager_cash_amount, 0), 0);
  end if;
  if new.valued_usd > greatest(coalesce(new.manager_usd_amount, 0), 0) then
    new.valued_usd_585_g := case when new.valued_usd > 0
      then round(new.valued_usd_585_g * greatest(coalesce(new.manager_usd_amount, 0), 0) / new.valued_usd, 6) else 0 end;
    new.valued_usd := greatest(coalesce(new.manager_usd_amount, 0), 0);
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_cap_valued_pool() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_cap_valued_pool() to public;
grant execute on function trg_goldia_cap_valued_pool() to anon;
grant execute on function trg_goldia_cap_valued_pool() to authenticated;
grant execute on function trg_goldia_cap_valued_pool() to service_role;

-- parity: trg_goldia_piece_markup_snapshot()
CREATE OR REPLACE FUNCTION public.trg_goldia_piece_markup_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.sale_id is not null and old.sale_id is null and new.seller_markup_pct is not null then
    update public.jewelry_sales s
       set assigned_seller_markup_pct = new.seller_markup_pct,
           markup_difference_g = round(coalesce(s.base_weight_grams, 0) * (s.client_markup_pct - new.seller_markup_pct) / 100.0, 4),
           markup_snapshot_source = 'sale_time'
     where s.id = new.sale_id
       and s.client_markup_pct is not null
       and coalesce(s.markup_snapshot_source, 'sale_time') = 'sale_time'
       and s.assigned_seller_markup_pct is distinct from new.seller_markup_pct
       and s.created_at > now() - interval '1 minute';
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_piece_markup_snapshot() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_piece_markup_snapshot() to service_role;

-- parity: trg_goldia_rate_difference_from_purchase()
CREATE OR REPLACE FUNCTION public.trg_goldia_rate_difference_from_purchase()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vault        public.manager_vault_account%rowtype;
  v_cash         numeric(18, 2) := coalesce(new.cash_spent_uzs, 0);
  v_usd          numeric(18, 2) := coalesce(new.usd_spent, 0);
  v_usd_rate     numeric(14, 2) := new.usd_rate;
  v_total_cost   numeric(18, 2);
  v_pool_uzs     numeric(18, 2);
  v_pool_uzs_g   numeric(18, 6);
  v_pool_usd     numeric(18, 2);
  v_pool_usd_g   numeric(18, 6);
  v_val_cash     numeric(18, 2) := 0;
  v_val_cash_g   numeric(18, 6) := 0;
  v_val_usd      numeric(18, 2) := 0;
  v_val_usd_g    numeric(18, 6) := 0;
  v_valued_cost  numeric(18, 2);
  v_valued_585   numeric(18, 6);
  v_orig         public.company_rate_differences%rowtype;
begin
  if tg_op = 'INSERT' then
    if coalesce(new.status, 'confirmed') <> 'confirmed' then
      return new;
    end if;
    perform public._get_or_create_manager_vault(new.organization_id);
    select * into v_vault from public.manager_vault_account where organization_id = new.organization_id for update;

    -- The purchase RPC inserts this row before it deducts the vault, so the vault still shows the
    -- cash available before the purchase. Valued cash can never exceed the cash really present
    -- (other outflows such as expenses shrink it proportionally).
    v_pool_uzs   := least(v_vault.valued_cash_uzs, greatest(coalesce(v_vault.manager_cash_amount, 0), 0));
    v_pool_uzs_g := case when v_vault.valued_cash_uzs > 0
                         then v_vault.valued_cash_585_g * v_pool_uzs / v_vault.valued_cash_uzs else 0 end;
    v_pool_usd   := least(v_vault.valued_usd, greatest(coalesce(v_vault.manager_usd_amount, 0), 0));
    v_pool_usd_g := case when v_vault.valued_usd > 0
                         then v_vault.valued_usd_585_g * v_pool_usd / v_vault.valued_usd else 0 end;

    -- Weighted-average consumption of the valued pool
    if v_cash > 0 and v_pool_uzs > 0 then
      v_val_cash   := least(v_cash, v_pool_uzs);
      v_val_cash_g := round(v_pool_uzs_g * v_val_cash / v_pool_uzs, 6);
    end if;
    if v_usd > 0 and v_pool_usd > 0 then
      v_val_usd   := least(v_usd, v_pool_usd);
      v_val_usd_g := round(v_pool_usd_g * v_val_usd / v_pool_usd, 6);
    end if;

    update public.manager_vault_account
       set valued_cash_uzs   = round(v_pool_uzs - v_val_cash, 2),
           valued_cash_585_g = round(v_pool_uzs_g - v_val_cash_g, 6),
           valued_usd        = round(v_pool_usd - v_val_usd, 2),
           valued_usd_585_g  = round(v_pool_usd_g - v_val_usd_g, 6)
     where organization_id = new.organization_id;

    if v_val_cash = 0 and v_val_usd = 0 then
      return new; -- paid entirely from unvalued (pre-066 or non-handover) cash: no difference to record
    end if;

    v_total_cost  := coalesce(new.total_cost_uzs, v_cash + v_usd * coalesce(v_usd_rate, 0));
    v_valued_cost := round(v_val_cash + v_val_usd * coalesce(v_usd_rate, 0), 2);
    v_valued_585  := case when v_total_cost > 0
                          then round(coalesce(new.equiv_585_grams, 0) * v_valued_cost / v_total_cost, 6) else 0 end;

    insert into public.company_rate_differences (
      organization_id, entry_type, purchase_id,
      cash_spent_uzs, usd_spent, usd_rate, valued_cash_uzs, valued_usd, valued_cash_585_g, valued_usd_585_g, unvalued_cost_uzs,
      purchase_rate_per_gram, physical_grams, proba, purchased_585_g, valued_purchased_585_g,
      accounting_value_585_g, avg_conversion_rate, difference_585_g, created_by
    ) values (
      new.organization_id, 'purchase', new.id,
      v_cash, v_usd, v_usd_rate, v_val_cash, v_val_usd, v_val_cash_g, v_val_usd_g, round(greatest(v_total_cost - v_valued_cost, 0), 2),
      new.rate_per_gram, coalesce(new.gold_weight_grams, 0), new.proba, coalesce(new.equiv_585_grams, 0), v_valued_585,
      round(v_val_cash_g + v_val_usd_g, 6),
      case when v_val_cash_g > 0 then round(v_val_cash / v_val_cash_g, 2) end,
      round(v_valued_585 - (v_val_cash_g + v_val_usd_g), 6),
      coalesce(new.recorded_by, public.current_employee_id())
    );
    return new;
  end if;

  -- UPDATE: purchase reversed -> offset its difference and give the value back to the pool
  if old.status is distinct from 'reversed' and new.status = 'reversed' then
    select * into v_orig from public.company_rate_differences
     where purchase_id = new.id and entry_type = 'purchase';
    if not found then
      return new;
    end if;
    perform public._get_or_create_manager_vault(new.organization_id);
    update public.manager_vault_account
       set valued_cash_uzs   = round(valued_cash_uzs + v_orig.valued_cash_uzs, 2),
           valued_cash_585_g = round(valued_cash_585_g + v_orig.valued_cash_585_g, 6),
           valued_usd        = round(valued_usd + v_orig.valued_usd, 2),
           valued_usd_585_g  = round(valued_usd_585_g + v_orig.valued_usd_585_g, 6)
     where organization_id = new.organization_id;
    insert into public.company_rate_differences (
      organization_id, entry_type, purchase_id, reversal_of_id,
      cash_spent_uzs, usd_spent, usd_rate, valued_cash_uzs, valued_usd, valued_cash_585_g, valued_usd_585_g, unvalued_cost_uzs,
      purchase_rate_per_gram, physical_grams, proba, purchased_585_g, valued_purchased_585_g,
      accounting_value_585_g, avg_conversion_rate, difference_585_g, created_by
    ) values (
      v_orig.organization_id, 'purchase_reversal', v_orig.purchase_id, v_orig.id,
      -v_orig.cash_spent_uzs, -v_orig.usd_spent, v_orig.usd_rate, -v_orig.valued_cash_uzs, -v_orig.valued_usd,
      -v_orig.valued_cash_585_g, -v_orig.valued_usd_585_g, -v_orig.unvalued_cost_uzs,
      v_orig.purchase_rate_per_gram, -v_orig.physical_grams, v_orig.proba, -v_orig.purchased_585_g, -v_orig.valued_purchased_585_g,
      -v_orig.accounting_value_585_g, v_orig.avg_conversion_rate, -v_orig.difference_585_g,
      public.current_employee_id()
    );
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_rate_difference_from_purchase() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_rate_difference_from_purchase() to service_role;

-- parity: trg_goldia_sale_markup_snapshot()
CREATE OR REPLACE FUNCTION public.trg_goldia_sale_markup_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pct numeric(6, 2);
begin
  if new.assigned_seller_markup_pct is null and new.consignment_id is not null then
    select seller_markup_pct into v_pct from public.seller_consignments where id = new.consignment_id;
    if v_pct is not null then
      new.assigned_seller_markup_pct := v_pct;
      new.markup_snapshot_source := 'sale_time';
    end if;
  end if;
  if new.assigned_seller_markup_pct is not null and new.client_markup_pct is not null then
    new.markup_difference_g := round(coalesce(new.base_weight_grams, 0)
      * (new.client_markup_pct - new.assigned_seller_markup_pct) / 100.0, 4);
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_sale_markup_snapshot() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_sale_markup_snapshot() to service_role;

-- parity: trg_goldia_seller_till_pool()
CREATE OR REPLACE FUNCTION public.trg_goldia_seller_till_pool()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_acc    public.seller_gold_accounts%rowtype;
  v_take   numeric(18, 2);
  v_take_g numeric(18, 6);
begin
  if new.seller_id is null or new.direction not in ('client_to_seller', 'seller_to_manager') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.reversal_of_id is not null or coalesce(new.status, 'confirmed') <> 'confirmed' then
      return new;
    end if;
    if new.direction = 'client_to_seller' then
      -- record exactly what this payment adds to the pool
      new.till_pool_cash_uzs   := case when coalesce(new.cash_paid_amount, 0) > 0 then new.cash_paid_amount else 0 end;
      new.till_pool_cash_585_g := case when coalesce(new.cash_paid_amount, 0) > 0 then coalesce(new.cash_equivalent_grams, 0) else 0 end;
      new.till_pool_usd        := case when coalesce(new.usd_paid_amount, 0) > 0 then new.usd_paid_amount else 0 end;
      new.till_pool_usd_585_g  := case when coalesce(new.usd_paid_amount, 0) > 0 then coalesce(new.usd_equivalent_grams, 0) else 0 end;
      if new.till_pool_cash_uzs = 0 and new.till_pool_usd = 0 then
        return new;
      end if;
      insert into public.seller_gold_accounts (seller_id, organization_id, till_valued_cash_uzs, till_valued_cash_585_g,
                                               till_valued_usd, till_valued_usd_585_g, updated_at)
      values (new.seller_id, new.organization_id, new.till_pool_cash_uzs, new.till_pool_cash_585_g,
              new.till_pool_usd, new.till_pool_usd_585_g, now())
      on conflict (seller_id) do update set
        till_valued_cash_uzs   = round(seller_gold_accounts.till_valued_cash_uzs + excluded.till_valued_cash_uzs, 2),
        till_valued_cash_585_g = round(seller_gold_accounts.till_valued_cash_585_g + excluded.till_valued_cash_585_g, 6),
        till_valued_usd        = round(seller_gold_accounts.till_valued_usd + excluded.till_valued_usd, 2),
        till_valued_usd_585_g  = round(seller_gold_accounts.till_valued_usd_585_g + excluded.till_valued_usd_585_g, 6);
    else
      -- handover: the RPC already chose what it takes out of the pool
      update public.seller_gold_accounts
         set till_valued_cash_uzs   = round(greatest(0, till_valued_cash_uzs - new.till_pool_cash_uzs), 2),
             till_valued_cash_585_g = round(greatest(0, till_valued_cash_585_g - new.till_pool_cash_585_g), 6),
             till_valued_usd        = round(greatest(0, till_valued_usd - new.till_pool_usd), 2),
             till_valued_usd_585_g  = round(greatest(0, till_valued_usd_585_g - new.till_pool_usd_585_g), 6)
       where seller_id = new.seller_id;
    end if;
    return new;
  end if;

  -- UPDATE: a confirmed settlement was reversed -> move its own pool share back
  if old.status is distinct from 'reversed' and new.status = 'reversed' and new.reversal_of_id is null then
    select * into v_acc from public.seller_gold_accounts where seller_id = new.seller_id for update;
    if not found then
      return new;
    end if;
    if new.direction = 'client_to_seller' then
      if new.till_pool_cash_uzs > 0 then
        v_take   := least(v_acc.till_valued_cash_uzs, new.till_pool_cash_uzs);
        v_take_g := least(v_acc.till_valued_cash_585_g, new.till_pool_cash_585_g * v_take / new.till_pool_cash_uzs);
        v_acc.till_valued_cash_uzs := v_acc.till_valued_cash_uzs - v_take;
        v_acc.till_valued_cash_585_g := v_acc.till_valued_cash_585_g - v_take_g;
      end if;
      if new.till_pool_usd > 0 then
        v_take   := least(v_acc.till_valued_usd, new.till_pool_usd);
        v_take_g := least(v_acc.till_valued_usd_585_g, new.till_pool_usd_585_g * v_take / new.till_pool_usd);
        v_acc.till_valued_usd := v_acc.till_valued_usd - v_take;
        v_acc.till_valued_usd_585_g := v_acc.till_valued_usd_585_g - v_take_g;
      end if;
    else
      v_acc.till_valued_cash_uzs   := v_acc.till_valued_cash_uzs + new.till_pool_cash_uzs;
      v_acc.till_valued_cash_585_g := v_acc.till_valued_cash_585_g + new.till_pool_cash_585_g;
      v_acc.till_valued_usd        := v_acc.till_valued_usd + new.till_pool_usd;
      v_acc.till_valued_usd_585_g  := v_acc.till_valued_usd_585_g + new.till_pool_usd_585_g;
    end if;
    update public.seller_gold_accounts
       set till_valued_cash_uzs = round(v_acc.till_valued_cash_uzs, 2), till_valued_cash_585_g = round(v_acc.till_valued_cash_585_g, 6),
           till_valued_usd = round(v_acc.till_valued_usd, 2), till_valued_usd_585_g = round(v_acc.till_valued_usd_585_g, 6)
     where seller_id = new.seller_id;
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_seller_till_pool() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_seller_till_pool() to service_role;

-- parity: trg_goldia_valued_cash_from_settlement()
CREATE OR REPLACE FUNCTION public.trg_goldia_valued_cash_from_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_vault   public.manager_vault_account%rowtype;
  v_take    numeric(18, 2);
  v_take_g  numeric(18, 6);
begin
  if new.direction <> 'seller_to_manager' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    -- Only the original confirmed handover; compensating rows are inserted as 'reversed'.
    if new.reversal_of_id is not null or coalesce(new.status, 'confirmed') <> 'confirmed' then
      return new;
    end if;
    perform public._get_or_create_manager_vault(new.organization_id);
    update public.manager_vault_account
       set valued_cash_uzs   = round(valued_cash_uzs + coalesce(new.cash_paid_amount, 0), 2),
           valued_cash_585_g = round(valued_cash_585_g + case when coalesce(new.cash_paid_amount, 0) > 0
                                 then coalesce(new.cash_equivalent_grams, 0) else 0 end, 6),
           valued_usd        = round(valued_usd + coalesce(new.usd_paid_amount, 0), 2),
           valued_usd_585_g  = round(valued_usd_585_g + case when coalesce(new.usd_paid_amount, 0) > 0
                                 then coalesce(new.usd_equivalent_grams, 0) else 0 end, 6)
     where organization_id = new.organization_id;
    return new;
  end if;

  -- UPDATE: a confirmed handover was reversed -> take its own value back out of the pool
  -- (never more than the pool still holds).
  if old.status is distinct from 'reversed' and new.status = 'reversed' and new.reversal_of_id is null then
    select * into v_vault from public.manager_vault_account where organization_id = new.organization_id for update;
    if not found then
      return new;
    end if;
    if coalesce(new.cash_paid_amount, 0) > 0 then
      v_take   := least(v_vault.valued_cash_uzs, new.cash_paid_amount);
      v_take_g := least(v_vault.valued_cash_585_g,
                        coalesce(new.cash_equivalent_grams, 0) * v_take / new.cash_paid_amount);
      v_vault.valued_cash_uzs   := v_vault.valued_cash_uzs - v_take;
      v_vault.valued_cash_585_g := v_vault.valued_cash_585_g - v_take_g;
    end if;
    if coalesce(new.usd_paid_amount, 0) > 0 then
      v_take   := least(v_vault.valued_usd, new.usd_paid_amount);
      v_take_g := least(v_vault.valued_usd_585_g,
                        coalesce(new.usd_equivalent_grams, 0) * v_take / new.usd_paid_amount);
      v_vault.valued_usd       := v_vault.valued_usd - v_take;
      v_vault.valued_usd_585_g := v_vault.valued_usd_585_g - v_take_g;
    end if;
    update public.manager_vault_account
       set valued_cash_uzs = round(v_vault.valued_cash_uzs, 2), valued_cash_585_g = round(v_vault.valued_cash_585_g, 6),
           valued_usd = round(v_vault.valued_usd, 2), valued_usd_585_g = round(v_vault.valued_usd_585_g, 6)
     where organization_id = new.organization_id;
  end if;
  return new;
end;
$function$;
revoke all on function trg_goldia_valued_cash_from_settlement() from public, anon, authenticated, service_role;
grant execute on function trg_goldia_valued_cash_from_settlement() to service_role;

-- parity: trg_prevent_accounting_baseline_mutation()
CREATE OR REPLACE FUNCTION public.trg_prevent_accounting_baseline_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'DELETE' then
    raise exception 'ERR_BASELINE_IMMUTABLE: Tasdiqlangan boshlang''ich hisob daxlsizdir. Uni o''chirish qat''iyan taqiqlanadi (ID: %)', OLD.id
      using errcode = '42501';
  end if;

  if TG_OP = 'UPDATE' then
    -- Only allow status transition from 'active' to 'archived', NO financial modification allowed
    if OLD.status = 'active' and NEW.status = 'archived'
       and NEW.id = OLD.id
       and NEW.organization_id = OLD.organization_id
       and NEW.baseline_no = OLD.baseline_no
       and NEW.net_assets_585_g = OLD.net_assets_585_g
       and NEW.total_assets_585_g = OLD.total_assets_585_g
       and NEW.total_liabilities_585_g = OLD.total_liabilities_585_g
       and NEW.gold_rate_585 = OLD.gold_rate_585
       and NEW.usd_rate = OLD.usd_rate
       and NEW.baseline_date = OLD.baseline_date then
      return NEW;
    end if;

    raise exception 'ERR_BASELINE_IMMUTABLE: Tasdiqlangan boshlang''ich hisob ko''rsatkichlarini o''zgartirish taqiqlanadi (ID: %)', OLD.id
      using errcode = '42501';
  end if;

  return NEW;
end;
$function$;
revoke all on function trg_prevent_accounting_baseline_mutation() from public, anon, authenticated, service_role;
grant execute on function trg_prevent_accounting_baseline_mutation() to public;
grant execute on function trg_prevent_accounting_baseline_mutation() to anon;
grant execute on function trg_prevent_accounting_baseline_mutation() to authenticated;
grant execute on function trg_prevent_accounting_baseline_mutation() to service_role;

-- parity: trg_prevent_financial_transaction_mutation()
CREATE OR REPLACE FUNCTION public.trg_prevent_financial_transaction_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'DELETE' then
    raise exception 'ERR_FINANCIAL_TRANSACTION_IMMUTABLE: Tasdiqlangan moliyaviy operatsiya yozuvini o''chirish taqiqlanadi (ID: %)', OLD.id
      using errcode = '42501';
  end if;

  if TG_OP = 'UPDATE' then
    -- Allow transition from 'confirmed' to 'reversed' ONLY, no financial numbers can be altered
    if OLD.status = 'confirmed' and NEW.status = 'reversed'
       and NEW.id = OLD.id
       and NEW.organization_id = OLD.organization_id
       and NEW.transaction_no = OLD.transaction_no
       and NEW.transaction_date = OLD.transaction_date
       and NEW.transaction_type = OLD.transaction_type
       and NEW.source_till = OLD.source_till
       and NEW.amount_num = OLD.amount_num
       and NEW.currency = OLD.currency
       and NEW.equiv_585_grams = OLD.equiv_585_grams then
      return NEW;
    end if;

    -- Allow audited capital reclassification by Director (updating destination till and audit reason while preserving financial balance)
    if OLD.transaction_type = 'capital_contribution'
       and NEW.id = OLD.id
       and NEW.organization_id = OLD.organization_id
       and NEW.transaction_no = OLD.transaction_no
       and NEW.transaction_date = OLD.transaction_date
       and NEW.transaction_type = OLD.transaction_type
       and NEW.amount_num = OLD.amount_num
       and NEW.equiv_585_grams = OLD.equiv_585_grams
       and NEW.reclassification_reason is not null then
      return NEW;
    end if;

    raise exception 'ERR_FINANCIAL_TRANSACTION_IMMUTABLE: Tasdiqlangan moliyaviy operatsiya ko''rsatkichlarini o''zgartirish taqiqlanadi (ID: %)', OLD.id
      using errcode = '42501';
  end if;

  return NEW;
end;
$function$;
revoke all on function trg_prevent_financial_transaction_mutation() from public, anon, authenticated, service_role;
grant execute on function trg_prevent_financial_transaction_mutation() to public;
grant execute on function trg_prevent_financial_transaction_mutation() to anon;
grant execute on function trg_prevent_financial_transaction_mutation() to authenticated;
grant execute on function trg_prevent_financial_transaction_mutation() to service_role;

-- parity: trg_sync_consignment_pieces_purity_proba()
CREATE OR REPLACE FUNCTION public.trg_sync_consignment_pieces_purity_proba()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.purity is not null and (new.proba is null or new.proba <> new.purity) then
    new.proba := new.purity;
  elsif new.proba is not null and (new.purity is null or new.purity <> new.proba) then
    new.purity := new.proba;
  elsif new.purity is null and new.proba is null then
    new.purity := 585;
    new.proba := 585;
  end if;
  return new;
end;
