-- parity: try_cast_uuid(text)
CREATE OR REPLACE FUNCTION public.try_cast_uuid(p_val text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
